  .slot-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 9px; margin-top: 6px; }
  .slot-card { background: var(--bg-panel); border: 1px solid #3d2f47; border-radius: 6px; padding: 10px; position: relative; box-shadow: inset 0 0 18px rgba(0,0,0,0.65); display: flex; flex-direction: column; justify-content: space-between; }
  .hub-launcher-card {
