function getActiveHolidayEvent() {
  var d = new Date();
  var m = d.getMonth() + 1;
  var day = d.getDate();
  if ((m === 10 && day >= 25) || (m === 11 && day <= 1)) return HOLIDAY_WEEK_EVENTS.halloween;
  if (m === 11 && day >= 20 && day <= 28) return HOLIDAY_WEEK_EVENTS.thanksgiving;
  if (m === 12 && day >= 18 && day <= 26) return HOLIDAY_WEEK_EVENTS.krampus;
  if (window.hero && window.hero.forcedHolidayId && HOLIDAY_WEEK_EVENTS[window.hero.forcedHolidayId]) {
    return HOLIDAY_WEEK_EVENTS[window.hero.forcedHolidayId];
  }
  return null;
}

