function getTodayDateStr() { return new Date().toISOString().slice(0, 10); }

function getMaxFameForLevel(lv) {
  var safeLv = Math.max(1, lv || (hero ? hero.level : 1));
  return Math.max(100, safeLv * 70);
}

function addHeroFame(amt, targetH) {
  var h = targetH || hero;
  if (!h) return 0;
  var cap = getMaxFameForLevel(h.level || 1);
  h.fame = Math.max(0, Math.min(cap, (h.fame || 0) + amt));
  return h.fame;
}

function isHeroDrunk(targetH) {
  var h = targetH || hero;
  if (!h || !h.drunkUntil) return false;
  if (Date.now() >= h.drunkUntil) {
    h.drunkUntil = 0;
    return false;
  }
  return true;
}

function countTotalPartyDiseases(targetH) {
  var h = targetH || hero;
  if (!h) return 0;
  var cnt = Array.isArray(h.diseases) ? h.diseases.length : 0;
  if (Array.isArray(h.mercenaries)) {
    h.mercenaries.forEach(function(m) {
      if (m && m.disease) cnt++;
    });
  }
  return cnt;
}

// Strict 2-Helper Party Cap: Counts active Recruits + Alt Bodyguard + Animal Companion + Active Battle Heir
function getActiveHelperCount(targetH) {
  var h = targetH || hero;
  if (!h) return 0;
  var cnt = 0;
  if (Array.isArray(h.mercenaries)) cnt += h.mercenaries.length;
  if (h.altBodyguard && h.altBodyguard.name) cnt += 1;
  if (h.companion && h.companion.id) cnt += 1;
  if (h.activeChildIdx >= 0 && Array.isArray(h.children) && h.children[h.activeChildIdx]) {
    var ch = h.children[h.activeChildIdx];
    if (!ch.expeditionUntil || ch.expeditionUntil <= Date.now()) cnt += 1;
  }
  return cnt;
}

function enforceTwoHelperCap(h) {
  if (!h) return;
  while (getActiveHelperCount(h) > MAX_ACTIVE_HELPERS) {
    if (h.activeChildIdx >= 0) { h.activeChildIdx = -1; continue; }
    if (h.companion) { h.companion = null; continue; }
    if (h.altBodyguard) { h.altBodyguard = null; continue; }
    if (h.mercenaries && h.mercenaries.length > 2) { h.mercenaries.pop(); continue; }
    break;
  }
}

function pushBuffToFifo(buffId, targetH) {
  var h = targetH || hero;
  if (!h || !buffId) return;
  if (!Array.isArray(h.buffFifoOrder)) h.buffFifoOrder = [];
  h.buffFifoOrder = h.buffFifoOrder.filter(function(x) { return x !== buffId; });
  h.buffFifoOrder.push(buffId);
}

function getRealWeather() {
  var rw = (serverData && serverData.realWeather) ? serverData.realWeather : null;
  if (!rw) return { linked: false, active: false, rain: false, wind: false, lightning: false, cold: false, hot: false, conditions: [], summary: "🌤️ Mild Skies" };
  return rw;
}

function updateRealWeatherTopPill() {
  var pill = document.getElementById("realWeatherPill");
  if (!pill) return;
  var rw = getRealWeather();
  var hol = window.getActiveHolidayEvent ? getActiveHolidayEvent() : null;
  var holTag = hol ? (" " + hol.icon) : "";
  if (!rw.active || !rw.conditions || !rw.conditions.length) {
    pill.innerHTML = ((rw.tempF !== undefined && rw.tempF !== null) ? ("🌤️ " + rw.tempF + "°F") : "🌤️ Mild Skies") + holTag;
    return;
  }
  var icons = [];
  if (rw.rain) icons.push("🌧️Rain");
  if (rw.wind) icons.push("💨Wind");
  if (rw.lightning) icons.push("⚡Storm");
  if (rw.cold) icons.push("❄️Cold");
  if (rw.hot) icons.push("🔥Hot");
  pill.innerHTML = icons.join(" ") + ((rw.tempF !== undefined && rw.tempF !== null) ? (" (" + rw.tempF + "°F)") : "") + holTag;
}

function getWeaponArchetypePerk(wep) {
  if (!wep || !wep.name || !window.WEAPON_ARCHETYPE_PERKS) return null;
  var keys = Object.keys(WEAPON_ARCHETYPE_PERKS);
  for (var i = 0; i < keys.length; i++) {
    if (wep.name.indexOf(keys[i]) >= 0) {
      return WEAPON_ARCHETYPE_PERKS[keys[i]];
    }
  }
  return WEAPON_ARCHETYPE_PERKS["Broadsword"];
}

function getActiveRecruitSynergyBond(h) {
  var t = h || hero;
  if (!t || !t.mercenaries || !t.mercenaries.length || !window.RECRUIT_SYNERGY_BONDS) return null;
  var activeIds = t.mercenaries.map(function(m) { return m.id; });
  for (var i = 0; i < RECRUIT_SYNERGY_BONDS.length; i++) {
    var b = RECRUIT_SYNERGY_BONDS[i];
    var allPresent = b.ids.every(function(reqId) { return activeIds.includes(reqId); });
    if (allPresent) return b;
  }
  return null;
}

function getActiveBuffsAndWhyList(targetHero) {
  var h = targetHero || hero;
  if (!h) return [];
  ensureHeroV3Fields(h);
  var rawList = [];
  var nRank = NOBLE_RANKS[h.nobleIdx || 0] || NOBLE_RANKS[0];
  var maxF = getMaxFameForLevel(h.level || 1);

  if (isHeroDrunk(h)) {
    var drRem = formatCooldownSec(Math.max(1, Math.ceil((h.drunkUntil - Date.now()) / 1000)));
    rawList.push({ id: "debuff_drunk", icon: "🍺", name: "Stumbling Drunk (Boar's Head Taproom)", effect: "-15% Hit Accuracy, -12% Dodge & -15% Wits (" + drRem + " left)", why: "Drank too many goblets of Aged Dragon-Malt Reserve within 2 hours at the Boar's Head Tavern!", isDebuff: true });
  }
  if (h.deathsDoorTrauma) {
    rawList.push({ id: "debuff_trauma", icon: "🕯️", name: "Death's Door Trauma", effect: "-10% All Stats (Mortality Debuff)", why: "A Valkyrie Seal shattered to save your life. Cure by resting above the floor at the Inn or praying at the Sanctuary!", isDebuff: true });
  }
  if ((h.stress || 0) >= 75) {
    rawList.push({ id: "debuff_paranoia", icon: "😱", name: "Paranoia (75%+ Stress)", effect: "-10% Hit Accuracy, -10% Dodge & 15% Recruit Panic Chance", why: "Severe mental strain (75%+ Stress). Drink Aged Dragon-Malt at the Tavern, pray at the Confessional, or sleep above the floor at the Inn!", isDebuff: true });
  } else if ((h.stress || 0) >= 50) {
    rawList.push({ id: "debuff_dread", icon: "😰", name: "Creeping Dread (50%+ Stress)", effect: "-5% Hit Accuracy & -5% Dodge", why: "Mounting dungeon dread (50%+ Stress). Relieve Stress before it reaches 75% Paranoia!", isDebuff: true });
  }

  if (Array.isArray(h.diseases) && h.diseases.length > 0) {
    h.diseases.forEach(function(d) {
      rawList.push({ id: "debuff_dis_" + d.id, icon: "🦠", name: "Hero " + d.name, effect: d.desc, why: (d.caughtFrom ? ("Caught from " + d.caughtFrom + ". ") : "") + "Cure at the Plague-Doctor Leech Ward (2/day) or with Sister Vespera (15💎)!", isDebuff: true });
    });
  }
  if (Array.isArray(h.mercenaries)) {
    h.mercenaries.forEach(function(m) {
      if (m && m.disease) {
        rawList.push({ id: "debuff_recdis_" + m.id, icon: "🦠", name: "Recruit Infected (" + m.name + "): " + m.disease.name, effect: m.disease.recruitEffect || "-15% Recruit ATK", why: (m.disease.caughtFrom ? ("Caught from " + m.disease.caughtFrom + ". ") : "") + "Cure via Plague-Doctor Leech Ward or Sister Vespera (15💎)!", isDebuff: true });
      }
    });
  }

  var hol = window.getActiveHolidayEvent ? getActiveHolidayEvent() : null;
  if (hol) {
    rawList.push({ id: "buff_holiday", icon: hol.icon, name: hol.name, effect: hol.desc, why: "Active Holiday Week Event across Valoria!", isDebuff: false });
  }

  if ((nRank.bonusPct || 0) > 0) {
    rawList.push({ id: "buff_noble", icon: "👑", name: "Feudal Rank: " + nRank.title, effect: "+" + nRank.bonusPct + "% All Stats", why: "Granted by the High Court for holding the noble title of " + nRank.title + " (" + nRank.domainName + ").", isDebuff: false });
  }
  if ((h.fame || 0) < nRank.fameReq) {
    rawList.push({ id: "debuff_fame", icon: "⚠️", name: "Tarnished Court Reputation", effect: "-10% All Stats & -15% Kingdom Tax", why: "Your Court Fame (" + (h.fame || 0) + ") decayed below your " + nRank.title + " requirement (" + nRank.fameReq + "). Complete Warrants, Jousts, or Banquets!", isDebuff: true });
  } else if ((h.fame || 0) >= Math.round(maxF * 0.95)) {
    rawList.push({ id: "buff_toast", icon: "🌟", name: "Toast of the High Court", effect: "+5% All Stats & +10% Gold Find", why: "Your Court Fame (" + (h.fame || 0) + "/" + maxF + ") is at 95%+ of your Level " + h.level + " Max Fame Cap!", isDebuff: false });
  }

  if (h.spouse && h.spouse.name) {
    var spLove = h.spouse.love !== undefined ? h.spouse.love : 100;
    var lovePct = spLove >= 80 ? "100%" : (spLove >= 40 ? "50%" : "0%");
    var multiCnt = Array.isArray(h.marriedConsorts) ? h.marriedConsorts.length : 1;
    rawList.push({ id: "buff_consort", icon: "💍", name: "Chosen Consort Blessing: " + h.spouse.name, effect: lovePct + " of " + h.spouse.blessing + (h.consortAttire !== "Velvet Court Gown" ? " [+25% Wardrobe]" : ""), why: "Selected as your single active Consort Blessing in the Velvet Chamber (" + multiCnt + " Wed • Devotion: " + spLove + "%).", isDebuff: (spLove < 40) });
    if (h.spouse.diplomacyUntil && h.spouse.diplomacyUntil > Date.now()) {
      var dipRem = formatCooldownSec(Math.ceil((h.spouse.diplomacyUntil - Date.now()) / 1000));
      rawList.push({ id: "buff_diplomacy", icon: "🕊️", name: "Consort Diplomatic Mission", effect: "-50% Passive Fame Decay Rate", why: h.spouse.name + " is representing your House at neighboring courts (" + dipRem + " left).", isDebuff: false });
    }
  }

  if (h.activeFeast && h.activeFeast.questsLeft > 0) {
    rawList.push({ id: "buff_feast", icon: h.activeFeast.icon || "🍖", name: "Tavern Feast: " + h.activeFeast.name, effect: h.activeFeast.desc, why: "Ordered at the Boar's Head Inn (" + h.activeFeast.questsLeft + " Quests remaining).", isDebuff: false });
  }
  if (h.lodgingBuff && h.lodgingBuff.questsLeft > 0) {
    var isStiff = (h.lodgingBuff.dodgePen > 0);
    var stRedTxt = h.lodgingBuff.stressRedPct ? (" & -" + h.lodgingBuff.stressRedPct + "% Stress Gain") : "";
    rawList.push({ id: isStiff ? "debuff_lodging" : "buff_lodging", icon: isStiff ? "🪵" : "🛌", name: "Lodging Effect: " + h.lodgingBuff.name, effect: isStiff ? ("-" + h.lodgingBuff.dodgePen + "% Dodge") : ("+" + (h.lodgingBuff.statBonusPct || 12) + "% All Stats, +" + (h.lodgingBuff.xpBonusPct || 15) + "% XP" + stRedTxt), why: "Slept 2+ hours offline at the Inn or Royal Palace (" + h.lodgingBuff.questsLeft + " Quests remaining).", isDebuff: isStiff });
  }
  if (h.tarotBuff && h.tarotBuff.questsLeft > 0) {
    rawList.push({ id: "buff_tarot", icon: h.tarotBuff.icon || "🃏", name: "Tarot Arcana: " + h.tarotBuff.name, effect: h.tarotBuff.desc, why: "Drawn at the Tarot Seer's Vardo (" + h.tarotBuff.questsLeft + " Quests remaining).", isDebuff: false });
  }
  if (h.resolveState) {
    rawList.push({ id: h.resolveState.isVirtue ? "buff_virtue" : "debuff_affliction", icon: h.resolveState.isVirtue ? "🌟" : "😰", name: h.resolveState.name, effect: h.resolveState.desc, why: "Triggered when Stress reached 100% (" + (h.resolveState.questsLeft || 1) + " Quests remaining).", isDebuff: !h.resolveState.isVirtue });
  }
  if ((h.moonCurseTurns || 0) > 0) {
    rawList.push({ id: "debuff_moon", icon: "🐺", name: "Hunter's Moon Lycanthropy", effect: "+25% Guts & +15% Crit, -15% Wits", why: "Bitten by a feral Werewolf during patrol (" + h.moonCurseTurns + " Quests remaining).", isDebuff: true });
  }
  if ((h.petTreatBattles || 0) > 0 && h.companion) {
    rawList.push({ id: "buff_pettreat", icon: "🍖", name: "Companion Morale Surge (" + h.companion.name + ")", effect: "+50% Companion Damage & +5% Hit/Crit", why: "Fed rations/trout to your bound companion (" + h.petTreatBattles + " Battles remaining).", isDebuff: false });
  }
  if (h.overkillSurge) {
    rawList.push({ id: "buff_overkill", icon: "⚡", name: "Overkill Momentum Surge", effect: "+15% First-Strike Damage & +10% Colossus Charge", why: "Earned by slaying your previous foe with a 50%+ Overkill blow!", isDebuff: false });
  }

  var rw = getRealWeather();
  if (rw && rw.active && rw.conditions && rw.conditions.length) {
    rw.conditions.forEach(function(cKey) {
      var cfg = REAL_WEATHER_CONFIG[cKey];
      if (cfg) {
        rawList.push({ id: "buff_rw_" + cKey, icon: cfg.icon, name: cfg.name + " (Real Weather Station)", effect: "Perk: " + cfg.perk + " | Debuff: " + cfg.debuff, why: "Live outdoor sensor reading from your linked Hubitat Weather Station.", isDebuff: false });
      }
    });
  }

  var curse = getActiveRealmCurse();
  if (curse) {
    rawList.push({ id: "debuff_curse", icon: "☠️", name: "7-Day Cataclysm Curse: " + curse.name, effect: curse.desc, why: "World Boss reached 100% Devastation (Cleanse at Kingdom Cathedral).", isDebuff: true });
  }

  if (h.guild && h.guild.founded) {
    var stab = h.guild.stability !== undefined ? h.guild.stability : 75;
    if (stab >= 80) rawList.push({ id: "buff_stability", icon: "🏰", name: "High Kingdom Stability (" + stab + "%)", effect: "+8% All Stats" + (h.guild.festivalBoom ? " & +15% Festival Boom Gold/XP!" : ""), why: "Your Chartered Kingdom's Stability is maintained at 80%+.", isDebuff: false });
    else if (stab < 40) rawList.push({ id: "debuff_unrest", icon: "🔥", name: "Kingdom Unrest (" + stab + "%)", effect: "-10% All Stats", why: "Your Kingdom Stability fell below 40% due to famine or raids.", isDebuff: true });
    var dec = KINGDOM_DECREES[h.guild.decree || "martial"];
    if (dec) rawList.push({ id: "buff_decree", icon: "⚖️", name: dec.name, effect: dec.desc, why: "Enacted as your active Royal Edict in the Royal Works tab.", isDebuff: false });
  }

  var setBon = getActiveSetBonuses(h);
  if (setBon && setBon.activeSets && setBon.activeSets.length) {
    setBon.activeSets.forEach(function(s, sIdx) {
      rawList.push({ id: "buff_set_" + sIdx, icon: "⚜️", name: s.name, effect: s.desc, why: "Wearing 3 or more matching Set pieces in your equipment slots.", isDebuff: false });
    });
  }

  var wepPerk = getWeaponArchetypePerk(h.weapon);
  if (wepPerk && h.weapon && (h.weapon.dur === undefined || h.weapon.dur > 0)) {
    rawList.push({ id: "buff_wepperk", icon: "🗡️", name: "Weapon Archetype: " + wepPerk.name, effect: wepPerk.desc, why: "Passive archetype mastery from wielding " + h.weapon.name + ".", isDebuff: false });
  }

  var recBond = getActiveRecruitSynergyBond(h);
  if (recBond) {
    rawList.push({ id: "buff_recbond", icon: "🤝", name: "Recruit Synergy: " + recBond.name, effect: recBond.desc, why: "Active Mercenary covenant in your Sworn Retinue.", isDebuff: false });
  }

  var shardPct = 0;
  SACRED_SHARDS.forEach(function(sh) {
    if (h.bossesDefeated && h.bossesDefeated.includes(sh.areaId)) shardPct += (sh.areaId === 22 ? 10 : (sh.areaId <= 11 ? 5 : 4));
  });
  if (shardPct > 0) {
    rawList.push({ id: "buff_shards", icon: "💎", name: "Sacred Dragon Shards & Astral Seals", effect: "+" + shardPct + "% All Stats", why: "Unsealed by conquering regional bosses across Valoria.", isDebuff: false });
  }

  var tCnt = h.trophyWall ? h.trophyWall.length : 0;
  if (tCnt > 0) {
    rawList.push({ id: "buff_trophies", icon: "🦌", name: "Throne Room Trophy Wall (" + tCnt + "/22)", effect: "+" + (tCnt * 2) + "% All Stats", why: "Mounted severed heads of defeated Area Bosses in your Throne Room.", isDebuff: false });
  }
  if ((h.cosmicRunes || 0) > 0) {
    rawList.push({ id: "buff_runes", icon: "🌌", name: "Void-Rift Cosmic Runes (" + h.cosmicRunes + "/15)", effect: "+" + (Math.min(15, h.cosmicRunes) * 2) + "% All Stats", why: "Earned by clearing every 5th floor in the Void-Rifts or Mirror.", isDebuff: false });
  }
  if ((h.cipherPages || 0) >= 5) {
    rawList.push({ id: "buff_cipher", icon: "📜", name: "Deciphered Tome of Elowen (5/5)", effect: "+6% All Stats", why: "Collected all 5 Torn Cipher Pages from Dungeon Delves.", isDebuff: false });
  }
  if ((h.prestigeRank || 0) > 0) {
    rawList.push({ id: "buff_prestige", icon: "👑", name: "Lineage Ascendancy (Prestige Rank " + h.prestigeRank + ")", effect: "+" + (h.prestigeRank * 3) + "% All Stats & +" + (h.prestigeRank * 2) + "% Gold/Luck", why: "Reborn through the Rite of Eternal Ascendancy or Heir Succession.", isDebuff: false });
  }
  if (h.lineageMutation) {
    rawList.push({ id: "buff_mutation", icon: "🧬", name: "Bloodline Mutation: " + h.lineageMutation.name, effect: h.lineageMutation.desc, why: "Awakened through Prestige or conquering the Mirror of the First King.", isDebuff: false });
  }
  if (h.starChart && h.starChart !== "none") {
    var scDesc = h.starChart === "draco" ? "+5% Crit Chance" : (h.starChart === "chalice" ? "+15% Trophy Drop Luck" : "+12% Gold Find");
    rawList.push({ id: "buff_starchart", icon: "✨", name: "Astrologer's Star-Chart (" + h.starChart.toUpperCase() + ")", effect: scDesc, why: "Aligned constellation in the Void-Rifts tab.", isDebuff: false });
  }

  if (!Array.isArray(h.buffFifoOrder)) h.buffFifoOrder = [];
  var debuffs = [];
  var posBuffs = [];
  rawList.forEach(function(item) {
    if (item.isDebuff) {
      debuffs.push(item);
    } else {
      posBuffs.push(item);
      if (!h.buffFifoOrder.includes(item.id)) {
        h.buffFifoOrder.push(item.id);
      }
    }
  });
  var activePosIds = posBuffs.map(function(x) { return x.id; });
  h.buffFifoOrder = h.buffFifoOrder.filter(function(id) { return activePosIds.includes(id); });
  posBuffs.sort(function(a, b) {
    return h.buffFifoOrder.indexOf(a.id) - h.buffFifoOrder.indexOf(b.id);
  });

  var keptPosBuffs = posBuffs.slice(-MAX_ACTIVE_BUFFS);
  h._activeFifoBuffIds = keptPosBuffs.map(function(x) { return x.id; });
  h._displacedBuffCount = Math.max(0, posBuffs.length - MAX_ACTIVE_BUFFS);
  return debuffs.concat(keptPosBuffs.reverse());
}

function isPositiveBuffActiveFifo(h, buffId) {
  if (!h) return true;
  if (!Array.isArray(h._activeFifoBuffIds)) getActiveBuffsAndWhyList(h);
  return !h._activeFifoBuffIds || h._activeFifoBuffIds.includes(buffId);
}

function openActiveBuffsModal() {
  if (!hero) {
    showGothicToast("⚠️ Load a Hero Slot first to inspect Active Buffs!");
    return;
  }
  var buffs = getActiveBuffsAndWhyList(hero);
  var posCnt = buffs.filter(function(b) { return !b.isDebuff; }).length;
  var debCnt = buffs.filter(function(b) { return b.isDebuff; }).length;
  var displacedCnt = hero._displacedBuffCount || 0;
  var rowsHtml = buffs.length ? buffs.map(function(b) {
    var bCol = b.isDebuff ? "#ef4444" : "#4ade80";
    var bgCol = b.isDebuff ? "#1f090d" : "#0b1410";
    var tagTxt = b.isDebuff ? "[☠️ DEBUFF — UNLIMITED]" : "[✨ ACTIVE FIFO BUFF]";
    return '<div style="background:' + bgCol + ';border:1px solid ' + bCol + ';border-left:4px solid ' + bCol + ';border-radius:4px;padding:8px 10px;margin-bottom:6px;text-align:left;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px;">' +
        '<span style="font-weight:900;color:#fde047;font-family:Cinzel,serif;font-size:12.5px;">' + b.icon + ' ' + escapeHtml(b.name) + ' <span style="font-size:9.5px;color:' + bCol + ';">' + tagTxt + '</span></span>' +
        '<span style="font-size:11.5px;font-weight:bold;color:' + bCol + ';">' + escapeHtml(b.effect) + '</span>' +
      '</div>' +
      '<div style="font-size:11.5px;color:#e5dec9;margin-top:3px;">🕯️ <b>Why You Have This:</b> ' + escapeHtml(b.why) + '</div>' +
    '</div>';
  }).join('') : '<div style="padding:12px;color:#9c8f7a;">No active buffs or debuffs right now.</div>';

  showPopupModal(
    '<div style="font-size:38px;">✨📜🛡️</div>' +
    '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">Active Blessings (' + posCnt + '/' + MAX_ACTIVE_BUFFS + ' FIFO Cap) &amp; Afflictions (' + debCnt + ')</div>' +
    '<div style="font-size:11.5px;color:#86efac;margin-bottom:8px;">⚖️ <b>The Law of Six Blessings (First-In, First-Out):</b> Temporary blessings cap at <b>6 active slots</b> (' + displacedCnt + ' older displaced). <b>Innate Passives, Debuffs, Diseases &amp; Drunk Effects never displace!</b></div>' +
    '<div style="max-height:350px;overflow-y:auto;">' + rowsHtml + '</div>' +
    '<div style="display:flex;gap:8px;margin-top:10px;">' +
      '<button class="btn btn-gold" style="flex:1;" onclick="openHeroSheetModal()">⚜️ Hero Sheet</button>' +
      '<button class="btn" style="flex:1;" onclick="closePopupModal()">Close</button>' +
    '</div>'
  );
}

function countCompletedDailyCategories(h) {
  if (!h) return 0;
  var cnt = 0;
  if ((h.healsUsedToday || 0) > 0) cnt++;
  if ((h.restsUsedToday || 0) > 0) cnt++;
  if ((h.potionsBoughtToday || 0) > 0 || (h.ethersBoughtToday || 0) > 0) cnt++;
  if ((h.sealsBoughtToday || 0) > 0) cnt++;
  if ((h.alembicUsedToday || 0) > 0 || (h.cauldronUsedToday || 0) > 0) cnt++;
  if ((h.stealsUsedToday || 0) > 0) cnt++;
  if ((h.forgesUsedToday || 0) > 0 || (h.socketsUsedToday || 0) > 0) cnt++;
  if ((h.shopBuysToday || 0) > 0 || (h.beltBuysToday || 0) > 0) cnt++;
  if ((h.feastsOrderedToday || 0) > 0 || (h.bantersUsedToday || 0) > 0 || (h.drinksBoughtToday || 0) > 0) cnt++;
  if ((h.courtPetitionsToday || 0) > 0 || (h.intrigueUsedToday || 0) > 0) cnt++;
  if ((h.courtingUsedToday || 0) > 0) cnt++;
  if ((h.minigamesPlayedToday || 0) > 0 || (h.rouletteSpinsToday || 0) > 0) cnt++;
  if ((h.pvpDuelsToday || 0) > 0) cnt++;
  if ((h.spireRunsToday || 0) > 0 || (h.riftsRunToday || 0) > 0) cnt++;
  if ((h.delvesRunToday || 0) > 0 || (h.gauntletsRunToday || 0) > 0) cnt++;
  if ((h.sabotagesUsedToday || 0) > 0) cnt++;
  if ((h.caravansRunToday || 0) > 0 || (h.throneActionsToday || 0) > 0 || (h.armyWarsToday || 0) > 0) cnt++;
  if (h.lastTaxDateStr === getTodayDateStr()) cnt++;
  return cnt;
}

function claimDailyCommendationCache() {
  if (!hero) return;
  ensureHeroV3Fields(hero);
  var doneCnt = countCompletedDailyCategories(hero);
  if (hero.commendationClaimedToday || doneCnt < 5) return;
  hero.commendationClaimedToday = true;
  var gGain = 350 + hero.level * 65;
  hero.gold += gGain;
  addHeroFame(25);
  hero.potions = (hero.potions || 0) + 1;
  if (hero.guild) hero.guild.rations = (hero.guild.rations || 0) + 15;
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 36);
  addLog("🎁👑 <b>DAILY ROYAL COMMENDATION CACHE CLAIMED (5+ Daily Activities Completed):</b> Earned <b>+" + gGain.toLocaleString() + "g, +25 Court Fame, +1🧪 Healing Potion &amp; +15🍞 Rations</b>!");
  queueDeltaSaveHero();
  openDailyLimitsTrackerModal();
  renderGameScreen();
}

function openDailyLimitsTrackerModal() {
  if (!hero) {
    showGothicToast("⚠️ Load a Hero Slot first to view Daily Activity Caps!");
    return;
  }
  ensureHeroV3Fields(hero);
  var doneCnt = countCompletedDailyCategories(hero);
  var canClaimCache = (doneCnt >= 5 && !hero.commendationClaimedToday);
  var cacheBanner = '<div style="background:linear-gradient(90deg,#1f1408,#3b280a,#1f1408);border:2px solid #fde047;border-radius:6px;padding:8px 10px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
    '<div style="text-align:left;font-size:12px;"><b style="color:#fde047;font-family:Cinzel,serif;">🎁 Daily Royal Commendation Cache (' + doneCnt + '/5 Categories Done Today):</b><div style="color:#e5dec9;font-size:11px;">Complete 5 different daily activities for +' + (350 + hero.level * 65).toLocaleString() + 'g, +25 Fame, +1🧪 Potion &amp; +15🍞 Rations!</div></div>' +
    '<button class="btn ' + (hero.commendationClaimedToday ? 'btn-emerald' : (canClaimCache ? 'btn-shine' : 'btn-locked')) + '" style="min-height:28px;padding:4px 10px;font-size:11px;" onclick="claimDailyCommendationCache()">' + (hero.commendationClaimedToday ? '✅ Claimed Today' : (canClaimCache ? '🎁 Claim Cache!' : ('🔒 ' + doneCnt + '/5 Done'))) + '</button>' +
  '</div>';

  var rows = [
    ["🪽 Valkyrie Seals Consecrated (Max 3 Carried)", (hero.sealsBoughtToday || 0) + " / " + MAX_DAILY_VALKYRIE_SEALS],
    ["⚔️ Mercenary Guild Contracts Signed", (hero.mercHiresToday || 0) + " / 2"],
    ["🙏 Cathedral Confessions / 🩸 Leech Ward", (hero.confessionsToday || 0) + "/2 • " + (hero.leechesUsedToday || 0) + "/2"],
    ["💎 Sister Vespera Dragon-Glass Purges", "Unlimited (15💎 per Disease)"],
    ["🥃 Boar's Head Taproom Drinks (-50% Stress)", (hero.drinksBoughtToday || 0) + " / " + MAX_DAILY_DRINKS],
    ["🧪 Thermal Alembic Brews", (hero.alembicUsedToday || 0) + " / " + MAX_DAILY_ALEMBIC],
    ["🥷 Bazaar Shoplifting Attempts", (hero.stealsUsedToday || 0) + " / " + MAX_DAILY_STEALS],
    ["🕯️ Sanctuary Healing Rites", (hero.healsUsedToday || 0) + " / " + MAX_DAILY_HEALS],
    ["🛌 Inn Quick-Rests", (hero.restsUsedToday || 0) + " / " + MAX_DAILY_RESTS],
    ["🧪 Potions / 💧 Elixirs Bought", (hero.potionsBoughtToday || 0) + "/" + MAX_DAILY_POTIONS + " • " + (hero.ethersBoughtToday || 0) + "/" + MAX_DAILY_ETHERS],
    ["🔮 Mira's Discovery Cauldron", (hero.cauldronUsedToday || 0) + " / 2"],
    ["⚒️ Blacksmith Brom Forgings", (hero.forgesUsedToday || 0) + " / " + MAX_DAILY_FORGES],
    ["💎 Dragon Gem Socketings", (hero.socketsUsedToday || 0) + " / " + MAX_DAILY_SOCKETS],
    ["⚖️ Bazaar Gear / 🎒 Belt Buys", (hero.shopBuysToday || 0) + "/" + MAX_DAILY_SHOP_BUYS + " • " + (hero.beltBuysToday || 0) + "/" + MAX_DAILY_BELT_BUYS],
    ["🍖 Tavern Feasts / 🔥 Banters", (hero.feastsOrderedToday || 0) + "/" + MAX_DAILY_FEASTS + " • " + (hero.bantersUsedToday || 0) + "/" + MAX_DAILY_BANTERS],
    ["👑 High Court Petitions / 🕵️ Intrigue", (hero.courtPetitionsToday || 0) + "/" + MAX_DAILY_COURT_PETITIONS + " • " + (hero.intrigueUsedToday || 0) + "/" + MAX_DAILY_INTRIGUE],
    ["🌹 Velvet Chamber Courting Actions", (hero.courtingUsedToday || 0) + " / " + MAX_DAILY_COURTING],
    ["🏇 Tourney Wagers & Mini-Games", (hero.minigamesPlayedToday || 0) + " / " + MAX_DAILY_MINIGAMES],
    ["🎰 Catacomb Gem Roulette Spins", (hero.rouletteSpinsToday || 0) + " / 2"],
    ["⚔️ Blood-Lists PvP Duels", (hero.pvpDuelsToday || 0) + " / " + MAX_DAILY_PVP_DUELS],
    ["🗼 Abyssal Spire / 🌌 Void-Rifts", (hero.spireRunsToday || 0) + "/" + MAX_DAILY_SPIRE_RUNS + " • " + (hero.riftsRunToday || 0) + "/3"],
    ["🔦 Dungeon Delves / 🕳️ Gauntlets", (hero.delvesRunToday || 0) + "/" + MAX_DAILY_DELVES + " • " + (hero.gauntletsRunToday || 0) + "/" + MAX_DAILY_GAUNTLETS],
    ["💣 Pre-Boss Sabotage / 🦌 Trophy Echoes", (hero.sabotagesUsedToday || 0) + "/" + MAX_DAILY_SABOTAGES + " • " + (hero.echoRematchesToday || 0) + "/1"],
    ["🐎 Caravans / ⚖️ Throne / 🚩 Wars", (hero.caravansRunToday || 0) + "/" + MAX_DAILY_CARAVANS + " • " + (hero.throneActionsToday || 0) + "/" + MAX_DAILY_THRONE_ACTIONS + " • " + (hero.armyWarsToday || 0) + "/" + MAX_DAILY_ARMY_WARS],
    ["💰 Daily Kingdom Tax Levy", (hero.lastTaxDateStr === getTodayDateStr() ? "1 / 1" : "0 / 1")]
  ];
  var listHtml = rows.map(function(r) {
    return '<div class="stat-row" style="padding:4px 6px;"><span>' + r[0] + '</span><b style="color:#fde047;">' + r[1] + '</b></div>';
  }).join('');
  showPopupModal(
    '<div style="font-size:36px;">📅⚖️⏳</div>' +
    '<div style="font-size:18px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">Daily Activity Caps (' + escapeHtml(hero.name) + ')</div>' +
    '<div style="font-size:11.5px;color:#86efac;margin-bottom:8px;">⚡ <b>Patrol/Questing &amp; Huntsman Trophy Exchanges have NO daily limit!</b> All non-questing facilities reset at midnight.</div>' +
    cacheBanner +
