  var btnAction = returnFacility ? ("openTownFacilityModal(&#39;" + returnFacility + "&#39;)") : "closePopupModal()";
  var btnText = returnFacility ? "⬅️ Return &amp; Continue" : "⚜️ Continue";
  showPopupModal(
    '<div style="margin-bottom:6px;">' + artHtml + '</div>' +
