  });
  if (h.activeChildIdx === undefined) h.activeChildIdx = -1;
  if (!h.belt || typeof h.belt !== "object") h.belt = { firebomb: 1, ironnet: 1, warhorn: 1 };
  if (!h.spireFloor) h.spireFloor = 1;
