  if (!Array.isArray(h.vault.items)) h.vault.items = [];
  if (h.vault.gems > 0 && h.vault.gemsLockedEpoch > 0 && (Date.now() - h.vault.gemsLockedEpoch) >= SEVEN_DAYS_MS) {
    h.vault.dulledGems = (h.vault.dulledGems || 0) + h.vault.gems;
    h.vault.gems = 0;
