String buildHeroChunkB() {
    return buildHeroChunkB1() + "\n" + buildHeroChunkB2() + "\n" + buildHeroChunkB3()
}

String buildHeroChunkB1() {
    return '''
var QUEST_GATHER_FLAVORS = [
  "To fortify our domain's border in {area}, {giver} urgently requests {qty} {item}.",
  "{giver} has posted a Royal Writ: recover {qty} {item} from the monsters of {area}.",
  "Our Alchemists need {qty} {item} from {area} to counter the Shadow Covenant's blight."
];
var QUEST_KILL_FLAVORS = [
  "War-bands of {item} in {area} are raiding supply lines! Slay {qty} of them for {giver}.",
  "{giver} reports that {item} packs are massing in {area}. Exterminate {qty} to raise Stability!",
  "By order of the High Court: hunt down {qty} {item} in {area} so citizens can travel safely."
];

function generateSingleBoardQuest(h, targetAreaId, forceType) {
  var aId = targetAreaId || Math.max(1, Math.min(22, Math.floor(Math.random() * (h.unlockedArea || 1)) + 1));
  var area = AREAS[aId - 1] || AREAS[0];
  var curTier = (h.areaQuestTier && h.areaQuestTier[aId]) ? h.areaQuestTier[aId] : 0;
  var nextTier = Math.min(10, curTier + 1);
  var qType = forceType || (Math.random() < 0.50 ? "kill" : "gather");

  if (qType === "kill") {
    var mobObj = area.enemies[Math.floor(Math.random() * area.enemies.length)] || area.enemies[0];
    var reqKills = 4 + Math.min(6, nextTier) + Math.floor(Math.random() * 3);
    var kFlav = QUEST_KILL_FLAVORS[Math.floor(Math.random() * QUEST_KILL_FLAVORS.length)];
    var kDesc = kFlav.replace("{qty}", reqKills).replace("{item}", mobObj.icon + " " + mobObj.name).replace("{area}", area.name).replace("{giver}", area.questGiver);
    return {
      id: "tq_" + Date.now() + "_" + Math.floor(Math.random() * 9999),
      qType: "kill",
      areaId: aId, areaName: area.name, giver: area.questGiver, giverIcon: area.questGiverIcon,
      tier: nextTier, isBossUnlockQuest: (curTier < 10),
      targetMob: mobObj.name, targetMobIcon: mobObj.icon, progress: 0, reqQty: reqKills,
      matName: mobObj.name, matIcon: mobObj.icon,
      accepted: false, desc: kDesc,
      rewardGold: Math.round(aId * reqKills * 45 * (1 + Math.min(5, nextTier) * 0.20)),
      rewardXp: Math.round(aId * reqKills * 38 * (1 + Math.min(5, nextTier) * 0.20)),
      rewardStability: 4 + Math.min(6, nextTier),
      rewardGems: (nextTier >= 10 ? 1 : 0)
    };
  } else {
    var dropObj = area.drops[(nextTier - 1) % area.drops.length] || area.drops[0];
    var reqQty = 3 + Math.min(5, nextTier) + Math.floor(Math.random() * 2);
    var flavorTemplate = QUEST_GATHER_FLAVORS[Math.floor(Math.random() * QUEST_GATHER_FLAVORS.length)];
    var descText = flavorTemplate.replace("{qty}", reqQty).replace("{item}", dropObj.icon + " " + dropObj.name).replace("{area}", area.name).replace("{giver}", area.questGiver);
    return {
      id: "tq_" + Date.now() + "_" + Math.floor(Math.random() * 9999),
      qType: "gather",
      areaId: aId, areaName: area.name, giver: area.questGiver, giverIcon: area.questGiverIcon,
      tier: nextTier, isBossUnlockQuest: (curTier < 10),
      matName: dropObj.name, matIcon: dropObj.icon, reqQty: reqQty, progress: 0,
      accepted: false, desc: descText,
      rewardGold: Math.round(aId * reqQty * 48 * (1 + Math.min(5, nextTier) * 0.20)),
      rewardXp: Math.round(aId * reqQty * 40 * (1 + Math.min(5, nextTier) * 0.20)),
      rewardStability: 4 + Math.min(6, nextTier),
      rewardGems: (nextTier >= 10 ? 1 : 0)
    };
  }
}

function generateTownBoardQuests(h) {
  var list = [];
  var maxA = h.unlockedArea || 1;
  list.push(generateSingleBoardQuest(h, maxA, "kill"));
  list.push(generateSingleBoardQuest(h, maxA, "gather"));
  while (list.length < 4) {
    var randA = Math.max(1, Math.min(22, Math.floor(Math.random() * maxA) + 1));
    list.push(generateSingleBoardQuest(h, randA, null));
  }
  return list;
}

function getBoardQuestProgress(q) {
  if (!q || !hero) return 0;
  if (q.qType === "kill") return q.progress || 0;
  return hero.materials[q.matName] || 0;
}

function toggleWarrantsStripCollapse() {
  if (!hero) return;
  hero.warrantsCollapsed = !hero.warrantsCollapsed;
  renderGameScreen();
}

function openQuestAcceptModal(qIdx) {
  ensureHeroV3Fields(hero);
  var q = hero.boardQuests[qIdx];
  if (!q) return;
  showPopupModal(
    '<div style="margin-bottom:6px;">' + renderEntityAvatar(q.giver, q.giverIcon, 60, false) + '</div>' +
    '<div style="font-size:18px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;">📋 Royal Warrant Parley: ' + escapeHtml(q.giver) + '</div>' +
    '<div style="font-size:12px;color:#7dd3fc;margin-bottom:8px;">Region: <b>' + escapeHtml(q.areaName) + ' (Warrant Tier ' + q.tier + ' / 10)</b></div>' +
    '<div style="background:#0b0811;border:1px solid #c5a059;border-radius:4px;padding:12px;margin-bottom:10px;text-align:left;font-size:13px;line-height:1.6;color:#e5dec9;">' +
      '&ldquo;' + escapeHtml(q.desc) + '&rdquo;<br><br>' +
      '• <b>Objective:</b> ' + (q.qType === "kill" ? "Slay " : "Recover ") + '<b>' + q.reqQty + 'x ' + q.matIcon + ' ' + escapeHtml(q.matName) + '</b><br>' +
      '• <b>Bounty Payout:</b> <span style="color:#4ade80;">+' + q.rewardXp.toLocaleString() + ' XP, +' + q.rewardGold.toLocaleString() + 'g, +18 Fame &amp; +' + (q.rewardStability || 5) + '% Kingdom Stability</span>' +
    '</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn btn-gold" style="flex:1;" onclick="acceptBoardQuest(' + qIdx + ')">📌 Sign Royal Warrant</button>' +
      '<button class="btn" onclick="closePopupModal()">Decline</button>' +
    '</div>'
  );
}

function acceptBoardQuest(qIdx) {
  ensureHeroV3Fields(hero);
  var q = hero.boardQuests[qIdx];
  if (!q) return;
  q.accepted = true;
  playSfx("coin");
  addLog("📌 Swore Royal Warrant for <b>" + escapeHtml(q.giver) + "</b>: " + q.reqQty + "x " + q.matIcon + " " + escapeHtml(q.matName) + " in " + escapeHtml(q.areaName) + "!");
  closePopupModal();
  queueDeltaSaveHero();
  renderGameScreen();
}

function turnInBoardQuest(qIdx) {
  ensureHeroV3Fields(hero);
  var q = hero.boardQuests[qIdx];
  if (!q) return;
  var prog = getBoardQuestProgress(q);
  if (prog < q.reqQty) {
    showRequirementModal(
      "Warrant Incomplete (" + prog + " / " + q.reqQty + ")", q.matIcon || "📋",
      "You need <b>" + q.reqQty + "x " + escapeHtml(q.matName) + "</b> to claim this Warrant reward (Currently have <b>" + prog + "</b>).",
      (q.qType === "kill" && !q.accepted) ? "⚠️ Make sure you click <b>💬 Parley ➔ 📌 Sign Warrant</b> first so your kills are tracked!" : ("Patrol <b>" + escapeHtml(q.areaName) + "</b> in the Realms tab to finish collecting!"),
      ""
    );
    return;
  }
  if (q.qType !== "kill") {
    hero.materials[q.matName] = Math.max(0, (hero.materials[q.matName] || 0) - q.reqQty);
  }
  var st = getHeroStats();
  var gWon = Math.round(q.rewardGold * st.goldBonusMult);
  var xpWon = Math.round(q.rewardXp * (serverData.xpMult || 1));
  hero.gold += gWon;
  hero.xp += xpWon;
  addHeroFame(18);
  var curT = hero.areaQuestTier[q.areaId] || 0;
  var newT = Math.min(10, curT + 1);
  hero.areaQuestTier[q.areaId] = newT;
  if (newT === 10) hero.gems = (hero.gems || 0) + 1;
  if (hero.guild && hero.guild.founded) {
    hero.guild.stability = Math.min(100, (hero.guild.stability || 75) + (q.rewardStability || 5));
  }

  var nextType = (q.qType === "kill") ? "gather" : "kill";
  hero.boardQuests[qIdx] = generateSingleBoardQuest(hero, q.areaId, nextType);
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 35);
  var msg = "🏆📜 <b>ROYAL WARRANT COMPLETED (" + escapeHtml(q.areaName) + " Tier " + newT + "/10)!</b><br>" +
    "• <b>Rewards:</b> +" + xpWon.toLocaleString() + " XP, +" + gWon.toLocaleString() + " Gold &amp; +18 Court Fame" +
    (newT === 10 ? " &amp; <b>+1💎 Dragon Gem</b>!" : "!") +
    (newT >= 10 ? "<br>🐉 <b style='color:#4ade80;'>ZONE BOSS WARRANT UNLOCKED (10/10)!</b> You may now confront the Region Boss in the Realms tab!" : "");
  addLog(msg);
  checkLevelUp();
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("🏆 Warrant Claimed (Tier " + newT + "/10)!", q.giverIcon || "📋", q.giver, "#4ade80", msg, null);
}

// ============================================================================
// HUNTSMAN'S TROPHY EXCHANGE & WYRM-BRAZIER (UNLIMITED SURPLUS TROPHY SINK!)
// ============================================================================
function openHuntsmanTrophyExchangeModal() {
  ensureHeroV3Fields(hero);
  var totMats = getTotalMaterialsCount();
  var lv = Math.max(1, hero.level || 1);
  var gold10 = 320 + (lv * 75);
  showPopupModal(
    '<div style="margin-bottom:6px;">' + renderEntityAvatar("Master Huntsman Kraven", "🏹🔥", 62, false) + '</div>' +
    '<div style="font-size:19px;font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;">🏹🔥 The Huntsman&apos;s Trophy Exchange &amp; Wyrm-Brazier</div>' +
    '<div style="font-size:12px;color:#86efac;margin:4px 0 8px 0;">📦 <b>Monster Trophies in Your Pouch: <span style="color:#fde047;font-size:14px;">' + totMats + ' Trophies</span></b> • 😰 Stress: <b>' + (hero.stress || 0) + '%</b> • 💎 Gems: <b>' + (hero.gems || 0) + '</b></div>' +
    '<div class="lore-subtitle-box">Have dozens of surplus Monster Trophies piling up from patrols? Master Huntsman Kraven trades bulk trophy bundles with <b>no daily cap and 0⚡ Quest cost</b>—burning bones and hides in the Wyrm-Brazier for calm nerves, Kingdom materials, Reliquary Chests, or crystallized Dragon Gems!</div>' +
    '<div style="display:flex;flex-direction:column;gap:8px;text-align:left;">' +
      '<div class="item-row" style="border-color:#4ade80;">' +
        '<div style="flex:1;"><b style="color:#86efac;font-family:Cinzel,serif;">🔥 I. Pyre of Calm &amp; Stronghold Tithe (Cost: 10 Trophies)</b>' +
        '<div style="font-size:11.5px;color:#e5dec9;">Burn 10 Trophies in purifying sage: <b style="color:#4ade80;">-' + Math.min(30, hero.stress || 30) + '% Stress (-30% Max)</b>, <b style="color:#fbbf24;">+' + gold10.toLocaleString() + 'g</b>, <b>+25 Court Fame</b> &amp; <b>+15🪵 Timber / +15🪨 Stone / +10⛏️ Iron</b>!</div></div>' +
        '<button class="btn ' + (totMats >= 10 ? 'btn-emerald' : 'btn-locked') + '" onclick="redeemTrophyExchangeTier(10)">🔥 Burn 10 (' + totMats + '/10)</button>' +
      '</div>' +
      '<div class="item-row" style="border-color:#38bdf8;">' +
        '<div style="flex:1;"><b style="color:#7dd3fc;font-family:Cinzel,serif;">🎁 II. Huntsman&apos;s Masterwork Reliquary Chest (Cost: 15 Trophies)</b>' +
        '<div style="font-size:11.5px;color:#e5dec9;">Trade 15 Trophies for <b>1x Rare–Mythic Equipment Piece (Lv ' + (lv + 1) + ')</b>, <b>+2🧪 Healing Potions</b> &amp; <b>+1💣 Dwarven Fire-Bomb</b>!</div></div>' +
        '<button class="btn ' + (totMats >= 15 && hero.inventory.length < 30 ? 'btn-sky' : 'btn-locked') + '" onclick="redeemTrophyExchangeTier(15)">🎁 Trade 15 (' + totMats + '/15)</button>' +
      '</div>' +
      '<div class="item-row" style="border-color:#fde047;background:#1a1209;">' +
        '<div style="flex:1;"><b style="color:#fde047;font-family:Cinzel,serif;">💎 III. Wyrm-Heart Crucible Offering (Cost: 30 Trophies)</b>' +
        '<div style="font-size:11.5px;color:#e5dec9;">Smelt 30 Trophies in the dragon-crucible for <b style="color:#fde047;">+1💎 Guaranteed Dragon Gem</b>, <b style="color:#4ade80;">+1 Permanent Hero Stat Point</b> &amp; <b>+40🪵 / +40🪨 / +25⛏️</b>!</div></div>' +
        '<button class="btn ' + (totMats >= 30 ? 'btn-shine' : 'btn-locked') + '" onclick="redeemTrophyExchangeTier(30)">💎 Smelt 30 (' + totMats + '/30)</button>' +
      '</div>' +
    '</div>' +
    '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Close Trophy Exchange</button>'
  );
}

function redeemTrophyExchangeTier(costMats) {
  ensureHeroV3Fields(hero);
  var totMats = getTotalMaterialsCount();
  if (totMats < costMats) {
    showRequirementModal(
      "Need " + costMats + " Monster Trophies (Have " + totMats + ")", "📦🏹",
      "This Huntsman Trophy Exchange bundle requires <b>" + costMats + " Monster Trophies</b>, and you currently hold <b>" + totMats + " Trophies</b>.",
      "Patrol any unlocked region in the <b>🗺️ Realms</b> tab to gather more Monster Trophies!",
      ""
    );
    return;
  }
  if (costMats === 15 && hero.inventory.length >= 30) {
    showGothicToast("⚠️ Your Backpack is full (30/30)! Salvage or sell an unequipped item first.");
    return;
  }
  consumeAnyMaterials(costMats);
  var lv = Math.max(1, hero.level || 1);
  var remMats = getTotalMaterialsCount();
  var outMsg = "";

  if (costMats === 10) {
    var gGain = 320 + (lv * 75);
    hero.gold += gGain;
    hero.stress = Math.max(0, (hero.stress || 0) - 30);
    addHeroFame(25);
    hero.guild.timber = (hero.guild.timber || 0) + 15;
    hero.guild.stone  = (hero.guild.stone || 0) + 15;
    hero.guild.iron   = (hero.guild.iron || 0) + 10;
    playSfx("magic");
    outMsg = "🔥📦 <b>PYRE OF CALM &amp; STRONGHOLD TITHE (-10 Trophies • " + remMats + " Left):</b><br>• Calmed <b>-30% Stress (Now " + hero.stress + "%)</b><br>• Earned <b>+" + gGain.toLocaleString() + " Gold &amp; +25 Court Fame</b><br>• Stocked <b>+15🪵 Timber, +15🪨 Stone &amp; +10⛏️ Iron</b>!";
  } else if (costMats === 15) {
    var chestItm = sanitizeGearItem(generateRandomItem(lv + 1, 2, 5), "weapon");
    hero.inventory.push(chestItm);
    hero.potions = (hero.potions || 0) + 2;
    hero.belt.firebomb = Math.min(5, (hero.belt.firebomb || 0) + 1);
    playSfx("levelup");
    outMsg = "🎁📦 <b>HUNTSMAN'S RELIQUARY CHEST UNSEALED (-15 Trophies • " + remMats + " Left):</b><br>• Forged Gear: <b>" + formatItemStats(chestItm, true, false) + "</b><br>• Supplies: <b>+2🧪 Healing Potions (Have " + hero.potions + ") &amp; +1💣 Fire-Bomb (Have " + hero.belt.firebomb + "/5)</b>!";
  } else {
    hero.gems = (hero.gems || 0) + 1;
    hero.statPoints = (hero.statPoints || 0) + 1;
    hero.guild.timber = (hero.guild.timber || 0) + 40;
    hero.guild.stone  = (hero.guild.stone || 0) + 40;
    hero.guild.iron   = (hero.guild.iron || 0) + 25;
    playSfx("levelup");
    if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 42);
    outMsg = "💎🔥 <b>WYRM-HEART CRUCIBLE OFFERING (-30 Trophies • " + remMats + " Left):</b><br>• Crystallized <b style='color:#fde047;'>+1💎 Dragon Gem (Now " + hero.gems + "💎)</b><br>• Granted <b style='color:#4ade80;'>+1 Permanent Stat Point (Spend in ⚜️ Hero Sheet!)</b><br>• Stocked <b>+40🪵 Timber, +40🪨 Stone &amp; +25⛏️ Iron</b>!";
  }
  addLog(outMsg);
  queueSaveHero();
  renderGameScreen();
  openHuntsmanTrophyExchangeModal();
  showGothicToast("✅ Exchanged " + costMats + " Trophies (" + remMats + " Trophies Remaining)!");
}

function rerollTownBoard() {
  ensureHeroV3Fields(hero);
  var nowMs = Date.now();
  var elapsed = nowMs - (hero.lastBoardRerollEpoch || 0);
  if (elapsed < SIX_HOURS_MS) {
    var remSec = Math.ceil((SIX_HOURS_MS - elapsed) / 1000);
    showRequirementModal("Warrant Couriers En Route", "📋⏳", "New Royal Warrants are posted every <b>6 hours</b>. Time remaining: <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b>.", "Complete your current Warrants to advance your Zone Boss tier automatically!", "");
    return;
  }
  hero.lastBoardRerollEpoch = nowMs;
  hero.boardQuests = generateTownBoardQuests(hero);
  playSfx("coin");
  addLog("📋 Royal Heralds posted 4 fresh Warrants on the Town Board!");
  queueSaveHero();
  renderGameScreen();
}

function pinCoOpWarrant(qIdx) {
  ensureHeroV3Fields(hero);
  var q = hero.boardQuests[qIdx];
  if (!q) return;
  q.accepted = true;
  var sw = {
    id: q.id, ownerSlot: activeSlotKey, ownerHero: hero.name,
    qType: q.qType, areaId: q.areaId, areaName: q.areaName,
    giver: q.giver, giverIcon: q.giverIcon, tier: q.tier,
    matName: q.matName, matIcon: q.matIcon,
    progress: getBoardQuestProgress(q), reqQty: q.reqQty,
    rewardGold: q.rewardGold, rewardXp: q.rewardXp
  };
  serverData.sharedWarrant = sw;
  playSfx("coin");
  addLog("🤝📌 <b>Co-Op Warrant Pinned:</b> Shared <b>" + escapeHtml(q.matName) + " (" + sw.progress + "/" + sw.reqQty + ")</b> across all Hero Slots on your Hub!");
  saveCurrentHero(null, false, null, { sharedWarrantUpdate: sw });
  renderGameScreen();
}

function assistCoOpWarrant() {
  ensureHeroV3Fields(hero);
  var sw = serverData.sharedWarrant;
  if (!sw || !sw.matName) return;
  if (activeSlotKey === sw.ownerSlot) {
    showRequirementModal(
      "Switch to Another Hero Slot to Assist!", "🤝📌",
      "You pinned this Co-Op Warrant from <b>" + escapeHtml(hero.name) + " (" + activeSlotKey.toUpperCase() + ")</b>! Cross-Slot Co-Op Assists are designed for your <b>other Hero Slots</b> to help complete this contract.",
      "Tap <b>⚜️ Heroes</b> in the top bar, load one of your other character slots, and click <b>🤝 Assist Co-Op Warrant</b> from their Warrant Board!",
      ""
    );
    return;
  }
  if (hero.quests < 2) {
    showRequirementModal("Need 2⚡ Quests for Co-Op Warrant Assist", "🤝⚡", "Dispatching a Co-Op Warrant Strike to assist <b>" + escapeHtml(sw.ownerHero) + "</b> requires <b>2⚡ Quests</b> (You have " + hero.quests + "⚡).", "Wait for the 45m stamina tick or Quick-Rest at the Inn!", "");
    return;
  }
  hero.quests -= 2;
  var addProg = 2;
  if (sw.qType !== "kill" && (hero.materials[sw.matName] || 0) > 0) {
    var takeM = Math.min(hero.materials[sw.matName], sw.reqQty - (sw.progress || 0));
    if (takeM > 0) {
      hero.materials[sw.matName] -= takeM;
      addProg = Math.max(2, takeM);
    }
  }
  sw.progress = Math.min(sw.reqQty, (sw.progress || 0) + addProg);

  var splitGold = Math.round((sw.rewardGold || 200) * 0.45);
  var splitXp   = Math.round((sw.rewardXp || 180) * 0.45);
  hero.gold += splitGold;
  hero.xp += splitXp;
  addHeroFame(12);

  var done = (sw.progress >= sw.reqQty);
  playSfx("levelup");
  var cMsg = "🤝📜 <b>CROSS-SLOT CO-OP WARRANT ASSIST (-2⚡):</b><br>Contributed <b>+" + addProg + " progress</b> toward <b>" + sw.matIcon + " " + escapeHtml(sw.matName) + " (" + sw.progress + "/" + sw.reqQty + ")</b>!<br>• <b>Your Split Share:</b> +" + splitGold.toLocaleString() + "g, +" + splitXp.toLocaleString() + " XP &amp; +12 Fame" +
    (done && sw.ownerSlot !== activeSlotKey ? ("<br>• <b>Owner Share Dispatched:</b> Sent +" + splitGold.toLocaleString() + "g &amp; +" + splitXp.toLocaleString() + " XP to <b>" + escapeHtml(sw.ownerHero) + "</b>!") : "");
  addLog(cMsg);
  checkLevelUp();
  var extra = done ? { clearSharedWarrant: true } : { sharedWarrantUpdate: sw };
  if (done && sw.ownerSlot && sw.ownerSlot !== activeSlotKey) {
    extra.mailTransfer = { targetSlot: sw.ownerSlot, gold: splitGold, xp: splitXp, fame: 12 };
  }
  if (done) serverData.sharedWarrant = null;
  saveCurrentHero("🤝 " + hero.name + " assisted Co-Op Warrant '" + sw.matName + "' (" + sw.progress + "/" + sw.reqQty + ")!", false, null, extra);
  renderGameScreen();
  showOutcomeModal(done ? "🤝 Co-Op Warrant Completed!" : "🤝 Co-Op Progress Added!", "🤝📜", hero.name, "#4ade80", cMsg, null);
}

function sabotageBossSupplyCamp() {
  ensureHeroV3Fields(hero);
  if ((hero.sabotagesUsedToday || 0) >= MAX_DAILY_SABOTAGES) {
    showRequirementModal("Pre-Boss Sabotage Daily Limit Reached (2/2 Today)", "💣⏳", "You have already conducted <b>2 Pre-Boss Sabotage missions today</b>.", "Return after midnight rollover (or use Admin Reset) for fresh sabotage operations!", "");
    return;
  }
  if (hero.bossSabotaged) {
    showGothicToast("💣 Boss supply camp is already sabotaged (-15% Boss Starting HP ready)!");
    return;
  }
  if (hero.quests < 2) {
    showRequirementModal("Need 2⚡ Quests for Pre-Boss Sabotage", "💣⛺", "Infiltrating the Area Boss's war-camp to spike their supply casks requires <b>2⚡ Quests</b> (You have " + hero.quests + "⚡).", "Wait for the 45m stamina tick or Quick-Rest at the Inn!", "");
    return;
  }
  hero.quests -= 2;
  hero.sabotagesUsedToday = (hero.sabotagesUsedToday || 0) + 1;
  hero.bossSabotaged = true;
  playSfx("crit");
  var sMsg = "💣⛺ <b>PRE-BOSS SABOTAGE MISSION COMPLETE (" + hero.sabotagesUsedToday + "/" + MAX_DAILY_SABOTAGES + " Today • -2⚡):</b><br>Under cover of darkness, you slipped past the sentries and spiked the regional overlord's supply casks with alchemical pitch! <b>Your next Boss encounter will start with -15% Max HP!</b>";
  addLog(sMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("💣 Boss Supply Camp Sabotaged (-15% HP)!", "💣⛺", hero.name, "#4ade80", sMsg, null);
}

function deliverUnmakingAnchorWarrant() {
  ensureHeroV3Fields(hero);
  var unm = serverData.unmaking || {};
  if (!unm.active) {
    showGothicToast("🌌 The Unmaking is currently Dormant—no Aether-Anchors needed today!");
    return;
  }
  if (hero.quests < 2 || getTotalMaterialsCount() < 3) {
    showRequirementModal(
      "Need 2⚡ Quests & 3 Monster Trophies for Anchor Ward", "⏳⚓",
      "Forging and delivering an <b>Aether-Anchor</b> to delay <b>The Unmaking</b> by +6 Hours requires <b style='color:#fbbf24;'>2⚡ Quests</b> (Have " + hero.quests + "⚡) and <b style='color:#fbbf24;'>3 Monster Trophies</b> (Have " + getTotalMaterialsCount() + ").",
      "Even Level 1 heroes can patrol Area 1 to gather 3 Monster Trophies and earn +1💎 Dragon Gem!",
      ""
    );
    return;
  }
  hero.quests -= 2;
  consumeAnyMaterials(3);
  var gGain = 120 + hero.level * 35;
  var xpGain = 100 + hero.level * 30;
  hero.gold += gGain;
  hero.xp += xpGain;
  addHeroFame(25);
  hero.gems = (hero.gems || 0) + 1;
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 30);
  var uMsg = "⏳⚓ <b style='color:#4ade80;'>AETHER-ANCHOR DELIVERED TO CITADEL!</b><br>Your ward pushed back <b>The Unmaking Clock by +6 Hours</b> (+1 Anchor)!<br>• <b>Salvation Reward:</b> +" + xpGain.toLocaleString() + " XP, +" + gGain.toLocaleString() + "g, +25 Fame &amp; <b>+1💎 Dragon Gem</b>!";
  addLog(uMsg);
  checkLevelUp();
  saveCurrentHero("⏳ " + hero.name + " anchored the timeline against The Unmaking (+6h Delay)!", false, null, { unmakingAnchors: 1 });
  renderGameScreen();
  showOutcomeModal("⏳ Timeline Anchored (+6h)!", "⏳⚓", hero.name, "#4ade80", uMsg, null);
}

function toRomanNumeral(num) {
  var lookup = {M:1000,CM:900,D:500,CD:400,C:100,XC:90,L:50,XL:40,X:10,IX:9,V:5,IV:4,I:1}, roman = '', i;
  for (i in lookup) { while (num >= lookup[i]) { roman += i; num -= lookup[i]; } }
  return roman || "I";
}

function prestigeHeroPersonal() {
  ensureHeroV3Fields(hero);
  if (hero.level < 100) {
    showRequirementModal(
      "Level 100+ Required for Rite of Eternal Ascendancy", "👑⏳",
      "Personal Prestige (re-ascending as <b>" + escapeHtml(hero.baseLineageName || hero.name) + " " + toRomanNumeral((hero.prestigeRank || 0) + 2) + "</b>) requires reaching at least <b style='color:#fbbf24;'>Level 100</b> (Currently Lv " + hero.level + ").",
      "Conquer the higher realms or climb the Abyssal Spire to reach Level 100!",
      ""
    );
    return;
  }
  var oldLv = hero.level;
  var baseN = hero.baseLineageName || hero.name;
  hero.prestigeRank = (hero.prestigeRank || 0) + 1;
  pushBuffToFifo("buff_prestige", hero);
  var nextRom = toRomanNumeral(hero.prestigeRank + 1);
  if (!hero.ancestors) hero.ancestors = [];
  hero.ancestors.unshift({ name: hero.name, level: oldLv, title: hero.nobleRank || "Regent", calling: hero.calling, date: getTodayDateStr() });
  if (hero.ancestors.length > 10) hero.ancestors.pop();
  hero.name = baseN + " " + nextRom;
  hero.level = 1;
  hero.xp = 0;
  hero.xpNext = getXpRequiredForLevel(1);
  hero.gems = (hero.gems || 0) + 5;
  hero.skillPoints = (hero.skillPoints || 0) + 3;
  var muts = [
    { id: "wyrm_blood", name: "🐉 Dragon-Blooded Scales", desc: "+8% ATK & +8% DEF" },
    { id: "night_eyes", name: "🌑 Night-Seer Eyes", desc: "+6% Hit & +6% Dodge" },
    { id: "titan_marrow", name: "🗿 Titan-Marrow Bones", desc: "+6% Parry & +60 Max HP" },
    { id: "vamp_veins", name: "🩸 Crimson Sovereign Veins", desc: "+6% Lifesteal" }
  ];
  hero.lineageMutation = muts[(hero.prestigeRank - 1) % muts.length];
  pushBuffToFifo("buff_mutation", hero);
  if (hero.lineageMutation.id === "titan_marrow") hero.maxHp += 60;
  syncHeroVitalityMaxHp(hero);
  hero.hp = hero.maxHp;
  hero.mp = hero.maxMp;
  recordMemoirMilestone("Completed the Rite of Eternal Prestige and ascended as " + hero.name + " (★Prestige " + hero.prestigeRank + ").");
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 55);
  var pMsg = "👑🌟 <b style='color:#fde047;'>RITE OF ETERNAL PRESTIGE COMPLETE!</b><br>Reborn as <b>" + escapeHtml(hero.name) + " (★Prestige " + hero.prestigeRank + " ➔ +" + (hero.prestigeRank * 3) + "% Permanent All Stats)</b>!<br>• <b>Bloodline Mutation Awakened:</b> " + hero.lineageMutation.name + " (" + hero.lineageMutation.desc + ")<br>• <b>Ascension Tribute:</b> +5💎 Dragon Gems &amp; +3 Skill Points!";
  addLog(pMsg);
  saveCurrentHero("👑 " + hero.name + " ascended to ★Prestige Rank " + hero.prestigeRank + "!", false, null);
  renderGameScreen();
  showOutcomeModal("👑 Ascended as " + hero.name + "!", "👑🌟", hero.name, "#fde047", pMsg, null);
}

function prestigeHeroHeirSuccession(childIdx) {
  ensureHeroV3Fields(hero);
  if (hero.level < 50) {
    showRequirementModal("Hero Level 50+ Required for Royal Abdication", "👑👶", "Crowning a Dynasty Heir to succeed your throne requires your current ruler to reach at least <b>Level 50</b> (Currently Lv " + hero.level + ").", "Continue conquering realms until Level 50, then return to pass the crown!", "");
    return;
  }
  var ch = (hero.children && hero.children[childIdx]) ? hero.children[childIdx] : null;
  if (!ch) return;
  var oldName = hero.name;
  var oldLv = hero.level;
  hero.prestigeRank = (hero.prestigeRank || 0) + 1;
  pushBuffToFifo("buff_prestige", hero);
  if (!hero.ancestors) hero.ancestors = [];
  hero.ancestors.unshift({ name: oldName, level: oldLv, title: hero.nobleRank || "Sovereign", calling: hero.calling, date: getTodayDateStr() });
  if (hero.ancestors.length > 10) hero.ancestors.pop();
  hero.name = ch.name;
  hero.baseLineageName = ch.name;
  hero.level = Math.max(1, ch.level || 1);
  hero.xp = 0;
  hero.xpNext = getXpRequiredForLevel(hero.level);
  hero.guts += Math.max(4, Math.round((ch.atk || 20) * 0.18));
  hero.wits += 4;
  hero.charm += 4;
  hero.gems = (hero.gems || 0) + 3;
  hero.children.splice(childIdx, 1);
  hero.activeChildIdx = -1;
  syncHeroVitalityMaxHp(hero);
  hero.hp = hero.maxHp;
  hero.mp = hero.maxMp;
  recordMemoirMilestone(oldName + " abdicated the Dragon Throne, crowning Royal Heir " + hero.name + "!");
  playSfx("levelup");
  var sMsg = "👑👶 <b style='color:#fde047;'>DYNASTY SUCCESSION COMPLETE!</b><br><b>" + escapeHtml(oldName) + "</b> passed the Dragon Crown to <b>" + escapeHtml(hero.name) + " (★Prestige " + hero.prestigeRank + " • +" + (hero.prestigeRank * 3) + "% All Stats &amp; +3💎 Gems)</b>!";
  addLog(sMsg);
  saveCurrentHero("👑 " + oldName + " passed the Dragon Crown to Royal Heir " + hero.name + "!", false, null);
  renderGameScreen();
  showOutcomeModal("👑 Hail Sovereign " + hero.name + "!", "👑👶", hero.name, "#fde047", sMsg, "courting");
}
'''
}

String buildHeroChunkB2() {
    return '''
function awakenHeroCalling() {
  ensureHeroV3Fields(hero);
  if (hero.awakened) { showGothicToast("✅ Your Calling is already Awakened!"); return; }
  var awk = CLASS_AWAKENINGS[hero.calling] || { title: "Grandmaster", desc: "" };
  if (hero.level < 20 || hero.gold < 3500 || (hero.gems || 0) < 6) {
    showRequirementModal(
      "Cannot Awaken Calling Yet", "🌟⚔️",
      "Tier I Class Awakening (<b>" + escapeHtml(awk.title) + "</b>) requires:<br>• <b>Hero Level 20+</b> (Currently Lv " + hero.level + ")<br>• <b>3,500 Gold</b> (Have " + hero.gold.toLocaleString() + "g)<br>• <b>6💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎)",
      "Defeat Zone Bosses, complete Tier 10 Warrants, or smelt 30 Trophies at the Huntsman's Exchange to earn Dragon Gems!",
      ""
    );
    return;
  }
  hero.gold -= 3500;
  hero.gems -= 6;
  hero.awakened = true;
  hero.awakenedTitle = awk.title;
  hero.maxHp += 55;
  hero.maxMp += 30;
  syncHeroVitalityMaxHp(hero);
  hero.hp = hero.maxHp;
  hero.mp = hero.maxMp;
  recordMemoirMilestone("Awakened Tier I Calling as a " + awk.title + "!");
  playSfx("levelup");
  var aMsg = "🌟⚔️ <b style='color:#4ade80;'>TIER I CALLING AWAKENED: " + escapeHtml(awk.title.toUpperCase()) + "!</b><br>• <b>Passive Mastery:</b> " + escapeHtml(awk.desc) + "<br>• <b>Vitals Surge:</b> +55 Max HP &amp; +30 Max MP!";
  addLog(aMsg);
  saveCurrentHero("🌟 " + hero.name + " awakened as a " + awk.title + "!", false, null);
  renderGameScreen();
  showOutcomeModal("🌟 Calling Awakened!", "🌟⚔️", hero.name, "#4ade80", aMsg, null);
}

function ascendMythicCalling() {
  ensureHeroV3Fields(hero);
  if (hero.mythicAscended) { showGothicToast("✅ You have already achieved Tier II Mythic Ascension!"); return; }
  var awk = CLASS_AWAKENINGS[hero.calling] || { mythicTitle: "Mythic Sovereign" };
  if (!hero.awakened || hero.level < 75 || hero.gold < 45000 || (hero.gems || 0) < 15) {
    showRequirementModal(
      "Cannot Ascend to Mythic Tier II Yet", "☄️👑",
      "Tier II Mythic Ascension (<b>" + escapeHtml(awk.mythicTitle) + "</b>) requires:<br>• <b>Tier I Awakening Completed</b><br>• <b>Hero Level 75+</b> (Currently Lv " + hero.level + ")<br>• <b>45,000 Gold</b> (Have " + hero.gold.toLocaleString() + "g) &amp; <b>15💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎)",
      "Advance through the mid-game realms and Spire floors to gather 15 Dragon Gems!",
      ""
    );
    return;
  }
  hero.gold -= 45000;
  hero.gems -= 15;
  hero.mythicAscended = true;
  hero.mythicTitle = awk.mythicTitle;
  hero.maxHp += 180;
  hero.maxMp += 80;
  syncHeroVitalityMaxHp(hero);
  hero.hp = hero.maxHp;
  hero.mp = hero.maxMp;
  recordMemoirMilestone("Achieved Tier II Mythic Ascension as " + awk.mythicTitle + "!");
  playSfx("levelup");
  var mMsg = "☄️👑 <b style='color:#c084fc;'>TIER II MYTHIC ASCENSION: " + escapeHtml(awk.mythicTitle.toUpperCase()) + "!</b><br>Granted <b>+25% All Stats, +180 Max HP &amp; +80 Max MP</b>!";
  addLog(mMsg);
  saveCurrentHero("☄️ " + hero.name + " ascended to Mythic Tier II (" + awk.mythicTitle + ")!", false, null);
  renderGameScreen();
  showOutcomeModal("☄️ Mythic Ascension Complete!", "☄️👑", hero.name, "#c084fc", mMsg, null);
}

function unlockEclipseDualClass() {
  ensureHeroV3Fields(hero);
  if (hero.hybridClass) { showGothicToast("✅ Dual-Class Hybridization already active (" + hero.hybridClass + ")!"); return; }
  if (!hero.mythicAscended || hero.level < 125 || (hero.gems || 0) < 20) {
    showRequirementModal(
      "Cannot Unlock Tier III Eclipse Dual-Class Yet", "🌑⚔️",
      "Tier III Eclipse Dual-Classing requires:<br>• <b>Tier II Mythic Ascension Completed</b><br>• <b>Hero Level 125+</b> (Currently Lv " + hero.level + ")<br>• <b>20💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎)",
      "Conquer the late-game realms to reach Level 125!",
      ""
    );
    return;
  }
  var opts = Object.keys(CALLINGS).filter(function(k) { return k !== hero.calling; }).map(function(k) {
    return '<button class="btn btn-gold" style="width:100%;margin-top:6px;" onclick="applySelectedHybridClass(&#39;' + k + '&#39;)">' + CALLINGS[k].icon + ' Hybridize with ' + k + ' (+15% All Stats &amp; +220 HP)</button>';
  }).join('');
  showPopupModal(
    '<div style="font-size:19px;font-weight:900;color:#fde047;font-family:Cinzel,serif;margin-bottom:6px;">🌑 Select Secondary Eclipse Calling (-20💎 • Have ' + (hero.gems || 0) + '💎)</div>' +
    opts +
    '<button class="btn" style="width:100%;margin-top:10px;" onclick="openHeroSheetModal()">Cancel</button>'
  );
}

function applySelectedHybridClass(secClass) {
  if (!CALLINGS[secClass] || (hero.gems || 0) < 20) return;
  hero.gems -= 20;
  hero.hybridClass = secClass;
  hero.maxHp += 220;
  syncHeroVitalityMaxHp(hero);
  hero.hp = hero.maxHp;
  playSfx("levelup");
  var hMsg = "🌑⚔️ <b style='color:#7dd3fc;'>ECLIPSE DUAL-CLASS UNLOCKED (" + hero.calling + " / " + secClass + ")!</b><br>Granted <b>+15% All Stats &amp; +220 Max HP</b>!";
  addLog(hMsg);
  saveCurrentHero("🌑 " + hero.name + " unlocked Eclipse Dual-Class (" + hero.calling + "/" + secClass + ")!", false, null);
  renderGameScreen();
  showOutcomeModal("🌑 Dual-Class Hybridized!", "🌑⚔️", hero.name, "#7dd3fc", hMsg, null);
}

function isConsortSacrificedForever(candIdOrName) {
  if (!hero || !Array.isArray(hero.sacrificedBrides)) return false;
  return hero.sacrificedBrides.includes(candIdOrName);
}

function selectActiveConsortBlessing(candId) {
  ensureHeroV3Fields(hero);
  if (!Array.isArray(hero.marriedConsorts)) return;
  var found = hero.marriedConsorts.find(function(mc) { return mc.id === candId; });
  if (!found) return;
  hero.spouse = found;
  pushBuffToFifo("buff_consort", hero);
  playSfx("magic");
  addLog("💍👑 Switched Active Consort Blessing to <b>" + found.icon + " " + escapeHtml(found.name) + "</b> (" + escapeHtml(found.blessing) + ")!");
  queueSaveHero();
  if (window.currentTownModal === "courting") openTownFacilityModal("courting");
  renderGameScreen();
}

function courtNobleCandidate(candId, actType) {
  ensureHeroV3Fields(hero);
  var c = COURTING_POOL.find(function(x) { return x.id === candId; });
  if (!c) return;
  if (isConsortSacrificedForever(c.id) || isConsortSacrificedForever(c.name)) {
    showRequirementModal(
      "⚰️ " + c.name + " Was Sacrificed Forever!", "⚰️🩸",
      "You previously sacrificed <b>" + escapeHtml(c.name) + "</b> upon the Obsidian Blood-Price Altar to defy death! Her mortal life was extinguished forever on this character.",
      "A sacrificed Princess cannot be courted or wed again on this character—she may only be courted in another character slot!",
      ""
    );
    return;
  }
  if ((hero.courtingUsedToday || 0) >= MAX_DAILY_COURTING) {
    showRequirementModal("Velvet Chamber Daily Limit Reached (3/3 Today)", "🌹⏳", "You have already performed <b>3 Courting or Romance actions today</b>.", "Return tomorrow (or use Admin Reset) to continue your courtship!", "");
    return;
  }
  if ((hero.nobleIdx || 0) < c.minNobleIdx) {
    showRequirementModal("Higher Noble Title Required", c.icon, "Courting <b>" + escapeHtml(c.name) + "</b> requires the feudal rank of <b>" + NOBLE_RANKS[c.minNobleIdx].title + "+</b>.", "Petition the High Court in the Citadel to advance your rank!", "");
    return;
  }
  if (hero.quests < 4 || (actType === "gift" && hero.gold < c.giftGold)) {
    showRequirementModal("Insufficient Stamina or Gold for Courtship", c.icon, "Requires <b>4⚡ Quests</b> (Have " + hero.quests + "⚡)" + (actType === "gift" ? (" and <b>" + c.giftGold.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g)") : "") + ".", "Rest at the Inn or collect Kingdom Taxes!", "");
    return;
  }
  hero.quests -= 4;
  hero.courtingUsedToday = (hero.courtingUsedToday || 0) + 1;
  if (actType === "gift") hero.gold -= c.giftGold;
  var st = getHeroStats();
  var reqCharmScale = Math.round(16 + (hero.level || 1) * 1.65 + c.minNobleIdx * 14);
  var charmBonus = Math.max(-2, Math.min(8, Math.floor((st.effCharm - reqCharmScale) / 7)));
  var gain = Math.max(8, (actType === "gift" ? 18 : 12) + charmBonus);
  hero.courtingProgress[c.id] = Math.min(100, (hero.courtingProgress[c.id] || 0) + gain);
  addHeroFame(10);
  playSfx("magic");
  var cMsg = "🌹 <b>Velvet Chamber Courtship (" + hero.courtingUsedToday + "/" + MAX_DAILY_COURTING + " Today):</b><br>Your " + (actType === "gift" ? "lavish gift" : "lute serenade") + " raised <b>" + escapeHtml(c.name) + "&apos;s</b> affection by <b>+" + gain + "%</b> to <b>" + hero.courtingProgress[c.id] + "% / 100%</b> (+10 Fame)!<br><i style='font-size:11.5px;color:#fda4af;'>⚠️ Note: Courtship Affection decays by -4% every 45m tick and -12% at midnight unless maintained!</i>";
  addLog(cMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🌹 Affection Raised (" + hero.courtingProgress[c.id] + "%)!", c.icon, c.name, "#f472b6", cMsg, "courting");
}

function marryNobleCandidate(candId) {
  ensureHeroV3Fields(hero);
  var c = COURTING_POOL.find(function(x) { return x.id === candId; });
  if (!c) return;
  if (isConsortSacrificedForever(c.id) || isConsortSacrificedForever(c.name)) {
    showRequirementModal(
      "⚰️ " + c.name + " Was Sacrificed Forever!", "⚰️🩸",
      "<b>" + escapeHtml(c.name) + "</b> perished permanently upon the Blood-Price Altar on this character slot.",
      "She can only be courted or remarried on another character slot!",
      ""
    );
    return;
  }
  var aff = hero.courtingProgress[c.id] || 0;
  var wedCost = c.giftGold * 2;
  if (aff < 100 || hero.gold < wedCost) {
    showRequirementModal("Cannot Wed " + c.name + " Yet", "💍🌹", "Requires <b>100% Courtship Affection</b> (Have " + aff + "%) and <b>" + wedCost.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g) for the Royal Wedding.", "Serenade or gift " + escapeHtml(c.name) + " before her affection decays!", "");
    return;
  }
  hero.gold -= wedCost;
  var newConsort = { id: c.id, name: c.name, icon: c.icon, blessing: c.blessing, bonusGuts: c.bonusGuts, bonusWits: c.bonusWits, bonusCharm: c.bonusCharm, love: 100, diplomacyUntil: 0 };
  if (!Array.isArray(hero.marriedConsorts)) hero.marriedConsorts = [];
  var existingIdx = hero.marriedConsorts.findIndex(function(mc) { return mc.id === c.id; });
  if (existingIdx >= 0) hero.marriedConsorts[existingIdx] = newConsort;
  else hero.marriedConsorts.push(newConsort);
  hero.spouse = newConsort;
  pushBuffToFifo("buff_consort", hero);
  addHeroFame(50);
  recordMemoirMilestone("Wed Royal Consort " + c.name + " in the Grand Cathedral of Valoria.");
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 45);
  var wMsg = "💍👑 <b style='color:#f472b6;'>ROYAL WEDDING CELEBRATED!</b><br>You wed <b>" + c.icon + " " + escapeHtml(c.name) + "</b> (" + escapeHtml(c.blessing) + " &amp; +50 Court Fame)!<br>• <i>If you wed multiple Royal Consorts, only your <b>1 Chosen Active Consort Blessing</b> applies at a time (switch anytime in the Velvet Chamber).</i>";
  addLog(wMsg);
  saveCurrentHero("💍 " + hero.name + " wed Royal Consort " + c.name + "!", false, null);
  renderGameScreen();
  showOutcomeModal("💍 Royal Wedding Sealed!", c.icon, c.name, "#f472b6", wMsg, "courting");
}

function takeWifeOnRoyalDate() {
  ensureHeroV3Fields(hero);
  if (!hero.spouse) return;
  if ((hero.courtingUsedToday || 0) >= MAX_DAILY_COURTING) {
    showRequirementModal("Velvet Chamber Daily Limit (3/3 Today)", "🌹⏳", "You have already completed 3 Courting/Romance actions today.", "Return tomorrow!", "");
    return;
  }
  var cost = Math.max(300, hero.level * 45);
  if (hero.quests < 4 || hero.gold < cost) {
    showRequirementModal("Need 4⚡ Quests & " + cost.toLocaleString() + "g", "🌹🍷", "Taking <b>" + escapeHtml(hero.spouse.name) + "</b> on a Royal Date requires <b>4⚡ Quests</b> (Have " + hero.quests + "⚡) and <b>" + cost.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g).", "Collect taxes or rest at the Inn!", "");
    return;
  }
  hero.quests -= 4;
  hero.gold -= cost;
  hero.courtingUsedToday = (hero.courtingUsedToday || 0) + 1;
  hero.spouse.love = Math.min(100, (hero.spouse.love !== undefined ? hero.spouse.love : 100) + 22);
  if (Array.isArray(hero.marriedConsorts)) {
    hero.marriedConsorts.forEach(function(mc) { if (mc.id === hero.spouse.id) mc.love = hero.spouse.love; });
  }
  hero.stress = Math.max(0, (hero.stress || 0) - 20);
  addHeroFame(15);
  playSfx("levelup");
  var dMsg = "🌹🍷 <b>Royal Moonlight Date (" + hero.courtingUsedToday + "/" + MAX_DAILY_COURTING + " Today):</b><br>Restored <b>" + escapeHtml(hero.spouse.name) + "&apos;s</b> Devotion to <b>" + hero.spouse.love + "% ❤️</b> (-20% Stress &amp; +15 Fame)!";
  addLog(dMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🌹 Marital Devotion Restored!", hero.spouse.icon, hero.spouse.name, "#f472b6", dMsg, "courting");
}

function embarkConsortRomanceQuest() {
  ensureHeroV3Fields(hero);
  if (!hero.spouse) return;
  if ((hero.courtingUsedToday || 0) >= MAX_DAILY_COURTING) {
    showRequirementModal("Velvet Chamber Daily Limit (3/3 Today)", "🗺️⏳", "You have already completed 3 Courting/Romance actions today.", "Return tomorrow!", "");
    return;
  }
  if (hero.quests < 4) {
    showRequirementModal("Need 4⚡ Quests for Romance Quest", "🗺️🌹", "Embarking on a Consort Romance Quest requires 4⚡ Quests (Have " + hero.quests + "⚡).", "Wait for the 45m tick!", "");
    return;
  }
  hero.quests -= 4;
  hero.courtingUsedToday = (hero.courtingUsedToday || 0) + 1;
  hero.spouse.love = Math.min(100, (hero.spouse.love !== undefined ? hero.spouse.love : 100) + 18);
  if (Array.isArray(hero.marriedConsorts)) {
    hero.marriedConsorts.forEach(function(mc) { if (mc.id === hero.spouse.id) mc.love = hero.spouse.love; });
  }
  hero.guts += 1; hero.wits += 1; hero.charm += 1;
  syncHeroVitalityMaxHp(hero);
  playSfx("levelup");
  var rMsg = "🗺️🌹 <b>Consort Romance Quest Complete (" + hero.courtingUsedToday + "/" + MAX_DAILY_COURTING + " Today):</b><br>Adventured alongside <b>" + escapeHtml(hero.spouse.name) + "</b> (+18% ❤️ Devotion &amp; <b>+1 Permanent Guts/Wits/Charm</b>)!";
  addLog(rMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🗺️ Consort Quest Triumph!", hero.spouse.icon, hero.spouse.name, "#4ade80", rMsg, "courting");
}

function dispatchConsortDiplomacy() {
  ensureHeroV3Fields(hero);
  if (!hero.spouse) return;
  if (hero.quests < 3) {
    showRequirementModal("Need 3⚡ Quests for Diplomatic Envoy", "🕊️👑", "Dispatching your Consort to the High Court requires <b>3⚡ Quests</b> (Have " + hero.quests + "⚡).", "Wait for the 45m tick!", "");
    return;
  }
  hero.quests -= 3;
  hero.spouse.diplomacyUntil = Date.now() + TWO_HOURS_MS;
  pushBuffToFifo("buff_diplomacy", hero);
  addHeroFame(22);
  playSfx("magic");
  var eMsg = "🕊️👑 <b>Consort Diplomatic Mission Launched (-3⚡):</b><br><b>" + escapeHtml(hero.spouse.name) + "</b> is representing your House at Court (+22 Fame &amp; <b>-50% Passive Fame Decay for 2 Hours</b>)!";
  addLog(eMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🕊️ Diplomatic Envoy Active!", hero.spouse.icon, hero.spouse.name, "#7dd3fc", eMsg, "courting");
}

function hostGrandRoyalBanquet() {
  ensureHeroV3Fields(hero);
  if ((hero.courtingUsedToday || 0) >= MAX_DAILY_COURTING) {
    showRequirementModal("Velvet Chamber Daily Limit (3/3 Today)", "🍷⏳", "You have already completed 3 Courting/Banquet actions today.", "Return tomorrow!", "");
    return;
  }
  var cost = Math.max(600, hero.level * 85);
  if (hero.quests < 6 || hero.gold < cost) {
    showRequirementModal("Need 6⚡ Quests & " + cost.toLocaleString() + "g for Banquet", "🍷👑", "Hosting a Grand Royal Banquet requires <b>6⚡ Quests</b> (Have " + hero.quests + "⚡) and <b>" + cost.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g).", "Collect Kingdom Taxes or patrol regions!", "");
    return;
  }
  hero.quests -= 6;
  hero.gold -= cost;
  hero.courtingUsedToday = (hero.courtingUsedToday || 0) + 1;
  addHeroFame(45);
  if (hero.spouse) hero.spouse.love = 100;
  if (Array.isArray(hero.marriedConsorts)) {
    hero.marriedConsorts.forEach(function(mc) { mc.love = 100; });
  }
  hero.stress = Math.max(0, (hero.stress || 0) - 35);
  playSfx("levelup");
  var bMsg = "🍷👑 <b>Grand Royal Banquet Hosted (" + hero.courtingUsedToday + "/" + MAX_DAILY_COURTING + " Today):</b><br>Earned <b>+45 Court Fame</b>, restored <b>100% ❤️ Consort Devotion</b> &amp; relieved -35% Stress!";
  addLog(bMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🍷 Grand Banquet Hosted (+45 Fame)!", "🍷👑", hero.name, "#fde047", bMsg, "courting");
}

function conceiveDynastyChild() {
  ensureHeroV3Fields(hero);
  if (!hero.spouse) return;
  if ((hero.children ? hero.children.length : 0) >= 6) {
    showRequirementModal("Dynasty Nursery Full (6/6 Heirs)", "👶👑", "Your Royal Estate already houses the maximum of <b>6 Dynasty Heirs</b>.", "You can crown a Level 50+ Heir via Royal Succession to free a slot!", "");
    return;
  }
  var cost = Math.max(800, hero.level * 120);
  if (hero.quests < 4 || hero.gold < cost) {
    showRequirementModal("Need 4⚡ Quests & " + cost.toLocaleString() + "g", "👶🌹", "Welcoming and outfitting a new Royal Heir requires <b>4⚡ Quests</b> (Have " + hero.quests + "⚡) and <b>" + cost.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g).", "Collect Kingdom Taxes first!", "");
    return;
  }
  hero.quests -= 4;
  hero.gold -= cost;
  var strongRoll = Math.random() < 0.55;
  var traitPool = strongRoll ?
    [{ name: "Dragon-Blooded Prodigy", mult: 1.35 }, { name: "Sun-Blessed Scion", mult: 1.30 }, { name: "Iron-Willed Heir", mult: 1.25 }] :
    [{ name: "Frail Bookworm", mult: 0.85 }, { name: "Pampered Courtier", mult: 0.88 }];
  var tr = traitPool[Math.floor(Math.random() * traitPool.length)];
  var cNames = ["Prince Aldric", "Princess Lyra", "Prince Kaelen", "Princess Seraphina", "Prince Valen", "Princess Isolde", "Prince Cassian", "Princess Rowena"];
  var cIcons = ["🤴", "👸", "⚔️", "🏹", "🔮", "🛡️"];
  var cIdx = hero.children.length;
  var newCh = {
    name: cNames[(cIdx + hero.level) % cNames.length] + " of " + hero.name.split(" ")[0],
    icon: cIcons[cIdx % cIcons.length],
    level: Math.max(1, Math.round(hero.level * 0.35)),
    isStrong: strongRoll,
    traitName: tr.name,
    atk: Math.round((14 + hero.level * 2.1) * tr.mult),
    maxHp: Math.round((65 + hero.level * 12) * tr.mult),
    hp: Math.round((65 + hero.level * 12) * tr.mult),
    apprentice: "none",
    trialDone: false,
    totalDmg: 0,
    expeditionUntil: 0
  };
  hero.children.push(newCh);
  if (hero.activeChildIdx < 0 && getActiveHelperCount(hero) < MAX_ACTIVE_HELPERS) {
    hero.activeChildIdx = hero.children.length - 1;
  }
  recordMemoirMilestone("Welcomed Royal Dynasty Heir " + newCh.name + " (" + newCh.traitName + ").");
  playSfx("levelup");
  var chMsg = "👶👑 <b style='color:#4ade80;'>ROYAL DYNASTY HEIR BORN!</b><br>Welcomed <b>" + newCh.icon + " " + escapeHtml(newCh.name) + " (Lv " + newCh.level + " • " + escapeHtml(newCh.traitName) + ")</b>!<br>⚠️ <i>Note: You may bring at most 2 Helpers into battle, and active Battle Heirs can die permanently if their HP reaches 0!</i>";
  addLog(chMsg);
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("👶 Royal Heir Welcomed!", newCh.icon, newCh.name, "#4ade80", chMsg, "courting");
}

function setChildApprenticeship(cIdx, role) {
  ensureHeroV3Fields(hero);
  var ch = hero.children[cIdx];
  if (!ch) return;
  ch.apprentice = (ch.apprentice === role) ? "none" : role;
  playSfx("coin");
  addLog("👶 Assigned <b>" + escapeHtml(ch.name) + "</b> to Apprentice Role: <b>" + ch.apprentice.toUpperCase() + "</b>.");
  queueSaveHero();
  openTownFacilityModal("courting");
  renderGameScreen();
}

function trainChildAtWarAcademy(cIdx) {
  ensureHeroV3Fields(hero);
  var ch = hero.children[cIdx];
  if (!ch || ch.isStrong) return;
  var cost = Math.max(500, hero.level * 75);
  if (hero.gold < cost || (hero.gems || 0) < 2) {
    showRequirementModal("Need " + cost.toLocaleString() + "g & 2💎 for War Academy", "🎓⚔️", "Training <b>" + escapeHtml(ch.name) + "</b> at the Royal War Academy requires <b>" + cost.toLocaleString() + " Gold</b> (Have " + hero.gold.toLocaleString() + "g) and <b>2💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎).", "Hunt Bosses for Gems and collect Kingdom Taxes!", "");
    return;
  }
  hero.gold -= cost;
  hero.gems -= 2;
  ch.isStrong = true;
  ch.traitName = "War-Academy Champion";
  ch.atk = Math.round(ch.atk * 1.45) + 12;
  ch.maxHp = Math.round(ch.maxHp * 1.45) + 40;
  ch.hp = ch.maxHp;
  playSfx("levelup");
  addLog("🎓⚔️ <b>Royal War Academy Graduation:</b> <b>" + escapeHtml(ch.name) + "</b> became a <b>War-Academy Champion</b> (+45% ATK/HP)!");
  queueSaveHero();
  openTownFacilityModal("courting");
  renderGameScreen();
}

function undertakeHeirComingOfAgeTrial(cIdx) {
  ensureHeroV3Fields(hero);
  var ch = hero.children[cIdx];
  if (!ch || ch.trialDone) return;
  if ((ch.level || 1) < 10 || hero.quests < 3) {
    showRequirementModal("Requires Heir Level 10+ & 3⚡ Quests", "🦁👶", "The Coming-of-Age Proving Ground Trial requires <b>" + escapeHtml(ch.name) + "</b> to reach <b>Level 10+</b> (Currently Lv " + (ch.level || 1) + ") and costs <b>3⚡ Quests</b> (Have " + hero.quests + "⚡).", "Bring your Heir into battle or send them on Expeditions to level them up!", "");
    return;
  }
  hero.quests -= 3;
  ch.trialDone = true;
  ch.isStrong = true;
  ch.traitName = "Heroic Vanguard Scion";
  ch.atk = Math.round(ch.atk * 1.30) + 15;
  ch.maxHp = Math.round(ch.maxHp * 1.30) + 50;
  ch.hp = ch.maxHp;
  addHeroFame(25);
  playSfx("levelup");
  var tMsg = "🦁👑 <b>HEIR COMING-OF-AGE TRIAL COMPLETE!</b><br><b>" + escapeHtml(ch.name) + "</b> slew a shadow-drake solo in the Proving Grounds, ascending as a <b>Heroic Vanguard Scion (+30% ATK/HP &amp; +25 Fame)</b>!";
  addLog(tMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🦁 Heir Proving-Ground Triumph!", ch.icon, ch.name, "#4ade80", tMsg, "courting");
}

function setActiveBattleChild(cIdx) {
  ensureHeroV3Fields(hero);
  if (hero.activeChildIdx === cIdx) {
    hero.activeChildIdx = -1;
    playSfx("coin");
    openTownFacilityModal("courting");
    renderGameScreen();
    return;
  }
  var currentWithoutChild = getActiveHelperCount(hero) - (hero.activeChildIdx >= 0 ? 1 : 0);
  if (currentWithoutChild >= MAX_ACTIVE_HELPERS) {
    showRequirementModal(
      "Two-Helper Party Limit Reached (2/2 Active)", "👶🛡️",
      "By Royal Decree, you may bring at most <b>2 Helpers</b> into battle (any combination of Recruits, Animal Companion, Dynasty Heir, or Alt Bodyguard).",
      "Dismiss 1 Mercenary/Companion in the <b>🏰 Kingdom ➔ ⚜️ Retinue</b> tab first to free a helper slot for your Dynasty Heir!",
      ""
    );
    return;
  }
  hero.activeChildIdx = cIdx;
  playSfx("coin");
  openTownFacilityModal("courting");
  renderGameScreen();
}

function sendChildExpedition(cIdx) {
  ensureHeroV3Fields(hero);
  var ch = hero.children[cIdx];
  if (!ch) return;
  if (ch.expeditionUntil && ch.expeditionUntil > Date.now()) return;
  ch.expeditionUntil = Date.now() + TWO_HOURS_MS;
  var gFound = 140 + (ch.level || 1) * 35;
  hero.gold += gFound;
  ch.level = Math.min(hero.level, (ch.level || 1) + 1);
  ch.atk += 4;
  ch.maxHp += 15;
  ch.hp = ch.maxHp;
  playSfx("coin");
  addLog("🗺️👶 Sent <b>" + escapeHtml(ch.name) + "</b> on a 2h Border Expedition (+1 Heir Level &amp; +" + gFound.toLocaleString() + "g upfront spoil)!");
  queueSaveHero();
  openTownFacilityModal("courting");
  renderGameScreen();
}

function triggerCampfireBanter() {
  ensureHeroV3Fields(hero);
  if ((hero.bantersUsedToday || 0) >= MAX_DAILY_BANTERS) {
    showRequirementModal("Campfire Banter Daily Limit (3/3 Today)", "🔥⏳", "Your retinue has already shared <b>3 Campfire Banters today</b>.", "Return tomorrow (or use Admin Reset) for fresh hearthside stories!", "");
    return;
  }
  var nowMs = Date.now();
  var remSec = Math.ceil((TWO_HOURS_MS - (nowMs - (hero.lastBanterEpoch || 0))) / 1000);
  if (remSec > 0) {
    showRequirementModal("Campfire Embers Cooling", "🔥⏳", "Wait <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b> before your next Campfire Banter (2h cooldown).", "Patrol regions or visit the Boar's Head Taproom in the meantime!", "");
    return;
  }
  hero.lastBanterEpoch = nowMs;
  hero.bantersUsedToday = (hero.bantersUsedToday || 0) + 1;
  var hpGain = Math.round(hero.maxHp * 0.10);
  hero.hp = Math.min(hero.maxHp, hero.hp + hpGain);
  hero.stress = Math.max(0, (hero.stress || 0) - 20);
  if (hero.spouse) hero.spouse.love = Math.min(100, (hero.spouse.love !== undefined ? hero.spouse.love : 100) + 10);
  var affNote = (hero.resolveState && !hero.resolveState.isVirtue) ? "<br>⚠️ <b style='color:#f87171;'>Sticky Affliction (" + escapeHtml(hero.resolveState.name) + ") Remains:</b> Visit the <b>🙏 Cathedral Confessional</b>, <b>🕯️ Sanctuary Rite</b>, or <b>🛌 2h Offline Bedchamber (Cot/Suite/Palace)</b> to cure a mental breakdown!" : "";
  playSfx("magic");
  var bMsg = "🔥🪕 <b>Hearthside Campfire Banter (" + hero.bantersUsedToday + "/" + MAX_DAILY_BANTERS + " Today):</b><br>Shared ale and war-stories by the fire (+<b>" + hpGain + " HP</b>, <b>-20% Stress</b>" + (hero.spouse ? " &amp; +10% ❤️ Consort Love" : "") + ")!" + affNote;
  addLog(bMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🔥 Campfire Banter Shared!", "🔥🪕", hero.name, "#4ade80", bMsg, window.currentTownModal);
}
'''
}

String buildHeroChunkB3() {
    return buildHeroChunkB3a() + "\n" + buildHeroChunkB3b()
}

String buildHeroChunkB3a() {
    return '''
function toggleInventoryItemLock(idx) {
  ensureHeroV3Fields(hero);
  var itm = hero.inventory[idx];
  if (!itm) return;
  itm.locked = !itm.locked;
  playSfx("coin");
  showGothicToast(itm.locked ? ("🔒 Locked " + itm.name) : ("🔓 Unlocked " + itm.name));
  queueSaveHero();
  renderGameScreen();
}

function setLootFilter(val) {
  ensureHeroV3Fields(hero);
  hero.lootFilter = val || "none";
  addLog("♻️ Set Auto-Salvage Loot Filter to: <b>" + hero.lootFilter.toUpperCase() + "</b>.");
  queueDeltaSaveHero();
  renderGameScreen();
}

function getSalvageYield(itm) {
  if (!itm) return { timber: 1, stone: 1, iron: 1, gold: 10 };
  var sc = Math.max(1, Math.round(getItemPowerScore(itm) / 14));
  return {
    timber: Math.max(2, Math.round(sc * 0.8)),
    stone:  Math.max(2, Math.round(sc * 0.7)),
    iron:   Math.max(1, Math.round(sc * 0.5)),
    gold:   Math.max(12, Math.round((itm.value || 30) * 0.28))
  };
}

function shouldAutoSalvageDrop(itm) {
  if (!hero || !itm || itm.isGodTier || itm.setId || itm.locked) return false;
  var lf = hero.lootFilter || "none";
  if (lf === "none") return false;
  if (lf === "common" && itm.rarity === "Common") return true;
  if (lf === "below_rare" && (itm.rarity === "Common" || itm.rarity === "Uncommon")) return true;
  if (lf === "non_upgrades" && getUpgradeDelta(itm) <= 0) return true;
  return false;
}

function salvageInventoryItem(idx) {
  ensureHeroV3Fields(hero);
  var itm = hero.inventory[idx];
  if (!itm) return;
  if (itm.locked) {
    showGothicToast("🔒 This item is Locked! Tap 🔒 to unlock before salvaging.");
    return;
  }
  var y = getSalvageYield(itm);
  hero.guild.timber = (hero.guild.timber || 0) + y.timber;
  hero.guild.stone  = (hero.guild.stone || 0) + y.stone;
  hero.guild.iron   = (hero.guild.iron || 0) + y.iron;
  hero.gold += y.gold;
  var setGemBonus = itm.setId ? 2 : 0;
  if (setGemBonus > 0) hero.gems = (hero.gems || 0) + setGemBonus;
  hero.inventory.splice(idx, 1);
  playSfx("coin");
  addLog("♻️ Salvaged <b>" + escapeHtml(itm.name) + "</b> into <b>+" + y.timber + "🪵, +" + y.stone + "🪨, +" + y.iron + "⛏️, +" + y.gold + "g</b>" + (setGemBonus ? " &amp; <b>+2💎 Gems</b>!" : "!"));
  queueSaveHero();
  renderGameScreen();
}

function salvageAllNonUpgrades() {
  ensureHeroV3Fields(hero);
  if (!hero.inventory || !hero.inventory.length) return;
  var kept = [], cnt = 0, tG = 0, sG = 0, iG = 0, gG = 0, gemG = 0;
  hero.inventory.forEach(function(itm) {
    if (!itm) return;
    if (itm.locked || itm.isGodTier || getUpgradeDelta(itm) > 0) {
      kept.push(itm);
    } else {
      cnt++;
      var y = getSalvageYield(itm);
      tG += y.timber; sG += y.stone; iG += y.iron; gG += y.gold;
      if (itm.setId) gemG += 2;
    }
  });
  if (cnt === 0) {
    showGothicToast("♻️ No unlocked non-upgrade items to salvage!");
    return;
  }
  hero.inventory = kept;
  hero.guild.timber = (hero.guild.timber || 0) + tG;
  hero.guild.stone  = (hero.guild.stone || 0) + sG;
  hero.guild.iron   = (hero.guild.iron || 0) + iG;
  hero.gold += gG;
  if (gemG > 0) hero.gems = (hero.gems || 0) + gemG;
  playSfx("levelup");
  addLog("♻️ Bulk-Salvaged <b>" + cnt + " item(s)</b> into <b>+" + tG + "🪵, +" + sG + "🪨, +" + iG + "⛏️, +" + gG + "g</b>" + (gemG ? (" &amp; +" + gemG + "💎") : "") + "!");
  queueSaveHero();
  renderGameScreen();
}

function reforgeGearSetPrefix(slotKey) {
  ensureHeroV3Fields(hero);
  if ((hero.forgesUsedToday || 0) >= MAX_DAILY_FORGES) {
    showRequirementModal("Blacksmith Forge Limit Reached (5/5 Today)", "⚜️⏳", "Master Blacksmith Brom has already completed 5 forge operations today.", "Return tomorrow (or use Admin Reset)!", "");
    return;
  }
  var itm = hero[slotKey];
  if (!itm) return;
  var hasSlag = (hero.vault && (hero.vault.dulledGems || 0) > 0);
  if (getTotalMaterialsCount() < 3 || (!hasSlag && (hero.gems || 0) < 2)) {
    showRequirementModal("Need 3 Monster Trophies + (1🪨 Slag OR 2💎 Gems)", "⚜️🔨", "Reforging <b>" + escapeHtml(itm.name) + "</b> into a matching 3-Piece Class Gear Set prefix requires <b>3 Monster Trophies</b> (Have " + getTotalMaterialsCount() + ") plus either <b>1🪨 Dulled Gem Slag</b> (Have " + ((hero.vault && hero.vault.dulledGems) || 0) + ") or <b>2💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎).", "Patrol regions for Monster Trophies!", "");
    return;
  }
  consumeAnyMaterials(3);
  if (hasSlag) hero.vault.dulledGems -= 1;
  else hero.gems -= 2;
  hero.forgesUsedToday = (hero.forgesUsedToday || 0) + 1;
  var cSet = (window.CLASS_ZONE_SETS && CLASS_ZONE_SETS[hero.calling]) ? CLASS_ZONE_SETS[hero.calling] : { prefix: "Dragonforged", perk: "Set Synergy" };
  var cleanBase = itm.name.replace(/^(Dragonforged|Eldritch|Sovereign|Celestial|Vampiric|Valiant)[ ]+/i, "");
  itm.name = cSet.prefix + " " + cleanBase;
  itm.setPerk = cSet.perk;
  playSfx("levelup");
  var sMsg = "⚜️🔨 <b>SET-PREFIX REFORGED (" + hero.forgesUsedToday + "/" + MAX_DAILY_FORGES + " Today):</b><br>Reforged into <b>" + escapeHtml(itm.name) + "</b> (Counts toward the 3-Piece <b>" + cSet.prefix + "</b> Set Bonus)!";
  addLog(sMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚜️ Reforged into " + cSet.prefix + " Set!", itm.icon || "⚜️", "Blacksmith Brom", "#4ade80", sMsg, null);
}

function openEngraveGearModal(slotKey) {
  ensureHeroV3Fields(hero);
  var itm = hero[slotKey];
  if (!itm) return;
  showPopupModal(
    '<div style="font-size:38px;">' + (itm.icon || "🗡️") + '📜</div>' +
    '<div style="font-size:18px;font-weight:900;color:#d4af37;font-family:Cinzel,serif;">📜 Relic Kill-Counter &amp; Runic Engraving</div>' +
    '<div style="font-size:13px;color:#fde68a;margin:4px 0;"><b>' + escapeHtml(itm.name) + '</b> • 💀 Lifetime Kills: <b>' + (itm.kills || 0) + '</b></div>' +
    '<div style="font-size:11.5px;color:#e5dec9;margin-bottom:8px;">Inscribe a custom battle-motto onto this relic (First engraving grants <b>+2 ATK &amp; +2 DEF</b> for <b>1💎 Dragon Gem</b> • You have <b>' + (hero.gems || 0) + '💎</b>):</div>' +
    '<input type="text" id="engraveMottoInput" value="' + escapeHtml(itm.motto || "") + '" placeholder="Enter relic motto..." maxlength="60" style="margin-bottom:10px;">' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn btn-gold" style="flex:1;" onclick="saveEngravedGearMotto(&#39;' + slotKey + '&#39;)">✒️ Engrave Relic ' + (itm.engravedBonus ? '(Free Edit)' : '(-1💎 ➔ +2 ATK/DEF)') + '</button>' +
      '<button class="btn" onclick="closePopupModal()">Cancel</button>' +
    '</div>'
  );
}

function saveEngravedGearMotto(slotKey) {
  ensureHeroV3Fields(hero);
  var itm = hero[slotKey];
  if (!itm) return;
  var txt = ((document.getElementById("engraveMottoInput") || {}).value || "").trim() || "Forged in Dragonfire";
  if (!itm.engravedBonus) {
    if ((hero.gems || 0) < 1) {
      showGothicToast("⚠️ Need 1💎 Dragon Gem for initial runic engraving!");
      return;
    }
    hero.gems -= 1;
    itm.engravedBonus = true;
    itm.atk = (itm.atk || 0) + 2;
    itm.def = (itm.def || 0) + 2;
  }
  itm.motto = txt;
  syncHeroVitalityMaxHp(hero);
  playSfx("levelup");
  addLog("✒️📜 Engraved <b>" + escapeHtml(itm.name) + "</b>: <i>&ldquo;" + escapeHtml(txt) + "&rdquo;</i>!");
  closePopupModal();
  queueSaveHero();
  renderGameScreen();
}

function reforgeHellAnvilRelic(slotKey) {
  ensureHeroV3Fields(hero);
  var itm = hero[slotKey];
  if (!itm) return;
  if (itm.cursedAffix) {
    showGothicToast("🩸 This relic is already awakened as a Sentient Ego-Relic!");
    return;
  }
  if ((hero.forgesUsedToday || 0) >= MAX_DAILY_FORGES) {
    showRequirementModal("Blacksmith Forge Limit Reached (5/5 Today)", "🔥⏳", "Master Blacksmith Brom can only perform 5 forge operations per day.", "Return tomorrow!", "");
    return;
  }
  if ((hero.gems || 0) < 2 || getTotalMaterialsCount() < 3) {
    showRequirementModal("Need 2💎 Gems & 3 Monster Trophies", "🔥🩸", "Awakening <b>" + escapeHtml(itm.name) + "</b> on the Hell-Anvil requires <b>2💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎) and <b>3 Monster Trophies</b> (Have " + getTotalMaterialsCount() + ").", "Hunt Bosses and patrol regions first!", "");
    return;
  }
  hero.gems -= 2;
  consumeAnyMaterials(3);
  hero.forgesUsedToday = (hero.forgesUsedToday || 0) + 1;
  itm.cursedAffix = "Blood-Drinker Ego";
  if (itm.atk) itm.atk = Math.round(itm.atk * 1.15) + 3;
  if (itm.def) itm.def = Math.round(itm.def * 1.15) + 3;
  syncHeroVitalityMaxHp(hero);
  playSfx("levelup");
  var hMsg = "🔥🩸 <b>SENTIENT EGO-RELIC AWAKENED (" + hero.forgesUsedToday + "/" + MAX_DAILY_FORGES + " Today):</b><br><b>" + escapeHtml(itm.name) + "</b> now whispers in battle (+15% Base Stats &amp; +2 ATK every 10 kills up to 100)!";
  addLog(hMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🩸 Sentient Relic Awakened!", itm.icon || "🗡️", itm.name, "#f43f5e", hMsg, null);
}

function selectSocketTargetSlot(slotKey) {
  selectedSocketSlot = slotKey || "weapon";
  renderGameScreen();
}

function socketGemIntoGear(slotKey, traitId) {
  ensureHeroV3Fields(hero);
  if ((hero.socketsUsedToday || 0) >= MAX_DAILY_SOCKETS) {
    showRequirementModal("Gem Socketing Limit Reached (5/5 Today)", "💎⏳", "You can only bind <b>5 Dragon Gem sockets per day</b>.", "Return tomorrow (or use Admin Reset)!", "");
    return;
  }
  var itm = hero[slotKey];
  var tr = GEM_SOCKET_TRAITS.find(function(x) { return x.id === traitId; });
