  if (!activeSlotKey || !hero) return;
  if (debounceSaveTimer) { clearTimeout(debounceSaveTimer); debounceSaveTimer = null; }
  try {
    setSyncStatus("⚡ Delta Sync...", "#38bdf8");
    var deltaObj = {
      hp: hero.hp, maxHp: hero.maxHp, mp: hero.mp, maxMp: hero.maxMp, gold: hero.gold, xp: hero.xp, level: hero.level, xpNext: hero.xpNext,
      quests: hero.quests, fame: hero.fame || 0, gems: hero.gems || 0, potions: hero.potions || 0,
      valkyrieSeals: Math.min(3, hero.valkyrieSeals !== undefined ? hero.valkyrieSeals : 3), wantedLevel: hero.wantedLevel || 0, recruitOrder: hero.recruitOrder || "auto",
      recruitTargetZone: hero.recruitTargetZone || "torso", recruitsCardCollapsed: hero.recruitsCardCollapsed || false, warrantsCollapsed: hero.warrantsCollapsed || false,
      buffFifoOrder: hero.buffFifoOrder || [], overkillSurge: hero.overkillSurge || false, petTreatBattles: hero.petTreatBattles || 0,
      stress: hero.stress || 0, resolveState: hero.resolveState || null, diseases: hero.diseases || [], mercenaries: hero.mercenaries || [], deathsDoorTrauma: hero.deathsDoorTrauma || false,
      drunkUntil: hero.drunkUntil || 0, drinksInWindow: hero.drinksInWindow || 0, drinkWindowStart: hero.drinkWindowStart || 0, drinksBoughtToday: hero.drinksBoughtToday || 0,
      bossSabotaged: hero.bossSabotaged || false, sacrificedBrides: hero.sacrificedBrides || [], marriedConsorts: hero.marriedConsorts || [], mercCooldowns: hero.mercCooldowns || {}, totalRecruitDeaths: hero.totalRecruitDeaths || 0,
      sealsBoughtToday: hero.sealsBoughtToday || 0, alembicUsedToday: hero.alembicUsedToday || 0, stealsUsedToday: hero.stealsUsedToday || 0,
      forgesUsedToday: hero.forgesUsedToday || 0, socketsUsedToday: hero.socketsUsedToday || 0,
      shopBuysToday: hero.shopBuysToday || 0, beltBuysToday: hero.beltBuysToday || 0, feastsOrderedToday: hero.feastsOrderedToday || 0,
      courtPetitionsToday: hero.courtPetitionsToday || 0, intrigueUsedToday: hero.intrigueUsedToday || 0, courtingUsedToday: hero.courtingUsedToday || 0,
      minigamesPlayedToday: hero.minigamesPlayedToday || 0, pvpDuelsToday: hero.pvpDuelsToday || 0,
      spireRunsToday: hero.spireRunsToday || 0, delvesRunToday: hero.delvesRunToday || 0,
      caravansRunToday: hero.caravansRunToday || 0, throneActionsToday: hero.throneActionsToday || 0, armyWarsToday: hero.armyWarsToday || 0,
      bantersUsedToday: hero.bantersUsedToday || 0, sabotagesUsedToday: hero.sabotagesUsedToday || 0,
      rouletteSpinsToday: hero.rouletteSpinsToday || 0, cauldronUsedToday: hero.cauldronUsedToday || 0, riftsRunToday: hero.riftsRunToday || 0,
      echoRematchesToday: hero.echoRematchesToday || 0, commendationClaimedToday: hero.commendationClaimedToday || false, treatiesToday: hero.treatiesToday || 0,
      mercHiresToday: hero.mercHiresToday || 0, krampusBossToday: hero.krampusBossToday || 0, confessionsToday: hero.confessionsToday || 0, leechesUsedToday: hero.leechesUsedToday || 0,
      lastQuestRegenEpoch: hero.lastQuestRegenEpoch, lastBanterEpoch: hero.lastBanterEpoch || 0,
      vault: hero.vault, logs: (hero.logs || []).slice(0, 6)
    };
    var res = await fetch(API_SAVE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ slotKey: activeSlotKey, sessionId: CLIENT_SESSION_ID, heroDelta: deltaObj })
    });
    var data = await res.json();
    if (data && data.ok) {
      serverData.slots = data.slots;
      if (data.realWeather) { serverData.realWeather = data.realWeather; updateRealWeatherTopPill(); }
      serverData.sharedWarrant = data.sharedWarrant !== undefined ? data.sharedWarrant : serverData.sharedWarrant;
      setSyncStatus("🟢 Delta Saved", "#4ade80");
    }
  } catch (e) { setSyncStatus("⚠️ Offline", "#ef4444"); }
}

function queueSaveHero() {
  if (debounceSaveTimer) clearTimeout(debounceSaveTimer);
  setSyncStatus("⏳ Queued (12s)...", "#fbbf24");
  debounceSaveTimer = setTimeout(function() { saveCurrentHero(null, false, null); }, 12000);
}

async function saveCurrentHero(chronicleMsg, showNotice, raidUpdate, extraPayload) {
  if (!activeSlotKey || !hero) return;
  if (debounceSaveTimer) { clearTimeout(debounceSaveTimer); debounceSaveTimer = null; }
  try {
    setSyncStatus("💾 Saving...", "#fbbf24");
    var compactHero = JSON.parse(JSON.stringify(hero));
    compactHero.logs = (hero.logs || []).slice(0, 6);
    compactHero.inventory = (hero.inventory || []).map(compactItemSchema);
    ["weapon", "armor", "helm", "boots", "relic", "amulet"].forEach(function(sk) {
      if (compactHero[sk]) compactHero[sk] = compactItemSchema(compactHero[sk]);
    });
    if (compactHero.vault && Array.isArray(compactHero.vault.items)) {
      compactHero.vault.items = compactHero.vault.items.map(compactItemSchema);
    }
    var bodyObj = { slotKey: activeSlotKey, sessionId: CLIENT_SESSION_ID, hero: compactHero, chronicleEvent: chronicleMsg, raidUpdate: raidUpdate || null };
    if (extraPayload) {
      if (extraPayload.wonderUpdate) bodyObj.wonderUpdate = extraPayload.wonderUpdate;
      if (extraPayload.mailTransfer) bodyObj.mailTransfer = extraPayload.mailTransfer;
      if (extraPayload.tradeTreatyTransfer) bodyObj.tradeTreatyTransfer = extraPayload.tradeTreatyTransfer;
      if (extraPayload.pvpLog) bodyObj.pvpLog = extraPayload.pvpLog;
      if (extraPayload.altGuardEvent) bodyObj.altGuardEvent = extraPayload.altGuardEvent;
      if (extraPayload.sharedWarrantUpdate) bodyObj.sharedWarrantUpdate = extraPayload.sharedWarrantUpdate;
      if (extraPayload.clearSharedWarrant) bodyObj.clearSharedWarrant = true;
      if (extraPayload.revivedHero) bodyObj.revivedHero = extraPayload.revivedHero;
      if (extraPayload.clearPvpInboxSlot) bodyObj.clearPvpInboxSlot = extraPayload.clearPvpInboxSlot;
      if (extraPayload.clearAltGuardInboxSlot) bodyObj.clearAltGuardInboxSlot = extraPayload.clearAltGuardInboxSlot;
      if (extraPayload.clearCryptSlot) bodyObj.clearCryptSlot = extraPayload.clearCryptSlot;
      if (extraPayload.devastationDelta) bodyObj.devastationDelta = extraPayload.devastationDelta;
      if (extraPayload.cleanseCurseHours) bodyObj.cleanseCurseHours = extraPayload.cleanseCurseHours;
      if (extraPayload.unmakingAnchors) bodyObj.unmakingAnchors = extraPayload.unmakingAnchors;
      if (extraPayload.permadeath) { bodyObj.permadeath = true; bodyObj.deathCause = extraPayload.deathCause || "Slain in Battle"; }
    }
    var res = await fetch(API_SAVE_URL, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(bodyObj) });
    var data = await res.json();
    if (data && data.ok) {
      serverData.slots = data.slots;
      if (data.realWeather) { serverData.realWeather = data.realWeather; updateRealWeatherTopPill(); }
      serverData.fallenCrypt = data.fallenCrypt || serverData.fallenCrypt;
      serverData.sessionLocks = data.sessionLocks || serverData.sessionLocks;
      serverData.pvpInbox = data.pvpInbox || serverData.pvpInbox;
      serverData.altGuardInbox = data.altGuardInbox || serverData.altGuardInbox;
      serverData.sharedWarrant = data.sharedWarrant !== undefined ? data.sharedWarrant : serverData.sharedWarrant;
      serverData.unmaking = data.unmaking || serverData.unmaking;
      serverData.echoes = data.echoes || serverData.echoes;
      serverData.worldBoss = data.worldBoss || serverData.worldBoss;
      serverData.realmCurse = data.realmCurse !== undefined ? data.realmCurse : serverData.realmCurse;
      serverData.zoneRaidBosses = data.zoneRaidBosses || serverData.zoneRaidBosses;
      serverData.spireRecord = data.spireRecord || serverData.spireRecord;
      serverData.dynastyWonder = data.dynastyWonder || serverData.dynastyWonder;
      serverData.chronicle = data.chronicle;
      setSyncStatus("🟢 Saved", "#4ade80");
      if (showNotice) { addLog("📜 Progress saved to Hubitat state."); renderGameScreen(); }
    }
  } catch (e) { setSyncStatus("⚠️ Save Failed", "#ef4444"); }
}

function switchScreen(scr) {
  if (window.stopActiveMiniGames) window.stopActiveMiniGames();
  document.getElementById("screenSlots").style.display = (scr === "slots") ? "block" : "none";
  document.getElementById("screenCreate").style.display = (scr === "create") ? "block" : "none";
  document.getElementById("screenGame").style.display = (scr === "game") ? "block" : "none";
  if (scr === "slots") renderSlotsScreen();
}

function getWarCouncilBonusCount() {
  var cnt = 0;
  var maxS = serverData.maxSlots || 3;
  for (var i = 1; i <= maxS; i++) {
    var k = "slot_" + i;
    if (k !== activeSlotKey && serverData.slots && serverData.slots[k] && serverData.slots[k].name) cnt++;
  }
  return cnt;
}

function syncHeroVitalityMaxHp(h) {
  var t = h || hero;
  if (!t) return;
  if ((t.valkyrieSeals || 0) > 3) t.valkyrieSeals = 3;
  var gearG = 0, gearD = 0;
  ["weapon", "armor", "helm", "boots", "relic", "amulet"].forEach(function(sk) {
    var itm = t[sk];
    if (itm && (itm.dur === undefined || itm.dur > 0)) {
      gearG += (itm.guts || 0);
      gearD += (itm.def || 0);
    }
  });
  var disHpMult = 1.0;
  if (Array.isArray(t.diseases)) {
    t.diseases.forEach(function(d) {
      if (d.hpPen) disHpMult -= d.hpPen;
    });
  }
  disHpMult = Math.max(0.65, disHpMult);

  var cathLv = (t.guild && t.guild.buildings && t.guild.buildings.cathedral) ? t.guild.buildings.cathedral : 0;
  var awkBonus = (t.awakened ? 55 : 0) + (t.mythicAscended ? 180 : 0) + (t.hybridClass ? 220 : 0) + ((t.prestigeRank || 0) * 25);
  var baseLvHp = 65 + ((t.level || 1) * 16);
  var rawFormula = baseLvHp + Math.round(((t.guts || 5) + gearG) * 3.5) + Math.round(gearD * 2.0) + (cathLv * 18) + awkBonus;
  var hardcoreCap = Math.round(baseLvHp * 2.20) + (cathLv * 18) + awkBonus;
  var targetMax = Math.max(55, Math.round(Math.min(hardcoreCap, rawFormula) * disHpMult));
  var prevMax = t.maxHp || 50;
  t.maxHp = targetMax;
  if (prevMax < targetMax) {
    t.hp = Math.min(t.maxHp, (t.hp || 50) + (targetMax - prevMax));
  } else if ((t.hp || 50) > t.maxHp) {
    t.hp = t.maxHp;
  }
}

function getHeroStats(targetHero) {
  var h = targetHero || hero;
  ensureHeroV3Fields(h);
  getActiveBuffsAndWhyList(h);
  syncHeroVitalityMaxHp(h);
  var rMeta = RACES[h.race] || RACES["Human"];
  var origMeta = HERO_ORIGINS[h.origin] || HERO_ORIGINS["Disgraced High-Court Noble"];
  var origG = origMeta.bonusStat === "guts" ? (origMeta.bonusVal || 0) : 0;
  var origW = origMeta.bonusStat === "wits" ? (origMeta.bonusVal || 0) : 0;
  var origC = origMeta.bonusStat === "charm" ? (origMeta.bonusVal || 0) : 0;

  var blds = (h.guild && h.guild.buildings) ? h.guild.buildings : {};
  var nRank = NOBLE_RANKS[h.nobleIdx || 0] || NOBLE_RANKS[0];
  var maxFameCap = getMaxFameForLevel(h.level || 1);
  var tarnishedFame = (h.fame || 0) < nRank.fameReq;
  var toastOfCourt = ((h.fame || 0) >= Math.round(maxFameCap * 0.95)) && isPositiveBuffActiveFifo(h, "buff_toast");
  var regencySuspended = (h.fame || 0) < Math.round(nRank.fameReq * 0.70);
  var decree = (h.guild && h.guild.founded && !regencySuspended && isPositiveBuffActiveFifo(h, "buff_decree")) ? (h.guild.decree || "martial") : "";
  var stab = (h.guild && h.guild.founded) ? (h.guild.stability || 75) : 75;
  var stabMult = (stab >= 80 && isPositiveBuffActiveFifo(h, "buff_stability")) ? 1.08 : (stab < 40 ? 0.90 : 1.0);
  var famePenaltyMult = tarnishedFame ? 0.90 : (toastOfCourt ? 1.05 : 1.0);
  var lodgeMult = (h.lodgingBuff && h.lodgingBuff.questsLeft > 0 && isPositiveBuffActiveFifo(h, "buff_lodging")) ? (1 + (h.lodgingBuff.statBonusPct || 0) / 100.0) : 1.0;
  var prestigeMult = isPositiveBuffActiveFifo(h, "buff_prestige") ? (1 + ((h.prestigeRank || 0) * 0.03)) : 1.0;
  var tarotMult = (h.tarotBuff && h.tarotBuff.questsLeft > 0 && h.tarotBuff.id === "empress" && isPositiveBuffActiveFifo(h, "buff_tarot")) ? 1.20 : 1.0;
  var trophyWallMult = isPositiveBuffActiveFifo(h, "buff_trophies") ? (1 + ((h.trophyWall ? h.trophyWall.length : 0) * 0.02)) : 1.0;
  var cosmicRuneMult = isPositiveBuffActiveFifo(h, "buff_runes") ? (1 + (Math.min(15, (h.cosmicRunes || 0)) * 0.02)) : 1.0;
  var cipherMult = (h.cipherPages >= 5 && isPositiveBuffActiveFifo(h, "buff_cipher")) ? 1.06 : 1.0;
  var setBon = getActiveSetBonuses(h);
  var setActiveFifo = isPositiveBuffActiveFifo(h, "buff_set_0");
  var setStatMult = setActiveFifo ? (1 + (setBon.allStatPct / 100.0)) : 1.0;
  var mutId = (h.lineageMutation && isPositiveBuffActiveFifo(h, "buff_mutation")) ? h.lineageMutation.id : "";
  var glassMult = (mutId === "glass_walker") ? 1.10 : 1.0;
  var resolveMult = 1.0;
