  var petCritAdd  = (petId === "owl" ? 5 : 0) * petStage + treatAdd;

  var atk = Math.round(((effGuts * 1.18) + gearAtk + (h.level * 1.45)) * wepMasteryMult * stanceAtkMult * traumaMult * gambitHeroMult * avengeMult);
