  var holGoldAdd = (hol && hol.id === "thanksgiving") ? 0.30 : 0;
  var holLuckAdd = (hol && hol.id === "halloween") ? 0.25 : 0;
  var discountPct = Math.min(45, Math.round((effCharm * 0.12) + ((sk.fortune || 1) * 1.5) + (h.calling === "Trader" ? 14 : 0) - (curse && curse.id === "flood_tide" ? 20 : 0)));
  var goldBonusMult = 1 + ((sk.fortune || 1) * 0.04) + (isPositiveBuffActiveFifo(h, "buff_prestige") ? ((h.prestigeRank || 0) * 0.02) : 0) + ((awk.bonusGoldPct || 0) / 100.0) + (setActiveFifo ? (setBon.goldPct / 100.0) : 0) + (toastOfCourt ? 0.10 : 0) + festGoldAdd + holGoldAdd + (starActive && h.starChart === "scales" ? 0.12 : 0) + (rev.name.indexOf("Golden") >= 0 ? 0.20 : 0) + (decree === "trade" ? 0.25 : 0);
  var dropLuckBonus = ((sk.fortune || 1) * 0.01) + (isPositiveBuffActiveFifo(h, "buff_prestige") ? ((h.prestigeRank || 0) * 0.02) : 0) + ((blds.alchemy || 0) * 0.06) + holLuckAdd + (starActive && h.starChart === "chalice" ? 0.15 : 0) + (feastId === "dragon_stew" ? 0.25 : 0) + (rev.id === "zombie_rising" ? 0.25 : 0) + (decree === "hunt" ? 0.25 : 0);
