      addLog("🗡️🩸 <b>GORE-FOIL EXECUTION!</b> Sliced <b>" + escapeHtml(activeCombat.name) + "&apos;s</b> Tarot card in half in blue flames (+25% Bonus XP &amp; Guaranteed Trophy)!");
    } else {
