    var uDmg = Math.max(20, Math.round((Math.max(st.atk, st.mag) * 2.85 * clashMult - activeCombat.def * 0.25) * bossBonusMult * armBreakMult * masteryMult * lvMod.dmgDealtMult));
    activeCombat.hp -= uDmg;
