function executeBloodPriceSacrifice(sacType) {
  ensureHeroV3Fields(hero);
  var sacDesc = "";
  if (sacType === "heir" && hero.children && hero.children.length > 0 && (hero.children[0].level || 1) >= 10) {
    var lostChild = hero.children.shift();
    hero.activeChildIdx = -1;
    hero.valkyrieSeals = Math.min(3, (hero.valkyrieSeals || 0) + 1);
    hero.fallenHeroes.unshift({ name: lostChild.name, role: "Sacrificed Dynasty Heir", icon: lostChild.icon || "👶", slainBy: "Blood-Price Altar" });
    recordMemoirMilestone("Paid the Blood-Price by sacrificing Dynasty Heir " + lostChild.name + " upon the Obsidian Altar.");
    sacDesc = "Sacrificed Dynasty Heir <b>" + escapeHtml(lostChild.name) + "</b> upon the Obsidian Altar (Died Forever • +1🪽 Valkyrie Seal)!";
  } else if (sacType === "spouse" && hero.spouse) {
    var lostWife = hero.spouse.name;
    var lostWifeId = hero.spouse.id || lostWife;
    if (!Array.isArray(hero.sacrificedBrides)) hero.sacrificedBrides = [];
    if (!hero.sacrificedBrides.includes(lostWifeId)) hero.sacrificedBrides.push(lostWifeId);
    if (!hero.sacrificedBrides.includes(lostWife)) hero.sacrificedBrides.push(lostWife);
    if (hero.courtingProgress && lostWifeId) hero.courtingProgress[lostWifeId] = 0;
    if (Array.isArray(hero.marriedConsorts)) {
      hero.marriedConsorts = hero.marriedConsorts.filter(function(mc) { return mc.id !== lostWifeId && mc.name !== lostWife; });
    }
    hero.fallenHeroes.unshift({ name: lostWife, role: "Sacrificed Royal Consort", icon: hero.spouse.icon || "💍", slainBy: "Blood-Price Altar" });
    hero.spouse = (hero.marriedConsorts && hero.marriedConsorts.length > 0) ? hero.marriedConsorts[0] : null;
    hero.valkyrieSeals = Math.min(3, (hero.valkyrieSeals || 0) + 1);
    recordMemoirMilestone("Paid the Blood-Price by sacrificing Royal Consort " + lostWife + " — her soul is lost forever to this character.");
    sacDesc = "Sacrificed Royal Consort <b>" + escapeHtml(lostWife) + "</b> to the Valkyries (<b>Died Forever on this character — can only be remarried in another character slot</b> • +1🪽 Valkyrie Seal)!";
  } else {
    showGothicToast("⚠️ Blood-Price requires a Royal Consort or a Level 10+ Dynasty Heir!");
    return;
  }
  if (hero.deathMarker) {
    hero.gold += (hero.deathMarker.gold || 0);
    if (hero.deathMarker.item && hero.inventory.length < 30) hero.inventory.push(hero.deathMarker.item);
    hero.deathMarker = null;
  }
  hero.hp = hero.maxHp;
  hero.mp = hero.maxMp;
  playSfx("levelup");
  addLog("🩸⚖️ <b style='color:#fde047;'>BLOOD-PRICE PAID!</b> " + sacDesc + " Your Soul-Urn and vitals have been restored!");
  saveCurrentHero("🩸 " + hero.name + " paid the Blood-Price to defy death!", false, null);
  closePopupModal();
  renderGameScreen();
}

async function confirmHardcorePermadeath(defeatedBy) {
  if (!hero || !activeSlotKey) return;
  await saveCurrentHero("⚰️ PERMADEATH: " + hero.name + " (Lv " + hero.level + ") fell (" + defeatedBy + ") and was buried in " + activeSlotKey.toUpperCase() + "'s Grave!", false, null, { permadeath: true, deathCause: defeatedBy });
  hero = null;
  switchScreen("slots");
}

function pickSmartGodTierDrop(defeatedAreaId) {
  var slotOrder = ["weapon", "armor", "helm", "boots", "relic", "amulet"];
  if (defeatedAreaId >= 17 && defeatedAreaId <= 21 && BOSS_UNIQUES[defeatedAreaId]) {
    return JSON.parse(JSON.stringify(BOSS_UNIQUES[defeatedAreaId]));
  }
  for (var i = 0; i < slotOrder.length; i++) {
    var sKey = slotOrder[i];
    var eq = hero[sKey];
    var inBag = (hero.inventory || []).some(function(x) { return x && x.type === sKey && x.isGodTier; });
    if ((!eq || !eq.isGodTier) && !inBag) {
      return JSON.parse(JSON.stringify(GOD_TIER_PANOPLY[sKey]));
    }
  }
  var randSlot = slotOrder[Math.floor(Math.random() * slotOrder.length)];
  return JSON.parse(JSON.stringify(GOD_TIER_PANOPLY[randSlot]));
}
