  var echoBonusMult = 1 + (((serverData.echoes && serverData.echoes.bonusXpPct) ? serverData.echoes.bonusXpPct : 0) / 100.0);
  var curseXpMult = (curse && curse.id === "stasis") ? 0.80 : 1.0;
  var festXpMult = (hero.guild && hero.guild.festivalBoom && isPositiveBuffActiveFifo(hero, "buff_stability")) ? 1.15 : 1.0;
  var holXpMult = (hol && hol.id === "halloween" && isPositiveBuffActiveFifo(hero, "buff_holiday")) ? 1.20 : 1.0;
  var wfXpMult = (wFront && wFront.name.indexOf("Blood-Mist") >= 0) ? 1.20 : 1.0;
