    structsSvg += '<g><rect x="345" y="' + (140 - ph) + '" width="110" height="' + ph + '" fill="#2e1065" stroke="#fde047" stroke-width="2"/>' +
      '<polygon points="340,' + (140 - ph) + ' 400,' + (108 - ph) + ' 460,' + (140 - ph) + '" fill="#581c87" stroke="#fde047" stroke-width="1.8"/>' +
      '<text x="400" y="' + (125 - ph) + '" text-anchor="middle" font-size="14">' + (hero.guild.crest || '👑') + '</text>' +
      '<text x="400" y="' + (135 - ph / 2) + '" text-anchor="middle" fill="#fde047" font-size="10" font-family="Cinzel,serif" font-weight="bold">🏰Citadel ' + (manLv > 0 ? 'Lv' + manLv : '') + '</text></g>';
  }
  if (alcLv > 0) {
    var ah = 45 + alcLv * 4;
    structsSvg += '<g><rect x="485" y="' + (145 - ah) + '" width="44" height="' + ah + '" fill="#1e1b4b" stroke="#c084fc" stroke-width="1.5"/>' +
      '<polygon points="480,' + (145 - ah) + ' 507,' + (118 - ah) + ' 534,' + (145 - ah) + '" fill="#6b21a8" stroke="#e9d5ff" stroke-width="1.2"/>' +
      '<text x="507" y="' + (138 - ah / 2) + '" text-anchor="middle" fill="#e9d5ff" font-size="9" font-weight="bold">🔮Lv' + alcLv + '</text></g>';
  }
  if (catLv > 0) {
    var ch = 52 + catLv * 4.5;
    structsSvg += '<g><rect x="555" y="' + (145 - ch) + '" width="82" height="' + ch + '" fill="#1c1917" stroke="#fde047" stroke-width="1.6"/>' +
      '<circle cx="596" cy="' + (162 - ch) + '" r="10" fill="#991b1b" stroke="#fde047" stroke-width="1.2"/>' +
      '<text x="596" y="' + (140 - ch / 2) + '" text-anchor="middle" fill="#fde68a" font-size="9" font-weight="bold">⛪Cathedral Lv' + catLv + '</text></g>';
  }
  if (rstLv > 0) {
    var rh = 65 + rstLv * 5;
    structsSvg += '<g><polygon points="665,145 695,' + (145 - rh) + ' 735,145" fill="#450a0a" stroke="#f97316" stroke-width="1.8"/>' +
      '<text x="695" y="' + (135 - rh) + '" text-anchor="middle" font-size="18">🐉🔥</text>' +
      '<text x="695" y="138" text-anchor="middle" fill="#fed7aa" font-size="9" font-weight="bold">Roost Lv' + rstLv + '</text></g>';
  }
  if (fallenCnt > 0) {
    structsSvg += '<g><rect x="312" y="118" width="22" height="27" fill="#94a3b8" stroke="#fde047" stroke-width="1"/>' +
      '<text x="323" y="114" text-anchor="middle" font-size="11">🗿</text></g>';
  }

  var soldiersSvg = '<g class="patrol-soldier" style="animation-duration:16s;">' +
      '<circle cx="20" cy="184" r="5" fill="' + plumeHex + '"/><rect x="16" y="189" width="8" height="12" fill="' + plumeHex + '" stroke="#fde047" stroke-width="0.8"/>' +
      '<line x1="26" y1="174" x2="26" y2="202" stroke="#e5dec9" stroke-width="2"/><polygon points="26,170 30,178 22,178" fill="#7dd3fc"/>' +
      '<circle cx="42" cy="184" r="5" fill="' + plumeHex + '"/><rect x="38" y="189" width="8" height="12" fill="' + plumeHex + '" stroke="#fde047" stroke-width="0.8"/>' +
      '<line x1="48" y1="174" x2="48" y2="202" stroke="#e5dec9" stroke-width="2"/><polygon points="48,170 52,178 44,178" fill="#7dd3fc"/>' +
      '<text x="34" y="212" text-anchor="middle" fill="#fde68a" font-size="8.5" font-weight="bold">🛡️Vanguard (' + (hero.garrisonDye || 'Gold') + ')</text>' +
    '</g>' +
    '<g class="patrol-soldier-rev" style="animation-duration:21s;">' +
      '<circle cx="20" cy="186" r="5" fill="#4ade80"/><rect x="16" y="191" width="8" height="11" fill="#14532d" stroke="#86efac" stroke-width="0.8"/>' +
      '<path d="M27 180 Q34 190 27 200" fill="none" stroke="#d4af37" stroke-width="1.8"/>' +
      '<circle cx="40" cy="186" r="5" fill="#38bdf8"/><rect x="36" y="191" width="8" height="11" fill="#1e3a8a" stroke="#7dd3fc" stroke-width="0.8"/>' +
      '<text x="30" y="212" text-anchor="middle" fill="#86efac" font-size="8.5" font-weight="bold">🏹Ranger &amp; Watch</text>' +
    '</g>';

  if ((hero.guild.golems || 0) > 0) {
    soldiersSvg += '<g class="patrol-soldier" style="animation-duration:26s;animation-delay:-7s;">' +
      '<rect x="12" y="180" width="14" height="18" rx="2" fill="#b45309" stroke="#fef047" stroke-width="1.2"/>' +
      '<circle cx="19" cy="186" r="2.5" fill="#38bdf8"/>' +
      '<text x="19" y="209" text-anchor="middle" fill="#fde047" font-size="8" font-weight="bold">⚙️Golem x' + hero.guild.golems + (hero.guild.golemOverdriveTicks > 0 ? ' (2x🔥)' : '') + '</text>' +
    '</g>';
  }

  return '<div class="kingdom-vista-stage">' +
    '<svg viewBox="0 0 800 220" style="width:100%;height:100%;display:block;">' +
      '<defs><linearGradient id="kSky" x1="0%" y1="0%" x2="0%" y2="100%">' + skyGrad + '</linearGradient></defs>' +
      '<rect width="800" height="220" fill="url(#kSky)"/>' +
      '<circle cx="680" cy="42" r="22" fill="#fde047" opacity="0.22"/><circle cx="680" cy="42" r="14" fill="#fef08a" opacity="0.45"/>' +
      '<polygon points="0,155 140,85 290,155" fill="#120c1c"/><polygon points="240,155 420,65 610,155" fill="#181024"/><polygon points="520,155 690,78 800,155" fill="#120c1c"/>' +
      structsSvg + wallSvg +
      '<rect x="0" y="176" width="800" height="44" fill="#0d0a12" stroke="#785a28" stroke-width="1.5"/>' +
      '<line x1="0" y1="196" x2="800" y2="196" stroke="#3b2d47" stroke-width="1" stroke-dasharray="10,6"/>' +
      soldiersSvg +
    '</svg>' +
    '<div style="position:absolute;top:6px;left:8px;right:8px;display:flex;justify-content:space-between;align-items:center;font-size:11.5px;background:rgba(6,4,9,0.85);border:1px solid #c5a059;padding:4px 9px;border-radius:4px;">' +
      '<span><b style="font-family:&#39;Cinzel&#39;,serif;color:#d4af37;">' + hero.guild.crest + ' ' + escapeHtml(hero.guild.name) + '</b> — <span style="color:#fde68a;">' + km.tierTitle + '</span> (' + arch + (hero.guild.festivalBoom ? ' • 🎉Festival Boom!' : '') + ')</span>' +
      '<button class="btn btn-gold" style="min-height:22px;padding:1px 7px;font-size:10px;" onclick="kingdomIsoView=!kingdomIsoView;renderGameScreen();">📐 Royal Survey Map</button>' +
    '</div>' +
  '</div>';
}
'''
}

String buildKingdomChunkA2() {
    return '''
function constructBrassGolem() {
  ensureHeroV3Fields(hero);
  if (!hero.guild || !hero.guild.founded) return;
  if ((hero.guild.golems || 0) >= 5) {
    showRequirementModal("Automaton Labor Guild Full (5/5 Golems)", "⚙️🤖", "Your stronghold already operates the maximum of <b>5 Brass Golems</b>.", "You can feed Dulled Gem Slag to your golems to double their mining yield for 3 ticks!", "");
    return;
  }
  var curIrn = hero.guild.iron || 0;
  var curGems = hero.gems || 0;
  if (hero.gold < 2500 || curIrn < 25 || curGems < 2) {
    showRequirementModal("Need 2,500g, 25⛏️ Iron & 2💎 Gems for Brass Golem", "⚙️⛏️", "Forging an automated Brass Golem requires:<br>• <b>2,500 Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)<br>• <b>25⛏️ Kingdom Iron</b> (You have <b>" + curIrn + "⛏️</b>)<br>• <b>2💎 Dragon Gems</b> (You have <b>" + curGems + "💎</b>)", "Salvage spare gear in your Backpack or burn Trophies at the Huntsman's Brazier for Iron!", "");
    return;
  }
  hero.gold -= 2500;
  hero.guild.iron -= 25;
  hero.gems -= 2;
  hero.guild.golems = (hero.guild.golems || 0) + 1;
  playSfx("levelup");
  var gMsg = "⚙️🤖 <b>BRASS AUTOMATON GOLEM CONSTRUCTED (-2,500g, -25⛏️, -2💎):</b><br>Golem #" + hero.guild.golems + "/5 now patrols your stronghold road and automatically harvests <b>+2🪵 Timber, +2🪨 Stone &amp; +1⛏️ Iron</b> per tick!";
  addLog(gMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚙️ Brass Golem Activated!", "⚙️🤖", null, "#d4af37", gMsg, null);
}

function feedGolemDulledSlag() {
  ensureHeroV3Fields(hero);
  if ((hero.guild.golems || 0) <= 0) {
    showRequirementModal("No Brass Golems Constructed", "⚙️🤖", "You must construct at least <b>1 Brass Golem</b> before feeding Dulled Gem Slag into their furnaces.", "Build a Brass Golem on your Stronghold tab first!", "");
    return;
  }
  var curSlag = (hero.vault && hero.vault.dulledGems) ? hero.vault.dulledGems : 0;
  if (curSlag <= 0) {
    showRequirementModal("No Dulled Gem Slag Available (Have 0🪨)", "🪨⚙️", "Your Personal Vault currently has <b>0🪨 Dulled Gem Slag</b>.", "Dulled Slag is created when locked Vault Gems expire after 7 days (or when drained at the Catacomb Gem Roulette).", "");
    return;
  }
  hero.vault.dulledGems -= 1;
  hero.guild.golemOverdriveTicks = (hero.guild.golemOverdriveTicks || 0) + 3;
  playSfx("magic");
  var sMsg = "🪨⚙️ <b>DULLED GEM SLAG FED TO BRASS GOLEMS (-1🪨 Slag • Have " + hero.vault.dulledGems + "🪨 left):</b><br>Your automatons' furnaces roar with residual dragon-fire! <b>Golem Timber, Stone &amp; Iron mining output is DOUBLED for the next " + hero.guild.golemOverdriveTicks + " ticks!</b>";
  addLog(sMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚙️ Golem Overdrive Active (2x Yield)!", "🪨⚙️", null, "#4ade80", sMsg, null);
}

function toggleAutomatedCaravanRoute() {
  ensureHeroV3Fields(hero);
  if ((hero.nobleIdx || 0) < 3) {
    showRequirementModal("Noble Title Required: Baron", "🐎👑", "Chartering an Automated Supply Caravan Route requires the feudal rank of <b>Baron</b>.", "Petition the High Court in the Citadel to reach Baron rank!", "");
    return;
  }
  hero.guild.autoCaravan = !hero.guild.autoCaravan;
  playSfx("coin");
  addLog("🐎⚖️ <b>Automated Supply Caravan Route " + (hero.guild.autoCaravan ? "ENABLED" : "DISABLED") + ":</b> " + (hero.guild.autoCaravan ? "Converts 15🪵 Timber &amp; 15🪨 Stone into +25🍞 Rations &amp; +120g on every 45m tick!" : "Manual stockpiling resumed."));
  queueSaveHero();
  renderGameScreen();
}

function openCrossSlotTradeTreatyModal() {
  ensureHeroV3Fields(hero);
  var tLeft = Math.max(0, 2 - (hero.treatiesToday || 0));
  var maxS = serverData.maxSlots || 3;
  var rows = [];
  for (var i = 1; i <= maxS; i++) {
    var sk = "slot_" + i;
    var alt = (serverData.slots && serverData.slots[sk]) ? serverData.slots[sk] : null;
    if (alt && alt.name && sk !== activeSlotKey) {
      rows.push('<div class="item-row" style="text-align:left;">' +
        renderHeroPortraitSvg(alt, 40) +
        '<div style="flex:1;"><b>🤝 ' + escapeHtml(alt.name) + ' (' + sk.toUpperCase() + ' • Lv ' + (alt.level || 1) + ')</b><div style="font-size:11px;color:#e5dec9;">Ship <b>25🪵 Timber, 25🪨 Stone &amp; 15⛏️ Iron</b> (0% Fee) ➔ Receive <b style="color:#4ade80;">+' + (650 + hero.level * 25).toLocaleString() + ' Gold &amp; +15 Fame</b>!</div></div>' +
        '<button class="btn ' + (tLeft > 0 ? 'btn-gold' : 'btn-locked') + '" onclick="executeCrossSlotTradeTreaty(&#39;' + sk + '&#39;)">📦 Ship Cargo (' + tLeft + '/2)</button></div>');
    }
  }
  showPopupModal(
    '<div style="font-size:38px;">🤝📦🏰</div>' +
    '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:Cinzel,serif;margin-bottom:4px;">Royal Trade Treaties (' + tLeft + '/2 Today)</div>' +
    '<div class="lore-subtitle-box">Charter duty-free supply convoys between your own houses across Valoria. Shipping surplus materials to another Hero Slot enriches both estates without merchant tariffs.</div>' +
    '<div style="font-size:12px;color:#fde68a;margin-bottom:8px;">📦 <b>Your Current Stockpiles:</b> <b>' + (hero.guild.timber || 0) + '🪵 Timber</b> • <b>' + (hero.guild.stone || 0) + '🪨 Stone</b> • <b>' + (hero.guild.iron || 0) + '⛏️ Iron</b> • 💰 <b>' + hero.gold.toLocaleString() + 'g</b></div>' +
    (rows.length ? rows.join('') : '<div style="padding:12px;color:#9c8f7a;">Create a hero in another Character Slot on your Hubitat hub to sign Royal Trade Treaties!</div>') +
    '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Close Trade Treaties</button>'
  );
}

function executeCrossSlotTradeTreaty(targetSlot) {
  ensureHeroV3Fields(hero);
  if ((hero.treatiesToday || 0) >= 2) {
    showRequirementModal("Trade Treaty Daily Limit Reached (2/2 Today)", "🤝⏳", "You can only dispatch <b>2 Cross-Slot Trade Treaty shipments per day</b>.", "Return tomorrow (or use Admin Reset) for fresh trade shipments!", "");
    return;
  }
  var curTim = hero.guild.timber || 0, curStn = hero.guild.stone || 0, curIrn = hero.guild.iron || 0;
  if (curTim < 25 || curStn < 25 || curIrn < 15) {
    showRequirementModal("Insufficient Stockpiles for Trade Treaty", "📦🪵", "Shipping a Trade Treaty convoy requires:<br>• <b>25🪵 Timber</b> (You have <b>" + curTim + "🪵</b>)<br>• <b>25🪨 Stone</b> (You have <b>" + curStn + "🪨</b>)<br>• <b>15⛏️ Iron</b> (You have <b>" + curIrn + "⛏️</b>)", "Salvage spare gear in your Backpack or burn Trophies at the Huntsman's Exchange to gather materials!", "");
    return;
  }
  var alt = (serverData.slots && serverData.slots[targetSlot]) ? serverData.slots[targetSlot] : null;
  if (!alt) return;
  hero.guild.timber -= 25;
  hero.guild.stone -= 25;
  hero.guild.iron -= 15;
  hero.treatiesToday = (hero.treatiesToday || 0) + 1;
  var gPaid = 650 + hero.level * 25;
  hero.gold += gPaid;
  addHeroFame(15);
  playSfx("coin");
  var tMsg = "🤝📦 <b>ROYAL TRADE TREATY FULFILLED (" + hero.treatiesToday + "/2 Today):</b><br>Shipped <b>25🪵 Timber, 25🪨 Stone &amp; 15⛏️ Iron</b> with zero merchant fee to <b>" + escapeHtml(alt.name) + " (" + targetSlot.toUpperCase() + ")</b> and received <b>+" + gPaid.toLocaleString() + " Gold &amp; +15 Fame</b>!";
  addLog(tMsg);
  saveCurrentHero("🤝 " + hero.name + " shipped a Royal Trade Treaty convoy to " + alt.name + "!", false, null, {
    tradeTreatyTransfer: { targetSlot: targetSlot, timber: 25, stone: 25, iron: 15 }
  });
  renderGameScreen();
  showOutcomeModal("🤝 Trade Treaty Convoy Arrived!", "🤝📦", alt.name, "#4ade80", tMsg, null);
}

function openTrophyWallRematchModal(areaId) {
  ensureHeroV3Fields(hero);
  var ar = AREAS[areaId - 1];
  if (!ar || !ar.boss) return;
  var kills = (hero.bestiaryKills && hero.bestiaryKills[ar.boss.name]) ? hero.bestiaryKills[ar.boss.name] : 1;
  var echoLeft = Math.max(0, 1 - (hero.echoRematchesToday || 0));
  showPopupModal(
    '<div style="margin-bottom:6px;">' + renderEntityAvatar(ar.boss.name, ar.boss.icon, 64, true) + '</div>' +
    '<div style="font-size:19px;font-weight:900;color:#fde047;font-family:Cinzel,serif;">🦌 Mounted Trophy: ' + ar.boss.icon + ' ' + escapeHtml(ar.boss.name) + '</div>' +
    '<div style="font-size:12px;color:#86efac;margin:4px 0 8px 0;">Region: <b>' + escapeHtml(ar.name) + '</b> • Lifetime Victories: <b>' + kills + '</b> • Active Aura: <b>+2% All Stats</b></div>' +
    '<div style="background:#0b0811;border:1px solid #c5a059;border-radius:4px;padding:12px;margin-bottom:10px;text-align:left;font-size:13px;color:#e5dec9;">' +
      '&ldquo;' + escapeHtml(ar.boss.loreIntro) + '&rdquo;<br><br>' +
      '🕯️ <b>Spectral Trophy Rematch (1/Day Cap • Costs 3⚡ Quests • You have ' + hero.quests + '⚡):</b> Relive your clash against a spectral memory of <b>' + escapeHtml(ar.boss.name) + '</b> for <b>+35 Court Fame, +1💎 Dragon Gem</b> &amp; bonus Gold!' +
    '</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn ' + (echoLeft > 0 ? 'btn-shine' : 'btn-locked') + '" style="flex:1;" onclick="launchTrophyEchoRematch(' + areaId + ')">' + (echoLeft > 0 ? '⚔️ Awaken Trophy Memory (-3⚡ • Have ' + hero.quests + '⚡)' : '⏳ Trophy Memory Used Today (1/1)') + '</button>' +
      '<button class="btn" onclick="closePopupModal()">Close</button>' +
    '</div>'
  );
}

function launchTrophyEchoRematch(areaId) {
  ensureHeroV3Fields(hero);
  if ((hero.echoRematchesToday || 0) >= 1) return;
  if (hero.quests < 3) {
    showRequirementModal("Need 3⚡ Quests for Trophy Rematch", "🦌⚡", "Awakening a Throne Room Trophy Memory requires <b>3⚡ Quests</b> (You have " + hero.quests + "⚡).", "Wait for the 45m stamina tick or visit the Astral Ley-Well!", "");
    return;
  }
  var ar = AREAS[areaId - 1] || AREAS[0];
  var b = ar.boss;
  hero.quests -= 3;
  hero.echoRematchesToday = (hero.echoRematchesToday || 0) + 1;
  closePopupModal();
  clearTransientCombatFx();
  var bArm = Math.round(b.hp * 0.35);
  activeCombat = {
    isBoss: true, isTrophyEcho: true, isRoamingMiniBoss: true,
    isWorldRaid: false, isZoneRaid: false, isDelveBoss: false, isSpire: false, isHerald: false, isPvp: false,
    areaId: ar.id, baseMobName: b.name, trait: "Trophy-Echo", loreIntro: "A spectral memory awakened from your Throne Room Trophy Wall (+35 Fame & +1💎 on Victory)!",
    icon: b.icon, name: "TROPHY MEMORY: " + b.name, level: ar.maxLv,
    hp: b.hp, maxHp: b.hp, armor: bArm, maxArmor: bArm, poise: 100, maxPoise: 100, atk: b.atk, def: b.def, eva: b.eva, parry: 14, acc: b.acc, crit: 15,
    xp: Math.round(b.xp * 0.75), gold: Math.round(b.gold * 0.75),
    sessionDamage: 0, alliedUsed: false, tauntUsed: false, tauntedTurns: 0, armorBrokenTurns: 0, hamstrungTurns: 0, silencedTurns: 0, phase2Triggered: false, comboCount: 0, bossCharging: false, partyShield: 0, bleedTurns: 0, heroPoisonTurns: 0, stunned: false
  };
  addLog("🦌⚔️ <b style='color:#fde047;'>THRONE ROOM TROPHY MEMORY AWAKENED (1/1 Today • -3⚡)!</b> Rematching <b>" + b.icon + " " + escapeHtml(b.name) + "</b>!");
  renderGameScreen();
}

function openInquisitorialTrialModal() {
  ensureHeroV3Fields(hero);
  if (!hero.guild || !hero.guild.founded) return;
  var prisList = hero.prisoners || [];
  var tLeft = Math.max(0, MAX_DAILY_THRONE_ACTIONS - (hero.throneActionsToday || 0));
  var cellHtml = prisList.length ? prisList.map(function(pr, idx) {
    return '<div class="item-row" style="border-color:#f43f5e;text-align:left;">' +
      '<div style="flex:1;"><b>⛓️ Prisoner: ' + escapeHtml(pr.name) + ' (Lv ' + (pr.lv || 1) + ')</b><div style="font-size:11px;color:#e5dec9;">Extract Boss Intel (-20% Armor), Ransom to Court, or Recruit as Defector (+100 Troops)!</div></div>' +
      '<div style="display:flex;gap:4px;flex-wrap:wrap;">' +
        '<button class="btn btn-arcane" style="min-height:28px;padding:3px 7px;font-size:10.5px;" onclick="interrogatePrisonerCell(' + idx + ',&#39;intel&#39;)">🔎 Boss Intel</button>' +
        '<button class="btn btn-emerald" style="min-height:28px;padding:3px 7px;font-size:10.5px;" onclick="interrogatePrisonerCell(' + idx + ',&#39;defect&#39;)">🤝 Defect (+100 Troops)</button>' +
        '<button class="btn btn-gold" style="min-height:28px;padding:3px 7px;font-size:10.5px;" onclick="interrogatePrisonerCell(' + idx + ',&#39;ransom&#39;)">💰 Ransom (+' + (250 + (pr.lv || 1) * 45) + 'g)</button>' +
      '</div></div>';
  }).join('') : '<div style="font-size:11.5px;color:#9c8f7a;margin-bottom:8px;">No captured guards or spies in your Dungeon Cell yet. When a Shoplifting Guard drops below 25% HP in battle, tap <b>⛓️ Imprison in Dungeon Cell</b>!</div>';

  showPopupModal(
    '<div style="font-size:42px;">⚖️⛓️🕯️</div>' +
    '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-top:4px;">THE INQUISITORIAL GAOL &amp; TRIBUNAL</div>' +
    '<div style="font-size:11.5px;color:#86efac;margin-top:2px;">📅 Daily Tribunal Actions Remaining: <b>' + tLeft + ' / ' + MAX_DAILY_THRONE_ACTIONS + ' Today</b> • ⚡ Your Quests: <b>' + hero.quests + '/' + hero.maxQuests + '⚡</b></div>' +
    '<div style="text-align:left;font-size:13px;font-weight:bold;color:#fde047;font-family:Cinzel,serif;margin:8px 0 4px 0;">⛓️ Captured Prisoners in Your Gaol (' + prisList.length + ') ' + (hero.bossWeaknessIntel ? '• <span style="color:#4ade80;">[🎯 -20% Boss Armor Intel Ready!]</span>' : '') + ':</div>' +
    cellHtml +
    '<div style="background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13px;line-height:1.6;color:#e5dec9;">' +
      'Your Border Inquisitors have also dragged a captured <b>Shadow Covenant Commander</b> before your tribunal (Costs 3⚡ Quests • Have ' + hero.quests + '⚡):' +
    '</div>' +
    '<div style="display:flex;flex-direction:column;gap:8px;">' +
      '<button class="btn ' + (tLeft > 0 ? 'btn-crimson' : 'btn-locked') + '" onclick="resolveInquisitorialTrial(&#39;execute&#39;)">🪓 Public Execution (-3⚡ ➔ +40 Court Fame &amp; +8% Kingdom Stability)</button>' +
      '<button class="btn ' + (tLeft > 0 ? 'btn-gold' : 'btn-locked') + '" onclick="resolveInquisitorialTrial(&#39;ransom&#39;)">💰 Royal Ransom (-3⚡ ➔ +' + (350 + hero.level * 55).toLocaleString() + ' Gold &amp; +15🪵/🪨)</button>' +
      '<button class="btn ' + (tLeft > 0 ? 'btn-arcane' : 'btn-locked') + '" onclick="resolveInquisitorialTrial(&#39;brainwash&#39;)">🔮 Mind-Bind into Double-Agent (-3⚡ ➔ +1💎 Gem &amp; -20% Boss Armor Intel!)</button>' +
    '</div>'
  );
}

function interrogatePrisonerCell(pIdx, actionType) {
  ensureHeroV3Fields(hero);
  if ((hero.throneActionsToday || 0) >= MAX_DAILY_THRONE_ACTIONS) {
    showRequirementModal("Daily Tribunal Limit Reached (3/3 Today)", "⛓️⏳", "You have already conducted <b>3 Throne Room or Dungeon Gaol actions today</b>.", "Return after midnight rollover (or use Admin Reset) to interrogate more prisoners!", "");
    return;
  }
  if (!hero.prisoners || !hero.prisoners[pIdx]) return;
  hero.throneActionsToday = (hero.throneActionsToday || 0) + 1;
  var pr = hero.prisoners.splice(pIdx, 1)[0];
  var msg = "";
  if (actionType === "defect") {
    hero.guild.mercenaryTroops = (hero.guild.mercenaryTroops || 0) + 100;
    addHeroFame(15);
    playSfx("levelup");
    msg = "🤝🛡️ <b>PRISONER DEFECTED TO YOUR BANNER (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today)!</b><br>Impressed by your clemency, <b>" + escapeHtml(pr.name) + "</b> swore fealty and brought their squad over—adding <b>+100 Free Standing Legion Troops</b> &amp; <b>+15 Court Fame</b>!";
  } else if (actionType === "intel") {
    hero.bossWeaknessIntel = true;
    var bonusDefect = "";
    if (Math.random() < 0.20) {
      hero.guild.mercenaryTroops = (hero.guild.mercenaryTroops || 0) + 100;
      bonusDefect = "<br>• 🤝 <b>Bonus Defection:</b> The prisoner also defected to your banner (+100 Standing Legion Troops)!";
    }
    playSfx("magic");
    msg = "🔎⛓️ <b>BOSS WEAKNESS INTEL EXTRACTED (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today)!</b><br>Under interrogation, <b>" + escapeHtml(pr.name) + "</b> revealed the chink in the regional overlord's scales! Your next Boss encounter starts with <b>-20% Boss Armor</b>!" + bonusDefect;
  } else {
    var rGold = 250 + (pr.lv || 1) * 45;
    hero.gold += rGold;
    addHeroFame(15);
    playSfx("coin");
    msg = "💰⛓️ <b>PRISONER RANSOMED TO HIGH COURT (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today):</b><br>Released <b>" + escapeHtml(pr.name) + "</b> for <b>+" + rGold.toLocaleString() + " Gold &amp; +15 Court Fame</b>!";
  }
  addLog(msg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⛓️ Dungeon Gaol Verdict Sealed!", "⛓️🕯️", null, "#4ade80", msg, null);
}

function resolveInquisitorialTrial(verdict) {
  ensureHeroV3Fields(hero);
  if ((hero.throneActionsToday || 0) >= MAX_DAILY_THRONE_ACTIONS) {
    showRequirementModal("Daily Tribunal Limit Reached (3/3 Today)", "⚖️⏳", "You have already presided over <b>3 Throne Room or Inquisitorial Tribunal actions today</b>.", "Return tomorrow (or use Admin Reset) for fresh trials!", "");
    return;
  }
  if (hero.quests < 3) {
    showRequirementModal("Need 3⚡ Quests for Inquisitorial Tribunal", "⚖️🕯️", "Presiding over an Inquisitorial Tribunal requires <b>3⚡ Quests</b> (You have " + hero.quests + "⚡).", "Wait for the 45m stamina tick or visit the Astral Ley-Well!", "");
    return;
  }
  hero.quests -= 3;
  hero.throneActionsToday = (hero.throneActionsToday || 0) + 1;
  var msg = "";
  if (verdict === "execute") {
    addHeroFame(40);
    hero.guild.stability = Math.min(100, (hero.guild.stability || 75) + 8);
    playSfx("slash");
    msg = "🪓⚖️ <b>PUBLIC EXECUTION CARRIED OUT (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today • -3⚡):</b><br>The traitor's head was piked above the gatehouse! Earned <b>+40 Court Fame</b> &amp; <b>+8% Kingdom Stability</b>!";
  } else if (verdict === "ransom") {
    var rGold = 350 + hero.level * 55;
    hero.gold += rGold;
    hero.guild.timber = (hero.guild.timber || 0) + 15;
    hero.guild.stone = (hero.guild.stone || 0) + 15;
    playSfx("coin");
    msg = "💰⚖️ <b>PRISONER RANSOMED (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today • -3⚡):</b><br>Collected <b>+" + rGold.toLocaleString() + " Gold</b>, <b>+15🪵 Timber</b> &amp; <b>+15🪨 Stone</b>!";
  } else {
    hero.gems = (hero.gems || 0) + 1;
    hero.bossWeaknessIntel = true;
    hero.tarotBuff = { id: "tower", name: "Inquisitor's Mind-Seal", icon: "🔮👁️", desc: "+30% Crit Damage & +25% Gold for 8 Quests", questsLeft: 8 };
    pushBuffToFifo("buff_tarot", hero);
    playSfx("magic");
    msg = "🔮⚖️ <b>DOUBLE-AGENT MIND-BOUND (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today • -3⚡):</b><br>Extracted <b>+1💎 Dragon Gem</b>, <b>-20% Boss Armor Intel</b>, and activated <b>Inquisitor's Mind-Seal (+30% Crit DMG for 8 Quests)</b>!";
  }
  addLog(msg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚖️ Inquisitorial Verdict Sealed!", "⚖️🕯️", null, "#d4af37", msg, null);
}

function adjustWorkforce(jobKey, delta) {
  ensureHeroV3Fields(hero);
  if ((hero.nobleIdx || 0) < 2) {
    showRequirementModal(
      "Noble Title Required: Knight", "⚒️👑",
      "Assigning specialized Citizen Workforce units requires the title of <b style='color:#fbbf24;'>Knight</b> (Currently <b>" + hero.nobleRank + "</b>).",
      "Visit <b>🏛️ Citadel ➔ 👑 High Court</b> and petition for the title of <b>Knight</b>!",
      '<button class="btn btn-gold" style="flex:1;" onclick="openTownFacilityModal(&#39;court&#39;)">👑 Go to High Court</button>'
    );
    return;
  }
  var km = getKingdomMetrics();
  var wf = hero.guild.workforce;
  if (delta > 0 && km.usedWfPts >= km.maxWfPts) {
    showRequirementModal(
      "All Workforce Units Assigned (" + km.usedWfPts + "/" + km.maxWfPts + ")", "⚒️🏰",
      "Every available citizen workforce unit in your domain is currently assigned to a job.",
      "Upgrade your Kingdom Buildings or hear Throne Petitions to grow your Population (every +120 Citizens grants +1 Workforce Unit), or click <b>[ - ]</b> on another job first!",
      ""
    );
    return;
  }
  if (delta < 0 && (wf[jobKey] || 0) <= 0) return;
  wf[jobKey] = (wf[jobKey] || 0) + delta;
  queueSaveHero();
  renderGameScreen();
}

function dispatchTradeCaravan() {
  ensureHeroV3Fields(hero);
  if (!hero.guild || !hero.guild.founded) return;
  if ((hero.caravansRunToday || 0) >= MAX_DAILY_CARAVANS) {
    showRequirementModal("Trade Caravan Daily Limit Reached (3/3 Today)", "🐎⏳", "Your Royal Teamsters can only dispatch <b>3 Armored Trade Caravans per day</b>.", "Return tomorrow (or use Admin Reset) to send more caravans across the border!", "");
    return;
  }
  var curTim = hero.guild.timber || 0, curStn = hero.guild.stone || 0;
  if (hero.quests < 3 || curTim < 30 || curStn < 30) {
    showRequirementModal(
      "Need 3⚡ Quests, 30🪵 Timber & 30🪨 Stone for Trade Caravan", "🐎⚖️",
      "Dispatching an Armored Trade Caravan across the border requires:<br>• <b>3⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>)<br>• <b>30🪵 Timber</b> (You have <b>" + curTim + "🪵</b>)<br>• <b>30🪨 Stone</b> (You have <b>" + curStn + "🪨</b>)",
      "Assign Lumberjacks &amp; Quarrymen, salvage spare equipment, or burn Trophies at the Huntsman's Exchange to stock surplus materials!",
      ""
    );
    return;
  }
  hero.quests -= 3;
  hero.caravansRunToday = (hero.caravansRunToday || 0) + 1;
  hero.guild.timber -= 30;
  hero.guild.stone -= 30;

  if ((hero.wantedLevel || 0) >= 5 && Math.random() < 0.40) {
    var hLv = hero.level + 5;
    var hHp = Math.round(160 + hLv * 52);
    activeCombat = {
      isBoss: true, isGuard: true, guardFameLoss: 75,
      isWorldRaid: false, isZoneRaid: false, isDelveBoss: false, isSpire: false, isHerald: false, isPvp: false,
      areaId: hero.selectedArea || 1, baseMobName: "The Hound of the High Court", trait: "Savage",
      loreIntro: "🐺👑 WANTED LEVEL 5 CARAVAN INVASION! The Hound of the High Court intercepted your Trade Caravan at the border!",
      icon: "🐺👑", name: "CARAVAN INVASION: The Hound of the High Court", level: hLv,
      hp: hHp, maxHp: hHp, armor: Math.round(hHp * 0.40), maxArmor: Math.round(hHp * 0.40), poise: 100, maxPoise: 100,
      atk: Math.round(22 + hLv * 7.2), def: Math.round(10 + hLv * 3.8), eva: 20, parry: 16, acc: 105 + hLv, crit: 20,
      xp: hLv * 55, gold: 450 + hero.level * 65,
      sessionDamage: 0, alliedUsed: false, tauntUsed: false, tauntedTurns: 0, armorBrokenTurns: 0, hamstrungTurns: 0, silencedTurns: 0, phase2Triggered: false, comboCount: 0, bossCharging: false, partyShield: 0, bleedTurns: 0, heroPoisonTurns: 0, stunned: false
    };
    addLog("🐺👑 <b style='color:#ef4444;'>WANTED LV 5 CARAVAN INVASION!</b> <b>The Hound of the High Court</b> ambushed your Trade Caravan!");
    renderGameScreen();
    return;
  }

  var chk = rollContestedStatCheck("guts", 16, hero.unlockedArea || 1, false);
  var gProfit = Math.round((450 + hero.level * 65) * (chk.passed ? 1.35 : 0.85));
  hero.gold += gProfit;
  addHeroFame(20);
  var sealBonus = "";
  if (chk.passed && Math.random() < 0.25 && (hero.valkyrieSeals || 0) < 3) {
    hero.valkyrieSeals = Math.min(3, (hero.valkyrieSeals !== undefined ? hero.valkyrieSeals : 3) + 1);
    sealBonus = "<br>• <b>Relic Unearthed:</b> <span style='color:#fde047;'>+1🪽 Seal of the Valkyrie (" + hero.valkyrieSeals + "/3)!</span>";
  }
  playSfx("coin");
  var cMsg = "🐎⚖️ <b>Armored Trade Caravan Dispatched (" + hero.caravansRunToday + "/" + MAX_DAILY_CARAVANS + " Today • -3⚡, -30🪵, -30🪨):</b><br>" +
    (chk.passed ? "Your outriders repelled a roadside ambush and delivered the full cargo!" : "Roadside brigands harried the rear wagons, but the main chest arrived!") +
    "<br>• <b>Caravan Profit:</b> <span style='color:#fbbf24;font-weight:bold;'>+" + gProfit.toLocaleString() + " Gold &amp; +20 Fame</span>" + sealBonus;
  addLog(cMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🐎 Trade Caravan Returned!", "🐎⚖️", null, "#4ade80", cMsg, null);
}

function getBuildingUpgradeReqs(bMeta, curLv) {
  var mult = Math.pow(1.52, curLv);
  var curse = getActiveRealmCurse();
  var rw = getRealWeather();
  var timeMult = ((curse && curse.id === "tectonic") ? 1.50 : 1.0) * (rw.cold ? 1.15 : 1.0);
  return {
    gold: Math.round(bMeta.baseGold * mult),
    timber: Math.round(bMeta.baseTimber * mult),
    stone: Math.round(bMeta.baseStone * mult),
    iron: Math.round(bMeta.baseIron * mult),
    mins: Math.round(bMeta.baseMins * Math.pow(1.35, curLv) * timeMult)
  };
}

function upgradeKingdomBuilding(bId) {
  ensureHeroV3Fields(hero);
  if (!hero.guild.founded) {
    showRequirementModal("Royal Estate Not Chartered Yet", "🚩🏰", "You must charter your Royal Estate before constructing strongholds.", "Requires <b>Level 20+</b>, a <b>Royal Wife</b>, <b>Knight+ Title</b>, 25,000g, 35 Mats &amp; 5💎!", "");
    return;
  }
  if (hero.guild.activeBuild) {
    showRequirementModal(
      "Royal Masons Busy", "🔨⏳",
      "Your builders are currently constructing <b>" + escapeHtml(hero.guild.activeBuild.name) + " (Lv " + hero.guild.activeBuild.targetLv + ")</b>.",
      "Wait for the construction timer to finish, or click <b>⚡ Oversee Labor (-1⚡ Quest)</b> to shave 30 minutes off the build timer!",
      ""
    );
    return;
  }
  var bMeta = KINGDOM_BUILDINGS.find(function(x) { return x.id === bId; });
  if (!bMeta) return;
  if ((hero.nobleIdx || 0) < bMeta.minNobleIdx) {
    var reqTitle = NOBLE_RANKS[bMeta.minNobleIdx].title;
    showRequirementModal(
      "Noble Title Too Low for " + bMeta.name, bMeta.icon,
      "Constructing <b>" + escapeHtml(bMeta.name) + "</b> requires the feudal rank of <b style='color:#fbbf24;'>" + reqTitle + "</b> (Your current rank: <b>" + hero.nobleRank + "</b>).",
      "Visit <b>🏛️ Citadel ➔ 👑 High Court</b> to petition for higher Noble Titles!",
      '<button class="btn btn-gold" style="flex:1;" onclick="openTownFacilityModal(&#39;court&#39;)">👑 Go to High Court</button>'
    );
    return;
  }
  var curLv = hero.guild.buildings[bId] || 0;
  if (curLv >= 10) return;
  var req = getBuildingUpgradeReqs(bMeta, curLv);
  var missing = [];
  if (hero.gold < req.gold) missing.push("Need <b>" + req.gold.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)");
  if ((hero.guild.timber || 0) < req.timber) missing.push("Need <b>" + req.timber + "🪵 Timber</b> (You have <b>" + (hero.guild.timber || 0) + "🪵</b>)");
  if ((hero.guild.stone || 0) < req.stone) missing.push("Need <b>" + req.stone + "🪨 Stone</b> (You have <b>" + (hero.guild.stone || 0) + "🪨</b>)");
  if ((hero.guild.iron || 0) < req.iron) missing.push("Need <b>" + req.iron + "⛏️ Iron</b> (You have <b>" + (hero.guild.iron || 0) + "⛏️</b>)");

  if (missing.length > 0) {
    showRequirementModal(
      "Insufficient Kingdom Materials for " + bMeta.name, "🏗️🪵",
      missing.map(function(m) { return "• " + m; }).join("<br>"),
      "• <b>🔥 Huntsman Trophy Exchange:</b> Burn surplus Trophies in the <b>📋 Warrants</b> tab for Timber, Stone &amp; Iron!<br>• <b>♻️ Salvage Gear:</b> Salvage unwanted backpack items in <b>🎒 Reliquary</b>.",
      '<button class="btn btn-arcane" style="flex:1;" onclick="closePopupModal();openHuntsmanTrophyExchangeModal();">🏹 Exchange Trophies</button>'
    );
    return;
  }

  hero.gold -= req.gold;
  hero.guild.timber -= req.timber;
  hero.guild.stone -= req.stone;
  hero.guild.iron -= req.iron;
  hero.guild.activeBuild = {
    id: bId, name: bMeta.name, icon: bMeta.icon, targetLv: curLv + 1,
    readyEpoch: Date.now() + (req.mins * 60000)
  };
  playSfx("coin");
  var bMsg = "🏗️ <b>Royal Masons Dispatched:</b><br>Construction has begun on <b>" + bMeta.icon + " " + escapeHtml(bMeta.name) + " (Lv " + (curLv + 1) + ")</b>!<br>• <b>Estimated Time:</b> <span style='color:#fbbf24;font-weight:bold;'>" + req.mins + " minutes</span><br>• <i>Your Stronghold Skyline will automatically evolve upon completion!</i>";
  addLog(bMsg);
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("🏗️ Construction Started!", bMeta.icon, null, "#d4af37", bMsg, null);
}

function overseeKingdomBuild() {
  ensureHeroV3Fields(hero);
  if (!hero.guild.activeBuild) return;
  if (hero.quests <= 0) {
    showRequirementModal("Out of Quest Stamina (Have 0⚡)", "⚡🔨", "Overseeing construction labor requires <b>1⚡ Quest</b>.", "Wait for the 45m recovery tick or visit the Astral Ley-Well!", "");
    return;
  }
  hero.quests--;
  hero.guild.activeBuild.readyEpoch -= (30 * 60000);
  playSfx("slash");
  addLog("🔨 <b>Oversaw Royal Masons (-1⚡ Quest • Have " + hero.quests + "⚡ left):</b> Shaved 30 minutes off construction timer!");
  checkKingdomBuildCompletion();
  queueSaveHero();
  renderGameScreen();
}

function performCurseCleansingRitual() {
  ensureHeroV3Fields(hero);
  var curse = getActiveRealmCurse();
  if (!curse) return;
  var cathLv = (hero.guild && hero.guild.buildings && hero.guild.buildings.cathedral) ? hero.guild.buildings.cathedral : 0;
  var curTim = hero.guild.timber || 0, curStn = hero.guild.stone || 0, curRat = hero.guild.rations || 0;
  if (cathLv < 1 || hero.gold < 1500 || curTim < 15 || curStn < 15 || curRat < 20) {
    showRequirementModal(
      "Cannot Perform Grand Cleansing Ritual Yet", "🕯️⛪",
      "Performing a Royal Cleansing Ritual to purge 24 hours of the 7-Day Realm Curse requires:<br>• <b>Cathedral of the First Flame Lv 1+</b> (Currently Lv " + cathLv + ")<br>• <b>1,500 Gold</b> (Have " + hero.gold.toLocaleString() + "g)<br>• <b>15🪵 Timber</b> (Have " + curTim + "🪵)<br>• <b>15🪨 Stone</b> (Have " + curStn + "🪨)<br>• <b>20🍞 Rations</b> (Have " + curRat + "🍞)",
      "Build the Cathedral in the <b>🏗️ Royal Works</b> sub-tab and gather the required tribute!",
      ""
    );
    return;
  }
  hero.gold -= 1500;
  hero.guild.timber -= 15;
  hero.guild.stone -= 15;
  hero.guild.rations -= 20;
  addHeroFame(35);
  playSfx("magic");
  var cMsg = "🕯️⚜️ <b style='color:#4ade80;'>GRAND CLEANSING RITUAL PERFORMED!</b><br>Your Cathedral bells rang out across Valoria, purging <b>24 Hours</b> off the <b>" + escapeHtml(curse.name) + "</b> and earning <b>+35 Court Fame</b>!";
  addLog(cMsg);
  saveCurrentHero("🕯️ " + hero.name + "'s Cathedral performed a Grand Cleansing Ritual (-24h off Realm Curse)!", false, null, { cleanseCurseHours: 24 });
  renderGameScreen();
  showOutcomeModal("🕯️ Curse Cleansing Ritual!", "🕯️⛪", null, "#4ade80", cMsg, null);
}

function openThronePetitionModal() {
  ensureHeroV3Fields(hero);
  if ((hero.throneActionsToday || 0) >= MAX_DAILY_THRONE_ACTIONS) {
    showRequirementModal("Daily Throne Room Limit Reached (3/3 Today)", "👑⏳", "You have already ruled on <b>3 Throne Petitions or Trials today</b>.", "Return after midnight rollover (or use Admin Reset) for fresh petitioners!", "");
    return;
  }
  if ((hero.nobleIdx || 0) < 3) {
    showRequirementModal(
      "Noble Title Required: Baron", "👑⚖️",
      "Holding Throne Room Petitions requires the feudal rank of <b style='color:#fbbf24;'>Baron</b> (Currently <b>" + hero.nobleRank + "</b>).",
      "Visit <b>🏛️ Citadel ➔ 👑 High Court</b> to petition for Baron rank!",
      '<button class="btn btn-gold" style="flex:1;" onclick="openTownFacilityModal(&#39;court&#39;)">👑 Go to High Court</button>'
    );
    return;
  }
  var nowMs = Date.now();
  var elap = nowMs - (hero.guild.lastPetitionEpoch || 0);
  if (elap < 1800000) {
    var remS = Math.ceil((1800000 - elap) / 1000);
    showRequirementModal("No Petitioners Waiting", "⏳👑", "Your Herald reports the next Throne Room petitioner will arrive in <b style='color:#fbbf24;'>" + formatCooldownSec(remS) + "</b> (30m cooldown, Max 3/day).", "Patrol regions or manage your workforce while awaiting the next petition!", "");
    return;
  }
  var pIdx = Math.floor(Math.random() * THRONE_PETITIONS.length);
  var p = THRONE_PETITIONS[pIdx];
  var curRat = (hero.guild && hero.guild.rations) ? hero.guild.rations : 0;
  showPopupModal(
    '<div style="font-size:44px;">' + p.icon + '</div>' +
    '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-top:4px;">👑 THRONE ROOM PETITION</div>' +
    '<div style="font-size:14px;font-weight:bold;color:#7dd3fc;margin:4px 0 6px 0;">' + escapeHtml(p.title) + '</div>' +
    '<div style="font-size:11.5px;color:#fde68a;margin-bottom:8px;">💰 Your Gold: <b>' + hero.gold.toLocaleString() + 'g</b> • 🍞 Granary Rations: <b>' + curRat + '🍞</b></div>' +
    '<div style="background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:12px;margin-bottom:12px;font-size:13.5px;color:#e5dec9;line-height:1.6;text-align:left;">' + p.text + '</div>' +
    '<div style="display:flex;flex-direction:column;gap:8px;">' +
      '<button class="btn btn-emerald" style="justify-content:flex-start;padding:10px;" onclick="resolveThronePetition(' + pIdx + ', 1)">' + p.c1.label + '</button>' +
      '<button class="btn btn-gold" style="justify-content:flex-start;padding:10px;" onclick="resolveThronePetition(' + pIdx + ', 2)">' + p.c2.label + '</button>' +
    '</div>'
  );
}

function resolveThronePetition(pIdx, choiceNum) {
  var p = THRONE_PETITIONS[pIdx];
  if (!p) return;
  if ((hero.throneActionsToday || 0) >= MAX_DAILY_THRONE_ACTIONS) return;
  var ch = (choiceNum === 1) ? p.c1 : p.c2;
  if (ch.costRations && (hero.guild.rations || 0) < ch.costRations) {
    showRequirementModal("Not Enough Granary Rations", "🍞🌾", "This ruling requires <b>" + ch.costRations + "🍞 Rations</b> (You currently have <b>" + (hero.guild.rations || 0) + "🍞</b>).", "Assign more Shire Farmers or catch fish at the Royal Weir!", "");
    return;
  }
  if (ch.costGold && hero.gold < ch.costGold) {
    showRequirementModal("Not Enough Gold in Treasury", "💰👑", "This ruling requires <b>" + ch.costGold + " Gold</b> (You currently have <b>" + hero.gold.toLocaleString() + "g</b>).", "Collect Kingdom Taxes or complete Quest Board contracts!", "");
    return;
  }
  hero.throneActionsToday = (hero.throneActionsToday || 0) + 1;
  if (ch.costRations) hero.guild.rations -= ch.costRations;
  if (ch.costGold) hero.gold -= ch.costGold;
  if (ch.goldAdd) hero.gold += ch.goldAdd;
  if (ch.timberAdd) hero.guild.timber = (hero.guild.timber || 0) + ch.timberAdd;
  if (ch.stoneAdd) hero.guild.stone = (hero.guild.stone || 0) + ch.stoneAdd;
  if (ch.ironAdd) hero.guild.iron = (hero.guild.iron || 0) + ch.ironAdd;
  if (ch.fameAdd) addHeroFame(ch.fameAdd);
  if (ch.gemAdd) hero.gems = (hero.gems || 0) + ch.gemAdd;
  if (ch.stabAdd) hero.guild.stability = Math.max(10, Math.min(100, (hero.guild.stability || 75) + ch.stabAdd));

  hero.guild.lastPetitionEpoch = Date.now();
  playSfx("coin");
  var pMsg = "⚖️ <b>Royal Ruling Sealed (" + hero.throneActionsToday + "/" + MAX_DAILY_THRONE_ACTIONS + " Today • " + escapeHtml(p.title) + "):</b><br>" + ch.label + "<br>• <b>Domain Stability:</b> <span style='color:#4ade80;font-weight:bold;'>" + hero.guild.stability + "%</span>";
  addLog(pMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚖️ Royal Ruling Issued!", p.icon, null, "#d4af37", pMsg, null);
}

function contributeDynastyWonder() {
  ensureHeroV3Fields(hero);
  var w = serverData.dynastyWonder || { stage: 0, goldIn: 0, matsIn: 0 };
  if (w.stage >= 10) return;
  if (hero.quests < 5 || hero.gold < 50000 || (hero.guild.timber || 0) < 250 || (hero.guild.stone || 0) < 250 || (hero.guild.iron || 0) < 150 || (hero.gems || 0) < 10) {
    showRequirementModal(
      "Insufficient Tribute for Shared Dynasty Wonder", "🏛️🐉",
      "Raising the next monumental stage of the Shared Dynasty Wonder requires:<br>• <b>5⚡ Quests Stamina</b> (Have " + hero.quests + "⚡)<br>• <b>50,000 Gold</b> (Have " + hero.gold.toLocaleString() + "g)<br>• <b>250🪵 Timber</b> (Have " + (hero.guild.timber || 0) + "🪵)<br>• <b>250🪨 Stone</b> (Have " + (hero.guild.stone || 0) + "🪨)<br>• <b>150⛏️ Iron</b> (Have " + (hero.guild.iron || 0) + "⛏️)<br>• <b>10💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎)",
      "The Shared Dynasty Wonder is an account-wide mega-project! Salvage gear, burn Trophies, and run your Workforce to gather tribute!",
      ""
    );
    return;
  }
  hero.quests -= 5;
  hero.gold -= 50000;
  hero.guild.timber -= 250;
  hero.guild.stone -= 250;
  hero.guild.iron -= 150;
  hero.gems -= 10;
  addHeroFame(120);
  w.stage = (w.stage || 0) + 1;
  w.goldIn = (w.goldIn || 0) + 50000;
  w.matsIn = (w.matsIn || 0) + 650;
  serverData.dynastyWonder = w;
  playSfx("levelup");
  var wMsg = "🏛️ <b style='color:#fbbf24;'>SHARED DYNASTY WONDER STAGE " + w.stage + " / 10 COMPLETED!</b><br>All character slots on your server have raised the monument to Stage " + w.stage + "/10 (+120 Court Fame)!";
  addLog(wMsg);
  saveCurrentHero("🏛️ " + hero.name + " raised the Grand Dragon Wonder to Stage " + w.stage + "/10!", false, null, { wonderUpdate: w });
  renderGameScreen();
  showOutcomeModal("🏛️ Dynasty Wonder Stage " + w.stage + "/10!", "🏛️🐉", null, "#c084fc", wMsg, null);
}

function setKingdomDecree(decKey) {
  ensureHeroV3Fields(hero);
  if ((hero.nobleIdx || 0) < 4) {
    showRequirementModal(
      "Noble Title Required: Viscount", "⚖️👑",
      "Enacting Royal Kingdom Decrees requires the title of <b style='color:#fbbf24;'>Viscount</b> (Currently <b>" + hero.nobleRank + "</b>).",
      "Visit <b>🏛️ Citadel ➔ 👑 High Court</b> to petition for Viscount rank!",
      '<button class="btn btn-gold" style="flex:1;" onclick="openTownFacilityModal(&#39;court&#39;)">👑 Go to High Court</button>'
    );
    return;
  }
  if (!hero.guild.founded || !KINGDOM_DECREES[decKey]) return;
  hero.guild.decree = decKey;
  pushBuffToFifo("buff_decree", hero);
  var dMsg = "⚖️ <b>Royal Decree Enacted:</b><br><b>" + KINGDOM_DECREES[decKey].name + "</b><br>" + KINGDOM_DECREES[decKey].desc;
  addLog(dMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚖️ Royal Decree Enacted!", "⚖️📜", null, "#d4af37", dMsg, null);
}

function collectKingdomTaxes() {
  ensureHeroV3Fields(hero);
  if (!hero.guild.founded) return;
  var today = getTodayDateStr();
  if (hero.lastTaxDateStr === today) {
    showRequirementModal(
      "Daily Kingdom Tax Limit Reached (1/1 Today)", "💰⏳",
      "By Royal Charter, Direct Domain Tithes may only be levied <b>once per calendar day</b> (Already collected on <b>" + today + "</b>).",
      "Your Guild Burghers still generate passive auto-tax every 45m tick! Return tomorrow (or use Admin Reset) for your next daily levy.",
      ""
    );
    return;
  }
  var km = getKingdomMetrics();
  hero.lastTaxDateStr = today;
  hero.guild.lastTaxEpoch = Date.now();
  hero.gold += km.tax;
  playSfx("coin");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 34);
  var tMsg = "💰 <b>Daily Royal Domain Treasury Collection (1/1 Today):</b><br>Your bailiffs collected <b style='color:#fbbf24;'>+" + km.tax.toLocaleString() + " Gold</b> from your <b>" + km.pop.toLocaleString() + " citizens</b>!<br>• <b>New Treasury Balance:</b> " + hero.gold.toLocaleString() + " Gold";
  addLog(tMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("💰 Daily Domain Taxes Collected!", "💰🏛️", null, "#4ade80", tMsg, null);
}
