String buildKingdomChunkC() {
    return buildKingdomChunkC1() + "\n" + buildKingdomChunkC2() + "\n" + buildKingdomChunkC3()
}

String buildKingdomChunkC1() {
    return '''
var RIVAL_ARMIES = [
  { name: "Skarsnik's Blackpowder Vanguard", general: "High Warlord Skarsnik", icon: "👺💣", troops: 450, bias: "bow", rewardGold: 850, rewardGems: 1 },
  { name: "Ironcrag Uruk Siege-Host", general: "Grommash the Titan-Crusher", icon: "🪓❄️", troops: 920, bias: "charge", rewardGold: 1850, rewardGems: 2 },
  { name: "Catacomb Undying Phalanx", general: "Arch-Lich Malakor", icon: "💀👑", troops: 1650, bias: "magic", rewardGold: 3600, rewardGems: 3 },
  { name: "Obsidian Caldera Wyrm-Legion", general: "Ignisrath the Cinder Lord", icon: "🔥🐉", troops: 2800, bias: "charge", rewardGold: 6800, rewardGems: 4 },
  { name: "First-Age Astral Host", general: "Vaelthazar, Emperor of Dragons", icon: "🐉👑", troops: 4800, bias: "magic", rewardGold: 14500, rewardGems: 6 }
];

function getGuildArmySummary() {
  ensureHeroV3Fields(hero);
  var km = getKingdomMetrics();
  var recList = (hero.guild && hero.guild.recruits) ? hero.guild.recruits : [];
  var totalTroops = 200 + (hero.guild.mercenaryTroops || 0) + (km.bonusTroops || 0);
  var cBon = 1.0, bBon = 1.0, mBon = 1.0, extraScouts = 0, extraRallies = 0;
  GUILD_RECRUITS.forEach(function(r) {
    if (recList.includes(r.id)) {
      totalTroops += r.troops;
      if (r.unitType === "charge") cBon += 0.10;
      if (r.unitType === "bow") bBon += 0.10;
      if (r.unitType === "magic") mBon += 0.10;
      if (r.id === "kael") extraScouts += 1;
      if (r.id === "seraphina") extraRallies += 1;
    }
  });
  return { totalTroops: totalTroops, chargeBonus: cBon, bowBonus: bBon, magicBonus: mBon, extraScouts: extraScouts, extraRallies: extraRallies };
}

function foundPlayerGuild() {
  ensureHeroV3Fields(hero);
  var totMats = getTotalMaterialsCount();
  if (hero.level < 20 || !hero.spouse || (hero.nobleIdx || 0) < 2 || hero.gold < 25000 || totMats < 35 || (hero.gems || 0) < 5) {
    showRequirementModal(
      "Cannot Charter Sovereign Royal Estate Yet", "🏰👑",
      "Chartering your Sovereign Royal Estate requires:<br>• <b>Hero Level 20+</b> (Now Lv " + hero.level + ")<br>• <b>Married to a Royal Consort</b><br>• <b>Knight+ Noble Title</b><br>• <b>25,000 Gold</b> (Have " + hero.gold.toLocaleString() + "g)<br>• <b>35 Monster Trophies</b> (Have " + totMats + ")<br>• <b>5💎 Dragon Gems</b> (Have " + (hero.gems || 0) + "💎)",
      "Visit the Velvet Chamber to wed a Royal Consort and petition the High Court to reach Knight rank!",
      ""
    );
    return;
  }
  var gName = ((document.getElementById("guildNameInput") || {}).value || "").trim() || ("House of " + hero.name);
  var gCrest = ((document.getElementById("guildCrestSelect") || {}).value) || "🐉";
  var gMotto = ((document.getElementById("guildMottoInput") || {}).value || "").trim() || "Iron Within, Glory Without!";
  hero.gold -= 25000;
  consumeAnyMaterials(35);
  hero.gems -= 5;
  hero.guild.founded = true;
  hero.guild.name = gName;
  hero.guild.crest = gCrest;
  hero.guild.motto = gMotto;
  hero.guild.stability = 85;
  pushBuffToFifo("buff_stability", hero);
  pushBuffToFifo("buff_decree", hero);
  addHeroFame(60);
  recordMemoirMilestone("Chartered the Sovereign Royal Estate of " + gName + " (" + gCrest + ").");
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 50);
  var fMsg = "🏰👑 <b style='color:#4ade80;'>SOVEREIGN ROYAL ESTATE CHARTERED!</b><br>Founded <b>" + gCrest + " " + escapeHtml(gName) + "</b> (+60 Court Fame)!";
  addLog(fMsg);
  saveCurrentHero("🏰 " + hero.name + " chartered the Sovereign Royal Estate of " + gName + "!", false, null);
  renderGameScreen();
  showOutcomeModal("🏰 Royal Estate Chartered!", gCrest, hero.name, "#fde047", fMsg, null);
}

function hireMercenaryLevy() {
  ensureHeroV3Fields(hero);
  var cost = Math.max(350, hero.level * 40);
  var curRat = (hero.guild && hero.guild.rations) ? hero.guild.rations : 0;
  if (hero.gold < cost || curRat < 15) {
    showRequirementModal("Need " + cost.toLocaleString() + "g & 15🍞 Rations", "🛡️🍞", "Conscripting +150 Standing Legion Troops requires:<br>• <b>" + cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)<br>• <b>15🍞 Granary Rations</b> (You have <b>" + curRat + "🍞</b>)", "Assign Shire Serfs on the Stronghold tab to stock Rations!", "");
    return;
  }
  hero.gold -= cost;
  hero.guild.rations -= 15;
  hero.guild.mercenaryTroops = (hero.guild.mercenaryTroops || 0) + 150;
  playSfx("coin");
  addLog("🛡️ Conscripted <b>+150 Standing Legion Troops</b> (-" + cost.toLocaleString() + "g, -15🍞 • Have " + hero.guild.rations + "🍞 left)!");
  queueSaveHero();
  renderGameScreen();
}

function recruitGuildCaptain(capId) {
  ensureHeroV3Fields(hero);
  if ((hero.nobleIdx || 0) < 3) {
    showRequirementModal("Requires Baron+ Noble Title", "🤝👑", "Recruiting Division Captains &amp; Admiral Kaelen Vance requires the feudal rank of <b>Baron</b>.", "Petition the High Court in the Citadel!", "");
    return;
  }
  var cap = GUILD_RECRUITS.find(function(x) { return x.id === capId; });
  if (!cap || hero.guild.recruits.includes(capId)) return;
  if (hero.level < cap.minLv || hero.gold < cap.costGold) {
    showRequirementModal("Cannot Recruit " + cap.name + " Yet", cap.icon, "Requires <b>Hero Level " + cap.minLv + "+</b> (Now Lv " + hero.level + ") and <b>" + cap.costGold.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol realms and collect Kingdom Taxes!", "");
    return;
  }
  hero.gold -= cap.costGold;
  hero.guild.recruits.push(capId);
  playSfx("levelup");
  addLog("🤝 Swore Division Captain <b>" + cap.icon + " " + escapeHtml(cap.name) + " (+" + cap.troops + " Troops)</b> to your banner!");
  saveCurrentHero(null, false, null);
  renderGameScreen();
}

function startArmyBattle(armyIdx) {
  ensureHeroV3Fields(hero);
  if ((hero.armyWarsToday || 0) >= MAX_DAILY_ARMY_WARS) {
    showRequirementModal("Daily Legion War Limit Reached (3/3 Today)", "🚩⏳", "Your Standing Legion can only march to war <b>3 times per day</b>.", "Return tomorrow (or use Admin Reset)!", "");
    return;
  }
  var ra = RIVAL_ARMIES[armyIdx];
  if (!ra) return;
  var curRat = (hero.guild && hero.guild.rations) ? hero.guild.rations : 0;
  if (hero.quests < 4 || curRat < 20) {
    showRequirementModal("Need 4⚡ Quests & 20🍞 Rations", "🚩🍞", "Marching your Legion to war requires:<br>• <b>4⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>)<br>• <b>20🍞 Granary Rations</b> (You have <b>" + curRat + "🍞</b>)", "Stock Rations via Shire Serfs or Dark Weir Angling!", "");
    return;
  }
  hero.quests -= 4;
  hero.guild.rations -= 20;
  hero.armyWarsToday = (hero.armyWarsToday || 0) + 1;
  var gSum = getGuildArmySummary();
  var scaledEnemyTroops = Math.round(ra.troops * (1 + Math.max(0, hero.level - 10) * 0.04));
  activeArmyBattle = {
    name: ra.name, general: ra.general, icon: ra.icon, bias: ra.bias,
    rewardGold: ra.rewardGold + hero.level * 45, rewardGems: ra.rewardGems,
    heroTroops: gSum.totalTroops, heroMaxTroops: gSum.totalTroops,
    enemyTroops: scaledEnemyTroops, enemyMaxTroops: scaledEnemyTroops,
    strategistUses: 1 + gSum.extraScouts, rallyUses: 1 + gSum.extraRallies,
    scoutedOrder: null,
    lastRoundSummary: "🚩 Horns sound across the warfield! Choose your Legion Doctrine to counter <b>" + escapeHtml(ra.general) + "</b>!"
  };
  renderBattleModal();
}

function scoutEnemyArmy() {
  if (!activeArmyBattle || activeArmyBattle.strategistUses <= 0) return;
  activeArmyBattle.strategistUses--;
  var orders = ["charge", "bow", "magic"];
  var nextOrd = (Math.random() < 0.65 && activeArmyBattle.bias) ? activeArmyBattle.bias : orders[Math.floor(Math.random() * 3)];
  activeArmyBattle.scoutedOrder = nextOrd;
  var counterHint = nextOrd === "charge" ? "🔮 War Magic" : (nextOrd === "bow" ? "🐎 Cavalry Charge" : "🏹 Archer Volley");
  activeArmyBattle.lastRoundSummary = "🕵️ <b>Scoutmaster Report:</b> Enemy is preparing <b>" + nextOrd.toUpperCase() + "</b>! Counter with <b>" + counterHint + "</b>!";
  playSfx("magic");
  renderBattleModal();
}

function rallyHeroArmy() {
  if (!activeArmyBattle || activeArmyBattle.rallyUses <= 0) return;
  activeArmyBattle.rallyUses--;
  var healT = Math.round(activeArmyBattle.heroMaxTroops * 0.25);
  activeArmyBattle.heroTroops = Math.min(activeArmyBattle.heroMaxTroops, activeArmyBattle.heroTroops + healT);
  activeArmyBattle.lastRoundSummary = "📯 <b>War Cry Rally:</b> Restored <b>+" + healT + " Troops</b> to your battle line!";
  playSfx("levelup");
  renderBattleModal();
}

function retreatArmyBattle() {
  activeArmyBattle = null;
  renderBattleModal();
  renderGameScreen();
}

function executeArmyOrder(heroOrd) {
  if (!activeArmyBattle) return;
  var gSum = getGuildArmySummary();
  var orders = ["charge", "bow", "magic"];
  var enemyOrd = activeArmyBattle.scoutedOrder || ((Math.random() < 0.60 && activeArmyBattle.bias) ? activeArmyBattle.bias : orders[Math.floor(Math.random() * 3)]);
  activeArmyBattle.scoutedOrder = null;

  var counterMult = 1.0, enemyMult = 1.0, resTxt = "⚖️ Even Clash!";
  if ((heroOrd === "charge" && enemyOrd === "bow") || (heroOrd === "bow" && enemyOrd === "magic") || (heroOrd === "magic" && enemyOrd === "charge")) {
    counterMult = 1.48; enemyMult = 0.72; resTxt = "🔥 TACTICAL COUNTER! Your " + heroOrd.toUpperCase() + " crushed their " + enemyOrd.toUpperCase() + "!";
  } else if (heroOrd !== enemyOrd) {
    counterMult = 0.76; enemyMult = 1.38; resTxt = "⚠️ OUTMANEUVERED! Enemy " + enemyOrd.toUpperCase() + " countered your " + heroOrd.toUpperCase() + "!";
  }

  var docBon = heroOrd === "charge" ? gSum.chargeBonus : (heroOrd === "bow" ? gSum.bowBonus : gSum.magicBonus);
  var eLoss = Math.max(45, Math.round((activeArmyBattle.heroTroops * 0.26) * counterMult * docBon * (0.90 + Math.random() * 0.22)));
  var hLoss = Math.max(30, Math.round((activeArmyBattle.enemyTroops * 0.22) * enemyMult * (0.90 + Math.random() * 0.22)));

  activeArmyBattle.enemyTroops = Math.max(0, activeArmyBattle.enemyTroops - eLoss);
  activeArmyBattle.heroTroops  = Math.max(0, activeArmyBattle.heroTroops - hLoss);
  activeArmyBattle.lastRoundSummary = resTxt + " (Enemy -" + eLoss + " Troops | You -" + hLoss + " Troops)";
  playSfx(counterMult > 1 ? "crit" : "slash");

  if (activeArmyBattle.enemyTroops <= 0) {
    var wonG = activeArmyBattle.rewardGold, wonGems = activeArmyBattle.rewardGems, eName = activeArmyBattle.name;
    hero.gold += wonG; hero.gems = (hero.gems || 0) + wonGems; hero.armyWins = (hero.armyWins || 0) + 1;
    addHeroFame(45);
    activeArmyBattle = null;
    playSfx("levelup");
    renderBattleModal();
    var wMsg = "🚩🏆 <b>GRAND LEGION VICTORY vs " + escapeHtml(eName) + "!</b><br>Spoils: <b>+" + wonG.toLocaleString() + " Gold, +" + wonGems + "💎 Gems &amp; +45 Court Fame</b>!";
    addLog(wMsg);
    saveCurrentHero("🚩 " + hero.name + "'s Legion crushed " + eName + "!", false, null);
    renderGameScreen();
    showOutcomeModal("🚩 Legion War Victory!", "🚩🏆", hero.name, "#4ade80", wMsg, null);
    return;
  }
  if (activeArmyBattle.heroTroops <= 0) {
    activeArmyBattle = null;
    playSfx("death");
    renderBattleModal();
    hero.guild.stability = Math.max(15, (hero.guild.stability || 75) - 6);
    addLog("🚩💀 Your Legion was forced to retreat (-6% Kingdom Stability).");
    queueSaveHero();
    renderGameScreen();
    return;
  }
  renderBattleModal();
}
'''
}

String buildKingdomChunkC2() {
    return '''
function getFeastScaledCost(fMeta) {
  var lv = hero ? (hero.level || 1) : 1;
  return Math.round(fMeta.baseCost * (1 + (lv - 1) * 0.22));
}

function getTavernDrinkScaledCost() {
  var lv = hero ? Math.max(1, hero.level || 1) : 1;
  return Math.max(260, Math.round(220 + (lv * 95) + Math.pow(lv, 2.05) * 9));
}

// Boar's Head Taproom Reserve Drink: Lowers Stress by 50%, but drinking too many in 2h inflicts 2-Hour Stumbling Drunk debuff!
function orderBoarsHeadTaproomDrink() {
  ensureHeroV3Fields(hero);
  if ((hero.drinksBoughtToday || 0) >= MAX_DAILY_DRINKS) {
    showRequirementModal("Boar's Head Taproom Limit (5/5 Today)", "🥃⏳", "The Innkeeper refuses to pour more than <b>5 goblets of Aged Dragon-Malt Reserve per day</b>.", "Sleep in a bedchamber above the floor or pray at the Confessional!", "");
    return;
  }
  var cost = getTavernDrinkScaledCost();
  if (hero.gold < cost) {
    showRequirementModal(
      "Not Enough Gold for Aged Dragon-Malt Reserve", "🥃💰",
      "A goblet of <b>🥃 Aged Dragon-Malt Reserve</b> at Level " + hero.level + " costs <b style='color:#fbbf24;'>" + cost.toLocaleString() + " Gold</b> (You currently carry <b>" + hero.gold.toLocaleString() + "g</b>).",
      "Patrol regions, burn 10 Trophies at the Huntsman's Exchange, or collect Kingdom Taxes to afford top-shelf spirits!",
      ""
    );
    return;
  }
  var nowMs = Date.now();
  if (!hero.drinkWindowStart || (nowMs - hero.drinkWindowStart) >= TWO_HOURS_MS) {
    hero.drinkWindowStart = nowMs;
    hero.drinksInWindow = 0;
  }
  hero.gold -= cost;
  hero.drinksBoughtToday = (hero.drinksBoughtToday || 0) + 1;
  hero.drinksInWindow = (hero.drinksInWindow || 0) + 1;

  var oldStress = hero.stress || 0;
  var newStress = Math.max(0, oldStress - 50);
  if (oldStress > 0 && newStress === oldStress) newStress = 0;
  hero.stress = newStress;

  var gotDrunkNow = false;
  if (hero.drinksInWindow === 2 && Math.random() < 0.55) gotDrunkNow = true;
  else if (hero.drinksInWindow >= 3) gotDrunkNow = true;

  var drunkMsg = "";
  if (gotDrunkNow) {
    hero.drunkUntil = nowMs + TWO_HOURS_MS;
    playSfx("death");
    drunkMsg = "<br><br>🍺💫 <b style='color:#ef4444;'>OVERINDULGED — 2-HOUR STUMBLING DRUNK DEBUFF!</b><br>Goblet #" + hero.drinksInWindow + " within 2 hours went straight to your head! For the next <b>2 Hours</b>, you suffer <b style='color:#fca5a5;'>-15% Hit Accuracy, -12% Dodge &amp; -15% Effective Wits</b>!";
  } else {
    playSfx("coin");
    drunkMsg = "<br>• 🍺 <b>Taproom Tolerance (" + hero.drinksInWindow + " Goblet(s) in last 2h):</b> <i style='color:#fde68a;'>Careful—ordering another goblet within 2 hours risks a <b>2-Hour Stumbling Drunk</b> debuff (-15% Hit, -12% Dodge &amp; -15% Wits)!</i>";
  }

  var dMsg = "🥃🔥 <b>AGED DRAGON-MALT RESERVE IMBIBED (" + hero.drinksBoughtToday + "/" + MAX_DAILY_DRINKS + " Today • -" + cost.toLocaleString() + "g • " + hero.gold.toLocaleString() + "g Left):</b><br>" +
    "Liquid dragon-amber warmed your chest, cutting your Stress by <b>-50%</b> (<b>" + oldStress + "% ➔ " + hero.stress + "% Stress</b>)!" + drunkMsg;
  addLog(dMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal(gotDrunkNow ? "🍺 Stumbling Drunk (-50% Stress)!" : "🥃 Nerves Steeled (-50% Stress)!", gotDrunkNow ? "🍺💫" : "🥃🔥", null, gotDrunkNow ? "#ef4444" : "#4ade80", dMsg, "inn");
}

// ============================================================================
// NEW CITADEL SANCTUM: THE ASTRAL LEY-WELL (FULL ENERGY RESTORE • MAX 2/DAY!)
// ============================================================================
function getAstralLeyWellCosts() {
  var lv = hero ? Math.max(1, hero.level || 1) : 1;
  return {
    gold: Math.max(1200, Math.round(900 + (lv * 165) + Math.pow(lv, 2.08) * 14)),
    gems: 4,
    trophies: 12
  };
}

function openAstralLeyWellModal() {
  ensureHeroV3Fields(hero);
  if (hero.leyWellUsedToday === undefined) hero.leyWellUsedToday = 0;
  var usesLeft = Math.max(0, 2 - (hero.leyWellUsedToday || 0));
  var req = getAstralLeyWellCosts();
  var totMats = getTotalMaterialsCount();
  var myGems = hero.gems || 0;
  var canUse = usesLeft > 0 && hero.quests < hero.maxQuests && hero.gold >= req.gold && myGems >= req.gems && totMats >= req.trophies;

  showPopupModal(
    '<div style="font-size:42px;">⚡🔥🌌</div>' +
    '<div style="font-size:19.5px;font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">The Astral Ley-Well &amp; Soul-Brazier</div>' +
    '<div style="font-size:12px;color:#7dd3fc;margin-bottom:8px;">⚡ Current Energy: <b style="color:#4ade80;">' + hero.quests + ' / ' + hero.maxQuests + '⚡</b> • Daily Restorations Left: <b style="color:#fde047;">' + usesLeft + ' / 2 Today</b></div>' +
    '<div class="lore-subtitle-box">Beneath the High Citadel&apos;s star-spire roars a raw conduit of First-Age ley-energy. By casting a heavy tribute of <b>Gold, Dragon Gems, and Monster Trophies</b> into the brazier, you can surge your stamina back to <b>100% Full Max Quest Energy</b> up to <b>2 times per day</b>!</div>' +
    '<div style="background:#0b0811;border:2px solid #c5a059;border-radius:6px;padding:12px;margin:10px 0;text-align:left;font-size:13px;line-height:1.65;">' +
      '<div style="font-weight:900;color:#d4af37;font-family:Cinzel,serif;margin-bottom:4px;">🔥 Required Ley-Well Offering (100% Energy Surge):</div>' +
      '<div>• 💰 <b>Royal Bullion:</b> <b style="color:' + (hero.gold >= req.gold ? '#4ade80' : '#f87171') + ';">' + hero.gold.toLocaleString() + ' / ' + req.gold.toLocaleString() + ' Gold</b></div>' +
      '<div>• 💎 <b>Dragon Gems:</b> <b style="color:' + (myGems >= req.gems ? '#4ade80' : '#f87171') + ';">' + myGems + ' / ' + req.gems + '💎 Dragon Gems</b></div>' +
      '<div>• 📦 <b>Monster Trophies:</b> <b style="color:' + (totMats >= req.trophies ? '#4ade80' : '#f87171') + ';">' + totMats + ' / ' + req.trophies + ' Trophies</b></div>' +
      '<div>• 📅 <b>Daily Sanctum Limit:</b> <b style="color:' + (usesLeft > 0 ? '#4ade80' : '#f87171') + ';">' + usesLeft + ' / 2 Remaining Today</b></div>' +
    '</div>' +
    '<button class="btn ' + (canUse ? 'btn-shine' : 'btn-locked') + '" style="width:100%;padding:12px;font-size:14px;" onclick="channelAstralLeyWellEnergy()">' + (usesLeft <= 0 ? '⏳ Daily Ley-Well Cap Reached (2/2 Today)' : (hero.quests >= hero.maxQuests ? '✅ Already at 100% Full Energy (' + hero.quests + '/' + hero.maxQuests + '⚡)' : ('⚡🔥 Surge to 100% Full Energy (-' + req.gold.toLocaleString() + 'g, -' + req.gems + '💎, -' + req.trophies + ' Trophies)'))) + '</button>' +
    '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Leave the Astral Ley-Well</button>'
  );
}

function channelAstralLeyWellEnergy() {
  ensureHeroV3Fields(hero);
  if (hero.leyWellUsedToday === undefined) hero.leyWellUsedToday = 0;
  if (hero.leyWellUsedToday >= 2) {
    showRequirementModal("Astral Ley-Well Daily Limit Reached (2/2 Today)", "⚡⏳", "Mortal veins can only channel the raw Astral Ley-Well <b>2 times per day</b> without burning to ash.", "Return after midnight rollover (or use Admin Reset) for 2 fresh Ley-Well surges!", "");
    return;
  }
  if (hero.quests >= hero.maxQuests) {
    showGothicToast("⚡ Your Quest Energy is already at 100% (" + hero.quests + "/" + hero.maxQuests + "⚡)!");
    return;
  }
  var req = getAstralLeyWellCosts();
  var totMats = getTotalMaterialsCount();
  var myGems = hero.gems || 0;
  var missing = [];
  if (hero.gold < req.gold) missing.push("Need <b>" + req.gold.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)");
  if (myGems < req.gems) missing.push("Need <b>" + req.gems + "💎 Dragon Gems</b> (You have <b>" + myGems + "💎</b>)");
  if (totMats < req.trophies) missing.push("Need <b>" + req.trophies + " Monster Trophies</b> (You have <b>" + totMats + " Trophies</b>)");
  if (missing.length > 0) {
    showRequirementModal(
      "Insufficient Tribute for Astral Ley-Well", "⚡🔥",
      missing.map(function(m) { return "• " + m; }).join("<br>"),
      "Withdraw Gems from your 🏦 Reliquary Vault, collect Kingdom Taxes, or patrol realms for Monster Trophies!",
      ""
    );
    return;
  }
  hero.gold -= req.gold;
  hero.gems -= req.gems;
  consumeAnyMaterials(req.trophies);
  hero.leyWellUsedToday = (hero.leyWellUsedToday || 0) + 1;
  var gainedE = hero.maxQuests - hero.quests;
  hero.quests = hero.maxQuests;
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("void", 48);
  var wMsg = "⚡🔥 <b style='color:#fde047;'>ASTRAL LEY-WELL CHANNELED (" + hero.leyWellUsedToday + "/2 Today • -" + req.gold.toLocaleString() + "g, -" + req.gems + "💎, -" + req.trophies + " Trophies)!</b><br>" +
    "Star-fire erupted from the Soul-Brazier, surging <b>+" + gainedE + "⚡ Quest Stamina</b> and restoring you to <b style='color:#4ade80;'>100% FULL ENERGY (" + hero.quests + " / " + hero.maxQuests + "⚡)</b>!";
  addLog(wMsg);
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("⚡ 100% Quest Energy Restored (" + hero.quests + "/" + hero.maxQuests + "⚡)!", "⚡🔥", null, "#fde047", wMsg, null);
}

