}

// Plague-Doctor's Leech Ward (2/Day): Cures active diseases on Hero AND any infected Sellsword Recruits!
function undergoPlagueDoctorLeechWard() {
  ensureHeroV3Fields(hero);
  if ((hero.leechesUsedToday || 0) >= 2) {
    showRequirementModal(
      "Plague-Doctor Ward Limit (2/2 Today)", "🩸⏳",
      "The Plague-Surgeon can only administer <b>2 Leech &amp; Bloodletting treatments per day</b>.",
      "Visit <b>💎🩺 Sister Vespera in the Citadel</b> (15💎 Dragon Gems per disease, no daily limit) or return tomorrow!",
      '<button class="btn btn-shine" style="flex:1;" onclick="if(window.openSisterVesperaModal)openSisterVesperaModal()">💎 Visit Sister Vespera</button>'
    );
    return;
  }
  var totalPartyDis = countTotalPartyDiseases(hero);
  if (totalPartyDis === 0) {
    showGothicToast("✅ Neither your Hero nor your Recruits have any active physical Diseases!");
    return;
  }
  var cost = Math.max(160, hero.level * 35);
  var totMats = getTotalMaterialsCount();
  if (hero.gold < cost || totMats < 1) {
    showRequirementModal("Need " + cost.toLocaleString() + "g & 1 Monster Trophy for Leech Ward", "🦠🩸", "Purging physical diseases at the Plague-Doctor's Leech Ward requires:<br>• <b>" + cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)<br>• <b>1 Monster Trophy</b> (You have <b>" + totMats + " Trophies</b>)", "Patrol any region for 1 Monster Trophy and Gold!", "");
    return;
  }
  hero.gold -= cost;
  consumeAnyMaterials(1);
  hero.leechesUsedToday = (hero.leechesUsedToday || 0) + 1;
  var curedList = [];
  if (Array.isArray(hero.diseases)) {
    hero.diseases.forEach(function(d) { if (d) curedList.push(hero.name + " (" + d.name + ")"); });
    hero.diseases = [];
  }
  if (Array.isArray(hero.mercenaries)) {
    hero.mercenaries.forEach(function(m) {
      if (m && m.disease) {
        curedList.push(m.name + " (" + m.disease.name + ")");
        m.disease = null;
      }
    });
  }
  syncHeroVitalityMaxHp(hero);
  var hpGain = Math.round(hero.maxHp * 0.20);
  hero.hp = Math.min(hero.maxHp, hero.hp + hpGain);
  playSfx("levelup");
  var lMsg = "🦠🩸 <b>PLAGUE-DOCTOR LEECH WARD COMPLETE (" + hero.leechesUsedToday + "/2 Today • -" + cost.toLocaleString() + "g, -1 Trophy):</b><br>Medicinal leeches and alchemical poultices purged <b>" + escapeHtml(curedList.join(", ")) + "</b> and restored <b>+" + hpGain + " HP</b>!";
  addLog(lMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🦠 Party Diseases Purged!", "🦠🩸", null, "#4ade80", lMsg, "sanctuary");
}

function depositVaultGold() {
  ensureHeroV3Fields(hero);
  var amt = parseInt((document.getElementById("vaultGoldInput") || {}).value || "0", 10);
  if (isNaN(amt) || amt <= 0 || hero.gold < amt) {
    showGothicToast("⚠️ Enter a valid Gold amount up to " + hero.gold.toLocaleString() + "g!");
    return;
  }
  var netAmt = Math.max(1, Math.round(amt * 0.90));
  hero.gold -= amt;
  hero.vault.gold = (hero.vault.gold || 0) + netAmt;
  playSfx("coin");
  addLog("🏦 Deposited <b>" + netAmt.toLocaleString() + "g</b> into Personal Vault (10% Guard Fee).");
  queueDeltaSaveHero();
  openTownFacilityModal("post");
  renderGameScreen();
}

function withdrawVaultGold() {
  ensureHeroV3Fields(hero);
  var amt = parseInt((document.getElementById("vaultGoldInput") || {}).value || "0", 10);
  var avail = (hero.vault && hero.vault.gold) ? hero.vault.gold : 0;
  if (isNaN(amt) || amt <= 0) amt = avail;
  if (amt <= 0 || amt > avail) {
    showGothicToast("⚠️ Not enough Gold in Personal Vault!");
    return;
  }
  hero.vault.gold -= amt;
  hero.gold += amt;
  playSfx("coin");
  addLog("🏦 Withdrew <b>+" + amt.toLocaleString() + "g</b> from Personal Vault.");
  queueDeltaSaveHero();
  openTownFacilityModal("post");
  renderGameScreen();
}

function depositVaultGems() {
  ensureHeroV3Fields(hero);
  var qty = parseInt((document.getElementById("vaultGemInput") || {}).value || "0", 10);
  var curLocked = hero.vault.gems || 0;
  if (isNaN(qty) || qty <= 0 || (hero.gems || 0) < qty || (curLocked + qty) > 20) {
    showGothicToast("⚠️ Enter 1–" + Math.min(hero.gems || 0, 20 - curLocked) + " Gems (Max 20 Vault Gems)!");
    return;
  }
  hero.gems -= qty;
  hero.vault.gems = curLocked + qty;
  if (!hero.vault.gemsLockedEpoch) hero.vault.gemsLockedEpoch = Date.now();
  playSfx("magic");
  addLog("🏦💎 Sealed <b>" + qty + "💎 Dragon Gem(s)</b> in Personal Vault (" + hero.vault.gems + "/20💎).");
  queueDeltaSaveHero();
  openTownFacilityModal("post");
  renderGameScreen();
}

function withdrawVaultGems() {
  ensureHeroV3Fields(hero);
  var qty = parseInt((document.getElementById("vaultGemInput") || {}).value || "0", 10);
  var avail = (hero.vault && hero.vault.gems) ? hero.vault.gems : 0;
  if (isNaN(qty) || qty <= 0) qty = avail;
  if (qty <= 0 || qty > avail) {
    showGothicToast("⚠️ No locked Gems to withdraw!");
    return;
  }
  hero.vault.gems -= qty;
  if (hero.vault.gems <= 0) hero.vault.gemsLockedEpoch = 0;
  hero.gems = (hero.gems || 0) + qty;
  playSfx("coin");
  addLog("🏦💎 Withdrew <b>+" + qty + "💎 Dragon Gem(s)</b> from Personal Vault.");
  queueDeltaSaveHero();
  openTownFacilityModal("post");
  renderGameScreen();
}

function playCatacombGemRoulette() {
  ensureHeroV3Fields(hero);
  if ((hero.rouletteSpinsToday || 0) >= 2) {
    showRequirementModal("Catacomb Gem Roulette Limit (2/2 Today)", "🎰⏳", "You can only spin the Catacomb Gem Roulette <b>2 times per day</b>.", "Return tomorrow (or use Admin Reset)!", "");
    return;
  }
  if (!hero.vault || (hero.vault.gems || 0) <= 0 || hero.quests < 2) {
    showRequirementModal("Need 1 Locked Vault Gem & 2⚡ Quests", "🎰💎", "Spinning the Catacomb Gem Roulette requires at least <b>1💎 Locked Gem</b> in your Personal Vault (Have " + ((hero.vault && hero.vault.gems) || 0) + "💎) and <b>2⚡ Quests</b> (Have " + hero.quests + "⚡).", "Lock a Dragon Gem in your Personal Vault first!", "");
    return;
  }
  hero.quests -= 2;
  hero.rouletteSpinsToday = (hero.rouletteSpinsToday || 0) + 1;
  hero.vault.gemsLockedEpoch = Date.now();
  if (Math.random() < 0.48) {
    hero.vault.gems = Math.min(20, hero.vault.gems + 1);
    playSfx("levelup");
    addLog("🎰💎 <b>Catacomb Gem Roulette WON (" + hero.rouletteSpinsToday + "/2 Today):</b> +1💎 Vault Gem &amp; refreshed 7-Day Lock!");
    showOutcomeModal("🎰 Gem Roulette Jackpot (+1💎)!", "🎰💎", null, "#4ade80", "Refreshed your 7-Day Vault Gem lock and won <b>+1💎 Dragon Gem</b>!", "post");
  } else {
    hero.vault.gems -= 1;
    hero.vault.dulledGems = (hero.vault.dulledGems || 0) + 1;
    playSfx("death");
    addLog("🎰🪨 <b>Catacomb Gem Roulette Drained (" + hero.rouletteSpinsToday + "/2 Today):</b> 1 Gem turned into <b>1🪨 Dulled Slag</b> (7-Day Lock refreshed)!");
    showOutcomeModal("🎰 Gem Drained into Slag!", "🎰🪨", null, "#ef4444", "1 Vault Gem drained into <b>1🪨 Dulled Slag</b> (use with Brom or Golems), but your remaining Gems' 7-Day timer is refreshed!", "post");
  }
  queueDeltaSaveHero();
  renderGameScreen();
}

function depositVaultItem(idx) {
  ensureHeroV3Fields(hero);
  var itm = hero.inventory[idx];
  if (!itm) return;
  if (itm.locked) {
    showGothicToast("🔒 Unlock this item first before moving it to your Vault!");
    return;
  }
  if ((hero.vault.items ? hero.vault.items.length : 0) >= 25) {
    showGothicToast("⚠️ Personal Vault is full (25/25 items)!");
    return;
  }
  hero.inventory.splice(idx, 1);
  hero.vault.items.push(itm);
  playSfx("coin");
  addLog("🏦 Stored <b>" + escapeHtml(itm.name) + "</b> in Personal Vault.");
  queueSaveHero();
  renderGameScreen();
}

function withdrawVaultItem(idx) {
  ensureHeroV3Fields(hero);
  if (!hero.vault || !hero.vault.items || !hero.vault.items[idx]) return;
  if (hero.inventory.length >= 30) {
    showGothicToast("⚠️ Backpack is full (30/30)!");
    return;
  }
  var itm = hero.vault.items.splice(idx, 1)[0];
  hero.inventory.push(itm);
  playSfx("coin");
  addLog("🏦 Withdrew <b>" + escapeHtml(itm.name) + "</b> from Personal Vault.");
  queueSaveHero();
  openTownFacilityModal("post");
  renderGameScreen();
}

function brewAlchemicalMixture() {
  ensureHeroV3Fields(hero);
  if ((hero.alembicUsedToday || 0) >= MAX_DAILY_ALEMBIC) {
    showRequirementModal("Thermal Alembic Limit Reached (2/2 Today)", "🧪⏳", "You can only distill <b>2 Thermal Alembic mixtures per day</b>.", "Return tomorrow (or use Admin Reset)!", "");
