  var totMats = getTotalMaterialsCount();
  if (hero.quests < 2 || totMats < 2) {
    showRequirementModal("Need 2⚡ Quests & 2 Monster Trophies", "🧪🔥", "Distilling a Thermal Alembic mixture requires:<br>• <b>2⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>)<br>• <b>2 Monster Trophies</b> (You have <b>" + totMats + " Trophies</b>)", "Patrol regions for Monster Trophies!", "");
    return;
  }
  hero.quests -= 2;
  hero.alembicUsedToday = (hero.alembicUsedToday || 0) + 1;
  consumeAnyMaterials(2);
  var chk = rollContestedStatCheck("wits", 17, hero.unlockedArea || 1, false);
