    addLog(winMsg);
    queueDeltaSaveHero();
    renderGameScreen();
    showOutcomeModal("🧪 Alembic Distillation Succeeded!", "🧪✨", null, "#4ade80", winMsg, "sanctuary");
  } else {
    var singe = Math.max(10, Math.round(hero.maxHp * 0.14));
    hero.hp = Math.max(1, hero.hp - singe);
    hero.potions = (hero.potions || 0) + 1;
    var stNote = addHeroStress(12);
    playSfx("slash");
    var failMsg = "💥🧪 <b>Alembic Boil-Over (" + chk.chance + "% Wits Odds • " + hero.alembicUsedToday + "/2 Today):</b><br>The retort cracked (-" + singe + " HP &amp; +12% Stress), salvaging only <b>+1🧪 Potion</b>!" + stNote;
    addLog(failMsg);
    queueDeltaSaveHero();
    renderGameScreen();
    showOutcomeModal("💥 Alembic Retort Cracked!", "💥🧪", null, "#ef4444", failMsg, "sanctuary");
  }
}

