var fishTimer = null, fishPos = 15, fishVel = 5, hookPos = 40;
var slotReels = ["🗡️", "💎", "🐉"], slotSpinning = [false, false, false], slotTimers = [null, null, null];
var dicePlayerSum = 0, diceHouseSum = 0, diceActive = false;

function stopActiveMiniGames() {
  if (fishTimer) { clearInterval(fishTimer); fishTimer = null; }
  for (var i = 0; i < 3; i++) { if (slotTimers[i]) { clearInterval(slotTimers[i]); slotTimers[i] = null; } }
}

function openMiniGameModal(gameType) {
  ensureHeroV3Fields(hero);
  if (checkWantedHoundTavernInvasion() || !checkMiniGameDailyCap()) return;
  window.currentMiniGameModal = gameType;

  if (gameType === "joust") {
    var rows = JOUST_OPPONENTS.map(function(op, idx) {
      var chk = getContestedRollOdds("guts", 14 + idx * 2, Math.max(hero.unlockedArea || 1, Math.ceil(op.minLv / 6)), false);
      return '<div class="item-row" style="text-align:left;">' +
        '<div style="flex:1;"><b>' + op.icon + ' ' + escapeHtml(op.name) + ' (Req Lv ' + op.minLv + '+)</b><div style="font-size:11.5px;color:#e5dec9;">Wager: ' + op.wager + 'g (Have ' + hero.gold.toLocaleString() + 'g) • Prize: +' + (op.wager * 2) + 'g &amp; +' + op.rewardFame + ' Fame • Odds: <b style="color:#fde047;">' + chk + '%</b></div></div>' +
        '<button class="btn ' + (hero.level >= op.minLv && hero.gold >= op.wager ? 'btn-gold' : 'btn-locked') + '" onclick="runJoustPass(' + idx + ')">🏇 Tilt (-5⚡)</button></div>';
    }).join('');
    showPopupModal(
      '<div class="joust-tilt-stage" id="joustStageBox"><div class="joust-barrier"></div><div class="joust-knight-left">🏇</div><div class="joust-clash-spark">💥✨</div><div class="joust-knight-right">🏇</div></div>' +
      '<div style="font-size:18px;font-weight:900;color:#d4af37;font-family:Cinzel,serif;margin-bottom:4px;">🏇 The Grand Tourney Lists</div>' +
      '<div style="font-size:11.5px;color:#fde68a;margin-bottom:6px;">⚡ Your Quests: <b>' + hero.quests + '/' + hero.maxQuests + '⚡</b> • 💰 Your Gold: <b>' + hero.gold.toLocaleString() + 'g</b></div>' +
      rows +
      '<button class="btn" style="width:100%;margin-top:8px;" onclick="openTownFacilityModal(&#39;wagers&#39;)">⬅️ Back to Tourney Grounds</button>'
    );
  } else if (gameType === "fishing") {
    if (hero.quests < 3) { showRequirementModal("Need 3⚡ Quests for Angling", "🎣⚡", "Requires 3⚡ Quests (You have " + hero.quests + "⚡).", "Wait for the 45m tick!", ""); return; }
    hero.quests -= 3;
    hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
    fishPos = 20; hookPos = 38;
    showPopupModal(
      '<div style="font-size:18px;font-weight:900;color:#7dd3fc;font-family:Cinzel,serif;">🎣 The King&apos;s Dark Weir (+8% HP, -10% Stress &amp; +8🍞 Rations)</div>' +
      '<div style="font-size:11.5px;color:#e5dec9;margin-top:2px;">🍞 Current Granary Rations: <b>' + ((hero.guild && hero.guild.rations) || 0) + '🍞</b></div>' +
      '<div class="fishing-pond-track"><div id="fishHookBox" class="fishing-hook-zone" style="left:38%;width:24%;"></div><div id="fishSpriteBox" class="fishing-fish-sprite" style="left:20%;">🐟</div></div>' +
      '<button class="btn btn-shine" style="width:100%;padding:12px;" onclick="strikeFishingRod()">🎣 SET HOOK NOW!</button>'
    );
    if (fishTimer) clearInterval(fishTimer);
    fishTimer = setInterval(function() {
      fishPos += fishVel;
      if (fishPos >= 84 || fishPos <= 4) fishVel = -fishVel;
      var fEl = document.getElementById("fishSpriteBox");
      if (fEl) fEl.style.left = fishPos + "%";
    }, 65);
  } else if (gameType === "slots") {
    var wager = Math.max(100, hero.level * 25);
    if (hero.quests < 3 || hero.gold < wager) { showRequirementModal("Need 3⚡ Quests & " + wager + "g", "🎡💰", "Requires 3⚡ Quests (Have " + hero.quests + "⚡) and " + wager + " Gold (Have " + hero.gold.toLocaleString() + "g).", "Collect taxes or patrol first!", ""); return; }
    hero.quests -= 3; hero.gold -= wager;
    hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
    var syms = ["🗡️", "🛡️", "💎", "🐉", "👑"];
    slotSpinning = [true, true, true];
    showPopupModal(
      '<div style="font-size:18px;font-weight:900;color:#c084fc;font-family:Cinzel,serif;">🎡 The Wheel of Fate (Wager: ' + wager + 'g • Remaining Gold: ' + hero.gold.toLocaleString() + 'g)</div>' +
      '<div class="slot-machine-frame">' +
        [0, 1, 2].map(function(i) { return '<div class="slot-column"><div id="slotReel_' + i + '" class="slot-reel reel-spinning">💎</div><button class="btn btn-gold" onclick="stopSlotReel(' + i + ',' + wager + ')">⏹️ Stop</button></div>'; }).join('') +
      '</div>'
    );
    [0, 1, 2].forEach(function(i) {
      slotTimers[i] = setInterval(function() {
        slotReels[i] = syms[Math.floor(Math.random() * syms.length)];
        var rEl = document.getElementById("slotReel_" + i);
        if (rEl) rEl.textContent = slotReels[i];
      }, 95);
    });
  } else if (gameType === "dice") {
    var dWager = Math.max(120, hero.level * 30);
    if (hero.quests < 3 || hero.gold < dWager) { showRequirementModal("Need 3⚡ Quests & " + dWager + "g", "🥤🎲", "Requires 3⚡ Quests (Have " + hero.quests + "⚡) and " + dWager + " Gold (Have " + hero.gold.toLocaleString() + "g).", "Patrol realms first!", ""); return; }
    hero.quests -= 3; hero.gold -= dWager;
    hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
    dicePlayerSum = Math.floor(Math.random() * 10) + 4;
    diceHouseSum = Math.floor(Math.random() * 8) + 8;
    diceActive = true;
    renderBonesOf21Modal(dWager);
  }
}

function runJoustPass(idx) {
  if (!checkMiniGameDailyCap()) return;
  var op = JOUST_OPPONENTS[idx];
  if (!op || hero.quests < 5 || hero.level < op.minLv || hero.gold < op.wager) {
    showRequirementModal("Need 5⚡ Quests, Lv " + (op ? op.minLv : 1) + "+ & Wager Gold", "🏇💰", "Check your Quest Stamina (Have " + hero.quests + "⚡), Level (Lv " + hero.level + "), and Gold (Have " + hero.gold.toLocaleString() + "g)!", "Rest at the Inn or collect Taxes!", "");
    return;
  }
  hero.quests -= 5;
  hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
  var stg = document.getElementById("joustStageBox");
  if (stg) stg.classList.add("charging");
  playSfx("crit");
  setTimeout(function() {
    var chk = rollContestedStatCheck("guts", 14 + idx * 2, Math.max(hero.unlockedArea || 1, Math.ceil(op.minLv / 6)), false);
    if (chk.passed) {
      hero.gold += op.wager;
      addHeroFame(op.rewardFame);
      if (hero.spouse) hero.spouse.love = Math.min(100, (hero.spouse.love || 100) + 15);
      playSfx("levelup");
      showOutcomeModal("🏇 Jousting Triumph (" + chk.chance + "% Odds)!", "🏇🏆", op.name, "#4ade80", "Unhorsed <b>" + escapeHtml(op.name) + "</b>! Won <b>+" + op.wager.toLocaleString() + "g, +" + op.rewardFame + " Fame</b>" + (hero.spouse ? " &amp; +15% ❤️ Wife Love!" : "!"), "wagers");
    } else {
      hero.gold = Math.max(0, hero.gold - op.wager);
      var dmg = Math.max(12, Math.round(hero.maxHp * 0.18));
      hero.hp = Math.max(1, hero.hp - dmg);
      var stNote = addHeroStress(12);
      playSfx("slash");
      showOutcomeModal("🏇 Unhorsed in the Lists (" + chk.chance + "% Odds)!", "🏇💥", op.name, "#ef4444", "Lost <b>-" + op.wager.toLocaleString() + "g</b>, took <b>-" + dmg + " HP &amp; +12% Stress</b>!" + stNote, "wagers");
    }
    queueDeltaSaveHero();
    renderGameScreen();
  }, 680);
}

function strikeFishingRod() {
  stopActiveMiniGames();
  if (fishPos >= 34 && fishPos <= 66) {
    var hpGain = Math.round(hero.maxHp * 0.08);
    hero.hp = Math.min(hero.maxHp, hero.hp + hpGain);
    hero.stress = Math.max(0, (hero.stress || 0) - 10);
    hero.guild.rations = (hero.guild.rations || 0) + 8;
    var gFound = 65 + hero.level * 18;
    hero.gold += gFound;
    playSfx("levelup");
    showOutcomeModal("🎣 Caught Silver Weir-Trout!", "🐟✨", null, "#4ade80", "Restored <b>+" + hpGain + " HP</b>, calmed <b>-10% Stress</b>, stocked <b>+8🍞 Rations (Now " + hero.guild.rations + "🍞)</b> &amp; found <b>+" + gFound + "g</b>!", "wagers");
  } else {
    playSfx("slash");
    showOutcomeModal("🎣 Line Snapped!", "🐟💦", null, "#ef4444", "The trout slipped off the hook!", "wagers");
  }
  queueDeltaSaveHero();
  renderGameScreen();
}

function stopSlotReel(idx, wager) {
  if (!slotSpinning[idx]) return;
  slotSpinning[idx] = false;
  if (slotTimers[idx]) { clearInterval(slotTimers[idx]); slotTimers[idx] = null; }
  var rEl = document.getElementById("slotReel_" + idx);
  if (rEl) rEl.classList.remove("reel-spinning");
  playSfx("coin");
  if (!slotSpinning[0] && !slotSpinning[1] && !slotSpinning[2]) {
    var a = slotReels[0], b = slotReels[1], c = slotReels[2];
    if (a === b && b === c) {
      var winG = wager * 8;
      hero.gold += winG; hero.gems = (hero.gems || 0) + 2;
      playSfx("levelup");
      showOutcomeModal("🎡 TRIPLE RUNE JACKPOT!", a + b + c, null, "#fde047", "Won <b>+" + winG.toLocaleString() + "g &amp; +2💎 Dragon Gems</b>!", "wagers");
    } else if (a === b || b === c || a === c) {
      var pairG = Math.round(wager * 2.2);
      hero.gold += pairG;
      playSfx("coin");
      showOutcomeModal("🎡 Rune Pair Matched!", a + " " + b + " " + c, null, "#4ade80", "Won <b>+" + pairG.toLocaleString() + " Gold</b>!", "wagers");
    } else {
      showOutcomeModal("🎡 No Match (" + a + " " + b + " " + c + ")", "🎡🌑", null, "#9c8f7a", "Better fortune on the next spin!", "wagers");
    }
    queueDeltaSaveHero();
    renderGameScreen();
  }
}

function renderBonesOf21Modal(wager) {
  showPopupModal(
    '<div style="font-size:18px;font-weight:900;color:#86efac;font-family:Cinzel,serif;">🥤🎲 Gregor&apos;s Bones of Twenty-One (Wager: ' + wager + 'g)</div>' +
    '<div style="margin:10px 0;font-size:15px;">Your Bones: <b style="color:#fde047;">' + dicePlayerSum + ' / 21</b> • Gregor Shows: <b>' + diceHouseSum + '</b></div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn btn-gold" style="flex:1;" onclick="hitBonesOf21(' + wager + ')"><span class="dice-cup-shake">🥤🎲</span> Roll Another Bone</button>' +
      '<button class="btn btn-emerald" style="flex:1;" onclick="standBonesOf21(' + wager + ')">✋ Stand at ' + dicePlayerSum + '</button>' +
    '</div>'
  );
}

function hitBonesOf21(wager) {
  if (!diceActive) return;
  dicePlayerSum += Math.floor(Math.random() * 6) + 1;
  playSfx("coin");
  if (dicePlayerSum > 21) {
    diceActive = false;
    playSfx("death");
    showOutcomeModal("🎲 Bust at " + dicePlayerSum + "!", "🎲💀", null, "#ef4444", "Exceeded 21 and lost your wager!", "wagers");
    queueDeltaSaveHero(); renderGameScreen(); return;
  }
  renderBonesOf21Modal(wager);
}

function standBonesOf21(wager) {
  if (!diceActive) return;
  diceActive = false;
  while (diceHouseSum < 17) { diceHouseSum += Math.floor(Math.random() * 6) + 1; }
  if (diceHouseSum > 21 || dicePlayerSum >= diceHouseSum) {
    var winG = Math.round(wager * 2.2);
    hero.gold += winG;
    playSfx("levelup");
    showOutcomeModal("🎲 Bones of Twenty-One Won (" + dicePlayerSum + " vs " + diceHouseSum + ")!", "🎲🏆", null, "#4ade80", "Collected <b>+" + winG.toLocaleString() + " Gold</b>!", "wagers");
  } else {
    playSfx("slash");
    showOutcomeModal("🎲 House Wins (" + diceHouseSum + " vs " + dicePlayerSum + ")!", "🎲💀", null, "#ef4444", "Gregor swept the bones!", "wagers");
  }
  queueDeltaSaveHero();
  renderGameScreen();
}
'''
}

