function previewInnLodgingRoom(tierId) {
  selectedLodgingPreview = tierId;
  var box = document.getElementById("innRoomVectorPreviewBox");
  if (box) box.innerHTML = renderSleepingRoomVectorSvg(tierId);
}

// Above-Floor Sleep Stress Relief: Floor gives 0% Stress relief; Cot/Suite/Palace ease Stress immediately on check-in AND purge Stress on wake-up!
async function bedDownForLogout(tierId) {
  ensureHeroV3Fields(hero);
  selectedLodgingPreview = tierId;
  if (activeCombat || activeDelve || activeStory) {
    showRequirementModal("Active Encounter in Progress", "⚔️🛌", "Finish your current battle or delve before bedding down for offline lodging!", "Complete or flee your current encounter first.", "");
    return;
  }
  var t = LODGING_TIERS.find(function(x) { return x.id === tierId; });
  if (!t) return;
  var chk = checkLodgingTierUnlocked(tierId);
  if (!chk.ok) {
    showRequirementModal("Inn Room Upgrade Locked: " + t.name, t.icon, chk.reason, "Raise your <b>Hero Level</b>, earn <b>🏅 Court Fame</b> (via Warrants &amp; Jousting), or train <b>🔮 Wits</b> to unlock higher-tier Inn suites!", "");
    return;
  }
  var cost = getLodgingCost(tierId);
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for " + t.name, t.icon, "Checking into <b>" + escapeHtml(t.name) + "</b> at Level " + hero.level + " costs <b style='color:#fbbf24;'>" + cost.toLocaleString() + " Gold</b> (You currently have <b>" + hero.gold.toLocaleString() + "g</b>).", "Choose a lower-cost lodging option or earn Gold from patrols and Kingdom Taxes!", "");
    return;
  }
  hero.gold -= cost;
  var checkinStressRelief = (t.id === "mansion") ? 35 : ((t.id === "inn") ? 25 : ((t.id === "cot") ? 15 : 0));
  if (checkinStressRelief > 0) {
    hero.stress = Math.max(0, (hero.stress || 0) - checkinStressRelief);
  }
  hero.sleepingAt = { type: t.id, name: t.name, icon: t.icon, startedEpoch: Date.now() };
  addLog("🛌 <b>Bedded Down at " + t.icon + " " + escapeHtml(t.name) + " (-" + cost.toLocaleString() + "g):</b> " + (checkinStressRelief > 0 ? ("Soothing bedchamber eased -" + checkinStressRelief + "% Stress immediately (Now " + (hero.stress || 0) + "%); ") : "Cold floorboards offer 0% Stress relief; ") + "sleep 2+ hours for full perks!");
  await saveCurrentHero("🛌 " + hero.name + " bedded down at " + t.name + ".", false, null);
  switchScreen("slots");
  showPopupModal(
    '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:8px;">🛌 Bedded Down in ' + escapeHtml(t.name) + '</div>' +
    renderSleepingRoomVectorSvg(t.id) +
    '<div style="background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:10px;margin-bottom:10px;font-size:12.5px;color:#e5dec9;text-align:left;">' +
      '<div>• <b>Room Selected:</b> ' + t.icon + ' <b>' + escapeHtml(t.name) + '</b> (-' + cost.toLocaleString() + 'g)</div>' +
      '<div>• <b>Bedchamber Stress Relief:</b> ' + (t.id === "floor" ? '<span style="color:#f87171;">0% on Cold Floor (Upgrade to Straw Cot or Suite to heal Stress while sleeping!)</span>' : ('<span style="color:#4ade80;">-' + checkinStressRelief + '% Stress eased on check-in + Deep Sleep Stress Purge upon waking!</span>')) + '</div>' +
      '<div>• <b>Minimum Rest Lock:</b> 🔒 <b>30 Minutes</b> • <b>Full Blessings At:</b> ⏳ <b>2.0+ Hours Offline</b></div>' +
    '</div>' +
    '<button class="btn btn-gold" style="width:100%;" onclick="closePopupModal()">🕯️ Rest in Peace</button>'
  );
}

function wakeUpFromLodging() {
  if (!hero || !hero.sleepingAt) return;
  var slp = hero.sleepingAt;
  var elapsedMs = Date.now() - (slp.startedEpoch || Date.now());
  var hrs = (elapsedMs / 3600000).toFixed(2);
  var roomVec = renderSleepingRoomVectorSvg(slp.type);
  var isAboveFloor = (slp.type !== "floor");
  hero.sleepingAt = null;
  hero.drunkUntil = 0;

  var summaryHtml = "";
  if (elapsedMs < TWO_HOURS_MS) {
    var smallHp = Math.round(hero.maxHp * 0.25);
    hero.hp = Math.min(hero.maxHp, hero.hp + smallHp);
    if (isAboveFloor) {
      var shortRelief = slp.type === "cot" ? 30 : 50;
      hero.stress = Math.max(0, (hero.stress || 0) - shortRelief);
      hero.deathsDoorTrauma = false;
      summaryHtml = "⏰ <b>Woke Up After Short Bedchamber Rest (" + hrs + " / 2.00 hrs):</b> Restored <b>+" + smallHp + " HP</b>, calmed <b>-" + shortRelief + "% Stress (Now " + (hero.stress || 0) + "%)</b> &amp; cleared Trauma/Drunk haze!";
    } else {
      summaryHtml = "🪵 <b>Woke Up From Cold Tavern Floor (" + hrs + " / 2.00 hrs):</b> Restored <b>+" + smallHp + " HP</b>, but the damp planks gave <b>0% Stress relief</b> (Stress remains <b>" + (hero.stress || 0) + "%</b> — sleep on a Cot or Suite above the floor to remove Stress!).";
    }
    addLog(summaryHtml);
  } else {
    playSfx("levelup");
    if (slp.type === "floor") {
      var flHp = Math.round(hero.maxHp * 0.40), flMp = Math.round(hero.maxMp * 0.40);
      hero.hp = Math.min(hero.maxHp, hero.hp + flHp); hero.mp = Math.min(hero.maxMp, hero.mp + flMp);
      hero.quests = Math.min(hero.maxQuests + 4, hero.quests + 4);
      var badRoll = Math.random(), hazardTxt = "Cold planks offered <b>0% Stress relief</b>.";
      if (badRoll < 0.20) {
        var stolen = Math.round(hero.gold * 0.08);
        hero.gold = Math.max(0, hero.gold - stolen);
        hazardTxt = "<b style='color:#ef4444;'>A cutpurse slit your coin-pouch (-" + stolen + " Gold) &amp; 0% Stress relief!</b>";
      } else if (badRoll < 0.38) {
        hero.stress = Math.min(100, (hero.stress || 0) + 10);
        hero.lodgingBuff = { name: "Stiff Tavern Neck", questsLeft: 5, statBonusPct: 0, dodgePen: 5 };
        hazardTxt = "<b style='color:#f59e0b;'>Cellar rats &amp; cold planks gave you Nightmares (+10% Stress) &amp; a Stiff Neck (-5% Dodge for 5q)!</b>";
      }
      summaryHtml = "🪵 <b>Woke from Tavern Floor (" + hrs + " hrs):</b> +" + flHp + " HP, +" + flMp + " MP &amp; +4⚡ Quests. " + hazardTxt;
    } else if (slp.type === "cot") {
      var cHp = Math.round(hero.maxHp * 0.75), cMp = Math.round(hero.maxMp * 0.75);
      hero.hp = Math.min(hero.maxHp, hero.hp + cHp); hero.mp = Math.min(hero.maxMp, hero.mp + cMp);
      hero.quests = Math.min(hero.maxQuests + 8, hero.quests + 8);
      hero.stress = Math.max(0, (hero.stress || 0) - 65);
      hero.deathsDoorTrauma = false;
      if (hero.resolveState && !hero.resolveState.isVirtue) hero.resolveState = null;
      summaryHtml = "🍺 <b>Woke from Warm Hearthside Cot (" + hrs + " hrs):</b> +" + cHp + " HP, +" + cMp + " MP, +8⚡ Bonus Quests &amp; <b>purged -65% Stress (Now " + hero.stress + "%) + Afflictions/Trauma</b>!";
    } else if (slp.type === "inn") {
      hero.hp = hero.maxHp; hero.mp = hero.maxMp;
      (hero.mercenaries || []).forEach(function(m) { m.hp = m.maxHp; });
      (hero.children || []).forEach(function(ch) { ch.hp = ch.maxHp; });
      hero.quests = Math.min(hero.maxQuests + 14, hero.quests + 14);
      hero.stress = 0;
      hero.deathsDoorTrauma = false;
      if (hero.resolveState && !hero.resolveState.isVirtue) hero.resolveState = null;
      hero.lodgingBuff = { name: "Feather-Suite Lucid Calm", questsLeft: 10, statBonusPct: 12, xpBonusPct: 15, stressRedPct: 25, dodgePen: 0 };
      pushBuffToFifo("buff_lodging", hero);
      summaryHtml = "🛌 <b>Woke in Private Feather Suite (" + hrs + " hrs):</b> 100% Party HP/MP, +14⚡ Quests, <b>100% Stress &amp; Affliction Purge (0% Stress)</b> &amp; <b>Lucid Calm (+12% Stats, +15% XP &amp; -25% Stress Gain for 10q)</b>!";
    } else if (slp.type === "mansion") {
      hero.hp = hero.maxHp; hero.mp = hero.maxMp;
      (hero.mercenaries || []).forEach(function(m) { m.hp = m.maxHp; });
      (hero.children || []).forEach(function(ch) { ch.hp = ch.maxHp; });
      hero.quests = Math.min(hero.maxQuests + 22, hero.quests + 22);
      hero.gems = (hero.gems || 0) + 1;
      var stipend = hero.level * 35;
      hero.gold += stipend;
      hero.stress = 0;
      hero.deathsDoorTrauma = false;
      if (hero.resolveState && !hero.resolveState.isVirtue) hero.resolveState = null;
      if (hero.spouse) hero.spouse.love = Math.min(100, (hero.spouse.love !== undefined ? hero.spouse.love : 100) + 20);
      hero.lodgingBuff = { name: "Sovereign Palace Serenity", questsLeft: 15, statBonusPct: 20, xpBonusPct: 20, stressRedPct: 35, dodgePen: 0 };
      pushBuffToFifo("buff_lodging", hero);
      summaryHtml = "🏰 <b>Woke in Royal Palace Estate (" + hrs + " hrs):</b> 100% Party HP/MP, +22⚡ Quests, +1💎 Gem (Total: " + hero.gems + "💎), +" + stipend + "g Stipend, <b>100% Stress Purge</b> &amp; <b>Sovereign Serenity (+20% Stats &amp; -35% Stress Gain for 15q)</b>!";
    }
    addLog(summaryHtml);
  }

  saveCurrentHero(null, false, null);
  renderGameScreen();
  showPopupModal(
    '<div style="font-size:20px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:8px;">🕯️ DAWN BREAKS OVER VALORIA</div>' +
    roomVec +
    '<div style="background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:12px;margin:10px 0;font-size:13.5px;color:#e5dec9;line-height:1.65;text-align:left;">' + summaryHtml + '</div>' +
    '<button class="btn btn-gold" style="width:100%;justify-content:center;" onclick="closePopupModal()">⚔️ Ride Forth</button>'
  );
}
'''
}

String buildUiChunkA2b() {
    return '''
function playSlot(slotKey) {
  var lockObj = (serverData.sessionLocks && serverData.sessionLocks[slotKey]) ? serverData.sessionLocks[slotKey] : null;
  if (lockObj && lockObj.sessionId !== CLIENT_SESSION_ID && (lockObj.expiresEpoch || 0) > Date.now()) {
    alert("⚠️ Asynchronous 2-Player Concurrency Lock: This hero slot is currently active in another browser session! Please select another slot or wait 45 seconds.");
    return;
  }
  var slotHero = serverData.slots ? serverData.slots[slotKey] : null;
  if (!slotHero) return;
  if (slotHero.sleepingAt && slotHero.sleepingAt.startedEpoch) {
    var sleepElapsed = Date.now() - slotHero.sleepingAt.startedEpoch;
    if (sleepElapsed < THIRTY_MINS_MS) {
      var remSecs = Math.ceil((THIRTY_MINS_MS - sleepElapsed) / 1000);
      showPopupModal(
        '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:8px;">🛌🔒 30-Minute Lodging Rest Lock Active</div>' +
        renderSleepingRoomVectorSvg(slotHero.sleepingAt.type) +
        '<div style="background:#14090e;border:1px solid #991b1b;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13.5px;line-height:1.6;color:#e5dec9;">' +
          '<b>' + escapeHtml(slotHero.name) + '</b> is currently fast asleep inside <b>' + escapeHtml(slotHero.sleepingAt.name) + '</b>.<br><br>' +
          'To prevent spam-resting exploits, bedding down locks the character for a minimum of <b>30 minutes</b>. Time remaining on Rest Lock: <b style="color:#fbbf24;">' + formatCooldownSec(remSecs) + '</b>.' +
        '</div>' +
        '<button class="btn btn-gold" style="width:100%;justify-content:center;" onclick="closePopupModal()">Understood</button>'
      );
      return;
    }
  }

  activeSlotKey = slotKey;
  hero = JSON.parse(JSON.stringify(slotHero));
  ensureHeroV3Fields(hero);
  try {
    var sessLogs = JSON.parse(sessionStorage.getItem("dcr_sess_logs_" + slotKey) || "null");
    if (Array.isArray(sessLogs) && sessLogs.length > (hero.logs ? hero.logs.length : 0)) hero.logs = sessLogs;
  } catch (e) {}
  activeCombat = null; activeStory = null; activeDelve = null; activeDispatch = null; activeArmyBattle = null; lastCombatBanner = null;
  updateQuestRegenTimer();
  updateRealWeatherTopPill();
  if (window.updateDynamicSoundscape) window.updateDynamicSoundscape();
  switchScreen("game");
  if (hero.sleepingAt && hero.sleepingAt.type) {
    wakeUpFromLodging();
  } else {
    renderGameScreen();
    if (window.checkAltGuardRavenInbox) window.checkAltGuardRavenInbox();
    if (window.checkAsyncPvpRavenInbox) window.checkAsyncPvpRavenInbox();
  }
}

function hasOutlawDisguise() {
  if (!hero) return false;
  return (hero.helmStyle === "Inquisitor Hood" || hero.helmStyle === "Plague Doctor Beak");
}

function isMerchantBlacklisted() {
  if (!hero || !hero.merchantBlacklistUntil) return false;
  if (Date.now() >= hero.merchantBlacklistUntil) {
    hero.merchantBlacklistUntil = 0;
    return false;
  }
  return !hasOutlawDisguise();
}

function attemptShoplift(category, targetKey) {
  ensureHeroV3Fields(hero);
  if ((hero.stealsUsedToday || 0) >= MAX_DAILY_STEALS) {
    showRequirementModal("Shoplifting Daily Limit Reached (3/3 Today)", "🥷⏳", "You have already attempted <b>3 shoplifting heists today</b>.", "Return after midnight rollover (or use Admin Reset) for 3 more daily heist attempts!", "");
    return;
  }
  if (isMerchantBlacklisted()) {
    var remSec = Math.ceil((hero.merchantBlacklistUntil - Date.now()) / 1000);
    showRequirementModal(
      "Merchant Stall Barred (1-Hour Shoplifting Blacklist!)", "🚫🥷",
      "The shopkeeper recognizes your face from your last heist attempt and has barred their shutters for <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b>!",
      "🎭 <b>Outlaw Disguise Trick:</b> Open <b>🎨 Studio</b> and equip the <b>Inquisitor Hood</b> or <b>Plague Doctor Beak</b> to sneak back into the market incognito right now!",
      '<button class="btn btn-arcane" style="flex:1;" onclick="openCustomizeHeroModal()">🎭 Equip Disguise in Studio</button>'
    );
    return;
  }
  if (hero.quests < 1) {
    showRequirementModal("Need 1⚡ Quest Stamina to Attempt Heist", "🗡️⚡", "Attempting a five-finger shoplifting heist requires <b>1⚡ Quest</b> (You have 0⚡).", "Wait for the 45m stamina tick or visit the Astral Ley-Well!", "");
    return;
  }
  hero.quests -= 1;
  hero.stealsUsedToday = (hero.stealsUsedToday || 0) + 1;
  var rw = getRealWeather();
  var st = getHeroStats();
  var reqWitsSteal = 18 + (hero.level || 1) * 2.2 + Math.pow(hero.level || 1, 1.35) * 0.9;
  var witsMod = Math.max(-0.04, Math.min(0.08, ((st.effWits + st.effCharm * 0.4) - reqWitsSteal) * 0.002));
  var drunkPen = st.isDrunk ? -0.05 : 0;
  var stealthOdds = Math.max(0.05, Math.min(0.26, ((rw.rain || rw.lightning) ? 0.18 : 0.12) + witsMod + drunkPen));
  var stolenRewardDesc = "";
  var applyStolenGoods = function() {
    if (category === "shop") {
      var itm = hero.shopInventory[targetKey];
      if (itm && hero.inventory.length < 30) {
        itm = sanitizeGearItem(itm, itm.type || "weapon");
        itm.stolen = true;
        hero.inventory.push(itm);
        hero.shopInventory.splice(targetKey, 1);
        shopInventory = hero.shopInventory;
        stolenRewardDesc = "🥷 Contraband " + itm.icon + " " + escapeHtml(itm.name);
      }
    } else if (category === "belt") {
      hero.belt[targetKey] = Math.min(5, (hero.belt[targetKey] || 0) + 1);
      var bMeta = TACTICAL_BELT_ITEMS.find(function(x) { return x.id === targetKey; });
      stolenRewardDesc = "🥷 Stolen 1x " + (bMeta ? bMeta.icon + " " + bMeta.name : targetKey);
    } else if (category === "potion") {
      hero.potions = (hero.potions || 0) + 1;
      stolenRewardDesc = "🥷 Stolen 1x 🧪 Crimson Healing Draught";
    } else if (category === "ether") {
      var mpGain = Math.round(hero.maxMp * 0.70);
      hero.mp = Math.min(hero.maxMp, hero.mp + mpGain);
      stolenRewardDesc = "🥷 Stolen &amp; Imbibed 💧 Arcane Elixir (+" + mpGain + " MP)";
    }
  };

  if (Math.random() < stealthOdds) {
    applyStolenGoods();
    hero.alignment.Shadow = (hero.alignment.Shadow || 0) + 2;
    playSfx("coin");
    var winMsg = "🥷🌑 <b style='color:#4ade80;'>" + Math.round(stealthOdds * 100) + "% HEIST SUCCEEDED UNSEEN (" + hero.stealsUsedToday + "/" + MAX_DAILY_STEALS + " Today)!</b><br>Your fingers moved faster than candlelight—you slipped away with <b>" + stolenRewardDesc + "</b> without alerting the merchant or the Watch! (+2 Shadow Alignment)";
    addLog(winMsg);
    queueSaveHero();
    renderGameScreen();
    showOutcomeModal("🥷 Heist Succeeded (" + hero.stealsUsedToday + "/" + MAX_DAILY_STEALS + " Today)!", "🥷💰", null, "#4ade80", winMsg, window.currentTownModal);
    return;
  }

  applyStolenGoods();
  hero.merchantBlacklistUntil = Date.now() + ONE_HOUR_MS;
  var gRoll = Math.random();
  var gTier = SHOPLIFT_GUARDS[0];
  if (gRoll >= 0.85) gTier = SHOPLIFT_GUARDS[2];
  else if (gRoll >= 0.50) gTier = SHOPLIFT_GUARDS[1];

  var gLv = Math.max(2, hero.level + (gTier.tier === 3 ? 6 : (gTier.tier === 2 ? 2 : -1)));
  var gHp = Math.round((95 + gLv * 48 + hero.maxHp * 0.65) * gTier.statMult);
  var gArm = Math.round(gHp * 0.45);
  var gAtk = Math.round(Math.max(18, st.atk * 0.85 + gLv * 5.5) * gTier.statMult);
  var gDef = Math.round(Math.max(8, st.def * 0.80 + gLv * 3.0) * gTier.statMult);

  closePopupModal();
  clearTransientCombatFx();
  playSfx("death");
  activeCombat = {
    isBoss: false, isGuard: true, guardFameLoss: gTier.fameLoss, stolenRewardDesc: stolenRewardDesc,
    isWorldRaid: false, isZoneRaid: false, isDelveBoss: false, isSpire: false, isHerald: false, isPvp: false,
    areaId: hero.selectedArea || 1, baseMobName: gTier.name, trait: "Armored",
    loreIntro: "🚨 CAUGHT SHOPLIFTING (" + hero.stealsUsedToday + "/" + MAX_DAILY_STEALS + " Today • 1h Merchant Blacklist)! (" + gTier.diffLabel + " GUARD • 5% Flee Cap • Slaying costs -" + gTier.fameLoss + " Fame & +1 Wanted Lv, or Imprison below 25% HP!)",
    icon: gTier.icon, name: "GUARD (" + gTier.diffLabel + "): " + gTier.name, level: gLv,
    hp: gHp, maxHp: gHp, armor: gArm, maxArmor: gArm, poise: 100, maxPoise: 100,
    atk: gAtk, def: gDef, eva: 12 + gTier.tier * 4, parry: 14 + gTier.tier * 4, acc: 98 + gTier.tier * 6, crit: 12 + gTier.tier * 4,
    xp: gLv * 25, gold: gLv * 20,
    sessionDamage: 0, alliedUsed: false, tauntUsed: false, tauntedTurns: 0, armorBrokenTurns: 0, hamstrungTurns: 0, silencedTurns: 0, phase2Triggered: false, comboCount: 0, bossCharging: false, partyShield: 0, bleedTurns: 0, heroPoisonTurns: 0, stunned: false
  };
  addLog("🚨🛡️ <b style='color:#ef4444;'>CAUGHT STEALING (" + hero.stealsUsedToday + "/" + MAX_DAILY_STEALS + " Today • 1h Shop Blacklist)!</b> Alerted a <b>" + gTier.icon + " " + escapeHtml(gTier.name) + " [" + gTier.diffLabel + "]</b>!");
  renderGameScreen();
}

function spendStatPoint(stat, fromModal) {
  if (!hero.statPoints || hero.statPoints <= 0) return;
  hero.statPoints--;
  if (stat === "quests") {
    hero.maxQuests += 3; hero.quests += 3;
    addLog("⚡ <b>Stat Point Invested:</b> +3 Max Quests Capacity (" + hero.quests + "/" + hero.maxQuests + "⚡)!");
  } else {
    hero[stat]++;
    if (stat === "guts") { hero.maxHp += 8; hero.hp += 8; }
    if (stat === "wits") { hero.maxMp += 3; hero.mp += 3; }
    if (window.syncHeroVitalityMaxHp) syncHeroVitalityMaxHp(hero);
    addLog("⚜️ <b>Stat Point Invested:</b> Increased <b>" + stat.toUpperCase() + "</b> to <b>" + hero[stat] + "</b>" + (stat === "guts" ? " (+Vitality HP!)" : (stat === "wits" ? " (+3 MP!)" : "")) + "!");
  }
  queueSaveHero();
  if (fromModal) openHeroSheetModal();
  renderGameScreen();
}

function trainSkill(skKey, fromModal) {
  var meta = SKILLS_META[skKey];
  if (!meta) return;
  if ((hero.skillPoints || 0) <= 0 || (hero.skills[skKey] || 1) >= meta.max) {
    showRequirementModal(
      "Cannot Train " + meta.name + " Yet", meta.icon,
      (hero.skillPoints || 0) <= 0 ? "You have <b>0 Skill Points</b> available." : "This skill is already at its maximum rank (" + meta.max + ").",
      "Earn <b>+1 Skill Point</b> every time you Level Up, defeat an Area Boss, or conquer a World Raid Boss!",
      ""
    );
    return;
  }
  hero.skillPoints--;
  hero.skills[skKey] = (hero.skills[skKey] || 1) + 1;
  if (skKey === "stamina") {
    hero.maxQuests += 4; hero.quests += 4;
    addLog("⚡ <b>Trained Royal Stamina (Rank " + hero.skills[skKey] + "):</b> +4 Max Quests &amp; +0.4% Auto-Heal!");
  } else {
    addLog(meta.icon + " <b>Skill Trained:</b> Upgraded <b>" + meta.name + "</b> to Rank <b>" + hero.skills[skKey] + "</b>!");
  }
  queueSaveHero();
  if (fromModal) openHeroSheetModal();
  renderGameScreen();
}

function setCombatStance(s) {
  hero.stance = s;
  clearTransientCombatFx();
  addLog("🛡️ Switched Combat Stance to <b>" + s.toUpperCase() + "</b>.");
  if (activeCombat) renderBattleModal();
  else renderGameScreen();
}

function setTab(t) {
  if (t !== "minigames" && window.stopActiveMiniGames) window.stopActiveMiniGames();
  currentTab = t;
  renderGameScreen();
}

function adoptOrEquipCompanion(compId) {
  ensureHeroV3Fields(hero);
  var c = COMPANIONS.find(function(x) { return x.id === compId; });
  if (!c) return;
  if (hero.companion && hero.companion.id === compId) {
    dismissActiveCompanion();
    return;
  }
  var helpersWithoutPet = getActiveHelperCount(hero) - (hero.companion ? 1 : 0);
  if (helpersWithoutPet >= MAX_ACTIVE_HELPERS) {
    showRequirementModal(
      "Two-Helper Party Limit Reached (2/2 Active)", "🐾🛡️",
      "By Royal Decree, you may bring at most <b>2 Helpers</b> into battle (any combination of 2 Recruits, or 1 Recruit + 1 Animal Companion / Dynasty Heir / Alt Bodyguard).",
      "Dismiss 1 active Mercenary or Battle Heir first if you wish to bring <b>" + escapeHtml(c.name) + "</b> into battle!",
      ""
    );
    return;
  }
  if (hero.ownedCompanions.includes(compId)) {
    hero.companion = c;
    var sMsg = c.icon + " Summoned Companion <b>" + escapeHtml(c.name) + "</b> (" + escapeHtml(c.desc) + " • Active Helpers: " + getActiveHelperCount(hero) + "/2)!";
    addLog(sMsg);
    queueSaveHero(); renderGameScreen();
    showOutcomeModal(c.icon + " Companion Summoned!", c.icon, c.name, "#d4af37", sMsg, null);
  } else {
    if (hero.gold < c.costGold || (hero.gems || 0) < c.costGems) {
      showRequirementModal(
        "Cannot Bind " + c.name + " Yet", c.icon,
        "Binding <b>" + escapeHtml(c.name) + "</b> requires <b style='color:#fbbf24;'>" + c.costGold.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>) and <b style='color:#fde68a;'>" + c.costGems + "💎 Dragon Gems</b> (You have <b>" + (hero.gems || 0) + "💎</b>).",
        "Hunt Area Bosses, Delve Bosses, or smelt 30 Trophies at the Huntsman's Exchange to earn Dragon Gems!",
        ""
      );
      return;
    }
    hero.gold -= c.costGold; hero.gems -= c.costGems;
    hero.ownedCompanions.push(compId); hero.companion = c;
    if (!hero.petEvo) hero.petEvo = {};
    hero.petEvo[compId] = 1;
    playSfx("levelup");
    var aMsg = "⚜️ <b>Companion Bound (-" + c.costGold.toLocaleString() + "g, -" + c.costGems + "💎 • Remaining: " + hero.gold.toLocaleString() + "g &amp; " + hero.gems + "💎):</b><br><b>" + c.icon + " " + escapeHtml(c.name) + "</b> now stalks beside you (" + getActiveHelperCount(hero) + "/2 Helpers)!<br>• <b>Passive &amp; Combat Bonus:</b> " + escapeHtml(c.desc);
    addLog(aMsg);
    queueSaveHero(); renderGameScreen();
    showOutcomeModal("⚜️ Companion Bound!", c.icon, c.name, "#4ade80", aMsg, null);
  }
}

function getScaledHealCost() {
  var lv = hero ? (hero.level || 1) : 1;
  return Math.max(45, Math.round(55 * lv + Math.pow(lv, 2.05) * 8));
}
function getScaledPotionCost() {
  var lv = hero ? (hero.level || 1) : 1;
  var curse = getActiveRealmCurse();
  var mult = (curse && curse.id === "mire_plague") ? 1.50 : 1.0;
  return Math.round((50 + 40 * lv + Math.pow(lv, 2.0) * 6) * mult);
}
function getScaledEtherCost() {
  var lv = hero ? (hero.level || 1) : 1;
  return Math.round(70 + 45 * lv + Math.pow(lv, 2.0) * 7);
}
function getScaledInnRestCost() {
  var lv = hero ? (hero.level || 1) : 1;
  return Math.max(95, Math.round(95 + 62 * lv + Math.pow(lv, 2.22) * 3.15));
}
function getScaledBeltCost(bMeta) { return Math.round(bMeta.baseCost * (1 + ((hero ? hero.level : 1) - 1) * 0.24)); }

function buyValkyrieSeal() {
  ensureHeroV3Fields(hero);
  if ((hero.sealsBoughtToday || 0) >= 1) {
    showRequirementModal("Valkyrie Seal Daily Limit Reached (1/1 Today)", "🪽⏳", "Under Hardcore Reliquary Law, the Sanctuary Altar can only consecrate <b>1 Seal of the Valkyrie per day</b>.", "Return after midnight rollover (or use Admin Reset)!", "");
    return;
  }
  var sCost = Math.max(1500, hero.level * 180);
  if ((hero.valkyrieSeals || 0) >= 3) {
    showRequirementModal("Hardcore Valkyrie Reliquary Full (3/3 Max)", "🪽✨", "Your reliquary can hold at most <b>3x Seals of the Valkyrie</b> at one time.", "Each Seal automatically resurrects or evacuates your hero at 50% HP upon taking a fatal blow!", "");
    return;
  }
  if (hero.gold < sCost || (hero.gems || 0) < 2) {
    showRequirementModal("Need " + sCost.toLocaleString() + "g & 2💎 for Valkyrie Seal", "🪽💎", "Consecrating a new <b>Seal of the Valkyrie</b> requires <b style='color:#fbbf24;'>" + sCost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>) and <b style='color:#fde68a;'>2💎 Dragon Gems</b> (You have <b>" + (hero.gems || 0) + "💎</b>).", "Hunt Bosses and complete Warrants to earn Gold and Gems!", "");
    return;
  }
  hero.gold -= sCost;
  hero.gems -= 2;
  hero.sealsBoughtToday = (hero.sealsBoughtToday || 0) + 1;
  hero.valkyrieSeals = Math.min(3, (hero.valkyrieSeals || 0) + 1);
  playSfx("levelup");
  var sMsg = "🪽✨ <b>Seal of the Valkyrie Consecrated (1/1 Today • -" + sCost.toLocaleString() + "g, -2💎):</b><br>You now carry <b>" + hero.valkyrieSeals + " / 3 Auto-Resurrection Seals</b> (Remaining: " + hero.gold.toLocaleString() + "g &amp; " + hero.gems + "💎)!";
  addLog(sMsg);
  queueDeltaSaveHero(); renderGameScreen();
  showOutcomeModal("🪽 Valkyrie Seal Acquired (" + hero.valkyrieSeals + "/3)!", "🪽✨", null, "#fde047", sMsg, "sanctuary");
}

function buyBeltItem(itemId) {
  ensureHeroV3Fields(hero);
  if ((hero.beltBuysToday || 0) >= MAX_DAILY_BELT_BUYS) {
    showRequirementModal("Tactical Belt Purchase Limit Reached (5/5 Today)", "🎒⏳", "The Sanctuary Quartermaster only rations <b>5 Tactical Belt supplies per day</b>.", "Return tomorrow (or use Admin Reset) for fresh belt supplies!", "");
    return;
  }
  var bMeta = TACTICAL_BELT_ITEMS.find(function(x) { return x.id === itemId; });
  if (!bMeta) return;
  var cost = getScaledBeltCost(bMeta);
  if ((hero.belt[itemId] || 0) >= 5) {
    showRequirementModal("Tactical Belt Pouch Full (5/5)", bMeta.icon, "You can carry up to <b>5x " + escapeHtml(bMeta.name) + "</b> on your combat belt at one time.", "Use them in the Popup Battle Arena against tough enemies and bosses!", "");
    return;
  }
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for " + bMeta.name, bMeta.icon, "Purchasing <b>" + escapeHtml(bMeta.name) + "</b> costs <b>" + cost.toLocaleString() + " Gold</b> (You currently have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol regions, distill free supplies via 🧪 Alchemical Brewing, or risk a 🥷 Steal attempt!", "");
    return;
  }
  hero.gold -= cost;
  hero.beltBuysToday = (hero.beltBuysToday || 0) + 1;
  hero.belt[itemId] = (hero.belt[itemId] || 0) + 1;
  playSfx("coin");
  var bMsg = bMeta.icon + " <b>Tactical Supply Purchased (" + hero.beltBuysToday + "/" + MAX_DAILY_BELT_BUYS + " Today • -" + cost.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left):</b><br>Added <b>1x " + escapeHtml(bMeta.name) + "</b> to your Quick-Belt (Carrying: <b>" + hero.belt[itemId] + " / 5</b>)!<br>• <b>Effect:</b> " + escapeHtml(bMeta.desc);
  addLog(bMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal(bMeta.icon + " Belt Supply Added!", bMeta.icon, null, "#d4af37", bMsg, "sanctuary");
}

function cureMercenaryQuirkSanitarium(mIdx) {
  ensureHeroV3Fields(hero);
  var m = hero.mercenaries[mIdx];
  if (!m || !m.quirk) return;
  var cost = Math.max(200, hero.level * 30);
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for Sanitarium", "🏥💰", "Treating <b>" + escapeHtml(m.name) + "&apos;s</b> quirk (<b>" + m.quirk.name + "</b>) at the Sanctuary Sanitarium costs <b>" + cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol regions or collect Kingdom Taxes for Gold!", "");
    return;
  }
  hero.gold -= cost;
  var oldQ = m.quirk.name;
  m.quirk = null;
  playSfx("magic");
  addLog("🏥🕯️ <b>Sanctuary Sanitarium (-" + cost.toLocaleString() + "g):</b> Cured <b>" + escapeHtml(m.name) + "</b> of <b>" + oldQ + "</b>!");
  queueSaveHero();
  if (window.currentTownModal === "sanctuary") openTownFacilityModal("sanctuary");
  renderGameScreen();
}

function healAtSanctuary() {
  ensureHeroV3Fields(hero);
  var nowMs = Date.now(), used = hero.healsUsedToday || 0;
  if (used >= MAX_DAILY_HEALS) {
    showRequirementModal("Sanctuary Daily Limit Reached (3/3)", "🕯️⏳", "You have used all <b>3 Sanctuary Rites</b> for today.", "Use the 🙏 Confessional Booth (-45% Stress), 🥃 Boar's Head Taproom (-50% Stress), or Healing Potions!", "");
    return;
  }
  var elapsed = nowMs - (hero.lastHealEpoch || 0);
  if (elapsed < HEAL_COOLDOWN_MS) {
    var remSec = Math.ceil((HEAL_COOLDOWN_MS - elapsed) / 1000);
    showRequirementModal("Sanctuary Clerics Recharging", "🕯️⏳", "Wait <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b> before your next Sanctuary rite (15m cooldown).", "Drink a Healing Potion or pray at the Confessional Booth in the meantime!", "");
    return;
  }
  if (hero.hp >= hero.maxHp && hero.mp >= hero.maxMp && !hero.moonCurseTurns && (hero.stress || 0) <= 0 && !hero.resolveState && !hero.deathsDoorTrauma) {
    showRequirementModal("Already at Full Vitals & Calm Mind", "🕯️⚜️", "Your HP (" + hero.hp + "/" + hero.maxHp + "), MP (" + hero.mp + "/" + hero.maxMp + "), and Stress (0%) are already completely restored!", "Save your daily Sanctuary rites for when you are wounded or stressed.", "");
    return;
  }
  var cost = getScaledHealCost();
  if (hero.gold < cost) {
    if (hero.hp < Math.round(hero.maxHp * 0.25) && hero.quests > 0) {
      hero.quests--; hero.hp = Math.round(hero.maxHp * 0.40);
      hero.stress = Math.max(0, (hero.stress || 0) - 20);
      hero.deathsDoorTrauma = false;
      var cMsg = "🕯️ <b>Charity Poultice Applied (-1⚡, 0g):</b><br>The Sanctuary Sisters bandaged your critical wounds to <b>" + hero.hp + " / " + hero.maxHp + " HP (40%)</b> &amp; calmed -20% Stress!";
      addLog(cMsg);
      queueDeltaSaveHero(); renderGameScreen();
      showOutcomeModal("🕯️ Charity Poultice Applied!", "🕯️🩸", null, "#4ade80", cMsg, "sanctuary");
      return;
    }
    showRequirementModal("Not Enough Gold for Sanctuary Rite", "🕯️💰", "Treatment at Level " + hero.level + " costs <b>" + cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "If your HP is below 25% and you have 1⚡ Quest, tap Heal again for a free Charity Poultice, or wait for your passive Auto-Heal!", "");
    return;
  }
  hero.gold -= cost; hero.healsUsedToday = used + 1; hero.lastHealEpoch = nowMs;
  hero.moonCurseTurns = 0;
  hero.deathsDoorTrauma = false;
  hero.stress = Math.max(0, (hero.stress || 0) - 35);
  if (hero.resolveState && !hero.resolveState.isVirtue) hero.resolveState = null;
  var hpGain = Math.round(hero.maxHp * 0.60), mpGain = Math.round(hero.maxMp * 0.60);
  hero.hp = Math.min(hero.maxHp, hero.hp + hpGain); hero.mp = Math.min(hero.maxMp, hero.mp + mpGain);
  (hero.mercenaries || []).forEach(function(m) { m.hp = Math.min(m.maxHp, m.hp + Math.round(m.maxHp * 0.50)); });
  (hero.children || []).forEach(function(ch) { ch.hp = Math.min(ch.maxHp || 100, (ch.hp || ch.maxHp || 100) + Math.round((ch.maxHp || 100) * 0.60)); });
  playSfx("magic");
  var hMsg = "🕯️ <b>Sanctuary Rite (" + hero.healsUsedToday + "/3 Today, -" + cost.toLocaleString() + "g):</b><br>• <b>Hero Restored:</b> <span style='color:#4ade80;font-weight:bold;'>+" + hpGain + " HP, +" + mpGain + " MP &amp; -35% Stress</span> (Cleansed Afflictions, Death's Door Trauma &amp; Lycan Curse)<br>• <b>Retinue &amp; Heirs Healed:</b> +50–60% HP";
  addLog(hMsg);
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("🕯️ Sanctuary Rite Complete!", "🕯️⚜️", null, "#4ade80", hMsg, "sanctuary");
}

function buyConsumable(type) {
  ensureHeroV3Fields(hero);
  if (type === "potion") {
    var pBought = hero.potionsBoughtToday || 0;
    if (pBought >= MAX_DAILY_POTIONS) {
      showRequirementModal("Apothecary Out of Potions (3/3 Today)", "🧪⏳", "The Royal Apothecary only brews <b>3 Healing Potions per day</b>.", "Use 🧪 Alchemical Brewing (-2⚡, -2 Trophies), trade 15 Trophies at the Huntsman's Exchange, or assign an Heir to Apothecary Mira!", "");
      return;
    }
    var pCost = getScaledPotionCost();
    if (hero.gold < pCost) {
      showRequirementModal("Not Enough Gold for Potion", "🧪💰", "A Healing Potion at Level " + hero.level + " costs <b>" + pCost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol regions or collect Kingdom Taxes to earn Gold!", "");
      return;
    }
    hero.gold -= pCost; hero.potions++; hero.potionsBoughtToday = pBought + 1;
    playSfx("coin");
    var pMsg = "🧪 <b>Crimson Draught Purchased (-" + pCost.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left):</b><br>You now carry <b>" + hero.potions + " Healing Potion(s)</b> (" + hero.potionsBoughtToday + "/3 bought today).";
    addLog(pMsg);
    queueDeltaSaveHero(); renderGameScreen();
    showOutcomeModal("🧪 Healing Potion Bought!", "🧪🩸", null, "#4ade80", pMsg, "sanctuary");
  } else {
    var eBought = hero.ethersBoughtToday || 0;
    if (eBought >= MAX_DAILY_ETHERS) {
      showRequirementModal("Apothecary Out of Elixirs (2/2 Today)", "💧⏳", "Max 2 Arcane Elixirs per day reached.", "Wait for your passive 45m MP recovery tick or rest at the Inn!", "");
      return;
    }
    var eCost = getScaledEtherCost();
    if (hero.gold < eCost) {
      showRequirementModal("Not Enough Gold for Elixir", "💧💰", "An Arcane Elixir at Level " + hero.level + " costs <b>" + eCost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol regions or collect Kingdom Taxes to earn Gold!", "");
      return;
    }
    hero.gold -= eCost; hero.ethersBoughtToday = eBought + 1;
    var mpGain = Math.round(hero.maxMp * 0.70);
    hero.mp = Math.min(hero.maxMp, hero.mp + mpGain);
    playSfx("magic");
    var eMsg = "💧 <b>Arcane Elixir Imbibed (-" + eCost.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left):</b><br>Restored <b style='color:#c084fc;'>+" + mpGain + " MP</b> (Now " + hero.mp + " / " + hero.maxMp + " MP)!";
    addLog(eMsg);
    queueDeltaSaveHero(); renderGameScreen();
    showOutcomeModal("💧 Arcane Elixir Drank!", "💧🔮", null, "#c084fc", eMsg, "sanctuary");
  }
}

function restAtTavernInn() {
  ensureHeroV3Fields(hero);
  var nowMs = Date.now(), rUsed = hero.restsUsedToday || 0;
  if (rUsed >= MAX_DAILY_RESTS) {
    showRequirementModal("Inn Quick-Rest Limit Reached (2/2 Today)", "🍺🛌", "You have used both of your <b>2 daily Quick-Rests</b>.", "Visit the <b>⚡🔥 Astral Ley-Well</b> in the Citadel (2/day Full Energy Restore) or use <b>2-Hour Offline Lodging</b>!", "");
    return;
  }
  var elapsed = nowMs - (hero.lastRestEpoch || 0);
  if (elapsed < REST_COOLDOWN_MS) {
    var remSec = Math.ceil((REST_COOLDOWN_MS - elapsed) / 1000);
    showRequirementModal("30-Minute Inn Rest Lock Active", "🛌⏳", "Wait <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b> before your next Quick-Rest (30m cooldown).", "Patrol or visit the Astral Ley-Well while your room is readied!", "");
    return;
  }
  var innCost = getScaledInnRestCost();
  if (hero.gold < innCost) {
    showRequirementModal("Not Enough Gold for Quick-Rest", "🛌💰", "Quick-Resting at the Boar&apos;s Head Inn at Level " + hero.level + " costs <b style='color:#fbbf24;'>" + innCost.toLocaleString() + " Gold</b> (You currently have <b>" + hero.gold.toLocaleString() + "g</b>).", "Sell unequipped gear, burn 10 Trophies at the Huntsman's Exchange, or collect Kingdom Taxes!", "");
    return;
  }
  hero.gold -= innCost; hero.restsUsedToday = rUsed + 1; hero.lastRestEpoch = nowMs;
  hero.deathsDoorTrauma = false;
  hero.quests = Math.min(hero.maxQuests, hero.quests + 15);
  hero.hp = Math.min(hero.maxHp, hero.hp + Math.round(hero.maxHp * 0.75));
  hero.mp = Math.min(hero.maxMp, hero.mp + Math.round(hero.maxMp * 0.75));
  hero.stress = Math.max(0, (hero.stress || 0) - 25);
  (hero.mercenaries || []).forEach(function(m) { m.hp = Math.min(m.maxHp, m.hp + Math.round(m.maxHp * 0.60)); });
  (hero.children || []).forEach(function(ch) { ch.hp = Math.min(ch.maxHp || 100, (ch.hp || ch.maxHp || 100) + Math.round((ch.maxHp || 100) * 0.75)); });
  playSfx("levelup");
  var rMsg = renderSleepingRoomVectorSvg("cot") + "🛌 <b>Boar&apos;s Head Quick-Rest (" + hero.restsUsedToday + "/2 Today, -" + innCost.toLocaleString() + "g):</b><br>• <b>Quest Stamina:</b> <span style='color:#fbbf24;font-weight:bold;'>+15⚡ Quests (Now " + hero.quests + "/" + hero.maxQuests + "⚡)</span><br>• <b>Vitals Restored:</b> <span style='color:#4ade80;'>+75% HP/MP, -25% Stress &amp; Cured Death's Door Trauma</span> (30m Rest Lock started)";
  addLog("🛌 Quick-Rested at the Inn (+15⚡, 75% HP/MP & -25% Stress).");
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("🛌 Refreshed at the Inn!", "🛌🍺", null, "#d4af37", rMsg, "inn");
}

function equipInventoryItem(idx) {
  ensureHeroV3Fields(hero);
  var itm = hero.inventory[idx];
  if (!itm) return;
  var slotType = (itm.type && typeof itm.type === "string") ? itm.type : "weapon";
  itm = sanitizeGearItem(itm, slotType);
  var old = hero[slotType];
  hero[slotType] = itm;
  hero.inventory.splice(idx, 1);
  if (old) hero.inventory.push(sanitizeGearItem(old, slotType));
  if (slotType === "weapon") pushBuffToFifo("buff_wepperk", hero);
  syncHeroVitalityMaxHp(hero);
  addLog("🛡️ Equipped <b>" + (itm.icon || "🗡️") + " " + escapeHtml(itm.name) + "</b> (Old piece moved to Backpack)!");
  queueSaveHero(); renderGameScreen();
}

function sellInventoryItem(idx) {
  var itm = hero.inventory[idx];
  if (!itm) return;
  if (itm.locked) {
    showGothicToast("🔒 This item is Locked! Tap 🔒 to unlock before selling.");
    return;
  }
  var val = Math.max(10, Math.round((itm.value || 25) * 0.42));
  hero.gold += val; hero.inventory.splice(idx, 1);
  addLog("💰 Sold unequipped <b>" + escapeHtml(itm.name) + "</b> from Backpack for <b>+" + val + "g</b> (Total Gold: " + hero.gold.toLocaleString() + "g).");
  queueSaveHero(); renderGameScreen();
}

function buyShopItem(idx) {
  ensureHeroV3Fields(hero);
  if ((hero.shopBuysToday || 0) >= MAX_DAILY_SHOP_BUYS) {
    showRequirementModal("Bazaar Purchase Limit Reached (5/5 Today)", "⚖️⏳", "Dwarven Caravan Guild laws limit each champion to <b>5 equipment purchases per day</b>.", "Return after midnight rollover (or use Admin Reset) for fresh caravan purchases!", "");
    return;
  }
  if (isMerchantBlacklisted()) {
    var remSec = Math.ceil((hero.merchantBlacklistUntil - Date.now()) / 1000);
    showRequirementModal(
      "Merchant Stall Barred (1-Hour Shoplifting Blacklist!)", "🚫⚖️",
      "The dwarven merchant remembers your shoplifting attempt and refuses to trade for another <b style='color:#fbbf24;'>" + formatCooldownSec(remSec) + "</b>!",
      "🎭 <b>Outlaw Disguise Trick:</b> Open <b>🎨 Studio</b> and equip the <b>Inquisitor Hood</b> or <b>Plague Doctor Beak</b> to bypass the merchant's blacklist incognito!",
      '<button class="btn btn-arcane" style="flex:1;" onclick="openCustomizeHeroModal()">🎭 Equip Disguise in Studio</button>'
    );
    return;
  }
  var itm = hero.shopInventory[idx];
  if (!itm) return;
  var st = getHeroStats();
  var price = Math.max(35, Math.round((itm.value || 50) * (1.30 - st.discountPct / 100.0)));
  if (hero.gold < price || hero.inventory.length >= 30) {
    showRequirementModal(
      hero.inventory.length >= 30 ? "Backpack Full (30/30)" : "Not Enough Gold (" + hero.gold.toLocaleString() + " / " + price.toLocaleString() + "g)", "⚖️💰",
      hero.inventory.length >= 30 ? "Your backpack is full (30/30 items)." : "Buying <b>" + escapeHtml(itm.name) + "</b> requires <b style='color:#fbbf24;'>" + price.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).",
      "Salvage or sell unequipped gear in your Backpack, raise your 👑 Charm for up to 45% OFF, or risk a 🥷 Shoplift heist!",
      ""
    );
    return;
  }
  itm = sanitizeGearItem(itm, itm.type || "weapon");
  hero.gold -= price;
  hero.shopBuysToday = (hero.shopBuysToday || 0) + 1;
  hero.inventory.push(itm); hero.shopInventory.splice(idx, 1);
  shopInventory = hero.shopInventory;
  playSfx("coin");
  var bMsg = "⚖️ <b>Caravan Purchase (" + hero.shopBuysToday + "/" + MAX_DAILY_SHOP_BUYS + " Today • -" + price.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left):</b><br>Added <b>" + formatItemStats(itm, true, false) + "</b> to your Backpack!";
  addLog(bMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("⚖️ Equipment Purchased!", itm.icon || "🗡️", null, "#d4af37", bMsg, "market");
}

function getMaxForgeCap() {
  return (hero && hero.unlockedArea >= 13) ? 25 : 15;
}
function getForgeCost(itm) { return itm ? Math.round(((itm.upgrade || 0) + 1) * 260 * Math.max(1, hero.level * 0.65)) : 0; }
function getTotalMaterialsCount() {
  var sum = 0;
  Object.keys(hero.materials || {}).forEach(function(k) { sum += (hero.materials[k] || 0); });
  return sum;
}
function consumeAnyMaterials(qty) {
  var rem = qty, keys = Object.keys(hero.materials || {});
  for (var i = 0; i < keys.length && rem > 0; i++) {
    var k = keys[i], avail = hero.materials[k] || 0;
    if (avail > 0) { var take = Math.min(avail, rem); hero.materials[k] -= take; rem -= take; }
  }
}

// Increased Monster Trophy Requirements for Tempering Weapons (5 + 3*Tier) & Armor/Relics (3 + 2*Tier)!
function getForgeOddsAndPreview(itm) {
  if (!itm) return { curUp: 0, cost: 0, matReq: 5, successPct: 100, crackRisk: false, gainText: "None" };
  var curUp = itm.upgrade || 0, cost = getForgeCost(itm);
  var isWeap = (itm.type === "weapon" || (!itm.type && itm.atk && !itm.def));
  var matReq = isWeap ? (5 + (curUp * 3)) : (3 + (curUp * 2));
  var failRiskPct = curUp >= 3 ? Math.min(58, (curUp - 2) * 6) : 0;
  var successPct = 100 - failRiskPct, crackRisk = (curUp >= 8), gains = [];
  if (itm.atk) gains.push("+" + (Math.max(1, Math.round(itm.atk * 0.08) + 1)) + " ATK");
  if (itm.def) gains.push("+" + (Math.max(1, Math.round(itm.def * 0.08) + 1)) + " DEF");
  if ((curUp + 1) % 2 === 0) gains.push("+1 Guts/Wits");
  return { curUp: curUp, cost: cost, matReq: matReq, successPct: successPct, crackRisk: crackRisk, gainText: gains.join(", ") || "+1 Stat" };
}

function upgradeEquippedGear(slotType) {
  ensureHeroV3Fields(hero);
  if ((hero.forgesUsedToday || 0) >= MAX_DAILY_FORGES) {
    showRequirementModal("Blacksmith Forge Daily Limit Reached (5/5 Today)", "⚒️⏳", "Master Blacksmith Brom can only temper equipment <b>5 times per day</b> before his forge cools.", "Return after midnight rollover (or use Admin Reset) for 5 more daily temperings!", "");
    return;
  }
  var itm = hero[slotType];
  var maxCap = getMaxForgeCap();
  if (!itm) return;
  if ((itm.upgrade || 0) >= maxCap) {
    showRequirementModal(
      maxCap === 15 ? "Star-Metal Tempering Locked (+15 Cap)" : "Maximum Celestial Temper Reached (+25)", "⚒️☄️",
      maxCap === 15 ? "Standard Dwarven Forges can only temper equipment up to <b>+15</b>." : "This item has reached the absolute pinnacle of <b>+25 Star-Metal Tempering</b>!",
      maxCap === 15 ? "Conquer Area 12 (<i>Vaelthazar, Emperor of Dragons</i>) and enter <b>Area 13: The Shattered Firmament</b> to unlock <b>+16 to +25 Star-Metal Tempering</b>!" : "Your weapon is forged to perfection!",
      ""
    );
    return;
  }
  var info = getForgeOddsAndPreview(itm);
  if (hero.gold < info.cost || getTotalMaterialsCount() < info.matReq) {
    showRequirementModal(
      "Insufficient Forging Materials", "⚒️📦",
      "Tempering <b>" + escapeHtml(itm.name) + " to +" + (info.curUp + 1) + "</b> requires:<br>• <b>" + info.cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)<br>• <b>" + info.matReq + " Monster Trophies</b> (You have <b>" + getTotalMaterialsCount() + " Trophies</b>)",
      "Patrol any region in the Realms tab to gather Monster Trophies and Gold!",
      ""
    );
    return;
  }
  hero.gold -= info.cost;
  hero.forgesUsedToday = (hero.forgesUsedToday || 0) + 1;
  consumeAnyMaterials(info.matReq);
  if ((Math.random() * 100) > info.successPct) {
    playSfx("death");
    var failMsg = "";
    if (info.crackRisk && itm.upgrade > 0) {
      itm.upgrade--;
      if (itm.atk) itm.atk = Math.max(1, Math.round(itm.atk * 0.92));
      if (itm.def) itm.def = Math.max(1, Math.round(itm.def * 0.92));
      failMsg = "💥 <b style='color:#ef4444;'>ANVIL CRACK (" + hero.forgesUsedToday + "/" + MAX_DAILY_FORGES + " Today • " + info.successPct + "% Odds Failed)!</b><br><b>" + escapeHtml(itm.name) + "</b> cracked under the hammer and dropped to <b>+" + itm.upgrade + "</b>!";
    } else {
      failMsg = "💥 <b>Hammer Slipped (" + hero.forgesUsedToday + "/" + MAX_DAILY_FORGES + " Today • " + info.successPct + "% Odds Failed)!</b><br>The strike glanced off the rune-steel, leaving <b>" + escapeHtml(itm.name) + "</b> intact at <b>+" + (itm.upgrade || 0) + "</b>.";
    }
    addLog(failMsg);
    queueSaveHero(); renderGameScreen();
    showOutcomeModal("💥 Forging Failed!", "💥🔨", null, "#991b1b", failMsg, null);
    return;
  }
  itm.upgrade = info.curUp + 1;
  itm.dur = itm.maxDur || 100;
  if (itm.atk) itm.atk = Math.round(itm.atk * 1.08) + 1;
  if (itm.def) itm.def = Math.round(itm.def * 1.08) + 1;
  if (itm.upgrade % 2 === 0) {
    if (itm.wits !== undefined) itm.wits += 1;
    if (itm.guts !== undefined) itm.guts += 1;
  }
  syncHeroVitalityMaxHp(hero);
  playSfx("levelup");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("gold", 34);
  var winMsg = "⚒️ <b style='color:#4ade80;'>MASTERWORK TEMPER SUCCESS (" + hero.forgesUsedToday + "/" + MAX_DAILY_FORGES + " Today • -" + info.matReq + " Trophies)!</b><br>Reforged <b>" + formatItemStats(itm, false, true) + "</b> to <b style='color:#fbbf24;'>+" + itm.upgrade + "</b> (100% Durability Restored)!";
  addLog(winMsg);
  queueSaveHero(); renderGameScreen();
  showOutcomeModal("⚒️ Tempered to +" + itm.upgrade + "!", itm.icon || "⚒️", null, "#4ade80", winMsg, null);
}

function addLog(msg) {
  if (!hero) return;
  if (!hero.logs) hero.logs = [];
  var d = new Date();
  var ts = (d.getHours() < 10 ? "0" : "") + d.getHours() + ":" + (d.getMinutes() < 10 ? "0" : "") + d.getMinutes();
  hero.logs.unshift("<span style='color:#78716c;font-size:10.5px;'>[" + ts + "]</span> " + msg);
  if (hero.logs.length > 60) hero.logs.pop();
  if (activeSlotKey) {
    try { sessionStorage.setItem("dcr_sess_logs_" + activeSlotKey, JSON.stringify(hero.logs)); } catch (e) {}
  }
}

function escapeHtml(str) { return String(str || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }

function formatItemStats(itm, showUpgradeBadge, isEquippedSlot) {
  if (!itm || typeof itm !== "object") return "Empty";
  var parts = [];
  if (itm.locked) parts.push("🔒LOCKED");
  if (itm.atk) parts.push("+" + itm.atk + " ATK");
  if (itm.def) parts.push("+" + itm.def + " DEF");
  if (itm.eva) parts.push("+" + itm.eva + "% Dodge");
  if (itm.guts) parts.push("+" + itm.guts + " G");
  if (itm.wits) parts.push("+" + itm.wits + " W");
  if (itm.charm) parts.push("+" + itm.charm + " C");
  if (itm.socket) parts.push("💎" + String(itm.socket).toUpperCase());
  if (itm.setPerk) parts.push("✨" + itm.setPerk);
  if (itm.kills) parts.push("💀" + itm.kills + "k");
  if (itm.anvilBoosts) parts.push("🔨" + itm.anvilBoosts + "/3");
  if (itm.stolen) parts.push("🥷CONTRABAND");
  if (itm.dur !== undefined) parts.push((itm.dur <= 0 ? "💥BROKEN 0%" : ("🛠" + itm.dur + "%")));
  var up = itm.upgrade ? " [+" + itm.upgrade + "]" : "";
  var mottoSpan = itm.motto ? (" <i style='color:#fde68a;font-size:10.5px;'>&ldquo;" + escapeHtml(itm.motto) + "&rdquo;</i>") : "";
  var statusTag = "";
  if (isEquippedSlot === true) {
    statusTag = "<span class='equipped-safe-tag'>🛡️ EQUIPPED</span>";
  } else if (showUpgradeBadge) {
    statusTag = "<span class='bag-unequipped-tag'>🎒 UNEQUIPPED</span>";
  }
  var delta = showUpgradeBadge ? getUpgradeDelta(itm) : 0;
  var upBadge = "";
  if (showUpgradeBadge) {
    if (delta > 0) upBadge = "<span class='upgrade-pill'>✨ UPGRADE (+" + delta + " Pwr)</span>";
    else if (delta < 0) upBadge = "<span style='color:#78716c;font-size:10px;margin-left:5px;'>(" + delta + " vs Equipped)</span>";
  }
  return statusTag + (itm.icon || "🗡️") + " <span class='rarity-" + (itm.rarity || "Common") + "'>" + escapeHtml(itm.name || "Relic") + up + "</span> <span style='color:#9c8f7a;font-size:11.5px;'>(" + parts.join(", ") + ")</span>" + mottoSpan + upBadge;
}
'''
}

String buildUiChunkB1() {
    return '''
function openFullLogModal() {
  if (!hero) return;
  var logLines = (hero.logs || []).map(function(l) { return '<div class="log-entry" style="padding:3px 0;border-bottom:1px solid #1f1726;">' + l + '</div>'; }).join('');
  showPopupModal(
    '<div style="font-size:18px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">📜 The Royal Campaign Chronicle (' + (hero.logs ? hero.logs.length : 0) + ' Entries)</div>' +
    '<div class="lore-subtitle-box">Every battle, royal warrant, and courtly intrigue of your current session is inscribed below.</div>' +
    '<div style="max-height:360px;overflow-y:auto;text-align:left;background:#07050a;padding:10px;border-radius:4px;border:1px solid #4a3823;font-size:13px;line-height:1.55;">' + logLines + '</div>' +
    '<button class="btn btn-gold" style="width:100%;margin-top:12px;" onclick="closePopupModal()">Close Chronicle</button>'
  );
}

