    dollHtml += '<div class="doll-slot" style="border-color:#4ade80;" title="Equipped Gear (Protected from Selling) — Tap to inspect Kill-Counter &amp; Engraving Scroll!" onclick="openEngraveGearModal(&#39;' + g.key + '&#39;)"><div class="doll-icon">' + (itm.icon || "🗡️") + '</div>' +
