      '<button class="btn ' + (currentTab === "rifts" ? "btn-arcane" : "") + '" onclick="setTab(&#39;rifts&#39;)">🌌 The Astral Sanctum</button>' +
      '<button class="btn ' + (currentTab === "raids" ? "btn-crimson" : "") + '" onclick="setTab(&#39;raids&#39;)">🌍 World Calamity (' + wbDev + '%)</button>' +
      '<button class="btn ' + (currentTab === "pvp" ? "btn-gold" : "") + '" onclick="setTab(&#39;pvp&#39;)">⚔️ The Blood-Lists (' + pvpLeft + '/' + MAX_DAILY_PVP_DUELS + ')</button>' +
    '</div>';
  }

  if (currentTab === "adventure") {
    var curTier = hero.areaQuestTier[curArea.id] || 0;
    var zbToday = (hero.zoneBossDaily && hero.zoneBossDaily[curArea.id]) ? hero.zoneBossDaily[curArea.id] : 0;
    var bossCdUntil = (hero.areaBossCooldownUntil && hero.areaBossCooldownUntil[curArea.id]) ? hero.areaBossCooldownUntil[curArea.id] : 0;
    var lairReady = curTier >= 10 && zbToday < MAX_DAILY_ZONE_BOSS && bossCdUntil <= nowMs;
    var delvesLeft = Math.max(0, MAX_DAILY_DELVES - (hero.delvesRunToday || 0));
    var spireLeft = Math.max(0, MAX_DAILY_SPIRE_RUNS - (hero.spireRunsToday || 0));
    var sabLeft = Math.max(0, MAX_DAILY_SABOTAGES - (hero.sabotagesUsedToday || 0));
    var delveRemSec = Math.max(0, Math.ceil((SIX_HOURS_MS - (nowMs - (hero.lastDelveEpoch || 0))) / 1000));
    var delveBtnLabel = hero.deathMarker ? ('⚱️ Soul-Urn Rescue (Torch Camp +30% Heal!)') : (delvesLeft <= 0 ? '⏳ Delves Cap (3/3 Today)' : (delveRemSec > 0 ? ('⏳ Crypt Sealed (' + formatCooldownSec(delveRemSec) + ')') : ('🔦 Crypt Delve (' + delvesLeft + '/' + MAX_DAILY_DELVES + ' • -8⚡)')));
    var uniquePreview = BOSS_UNIQUES[curArea.id] ? (BOSS_UNIQUES[curArea.id].icon + ' ' + BOSS_UNIQUES[curArea.id].name + (BOSS_UNIQUES[curArea.id].isGodTier ? ' [GOD-TIER!]' : '')) : 'Reliquary Gear';
    var bannerStyle = getAreaBannerStyle(curArea.id, curArea.bg);
    var lvCheck = getLevelDeltaModifiers(hero.level, curArea.minLv);
