        '<button class="btn btn-gold" style="min-height:26px;padding:2px 8px;font-size:10px;" onclick="if(window.repairAllEquippedGear)window.repairAllEquippedGear()">🔧 Brom Repair All</button>' +
        '<button class="btn btn-crimson" style="min-height:26px;padding:2px 8px;font-size:10px;" onclick="buyBeltItem(&#39;firebomb&#39;)">💣 +1 Fire-Bomb (' + haveBombs + '/5 • ' + bombCost + 'g)</button>' +
        '<button class="btn btn-sky" style="min-height:26px;padding:2px 8px;font-size:10px;" onclick="openAstralLeyWellModal()">⚡ Ley-Well Energy</button>' +
        (hero.companion ? '<button class="btn btn-arcane" style="min-height:26px;padding:2px 8px;font-size:10px;" onclick="feedCompanionMoraleTreat()">🍖 Feed Pet (-5🍞 • Have ' + haveRations + '🍞)</button>' : '') +
      '</div>' +
    '</div>';

    var holidayAlert = "";
    if (activeHol && activeHol.boss) {
      var holBossDone = (hero.krampusBossToday || 0) >= 1;
      holidayAlert = '<div style="background:linear-gradient(90deg,#2b0712,#451a03,#2b0712);border:2px solid #f97316;border-radius:4px;padding:8px 10px;margin-bottom:8px;font-size:12px;color:#fde68a;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<span>' + activeHol.icon + ' <b>' + escapeHtml(activeHol.name.toUpperCase()) + ':</b> ' + escapeHtml(activeHol.desc) + '</span>' +
        '<button class="btn ' + (holBossDone ? 'btn-locked' : 'btn-crimson') + '" style="min-height:28px;padding:3px 10px;font-size:11px;" onclick="embarkOnQuest(&#39;holidayBoss&#39;)">' + (holBossDone ? '⏳ Holiday Boss Slain Today (1/1)' : (activeHol.boss.icon + ' Challenge ' + escapeHtml(activeHol.boss.name) + ' (-5⚡)')) + '</button>' +
