    });
    rightCol += '</div>';
  }
  else if (currentTab === "army") { rightCol += renderKingdomAndGuildTabHtml(); }
  else if (currentTab === "town") { rightCol += renderCleanTownHubHtml(); }
  else if (currentTab === "inventory") { rightCol += renderInventoryAndSocketsTabHtml(gearSlots, bagUpgradesCnt); }
  return rightCol;
}
'''
}

String buildUiChunkB3() {
    return buildUiChunkB3a() + "\n" + buildUiChunkB3b() + "\n" + buildUiChunkB3c() + "\n" + buildUiChunkB3d()
}

String buildUiChunkB3a() {
    return '''
function renderKingdomAndGuildTabHtml() {
  var htm = '<div class="sub-nav-pills">' +
    '<button class="btn ' + (kingdomSubTab === "vista" ? "btn-gold" : "") + '" onclick="setKingdomSubTab(&#39;vista&#39;)">🏰 The Sovereign Stronghold</button>' +
    '<button class="btn ' + (kingdomSubTab === "works" ? "btn-gold" : "") + '" onclick="setKingdomSubTab(&#39;works&#39;)">🏗️ Royal Works &amp; Edicts</button>' +
    '<button class="btn ' + (kingdomSubTab === "party" ? "btn-gold" : "") + '" onclick="setKingdomSubTab(&#39;party&#39;)">⚜️ Sworn Retinue &amp; Menagerie</button>' +
    '<button class="btn ' + (kingdomSubTab === "war" ? "btn-gold" : "") + '" onclick="setKingdomSubTab(&#39;war&#39;)">🚩 The War Room &amp; Armada</button>' +
  '</div>';

  if (kingdomSubTab === "party") {
    var spLove = (hero.spouse && hero.spouse.love !== undefined) ? hero.spouse.love : 100;
    var bantersLeft = Math.max(0, MAX_DAILY_BANTERS - (hero.bantersUsedToday || 0));
    var banterRemSec = Math.max(0, Math.ceil((TWO_HOURS_MS - (Date.now() - (hero.lastBanterEpoch || 0))) / 1000));
    var banterBtnLbl = bantersLeft <= 0 ? '⏳ Banter Cap (3/3 Today)' : (banterRemSec > 0 ? ('⏳ Banter (' + formatCooldownSec(banterRemSec) + ')') : ('🔥 Campfire Banter (' + bantersLeft + '/' + MAX_DAILY_BANTERS + ' • +10% HP)'));
    var curRecOrder = hero.recruitOrder || "auto";
    var recOrderMeta = RECRUIT_ORDERS[curRecOrder] || RECRUIT_ORDERS.auto;
    var recBond = getActiveRecruitSynergyBond(hero);
    var mercLeft = Math.max(0, 2 - (hero.mercHiresToday || 0));
    var activeHelperCnt = getActiveHelperCount(hero);
    var totDeaths = hero.totalRecruitDeaths || (hero.fallenHeroes ? hero.fallenHeroes.length : 0);
    var haveRat = (hero.guild && hero.guild.rations) ? hero.guild.rations : 0;

    htm += '<div class="lore-subtitle-box">⚖️ <b>The Two-Companion Decree (Active Helpers: ' + activeHelperCnt + ' / 2 Max):</b> You may march into battle with at most <b>2 total helpers</b> (any combination of Sellsword Recruits, an Animal Companion, a Dynasty Heir, or an Alt Slot Bodyguard). Dismiss an active helper anytime to free a slot.<br>' +
      '⚰️ <b>7-Day Resurrectionist Lore &amp; Hazard Pay:</b> If a recruit falls in battle, the Resurrectionists of the Weeping Graveyard require <b>7 Days</b> to stitch their soul back together—and every death under your banner raises sellsword contract costs by <b>+12% (Max +60%)</b> (Current Hazard Tax: <b style="color:' + (totDeaths > 0 ? '#f87171' : '#4ade80') + ';">+' + Math.min(60, totDeaths * 12) + '%</b> from ' + totDeaths + ' fallen)!</div>';

    htm += '<div class="velvet-consort-card" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">' +
      '<div style="display:flex;align-items:center;gap:10px;">' + (hero.spouse ? renderLadyPortraitSvg(hero.spouse.id || hero.spouse.name, 48) : '<div style="font-size:28px;">🌹</div>') +
      '<div><b>💍 The Velvet Chamber &amp; Royal Bloodline:</b> ' + (hero.spouse ? (hero.spouse.icon + ' <b>' + escapeHtml(hero.spouse.name) + '</b> (<span style="color:' + (spLove < 40 ? '#ef4444' : '#f472b6') + ';">' + spLove + '% ❤️' + (spLove >= 90 ? ' • 🌟Dual-Tech Ready!' : '') + '</span>)') : '<i>Unwed — Required to Charter Royal Estate!</i>') + ' • 👶 <b>' + (hero.children ? hero.children.length : 0) + '/6 Mortal Heirs</b></div></div>' +
      '<div style="display:flex;gap:6px;"><button class="btn ' + (banterRemSec > 0 || bantersLeft <= 0 ? 'btn-locked' : 'btn-sky') + '" onclick="triggerCampfireBanter()">' + banterBtnLbl + '</button><button class="btn btn-gold" onclick="openTownFacilityModal(&#39;courting&#39;)">🌹 Velvet Chamber</button></div></div>';

    htm += '<div class="recruits-battle-card" style="margin-bottom:10px;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px;">' +
        '<span style="font-size:12px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;">🛡️ DEFAULT RECRUIT BATTLE DOCTRINE: ' + recOrderMeta.name + (recBond ? ' • 🤝 ' + recBond.name : '') + '</span>' +
        '<span style="font-size:11px;color:#fde68a;">' + escapeHtml(recOrderMeta.desc) + '</span>' +
      '</div>' +
      (recBond ? '<div style="font-size:11px;color:#4ade80;margin-top:3px;">🤝 <b>Active Synergy Bond:</b> ' + escapeHtml(recBond.desc) + '</div>' : '') +
      '<div class="recruit-order-bar">' +
        '<button class="btn ' + (curRecOrder === "attack" ? "btn-crimson" : "") + '" style="flex:1;min-height:28px;font-size:10.5px;" onclick="setRecruitOrder(&#39;attack&#39;)">⚔️ Attack (+30% DMG)</button>' +
        '<button class="btn ' + (curRecOrder === "defend" ? "btn-sky" : "") + '" style="flex:1;min-height:28px;font-size:10.5px;" onclick="setRecruitOrder(&#39;defend&#39;)">🛡️ Defend (+12% DEF)</button>' +
        '<button class="btn ' + (curRecOrder === "mix" ? "btn-emerald" : "") + '" style="flex:1;min-height:28px;font-size:10.5px;" onclick="setRecruitOrder(&#39;mix&#39;)">⚖️ Mix (Strike + Heal)</button>' +
        '<button class="btn ' + (curRecOrder === "auto" ? "btn-gold" : "") + '" style="flex:1;min-height:28px;font-size:10.5px;" onclick="setRecruitOrder(&#39;auto&#39;)">🤖 Auto (Smart AI)</button>' +
        '<button class="btn ' + (curRecOrder === "protect" ? "btn-ult" : "") + '" style="flex:1.2;min-height:28px;font-size:10.5px;" onclick="setRecruitOrder(&#39;protect&#39;)">🩸 Protect (Sacrifice)</button>' +
      '</div>' +
    '</div>';

    var altCards = [];
    var maxS = serverData.maxSlots || 3;
    for (var s = 1; s <= maxS; s++) {
      var sk = "slot_" + s;
      var altH = (serverData.slots && serverData.slots[sk]) ? serverData.slots[sk] : null;
      if (altH && altH.name && sk !== activeSlotKey) {
        ensureHeroV3Fields(altH);
        var altSt = getHeroStats(altH);
        var retCost = Math.max(850, altH.level * 135 + hero.level * 65);
        var isHired = (hero.altBodyguard && hero.altBodyguard.slotKey === sk);
        altCards.push('<div class="slot-card" style="border-color:#38bdf8;">' +
          '<div style="display:flex;align-items:center;gap:8px;">' + renderHeroPortraitSvg(altH, 42) +
            '<div><div style="font-weight:800;color:#7dd3fc;font-family:Cinzel,serif;">🛡️ Alt Champion: ' + escapeHtml(altH.name) + ' (Lv ' + altH.level + ')</div>' +
            '<div style="font-size:11px;color:#e5dec9;">ATK: ' + altSt.atk + ' • Retainer: 8 Quests (100% Gold Paid to ' + escapeHtml(altH.name) + '!)</div></div></div>' +
          '<div style="font-size:10.5px;color:#86efac;margin:4px 0;">💰 Hiring transfers <b>' + retCost.toLocaleString() + 'g</b> directly into <b>' + escapeHtml(altH.name) + '&apos;s</b> treasury and sends them a Raven Battle Report if they survive or fall (never harms their actual character)!</div>' +
          '<button class="btn ' + (isHired ? 'btn-emerald' : 'btn-sky') + '" style="width:100%;margin-top:4px;" onclick="if(window.hireAltSlotBodyguard)window.hireAltSlotBodyguard(&#39;' + sk + '&#39;)">' + (isHired ? ('✅ Guarding (' + hero.altBodyguard.questsLeft + 'q left — Tap to Dismiss)') : ('🛡️ Hire Alt Bodyguard (' + retCost.toLocaleString() + 'g • Have ' + hero.gold.toLocaleString() + 'g)')) + '</button></div>');
      }
    }
    if (altCards.length > 0) {
      htm += '<div class="card-title"><span>🛡️ Sworn Bloodline Retainers (Hire Another Hero Slot into Battle)</span></div><div class="slot-grid" style="margin-bottom:10px;">' + altCards.join('') + '</div>';
    }

    if (hero.mercenaries && hero.mercenaries.length) {
      htm += '<div class="card-title"><span>🎖️ Active Sellsword Retinue (' + hero.mercenaries.length + ' Recruited • Total Helpers: ' + activeHelperCnt + '/2)</span></div><div class="slot-grid" style="margin-bottom:10px;">';
      hero.mercenaries.forEach(function(m, idx) {
        var stars = m.vetRank >= 3 ? "★★★ Champion" : (m.vetRank === 2 ? "★★ Elite" : (m.vetRank === 1 ? "★ Veteran" : "Sworn"));
        var qkLine = m.quirk ? ('<div style="font-size:11px;color:' + (m.quirk.isPositive ? '#4ade80' : '#f87171') + ';margin-bottom:4px;">🧠 Quirk: <b>' + m.quirk.name + '</b> (' + m.quirk.desc + ')</div>') : '';
        var disLine = m.disease ? ('<div style="font-size:11px;color:#fca5a5;background:#2b0712;border:1px solid #ef4444;padding:3px 6px;border-radius:4px;margin-bottom:4px;">🦠 <b>Infected: ' + escapeHtml(m.disease.name) + '</b> (' + escapeHtml(m.disease.recruitEffect || '-15% Recruit ATK') + (m.disease.caughtFrom ? ' • Caught from ' + escapeHtml(m.disease.caughtFrom) : '') + ')</div>') : '';
        htm += '<div class="slot-card" style="border-color:' + (m.disease ? '#ef4444' : '#c5a059') + ';">' +
          '<div style="display:flex;align-items:center;gap:8px;">' + renderEntityAvatar(m.name, m.icon, 42, false) +
          '<div style="font-weight:800;color:#86efac;font-family:&#39;Cinzel&#39;,serif;">' + m.icon + ' ' + escapeHtml(m.name) + ' <span style="color:#d4af37;">[' + stars + ']</span></div></div>' +
          '<div style="font-size:12px;color:#e5dec9;margin:4px 0;">❤️ HP: <b>' + m.hp + '/' + m.maxHp + '</b> • 🗡️ ATK: <b>' + m.atk + '</b> • 💀 Kills: <b>' + (m.kills || 0) + '</b></div>' +
          '<div style="background:#090d16;border:1px solid #38bdf8;border-radius:4px;padding:4px 6px;margin-bottom:5px;font-size:10.5px;color:#7dd3fc;">' +
            '📊 <b>Lifetime Service:</b> 💥 <b>' + (m.totalDmg || 0).toLocaleString() + ' DMG</b> • 💚 <b>' + (m.totalHeals || 0).toLocaleString() + ' Healed</b> • 🛡️ <b>' + (m.dmgAbsorbed || 0).toLocaleString() + ' Tanked</b> • 🐉 <b>' + (m.bossesAssisted || 0) + ' Bosses</b>' +
          '</div>' +
          disLine + qkLine +
          '<div style="font-size:11px;color:#fde68a;margin-bottom:5px;">🛡️ Gear: ' + (m.gear ? formatItemStats(m.gear, false, true) : '<i>None</i>') + '</div>' +
          '<div style="display:flex;gap:5px;flex-wrap:wrap;">' +
            '<button class="btn btn-sky" style="flex:1;" onclick="equipMercenaryGear(' + idx + ')">🎒 Equip Gear</button>' +
            (m.disease ? '<button class="btn btn-crimson" onclick="checkAndShowPostBattleDiseasePopup()">🦠 Cure Disease</button>' : '') +
            (m.quirk && !m.quirk.isPositive ? '<button class="btn btn-crimson" onclick="cureMercenaryQuirkSanitarium(' + idx + ')">🏥 Cure Quirk</button>' : '') +
            (m.vetRank >= 3 && !m.loyaltyDone ? '<button class="btn btn-shine" onclick="if(window.completeMercenaryLoyaltyQuest)window.completeMercenaryLoyaltyQuest(' + idx + ')">🌟 Loyalty Quest</button>' : '') +
            '<button class="btn" title="Honorably discharge this sellsword to free a Helper Slot" onclick="dismissMercenaryFighter(' + idx + ')">🏕️ Dismiss</button>' +
          '</div></div>';
      });
      htm += '</div>';
    }
    htm += '<div class="card-title"><span>⚔️ Sellsword Guild Hall &amp; Royal Kennels (Active Helpers: ' + activeHelperCnt + '/2 • 💰' + hero.gold.toLocaleString() + 'g • 💎' + (hero.gems || 0) + ' • 🍞' + haveRat + ')</span></div><div class="slot-grid">';
    MERCENARY_POOL.forEach(function(m) {
      var inParty = (hero.mercenaries || []).some(function(x) { return x.id === m.id; });
      var mCost = getMercHireCost(m);
      var cdUntil = (hero.mercCooldowns && hero.mercCooldowns[m.id]) ? hero.mercCooldowns[m.id] : 0;
      var onReviveCd = cdUntil > Date.now();
      var cdRemTxt = onReviveCd ? formatCooldownSec(Math.ceil((cdUntil - Date.now()) / 1000)) : "";
      var btnLbl = inParty ? '✅ In Retinue' : (onReviveCd ? ('⚰️ 7d Revival Rite (' + cdRemTxt + ')') : (mercLeft <= 0 ? '⏳ Daily Cap (2/2)' : ('Hire (' + mCost.toLocaleString() + 'g • Have ' + hero.gold.toLocaleString() + 'g)')));
      htm += '<div class="slot-card" style="' + (onReviveCd ? 'opacity:0.65;border-color:#991b1b;' : (m.isMartyr ? 'border-color:#f43f5e;' : '')) + '">' +
        '<div style="display:flex;align-items:center;gap:8px;">' + renderEntityAvatar(m.name, m.icon, 40, false) +
        '<div><div style="font-weight:800;color:' + (m.isMartyr ? '#fda4af' : '#d4af37') + ';font-family:&#39;Cinzel&#39;,serif;">' + m.icon + ' ' + m.name + '</div><div style="font-size:11px;color:#9c8f7a;">' + m.role + ' • HP: ' + (m.baseHp + hero.level * 15) + ' | ATK: ' + (m.baseAtk + Math.round(hero.level * 1.9)) + '</div></div></div>' +
        '<div style="font-size:11px;color:#e5dec9;margin:4px 0;">' + escapeHtml(m.desc) + (onReviveCd ? ('<br><b style="color:#f87171;">⚰️ Resurrectionists are stitching their soul back together (' + cdRemTxt + ' left)!</b>') : '') + '</div>' +
        '<button class="btn ' + (inParty ? 'btn-emerald' : (onReviveCd || mercLeft <= 0 || activeHelperCnt >= 2 ? 'btn-locked' : (m.isMartyr ? 'btn-crimson' : 'btn-gold'))) + '" style="width:100%;margin-top:4px;" onclick="hireMercenaryFighter(&#39;' + m.id + '&#39;)">' + btnLbl + '</button></div>';
    });
    COMPANIONS.forEach(function(c) {
      var owned = hero.ownedCompanions && hero.ownedCompanions.includes(c.id);
      var isEq = hero.companion && hero.companion.id === c.id;
      var evoTier = (hero.petEvo && hero.petEvo[c.id]) ? hero.petEvo[c.id] : 1;
      var reqMats = evoTier * 4, reqGems = evoTier * 3;
      htm += '<div class="slot-card"><div style="font-weight:800;color:#7dd3fc;font-family:&#39;Cinzel&#39;,serif;">' + c.icon + ' ' + c.name + (owned ? ' <span style="color:#fde047;">[Stage ' + evoTier + '/3]</span>' : '') + (isEq && (hero.petTreatBattles || 0) > 0 ? ' <span style="color:#4ade80;font-size:10px;">[🍖+' + hero.petTreatBattles + 'b Surge]</span>' : '') + '</div><div style="font-size:12px;color:#e5dec9;margin:4px 0;">' + c.desc + '</div>' +
        '<div style="display:flex;gap:4px;flex-wrap:wrap;">' +
          '<button class="btn ' + (isEq ? 'btn-emerald' : 'btn-arcane') + '" style="flex:1;" onclick="adoptOrEquipCompanion(&#39;' + c.id + '&#39;)">' + (isEq ? '✅ Active (Tap to Kennel)' : (owned ? 'Summon (1 Helper Slot)' : ('Bind (' + c.costGold.toLocaleString() + 'g, ' + c.costGems + '💎 • Have ' + (hero.gems || 0) + '💎)'))) + '</button>' +
          (isEq ? '<button class="btn btn-sky" title="Feed 5🍞 Rations for +50% Pet DMG &amp; +5% Hit/Crit for 3 Battles" onclick="feedCompanionMoraleTreat()">🍖 Feed (-5🍞 • Have ' + haveRat + '🍞)</button>' : '') +
          (owned && evoTier < 3 ? '<button class="btn btn-gold" onclick="if(window.evolveCompanionStage)window.evolveCompanionStage(&#39;' + c.id + '&#39;)">🌟 Evolve (' + reqMats + ' Mats, ' + reqGems + '💎)</button>' : '') +
        '</div></div>';
    });
    htm += '</div>';

    var menList = hero.menagerie || [];
    htm += '<div class="card-title" style="margin-top:12px;"><span>🦁 Beastmaster Thulsa&apos;s Grand Menagerie (' + menList.length + '/12 Captured Beasts • +' + (menList.length * 45) + 'g / tick)</span></div>';
    if (!menList.length) {
      htm += '<div style="font-size:12px;color:#9c8f7a;padding:6px;">No monsters captured yet. Weaken any non-boss monster below 25% HP in battle and tap <b>🕸️ Soul-Snare Capture</b> to cage them for Beastmaster Thulsa!</div>';
    } else {
      htm += '<div class="slot-grid">' + menList.map(function(b) {
        return '<div class="doll-slot">' + renderEntityAvatar(b.name, b.icon, 34, true) + '<div><b>' + b.icon + ' ' + escapeHtml(b.name) + '</b><div style="font-size:10.5px;color:#4ade80;">Lv ' + (b.lv || 1) + ' • +45g Exotic Tithe</div></div></div>';
      }).join('') + '</div>';
    }
    return htm;
  }

  if (!hero.guild || !hero.guild.founded) {
    var totMats = getTotalMaterialsCount();
    var canCharter = hero.level >= 20 && hero.spouse && (hero.nobleIdx || 0) >= 2 && hero.gold >= 25000 && totMats >= 35 && (hero.gems || 0) >= 5;
    var crestOpts = GUILD_CRESTS.map(function(cr) { return '<option value="' + cr + '">' + cr + ' Crest</option>'; }).join('');
    htm += '<div class="card-title"><span>🏰 Charter Your Sovereign Royal Estate</span><span class="gem-pill">💎 ' + (hero.gems || 0) + ' Gems</span></div>' +
      '<div class="lore-subtitle-box">Establishing a Sovereign Royal Estate unlocks citizen workforce allocation, stronghold fortifications, daily domain taxation, and the Royal Shipyard.</div>' +
      '<div class="slot-card" style="max-width:560px;margin:0 auto;text-align:left;">' +
        '<div style="font-size:13px;color:#e5dec9;margin-bottom:10px;line-height:1.6;background:#0b0811;padding:10px;border-radius:4px;border:1px solid #4a3823;">' +
          '<div style="font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">📜 Royal Estate Charter Requirements:</div>' +
          '<div>• Hero Level 20+: <b style="color:' + (hero.level >= 20 ? '#4ade80' : '#f87171') + ';">Lv ' + hero.level + ' / 20</b></div>' +
          '<div>• Married to a Royal Consort: <b style="color:' + (hero.spouse ? '#4ade80' : '#f87171') + ';">' + (hero.spouse ? escapeHtml(hero.spouse.name) : 'Unwed (Visit Velvet Chamber!)') + '</b></div>' +
          '<div>• Noble Title (Knight+): <b style="color:' + ((hero.nobleIdx || 0) >= 2 ? '#4ade80' : '#f87171') + ';">' + hero.nobleRank + '</b></div>' +
          '<div>• Treasury, Trophies &amp; Gems: <b style="color:' + (hero.gold >= 25000 && totMats >= 35 && (hero.gems || 0) >= 5 ? '#4ade80' : '#f87171') + ';">' + hero.gold.toLocaleString() + '/25,000g • ' + totMats + '/35 Mats • ' + (hero.gems || 0) + '/5💎</b></div>' +
        '</div>' +
        '<input type="text" id="guildNameInput" placeholder="Enter Royal Estate / Kingdom Name..." maxlength="28" style="margin-bottom:8px;">' +
        '<select id="guildCrestSelect" style="margin-bottom:8px;">' + crestOpts + '</select>' +
        '<input type="text" id="guildMottoInput" value="Iron Within, Glory Without!" maxlength="80" style="margin-bottom:10px;">' +
        '<button class="btn ' + (canCharter ? 'btn-shine' : 'btn-locked') + '" style="width:100%;" onclick="foundPlayerGuild()">🚩 Seal Royal Estate Charter (25,000g, 35 Mats, 5💎)</button></div>';
    return htm;
  }

  return renderCharteredKingdomSubTabs(htm);
}
'''
}

String buildUiChunkB3b() {
    return '''
function renderCharteredKingdomSubTabs(htm) {
  var km = getKingdomMetrics(), gSum = getGuildArmySummary();
  var blds = hero.guild.buildings || {};
  var wf = hero.guild.workforce || { farmers: 2, lumber: 1, quarry: 1, burghers: 1, watch: 1 };

  if (kingdomSubTab === "vista") {
    var taxCollectedToday = (hero.lastTaxDateStr === getTodayDateStr());
    var dulledCnt = (hero.vault && hero.vault.dulledGems) ? hero.vault.dulledGems : 0;
    var carLeft = Math.max(0, MAX_DAILY_CARAVANS - (hero.caravansRunToday || 0));
    var thrLeft = Math.max(0, MAX_DAILY_THRONE_ACTIONS - (hero.throneActionsToday || 0));
    var trtLeft = Math.max(0, 2 - (hero.treatiesToday || 0));
    htm += renderVectorKingdomVistaSvg(km);
    htm += '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:8px;text-align:center;font-size:12px;">' +
      '<div class="slot-card" style="padding:6px;">🪵 Timber<br><b style="color:#d4af37;font-size:14px;">' + (hero.guild.timber || 0) + '</b></div>' +
      '<div class="slot-card" style="padding:6px;">🪨 Stone<br><b style="color:#e5dec9;font-size:14px;">' + (hero.guild.stone || 0) + '</b></div>' +
      '<div class="slot-card" style="padding:6px;">⛏️ Iron<br><b style="color:#7dd3fc;font-size:14px;">' + (hero.guild.iron || 0) + '</b></div>' +
      '<div class="slot-card" style="padding:6px;">🍞 Rations<br><b style="color:#86efac;font-size:14px;">' + (hero.guild.rations || 0) + '</b></div>' +
    '</div>';
    htm += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:6px;margin-bottom:10px;">' +
      '<button class="btn ' + (taxCollectedToday ? 'btn-locked' : 'btn-emerald') + '" onclick="collectKingdomTaxes()">' + (taxCollectedToday ? '⏳ Tax Collected (1/1)' : ('💰 Levy Tithe (+' + km.tax + 'g)')) + '</button>' +
      '<button class="btn ' + (thrLeft > 0 ? 'btn-gold' : 'btn-locked') + '" onclick="openThronePetitionModal()">👑 Petitions (' + thrLeft + '/' + MAX_DAILY_THRONE_ACTIONS + ')</button>' +
      '<button class="btn ' + (thrLeft > 0 ? 'btn-crimson' : 'btn-locked') + '" onclick="openInquisitorialTrialModal()">⛓️ Gaol &amp; Tribunal (' + (hero.prisoners ? hero.prisoners.length : 0) + ')</button>' +
      '<button class="btn ' + (carLeft > 0 ? 'btn-sky' : 'btn-locked') + '" onclick="dispatchTradeCaravan()">🐎 Caravan (-30🪵/🪨 • ' + carLeft + '/' + MAX_DAILY_CARAVANS + ')</button>' +
      '<button class="btn ' + (hero.guild.autoCaravan ? 'btn-emerald' : '') + '" title="Baron+ Automated Supply Caravan Route: Converts 15🪵 + 15🪨 into +25🍞 Rations &amp; +120g on every 45m tick!" onclick="toggleAutomatedCaravanRoute()">🔄 Auto-Caravan: ' + (hero.guild.autoCaravan ? 'ON' : 'OFF') + '</button>' +
      '<button class="btn ' + (trtLeft > 0 ? 'btn-gold' : 'btn-locked') + '" onclick="openCrossSlotTradeTreatyModal()">🤝 Trade Treaty (' + trtLeft + '/2)</button>' +
