    '<div class="slot-grid">' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("court") + ';" onclick="openTownFacilityModal(&#39;court&#39;)"><div style="font-size:32px;">👑</div><div><div style="font-weight:900;color:#d4af37;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Obsidian High Court ' + (hero.level < 2 ? '🔒(Lv 2+)' : '') + '</div><div style="font-size:11.5px;color:#e5dec9;">Feudal Rank: <b>' + hero.nobleRank + ' (' + (hero.fame || 0) + '/' + maxF + ' Fame)</b>' + ((hero.wantedLevel || 0) > 0 ? ' • <b style="color:#ef4444;">🚨Wanted Lv ' + hero.wantedLevel + '</b>' : (nextRank ? ' ➔ Petition for <b>' + nextRank.title + '</b>' : '')) + '</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("courting") + ';border-color:#f472b6;" onclick="openTownFacilityModal(&#39;courting&#39;)"><div style="font-size:32px;">🌹</div><div><div style="font-weight:900;color:#f472b6;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Velvet Chamber ' + ((hero.nobleIdx || 0) < 1 ? '🔒(Squire+)' : '') + '</div><div style="font-size:11.5px;color:#e5dec9;">' + (hero.spouse ? ('Active Consort: <b>' + escapeHtml(hero.spouse.name) + ' (' + spLove + '% ❤️)</b>') : 'Court Noble Ladies &amp; Forge Royal Alliances') + ' • 👶 <b>' + (hero.children ? hero.children.length : 0) + '/6 Scions</b></div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("sanctuary") + ';" onclick="openTownFacilityModal(&#39;sanctuary&#39;)"><div style="font-size:32px;">🕯️</div><div><div style="font-weight:900;color:#86efac;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">Cathedral of the First Flame</div><div style="font-size:11.5px;color:#e5dec9;">Healing Rites, Confessional Penance, Leech Ward' + (disCnt > 0 ? (' <b style="color:#ef4444;">(🦠' + disCnt + ' Disease!)</b>') : '') + ' &amp; Valkyrie Reliquary</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("vespera") + ';border-color:' + (disCnt > 0 ? '#ef4444' : '#c084fc') + ';" onclick="openTownFacilityModal(&#39;vespera&#39;)"><div style="font-size:32px;">💎🩺</div><div><div style="font-weight:900;color:#e9d5ff;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">Sister Vespera&apos;s Dragon-Glass Clinic</div><div style="font-size:11.5px;color:#e5dec9;">' + (disCnt > 0 ? ('<b style="color:#fca5a5;">🦠 ' + disCnt + ' Active Party Disease(s) — Purge for 15💎!</b>') : 'Unlimited 15💎 Dragon-Glass Disease Purge (Hero &amp; Recruits)') + '</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("library") + ';border-color:#38bdf8;" onclick="openTownFacilityModal(&#39;library&#39;)"><div style="font-size:32px;">📚</div><div><div style="font-weight:900;color:#7dd3fc;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Grand Royal Library</div><div style="font-size:11.5px;color:#e5dec9;">World Guide, Diseases (' + disCnt + '), Sanity, Recruit Quirks &amp; Dynasty Archives</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("legends") + ';border-color:#fde047;" onclick="openAstralLeyWellModal()"><div style="font-size:32px;">⚡🔥</div><div><div style="font-weight:900;color:#fde047;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Astral Ley-Well (' + leyLeft + '/2 Today)</div><div style="font-size:11.5px;color:#e5dec9;">Sacrifice <b>4💎 Gems, Gold &amp; 12 Trophies</b> for <b>100% Full Energy (' + hero.quests + '/' + hero.maxQuests + '⚡)</b></div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("inn") + ';" onclick="openTownFacilityModal(&#39;inn&#39;)"><div style="font-size:32px;">🍺🛌</div><div><div style="font-weight:900;color:#7dd3fc;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Boar&apos;s Head Tavern &amp; Inn</div><div style="font-size:11.5px;color:#e5dec9;">🥃 Dragon-Malt (-50% Stress / 2h Drunk Risk), Feasts &amp; Stress-Healing Beds</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("market") + ';" onclick="openTownFacilityModal(&#39;market&#39;)"><div style="font-size:32px;">⚖️</div><div><div style="font-weight:900;color:#fde68a;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Ironcrag Caravan Bazaar</div><div style="font-size:11.5px;color:#e5dec9;">Dwarven Arms, Blacksmith Brom, Trophy Exchange (' + totMats + '📦) &amp; Jonah</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("vault") + ';" onclick="openTownFacilityModal(&#39;post&#39;)"><div style="font-size:32px;">🏦</div><div><div style="font-weight:900;color:#c084fc;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Royal Reliquary Vault</div><div style="font-size:11.5px;color:#e5dec9;">Treasury: <b style="color:#fbbf24;">' + (v.gold || 0).toLocaleString() + 'g</b> • Sealed Gems: <b style="color:#fde047;">' + (v.gems || 0) + '/20💎</b> • Heirlooms: <b>' + (v.items ? v.items.length : 0) + '/25</b></div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("graveyard") + ';border-color:#f43f5e;" onclick="openTownFacilityModal(&#39;graveyard&#39;)"><div style="font-size:32px;">⚰️</div><div><div style="font-weight:900;color:#fca5a5;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Weeping Graveyard</div><div style="font-size:11.5px;color:#e5dec9;">' + (mySlotDead ? ('<b style="color:#fde047;">⛏️👻 Ancestral Soul of ' + escapeHtml(mySlotDead.name) + ' Awaiting Exhumation!</b>') : 'Ancestral Burial Plots &amp; Memorials of the Fallen') + '</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("legends") + ';border-color:#fde047;" onclick="openTownFacilityModal(&#39;legends&#39;)"><div style="font-size:32px;">🌟</div><div><div style="font-weight:900;color:#fde047;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Hall of Legends ' + (hero.level < 50 ? '🔒(Lv 50+)' : '') + '</div><div style="font-size:11.5px;color:#e5dec9;">Seat of Grandmaster Solaris the Oath-Keeper (Trial Stage ' + (hero.ultQuestStage || 0) + '/5)</div></div></div>' +
      '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("wagers") + ';" onclick="openTownFacilityModal(&#39;wagers&#39;)"><div style="font-size:32px;">🏇</div><div><div style="font-weight:900;color:#fca5a5;font-size:14px;font-family:&#39;Cinzel&#39;,serif;text-shadow:0 2px 6px #000;">The Grand Tourney Grounds</div><div style="font-size:11.5px;color:#e5dec9;">Jousting Lists, Seer&apos;s Vardo, High Court Debates &amp; Royal Archives</div></div></div>' +
    '</div>';
}

function openTownFacilityModal(fac) {
  ensureHeroV3Fields(hero);
  if (fac === "library") {
    if (window.openGrandRoyalLibraryModal) window.openGrandRoyalLibraryModal("ui");
    return;
  }
  if (fac === "vespera") {
    if (window.openSisterVesperaModal) window.openSisterVesperaModal();
    return;
  }
  if (fac === "leywell") {
    openAstralLeyWellModal();
    return;
  }
  if (fac === "court" && hero.level < 2) {
    showRequirementModal("High Court Gates Locked (Requires Level 2+)", "👑🔒", "The obsidian doors of the High Court only open to heroes who have survived their first season of battle (<b>Level 2+</b>).", "Patrol Area 1 (The Blighted Shire Fields) to reach Level 2 and unlock the High Court!", "");
    return;
  }
  if (fac === "courting" && (hero.nobleIdx || 0) < 1 && !hero.spouse) {
    showRequirementModal("Velvet Chamber Sealed (Requires Squire+ Title)", "🌹🔒", "The royal attendants of the Velvet Chamber only admit titled nobility (<b>Squire</b> or higher).", "Reach Level 3 and petition the High Court for the rank of Squire to unlock the Velvet Chamber!", "");
    return;
  }
  if (fac === "legends" && hero.level < 50) {
    showRequirementModal("Hall of Legends Sealed (Requires Level 50+)", "🌟🔒", "<b>Grandmaster Solaris the Oath-Keeper</b> only admits seasoned champions of <b>Level 50 or higher</b> (Currently Lv " + hero.level + ") to undertake the 5-Stage Class Ultimate Saga.", "Conquer the realms and climb the Abyssal Spire to reach Level 50, then return to claim your Class Ultimate trial!", "");
    return;
  }
  if (window.checkFirstEntryTownLore && window.checkFirstEntryTownLore(fac)) return;

  window.currentTownModal = fac;
  var nowMs = Date.now(), st = getHeroStats();

  if (fac === "legends") { if (window.openHallOfLegendsModal) window.openHallOfLegendsModal(); return; }
  if (fac === "graveyard") { if (window.openWeepingGraveyardModal) window.openWeepingGraveyardModal(); return; }

  if (fac === "court") {
    var nextRank = NOBLE_RANKS[(hero.nobleIdx || 0) + 1];
    var curRankObj = NOBLE_RANKS[hero.nobleIdx || 0] || NOBLE_RANKS[0];
    var totMats = getTotalMaterialsCount();
    var maxF = getMaxFameForLevel(hero.level);
    var petLeft = Math.max(0, MAX_DAILY_COURT_PETITIONS - (hero.courtPetitionsToday || 0));
    var intLeft = Math.max(0, MAX_DAILY_INTRIGUE - (hero.intrigueUsedToday || 0));
    var wantedAlert = "";
    if ((hero.wantedLevel || 0) > 0) {
      var pardonCost = hero.wantedLevel * Math.max(400, hero.level * 55);
      wantedAlert = '<div style="background:#450a0a;border:2px solid #ef4444;border-radius:4px;padding:8px 10px;margin-top:6px;font-size:12px;color:#fecaca;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<span>🚨 <b>WANTED OUTLAW (Level ' + hero.wantedLevel + '):</b> High Court Petitions are barred and ' + (hero.wantedLevel >= 5 ? '<b>🐺 The Hound of the High Court</b>' : 'Royal Executioners') + ' hunt you!</span>' +
        '<button class="btn btn-gold" style="min-height:28px;padding:3px 8px;font-size:11px;" onclick="if(window.bribeWatchCaptainClearWanted)window.bribeWatchCaptainClearWanted()">💰 Purchase Royal Pardon (' + pardonCost.toLocaleString() + 'g • Have ' + hero.gold.toLocaleString() + 'g)</button>' +
      '</div>';
    }
    var petHtml = "";
    if (nextRank) {
      var odds = getHighCourtPetitionOdds(nextRank);
      var lvScaledCharmReq = Math.max(nextRank.charmReq, Math.round(14 + (hero.level || 1) * 2.15 + Math.pow(hero.level || 1, 1.32) * 0.95));
      var lvOk = hero.level >= nextRank.minLv, gOk = hero.gold >= nextRank.cost, fOk = (hero.fame || 0) >= nextRank.fameReq, mOk = totMats >= nextRank.matsReq;
      var allOk = lvOk && gOk && fOk && mOk && hero.quests >= 3 && (hero.wantedLevel || 0) === 0 && petLeft > 0;
      petHtml = '<div style="background:#0b0811;border:2px solid #c5a059;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13px;line-height:1.6;">' +
        '<div style="font-size:15px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">📜 Royal Petition for Title: ' + nextRank.title + ' (' + nextRank.domainName + ')</div>' +
        '<div style="font-size:12px;color:#7dd3fc;margin-bottom:6px;">Unlocks: ' + escapeHtml(nextRank.unlocks) + ' (+' + nextRank.bonusPct + '% All Stats) • Petitions Left Today: <b>' + petLeft + '/' + MAX_DAILY_COURT_PETITIONS + '</b></div>' +
        '<div>• Hero Level: <b style="color:' + (lvOk ? '#4ade80' : '#f87171') + ';">Lv ' + hero.level + ' / ' + nextRank.minLv + '</b></div>' +
        '<div>• Royal Investiture Gold: <b style="color:' + (gOk ? '#4ade80' : '#f87171') + ';">' + hero.gold.toLocaleString() + ' / ' + nextRank.cost.toLocaleString() + 'g</b> (30% kept if denied!)</div>' +
        '<div>• Courtly Fame (Level Cap ' + maxF + ' • Decays -8/45m): <b style="color:' + (fOk ? '#4ade80' : '#f87171') + ';">' + (hero.fame || 0) + ' / ' + nextRank.fameReq + ' Fame</b></div>' +
        '<div>• Monster Trophies: <b style="color:' + (mOk ? '#4ade80' : '#f87171') + ';">' + totMats + ' / ' + nextRank.matsReq + ' Trophies</b></div>' +
        '<div>• Chancellor Approval Odds (👑Charm ' + st.effCharm + ' vs Benchmark ' + lvScaledCharmReq + (st.isDrunk ? ' • 🍺-15% Drunk Penalty' : '') + '): <b style="color:#fde68a;">' + odds + '% Chance</b></div>' +
        '<button class="btn ' + (allOk ? 'btn-shine' : 'btn-locked') + '" style="width:100%;margin-top:10px;" onclick="submitHighCourtPetition()">👑 Submit Formal Petition (-3⚡ • Have ' + hero.quests + '⚡)</button>' +
      '</div>';
    } else {
      petHtml = '<div style="padding:12px;color:#4ade80;font-weight:bold;">🌟 You are crowned GOD-MONARCH OF GENESIS — supreme ruler of all 22 Realms!</div>';
    }
    showPopupModal(
      '<div style="font-size:40px;">👑⚖️</div>' +
      '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;">The Obsidian High Court of Valoria</div>' +
      '<div class="lore-subtitle-box">Advance your feudal rank to unlock higher-tier strongholds, noble consorts, and permanent stat blessings. Beware: Court Fame decays every 45 minutes, and falling below your rank&apos;s threshold tarnishes your house (-10% Stats).</div>' +
      '<div style="font-size:12.5px;color:#e5dec9;">Current Rank: <b>' + curRankObj.title + '</b> (Req Fame: ' + curRankObj.fameReq + ') • Your Fame: <b style="color:' + (st.tarnishedFame ? '#f87171' : '#4ade80') + ';">' + (hero.fame || 0) + '/' + maxF + '</b> • 💰 <b>' + hero.gold.toLocaleString() + 'g</b> • ⚡ <b>' + hero.quests + '⚡</b></div>' +
      wantedAlert +
      (st.tarnishedFame ? '<div style="background:#2b070c;border:1px solid #991b1b;padding:6px;border-radius:4px;font-size:12px;color:#fecaca;margin-top:6px;">⚠️ <b>Tarnished Reputation:</b> Your Fame decayed below ' + curRankObj.fameReq + ' (-10% Stats &amp; -15% Tax)! Win Jousts, Quests, or host a Banquet!</div>' : '') +
      petHtml +
      '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;">' +
        '<button class="btn ' + (intLeft > 0 ? 'btn-arcane' : 'btn-locked') + '" style="flex:1;" onclick="executeCourtIntrigue(&#39;spy&#39;)">🕵️ Espionage (' + intLeft + '/' + MAX_DAILY_INTRIGUE + ' • -2⚡)</button>' +
        '<button class="btn ' + (intLeft > 0 ? 'btn-crimson' : 'btn-locked') + '" style="flex:1;" onclick="executeCourtIntrigue(&#39;guard&#39;)">🗡️ Foil Assassin (' + intLeft + '/' + MAX_DAILY_INTRIGUE + ' • -2⚡)</button>' +
        '<button class="btn btn-gold" style="flex:1;" onclick="if(window.playTraitorsMasqueradeMystery)window.playTraitorsMasqueradeMystery()">🎭 Masquerade Inquiry (-3⚡)</button>' +
      '</div>' +
      '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Leave the High Court</button>'
    );
  }
  else if (fac === "courting") {
    var spLove = (hero.spouse && hero.spouse.love !== undefined) ? hero.spouse.love : 100;
    var courtLeft = Math.max(0, MAX_DAILY_COURTING - (hero.courtingUsedToday || 0));
    var dipActive = (hero.spouse && hero.spouse.diplomacyUntil && hero.spouse.diplomacyUntil > nowMs);
    var dipRemTxt = dipActive ? formatCooldownSec(Math.ceil((hero.spouse.diplomacyUntil - nowMs) / 1000)) : "";
    var loveStatus = spLove >= 90 ? "💖 Devoted (100% Blessing &amp; 🌟Dual-Tech Active!)" : (spLove >= 80 ? "💖 Devoted (100% Blessing)" : (spLove >= 40 ? "😐 Neglected (50% Blessing)" : "💔 Estranged (0% Blessing — Divorce Risk!)"));
    var attireOpts = ["Velvet Court Gown", "Starlight Silk Regalia", "Valkyrie War-Barding", "Empress Eclipse Robe"].map(function(at) {
      return '<option value="' + at + '" ' + (hero.consortAttire === at ? 'selected' : '') + '>' + at + (at !== "Velvet Court Gown" ? " (+25% Spouse Stats!)" : "") + '</option>';
    }).join('');

    var multiConsortSelectorHtml = "";
    if (Array.isArray(hero.marriedConsorts) && hero.marriedConsorts.length > 1) {
      multiConsortSelectorHtml = '<div style="background:#1a0920;border:2px solid #f472b6;border-radius:6px;padding:8px 10px;margin-bottom:8px;text-align:left;">' +
        '<div style="font-size:12px;font-weight:900;color:#fde047;font-family:Cinzel,serif;margin-bottom:4px;">👑 Choose Your Active Consort Blessing (' + hero.marriedConsorts.length + ' Royal Consorts Wed — Blessings Do Not Stack!):</div>' +
        '<div style="display:flex;gap:5px;flex-wrap:wrap;">' +
          hero.marriedConsorts.map(function(mc) {
            var isChosen = (hero.spouse && hero.spouse.id === mc.id);
            return '<button class="btn ' + (isChosen ? 'btn-shine' : 'btn-arcane') + '" style="flex:1;min-height:28px;font-size:10.5px;" onclick="selectActiveConsortBlessing(&#39;' + mc.id + '&#39;)">' + (isChosen ? '✅ Active: ' : '💍 Select ') + mc.icon + ' ' + escapeHtml(mc.name.split(" of ")[0]) + ' (' + escapeHtml(mc.blessing.split(",")[0]) + ')</button>';
          }).join('') +
        '</div>' +
      '</div>';
    }

    var dateCost = Math.max(300, hero.level * 45);
    var banquetCost = Math.max(600, hero.level * 85);
    var heirCost = Math.max(800, hero.level * 120);
    var mKeySpouse = hero.spouse ? (hero.spouse.id || hero.spouse.name) : "";
    var spBornCnt = (mKeySpouse && hero.consortChildrenCount && hero.consortChildrenCount[mKeySpouse]) ? hero.consortChildrenCount[mKeySpouse] : 0;

    var spouseBanner = hero.spouse ?
      (multiConsortSelectorHtml + '<div class="velvet-consort-card" style="text-align:left;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">' +
          '<div style="display:flex;align-items:center;gap:12px;">' + renderLadyPortraitSvg(hero.spouse.id || hero.spouse.name, 62) +
          '<div><div style="font-size:16px;font-weight:900;color:#f472b6;font-family:&#39;Cinzel&#39;,serif;">💍 Chosen Active Consort: ' + hero.spouse.icon + ' ' + escapeHtml(hero.spouse.name) + '</div>' +
          '<div style="font-size:11.5px;color:#86efac;">Active Blessing: <b>' + escapeHtml(hero.spouse.blessing) + '</b></div>' +
          '<div style="font-size:12px;color:#fde68a;">Status: <b>' + loveStatus + '</b> • Courting Left Today: <b>' + courtLeft + '/' + MAX_DAILY_COURTING + '</b></div></div></div>' +
        '</div>' +
        '<div class="bar-wrap" style="height:14px;margin:6px 0;"><div class="bar-fill" style="width:' + spLove + '%;background:linear-gradient(90deg,#831843,#db2777);"></div><div class="bar-text" style="line-height:13px;">❤️ Marital Devotion: ' + spLove + '% / 100% (Decays -3%/tick • 90%+ &amp; Active Heir unlocks Dual-Tech!)</div></div>' +
        '<div style="display:flex;gap:6px;align-items:center;margin:6px 0;font-size:11.5px;">' +
          '<span style="color:#f472b6;font-weight:bold;">👗 Royal Seamstress Genevieve&apos;s Wardrobe:</span>' +
          '<select id="consortWardrobeSelect" style="flex:1;padding:4px;" onchange="if(window.changeConsortWardrobe)window.changeConsortWardrobe(this.value)">' + attireOpts + '</select>' +
        '</div>' +
        '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:6px;margin-top:6px;">' +
          '<button class="btn ' + (courtLeft > 0 ? 'btn-sky' : 'btn-locked') + '" style="min-height:32px;font-size:11px;" onclick="takeWifeOnRoyalDate()">🌹 Date (-4⚡, ' + dateCost.toLocaleString() + 'g)</button>' +
          '<button class="btn ' + (courtLeft > 0 ? 'btn-arcane' : 'btn-locked') + '" style="min-height:32px;font-size:11px;" onclick="embarkConsortRomanceQuest()">🗺️ Romance (-4⚡ • +1 All Stats)</button>' +
          '<button class="btn ' + (dipActive ? 'btn-emerald' : (courtLeft > 0 ? 'btn-sky' : 'btn-locked')) + '" style="min-height:32px;font-size:11px;" title="Dispatch Consort on Diplomatic Mission: Cuts passive Court Fame decay by 50% for 2 Hours!" onclick="dispatchConsortDiplomacy()">' + (dipActive ? ('🕊️ Envoy (' + dipRemTxt + ')') : ('🕊️ Diplomacy (-3⚡ ➔ -50% Decay)')) + '</button>' +
          '<button class="btn ' + (courtLeft > 0 ? 'btn-gold' : 'btn-locked') + '" style="min-height:32px;font-size:11px;" onclick="hostGrandRoyalBanquet()">🍷 Banquet (-6⚡, ' + banquetCost.toLocaleString() + 'g)</button>' +
          '<button class="btn ' + (spBornCnt >= 3 ? 'btn-locked' : 'btn-shine') + '" style="min-height:32px;font-size:11px;" onclick="conceiveDynastyChild()">👶 Welcome Heir (' + spBornCnt + '/3 Born • -4⚡, ' + heirCost.toLocaleString() + 'g)</button>' +
        '</div></div>') :
      '<div class="lore-subtitle-box">Welcome to <b>The Velvet Chamber</b> (' + courtLeft + '/' + MAX_DAILY_COURTING + ' Courting Actions Left Today • 💰' + hero.gold.toLocaleString() + 'g • ⚡' + hero.quests + '⚡). Serenade or gift noble ladies to raise Affection to <b>100%</b> and celebrate a Royal Wedding. Beware: <b>Courtship Affection decays by -4% every 45m tick and -12% at midnight</b>, and if you wed multiple ladies, you must choose <b>1 active Consort Blessing</b> at a time!</div>';

    var childrenHtml = "";
    if (hero.children && hero.children.length) {
      var acadCost = Math.max(500, hero.level * 75);
      childrenHtml = '<div style="text-align:left;margin-bottom:12px;"><div style="font-size:13.5px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:6px;">👶 Your Mortal Dynasty Heirs (' + hero.children.length + '/6 • Active Helpers: ' + getActiveHelperCount(hero) + '/2 — ⚠️ Active Battle Heirs Can Die Permanently!):</div>' +
        hero.children.map(function(ch, cIdx) {
          var isAct = (hero.activeChildIdx === cIdx);
          var onExp = (ch.expeditionUntil && ch.expeditionUntil > nowMs);
          var expRem = onExp ? formatCooldownSec(Math.ceil((ch.expeditionUntil - nowMs) / 1000)) : "";
          var appRole = ch.apprentice || "none";
          return '<div class="item-row" style="border-color:' + (ch.isStrong ? '#15803d' : '#991b1b') + ';">' +
            renderEntityAvatar(ch.name, ch.icon, 44, false) +
            '<div style="flex:1;">' +
              '<div><b style="font-family:&#39;Cinzel&#39;,serif;">' + ch.icon + ' ' + escapeHtml(ch.name) + ' (Lv ' + (ch.level || 1) + ')</b> — <span style="color:' + (ch.isStrong ? '#4ade80' : '#fca5a5') + ';font-weight:bold;">[' + escapeHtml(ch.traitName) + ']</span></div>' +
              '<div style="font-size:11.5px;color:#e5dec9;">🗡️ ATK: <b>' + ch.atk + '</b> • ❤️ HP: <b>' + (ch.hp || ch.maxHp) + '/' + ch.maxHp + '</b> • 💥 Lifetime DMG: <b style="color:#7dd3fc;">' + (ch.totalDmg || 0).toLocaleString() + '</b> • Apprentice: <b style="color:#fde047;">' + (appRole === "brom" ? "🔨 Brom" : (appRole === "mira" ? "🧪 Mira" : "None")) + '</b></div>' +
            '</div>' +
            '<div style="display:flex;gap:4px;flex-wrap:wrap;">' +
              '<button class="btn ' + (appRole === "brom" ? "btn-gold" : "") + '" style="min-height:26px;padding:2px 6px;font-size:10px;" title="Apprentice to Blacksmith Brom (+5% All-Gear Durability / 45m tick)" onclick="setChildApprenticeship(' + cIdx + ',&#39;brom&#39;)">🔨Brom</button>' +
              '<button class="btn ' + (appRole === "mira" ? "btn-emerald" : "") + '" style="min-height:26px;padding:2px 6px;font-size:10px;" title="Apprentice to Apothecary Mira (+1 Healing Potion / 45m tick)" onclick="setChildApprenticeship(' + cIdx + ',&#39;mira&#39;)">🧪Mira</button>' +
              (!ch.isStrong ? '<button class="btn btn-shine" style="min-height:26px;padding:2px 6px;font-size:10px;" onclick="trainChildAtWarAcademy(' + cIdx + ')">🎓Academy (' + acadCost + 'g, 2💎)</button>' : '') +
              (!ch.trialDone ? '<button class="btn ' + ((ch.level || 1) >= 10 ? 'btn-shine' : 'btn-locked') + '" style="min-height:26px;padding:2px 6px;font-size:10px;" title="Heir Level 10+ Coming-of-Age Proving-Ground Trial (+30% ATK/HP &amp; Heroic Vanguard!)" onclick="undertakeHeirComingOfAgeTrial(' + cIdx + ')">🦁Trial(Lv10)</button>' : '') +
              '<button class="btn ' + (isAct ? 'btn-emerald' : 'btn-sky') + '" style="min-height:26px;padding:2px 6px;font-size:10px;" onclick="setActiveBattleChild(' + cIdx + ')">' + (isAct ? '⚔️Active (Dismiss)' : '⚔️Deploy (1 Helper)') + '</button>' +
              '<button class="btn ' + (onExp ? 'btn-locked' : 'btn-gold') + '" style="min-height:26px;padding:2px 6px;font-size:10px;" onclick="sendChildExpedition(' + cIdx + ')">' + (onExp ? '🗺️' + expRem : '🗺️Quest') + '</button>' +
              '<button class="btn ' + (hero.level >= 50 ? 'btn-arcane' : 'btn-locked') + '" style="min-height:26px;padding:2px 6px;font-size:10px;" onclick="prestigeHeroHeirSuccession(' + cIdx + ')">👑Crown</button>' +
              '<button class="btn btn-crimson" style="min-height:26px;padding:2px 6px;font-size:10px;" title="Move to Fallen Family Tree Memorial" onclick="if(window.removeChildFromNursery)removeChildFromNursery(' + cIdx + ')">🪦Remove</button>' +
            '</div></div>';
        }).join('') + '</div>';
    }

    var candHtml = COURTING_POOL.map(function(c) {
      var aff = hero.courtingProgress[c.id] || 0;
      var reqTitle = NOBLE_RANKS[c.minNobleIdx].title;
      var sacrificedDead = isConsortSacrificedForever(c.id) || isConsortSacrificedForever(c.name);
      var titleOk = !sacrificedDead && (hero.nobleIdx || 0) >= c.minNobleIdx && courtLeft > 0;
      var isWed = Array.isArray(hero.marriedConsorts) && hero.marriedConsorts.some(function(mc) { return mc.id === c.id; });
      var isChosenSpouse = hero.spouse && hero.spouse.id === c.id;
      return '<div class="velvet-consort-card" style="text-align:left;' + (sacrificedDead ? 'opacity:0.55;border-color:#991b1b;' : '') + '">' +
        '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">' +
          renderLadyPortraitSvg(c.id, 58) +
          '<div style="flex:1;min-width:190px;">' +
            '<div><b style="font-family:&#39;Cinzel&#39;,serif;color:' + (sacrificedDead ? '#ef4444' : '#f472b6') + ';font-size:14.5px;">' + c.icon + ' ' + escapeHtml(c.name) + '</b> ' + (sacrificedDead ? '<span style="background:#450a0a;color:#fca5a5;padding:1px 6px;border-radius:3px;font-size:10px;font-weight:bold;">⚰️ SACRIFICED FOREVER ON THIS CHARACTER</span>' : ('<span style="font-size:11px;color:' + ((hero.nobleIdx || 0) >= c.minNobleIdx ? '#4ade80' : '#f87171') + ';">[Req: ' + reqTitle + ']</span>')) + '</div>' +
            '<div style="font-size:11px;color:#c084fc;">✨ Motif: ' + escapeHtml(c.velvetTheme || 'Royal Velvet') + ' • Blessing: <b style="color:#fde68a;">' + escapeHtml(c.blessing) + '</b></div>' +
            '<div style="font-size:11.5px;color:#fbcfe8;font-style:italic;margin:3px 0;">' + (sacrificedDead ? '🩸 <b>Blood-Price Paid:</b> Her soul perished upon the Obsidian Altar—she can only be courted or remarried in another character slot!' : ('&ldquo;' + escapeHtml(c.vowQuote || c.desc) + '&rdquo;')) + '</div>' +
            (!sacrificedDead ? ('<div class="bar-wrap" style="height:12px;margin:4px 0;"><div class="bar-fill" style="width:' + aff + '%;background:linear-gradient(90deg,#9d174d,#f472b6);"></div><div class="bar-text" style="font-size:9.5px;line-height:11px;">❤️ Courtship Affection: ' + aff + '% / 100% (Decays -4%/tick &amp; -12% at midnight!)</div></div>') : '') +
          '</div>' +
        '</div>' +
        '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;">' +
          '<button class="btn ' + (titleOk ? 'btn-sky' : 'btn-locked') + '" style="flex:1;min-height:30px;padding:4px 8px;font-size:11px;" onclick="courtNobleCandidate(&#39;' + c.id + '&#39;,&#39;serenade&#39;)">' + (sacrificedDead ? '⚰️ Slain Forever' : ('🎵 Serenade (-4⚡ • Have ' + hero.quests + '⚡)')) + '</button>' +
          '<button class="btn ' + (titleOk ? 'btn-gold' : 'btn-locked') + '" style="flex:1;min-height:30px;padding:4px 8px;font-size:11px;" onclick="courtNobleCandidate(&#39;' + c.id + '&#39;,&#39;gift&#39;)">' + (sacrificedDead ? '⚰️ Slain Forever' : ('🎁 Gift (-4⚡, ' + c.giftGold + 'g • Have ' + hero.gold.toLocaleString() + 'g)')) + '</button>' +
          (isWed
            ? ('<button class="btn ' + (isChosenSpouse ? 'btn-emerald' : 'btn-arcane') + '" style="flex:1;min-height:30px;padding:4px 8px;font-size:11px;" onclick="selectActiveConsortBlessing(&#39;' + c.id + '&#39;)">' + (isChosenSpouse ? '💍 Active Blessing' : '💍 Activate Blessing') + '</button>')
            : ('<button class="btn ' + (sacrificedDead ? 'btn-locked' : (aff >= 100 ? 'btn-shine' : 'btn-locked')) + '" style="flex:1;min-height:30px;padding:4px 8px;font-size:11px;" onclick="marryNobleCandidate(&#39;' + c.id + '&#39;)">' + (sacrificedDead ? '⚰️ Remarry on Another Slot' : ('💍 Wed (' + (c.giftGold * 2) + 'g)')) + '</button>')) +
        '</div></div>';
    }).join('');

    showPopupModal(
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-wrap:wrap;gap:6px;"><span style="font-size:18px;font-weight:900;color:#f472b6;font-family:&#39;Cinzel&#39;,serif;">🌹 The Velvet Chamber — Noble Consorts &amp; Dynasty Scions</span><button class="btn btn-arcane" style="min-height:28px;padding:3px 8px;font-size:11px;" onclick="if(window.openDynastyTapestryModal)window.openDynastyTapestryModal()">🌳 Dynasty Tapestry</button></div>' +
      spouseBanner + childrenHtml +
      '<div style="text-align:left;font-size:13px;font-weight:bold;color:#f472b6;font-family:&#39;Cinzel&#39;,serif;margin-bottom:6px;">🌹 Noble Ladies of the Velvet Chamber (💰' + hero.gold.toLocaleString() + 'g • ⚡' + hero.quests + '⚡):</div>' +
      candHtml +
      '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Leave the Velvet Chamber</button>'
    );
  }
  else {
    openSecondaryTownFacilitiesModal(fac, nowMs, st);
  }
}
'''
}

String buildUiChunkB3d() {
    return '''
function openSecondaryTownFacilitiesModal(fac, nowMs, st) {
  var rw = getRealWeather();
  var reqWitsSteal = 18 + (hero.level || 1) * 2.2 + Math.pow(hero.level || 1, 1.35) * 0.9;
  var witsMod = Math.max(-0.04, Math.min(0.08, ((st.effWits + st.effCharm * 0.4) - reqWitsSteal) * 0.002));
  var stealOddsPct = Math.round(Math.max(0.05, Math.min(0.26, ((rw.rain || rw.lightning) ? 0.18 : 0.12) + witsMod - (st.isDrunk ? 0.05 : 0))) * 100);

  if (fac === "sanctuary") {
    var healCost = getScaledHealCost(), potCost = getScaledPotionCost(), ethCost = getScaledEtherCost();
    var sealCost = Math.max(1500, hero.level * 180);
    var confCost = Math.max(120, hero.level * 28);
    var leechCost = Math.max(160, hero.level * 35);
    var totMats = getTotalMaterialsCount();
    var healsLeft = Math.max(0, MAX_DAILY_HEALS - (hero.healsUsedToday || 0));
    var potsLeft = Math.max(0, MAX_DAILY_POTIONS - (hero.potionsBoughtToday || 0));
    var ethsLeft = Math.max(0, MAX_DAILY_ETHERS - (hero.ethersBoughtToday || 0));
    var sealsLeft = Math.max(0, MAX_DAILY_VALKYRIE_SEALS - (hero.sealsBoughtToday || 0));
    var curSeals = Math.min(3, hero.valkyrieSeals !== undefined ? hero.valkyrieSeals : 3);
    var alembicLeft = Math.max(0, MAX_DAILY_ALEMBIC - (hero.alembicUsedToday || 0));
    var stealsLeft = Math.max(0, MAX_DAILY_STEALS - (hero.stealsUsedToday || 0));
    var beltLeft = Math.max(0, MAX_DAILY_BELT_BUYS - (hero.beltBuysToday || 0));
    var caulLeft = Math.max(0, 2 - (hero.cauldronUsedToday || 0));
    var confLeft = Math.max(0, 2 - (hero.confessionsToday || 0));
    var leechLeft = Math.max(0, 2 - (hero.leechesUsedToday || 0));
    var totalPartyDis = countTotalPartyDiseases(hero);
    var healCdRemSec = Math.max(0, Math.ceil((HEAL_COOLDOWN_MS - (nowMs - (hero.lastHealEpoch || 0))) / 1000));
    var healBtnLabel = healCdRemSec > 0 ? '⏳ Cooldown (' + formatCooldownSec(healCdRemSec) + ')' : '🕯️ +60% Rite, Cure Trauma &amp; -35% Stress (' + healCost.toLocaleString() + 'g • ' + healsLeft + '/3 Left)';
    var belt = hero.belt || { firebomb: 0, ironnet: 0, warhorn: 0 };
    var beltShopHtml = TACTICAL_BELT_ITEMS.map(function(b) {
      var bc = getScaledBeltCost(b), haveB = belt[b.id] || 0;
      return '<div class="item-row" style="text-align:left;"><div style="flex:1;"><b>' + b.icon + ' ' + escapeHtml(b.name) + ' (Carrying: ' + haveB + '/5)</b><div style="font-size:11.5px;color:#e5dec9;">' + escapeHtml(b.desc) + '</div></div>' +
        '<div style="display:flex;gap:4px;">' +
          '<button class="btn ' + (haveB >= 5 || beltLeft <= 0 ? 'btn-locked' : 'btn-gold') + '" style="min-height:30px;padding:4px 8px;font-size:11px;" onclick="buyBeltItem(&#39;' + b.id + '&#39;)">Buy (' + bc.toLocaleString() + 'g • ' + beltLeft + '/5)</button>' +
          (haveB < 5 ? '<button class="btn ' + (stealsLeft > 0 ? 'btn-crimson' : 'btn-locked') + '" style="min-height:30px;padding:4px 8px;font-size:10.5px;" title="' + stealOddsPct + '% Wits/Charm Steal Chance (' + stealsLeft + '/3 Left Today • -1⚡)" onclick="attemptShoplift(&#39;belt&#39;,&#39;' + b.id + '&#39;)">🥷 Steal (' + stealsLeft + '/3)</button>' : '') +
        '</div></div>';
    }).join('');

    var vesperaInlineHtml = '<div id="sisterVesperaCathedralCard" style="background:linear-gradient(135deg,#1f0b2e 0%,#0b0614 100%);border:2px solid #c084fc;border-radius:6px;padding:10px;margin:6px 0;text-align:left;font-size:11.5px;color:#e9d5ff;">' +
      '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">' +
        renderLadyPortraitSvg("vespera", 48) +
        '<div style="flex:1;min-width:180px;"><b style="color:#fde047;font-family:Cinzel,serif;font-size:13px;">💎🩺 Sister Vespera, Dragon-Glass Chirurgeon (Unlimited Daily Cures):</b><br>' +
        '<i>&ldquo;When the Plague-Doctor&apos;s daily leeches are spent, offer me <b>15💎 Dragon Gems</b> to cauterize any physical plague from you or your sworn recruits (+25% HP).&rdquo;</i></div>' +
        '<div style="display:flex;gap:5px;width:100%;margin-top:4px;">' +
          '<button class="btn ' + (totalPartyDis > 0 && (hero.gems || 0) >= 15 ? 'btn-shine' : 'btn-locked') + '" style="flex:1;" onclick="if(window.purgeDiseaseSisterVespera)window.purgeDiseaseSisterVespera()">💎🩺 Purge 1 Disease (' + totalPartyDis + ' Active • 15💎 • Have ' + (hero.gems || 0) + '💎)</button>' +
          '<button class="btn btn-arcane" onclick="if(window.openSisterVesperaModal)window.openSisterVesperaModal()">🏥 Clinic Details</button>' +
        '</div>' +
