      beltShopHtml +
      '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Leave the Cathedral</button>'
    );
  }
  else if (fac === "inn") {
    var innCost = getScaledInnRestCost(), restsLeft = Math.max(0, MAX_DAILY_RESTS - (hero.restsUsedToday || 0));
