    var jonahUnlocked = (hero.level >= 85);
    var totMatsBazaar = getTotalMaterialsCount();
    var fenceUnlocked = ((hero.alignment && hero.alignment.Shadow >= 15) || (hero.wantedLevel || 0) > 0 || (hero.inventory || []).some(function(x) { return x && x.stolen; }));
    var blAlert = "";
    if (hero.merchantBlacklistUntil && hero.merchantBlacklistUntil > nowMs) {
      var blRem = Math.ceil((hero.merchantBlacklistUntil - nowMs) / 1000);
      blAlert = '<div style="background:#2b0712;border:1px solid #f43f5e;border-radius:4px;padding:6px 10px;margin-bottom:8px;font-size:11.5px;color:#fecdd3;">' +
        (hasOutlawDisguise() ? ('🎭 <b>OUTLAW DISGUISE ACTIVE (' + hero.helmStyle + '):</b> You are sneaking past the merchant&apos;s ' + formatCooldownSec(blRem) + ' shoplifting blacklist incognito!') : ('🚫 <b>MERCHANT BLACKLISTED (' + formatCooldownSec(blRem) + ' left):</b> Equip the <b>Inquisitor Hood</b> or <b>Plague Doctor Beak</b> in 🎨 Studio to trade incognito!')) +
      '</div>';
    }
    var itemsHtml = (hero.shopInventory || []).map(function(itm, idx) {
      var price = Math.max(35, Math.round((itm.value || 50) * (1.30 - st.discountPct / 100.0))), isUpg = getUpgradeDelta(itm) > 0;
      return '<div class="item-row ' + (isUpg ? 'gear-upgrade-shine' : '') + '" style="text-align:left;"><div style="flex:1;">[' + String(itm.type || 'weapon').toUpperCase() + '] ' + formatItemStats(itm, true, false) + '</div>' +
        '<div style="display:flex;gap:4px;">' +
          '<button class="btn ' + (shopBuysLeft <= 0 ? 'btn-locked' : (isUpg ? 'btn-shine' : 'btn-gold')) + '" onclick="buyShopItem(' + idx + ')">💰 ' + price.toLocaleString() + 'g (' + shopBuysLeft + '/5)</button>' +
          '<button class="btn ' + (stealsLeft2 <= 0 ? 'btn-locked' : 'btn-crimson') + '" title="' + stealOddsPct + '% Steal Chance (' + stealsLeft2 + '/3 Left Today • -1⚡)" onclick="attemptShoplift(&#39;shop&#39;,' + idx + ')">🥷 Steal (' + stealsLeft2 + '/3)</button>' +
        '</div></div>';
    }).join('');
    showPopupModal(
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;"><span style="font-size:18px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;">⚖️ The Ironcrag Caravan Bazaar (' + st.discountPct + '% Charm Discount)</span><button class="btn ' + (shopRemSec > 0 ? 'btn-locked' : 'btn-gold') + '" style="min-height:30px;padding:4px 8px;font-size:11px;" onclick="restockDwarvenMarket()">' + shopBtnLabel + '</button></div>' +
      '<div class="lore-subtitle-box">💰 <b>Your Treasury: ' + hero.gold.toLocaleString() + 'g</b> • 📦 <b>Trophies: ' + totMatsBazaar + '</b> • 🪵 <b>' + (hero.guild.timber || 0) + '</b> • 🪨 <b>' + (hero.guild.stone || 0) + '</b> • ⛏️ <b>' + (hero.guild.iron || 0) + '</b> • 🎒 <b>Pack: ' + hero.inventory.length + '/30</b>.</div>' +
      blAlert +
      '<div style="background:#141a0d;border:1px solid #4ade80;border-radius:6px;padding:8px;margin-bottom:8px;text-align:left;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<div style="display:flex;align-items:center;gap:8px;">' + renderEntityAvatar("Master Huntsman Kraven", "🏹🔥", 42, false) +
          '<div><b style="color:#86efac;">🏹🔥 Master Huntsman Kraven&apos;s Trophy Exchange (You Hold ' + totMatsBazaar + ' Trophies):</b><div style="font-size:11px;color:#e5dec9;">Trade <b>10, 15, or 30 Monster Trophies</b> for Stress Relief, Rare–Mythic Chests, Kingdom Materials &amp; Dragon Gems!</div></div>' +
        '</div>' +
        '<button class="btn ' + (totMatsBazaar >= 10 ? 'btn-shine' : 'btn-gold') + '" style="min-height:30px;padding:4px 10px;font-size:11px;" onclick="openHuntsmanTrophyExchangeModal()">🏹 Exchange Trophies (' + totMatsBazaar + ')</button>' +
      '</div>' +
      '<div style="background:#140d1c;border:1px solid #c5a059;border-radius:6px;padding:8px;margin-bottom:8px;text-align:left;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<div style="display:flex;align-items:center;gap:8px;">' + renderEntityAvatar("Blacksmith Brom Iron-Thumb", "🔨⚒️", 42, false) +
          '<div><b style="color:#fde047;">🔨 Master Blacksmith Brom Iron-Thumb:</b><div style="font-size:11px;color:#e5dec9;">&ldquo;Bring your notched steel to my anvil for repairs, hammer rune-steel on the beat, or crush Dulled Gem Slag!&rdquo;</div></div>' +
        '</div>' +
        '<div style="display:flex;gap:4px;"><button class="btn btn-gold" style="min-height:30px;padding:4px 8px;font-size:10.5px;" onclick="if(window.openBromRhythmAnvilModal)window.openBromRhythmAnvilModal()">🔨 Dwarven Anvil (-2⚡)</button><button class="btn btn-emerald" style="min-height:30px;padding:4px 8px;font-size:10.5px;" onclick="if(window.repairAllEquippedGear)window.repairAllEquippedGear()">🔧 Repair All</button></div>' +
      '</div>' +
      '<div style="background:#170a1c;border:1px solid ' + (fenceUnlocked ? '#f43f5e' : '#473e4f') + ';border-radius:6px;padding:8px;margin-bottom:8px;text-align:left;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<div><b style="color:#fda4af;">🥷 The Underground Sewer Fence:</b><div style="font-size:11px;color:#e5dec9;">Launder stolen contraband for <b>85% gold value</b>, smuggle aboard your Armada, or burn Wanted warrants!</div></div>' +
        '<button class="btn ' + (fenceUnlocked ? 'btn-crimson' : 'btn-locked') + '" style="min-height:30px;padding:4px 10px;font-size:11px;" onclick="if(window.openUndergroundFenceModal)window.openUndergroundFenceModal()">🥷 Enter Sewer Fence</button>' +
      '</div>' +
      '<div style="background:#0c1926;border:1px solid ' + (jonahUnlocked ? '#38bdf8' : '#473e4f') + ';border-radius:6px;padding:8px;margin-bottom:10px;text-align:left;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">' +
        '<div style="display:flex;align-items:center;gap:8px;">' + renderEntityAvatar("Jonah Star-Swallowed", "🐳🌟", 42, false) +
          '<div><b style="color:' + (jonahUnlocked ? '#7dd3fc' : '#9c8f7a') + ';">🐳 Jonah the Star-Swallowed (Req Lv 85+):</b><div style="font-size:11px;color:#e5dec9;">Barter <b>120🪵 Timber, 120🪨 Stone &amp; 80⛏️ Iron</b> (Have ' + (hero.guild.timber || 0) + '🪵, ' + (hero.guild.stone || 0) + '🪨, ' + (hero.guild.iron || 0) + '⛏️) for a <b>God-Tier Relic</b>!</div></div>' +
        '</div>' +
        '<button class="btn ' + (jonahUnlocked ? 'btn-arcane' : 'btn-locked') + '" style="min-height:30px;padding:4px 10px;font-size:11px;" onclick="if(window.tradeLeviathanRelic)window.tradeLeviathanRelic()">' + (jonahUnlocked ? '🐳 Barter God-Tier Relic' : ('🔒 Req Lv 85 (Now Lv ' + hero.level + ')')) + '</button>' +
      '</div>' +
      (itemsHtml || '<div style="padding:12px;color:#9c8f7a;">Sold out — wait for next caravan!</div>') +
      '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Leave the Bazaar</button>'
    );
  }
  else if (fac === "post") {
    var v = hero.vault || { gold: 0, gems: 0, gemsLockedEpoch: 0, dulledGems: 0, items: [] };
    var vGems = v.gems || 0;
    var vDulled = v.dulledGems || 0;
    var spinsLeft = Math.max(0, 2 - (hero.rouletteSpinsToday || 0));
    var gemExpHrs = (vGems > 0 && v.gemsLockedEpoch) ? Math.max(0, Math.ceil((SEVEN_DAYS_MS - (Date.now() - v.gemsLockedEpoch)) / 3600000)) : 168;
    var vHtml = (v.items && v.items.length) ? v.items.map(function(itm, idx) {
      return '<div class="item-row" style="text-align:left;"><div style="flex:1;">🏦 ' + formatItemStats(itm, true, false) + '</div><button class="btn btn-emerald" onclick="withdrawVaultItem(' + idx + ')">Withdraw to Pack</button></div>';
    }).join('') : '<div style="color:#9c8f7a;font-size:12.5px;padding:8px;">No heirloom items stored in your Personal Vault yet. Click 🏦 on any unequipped item in your Reliquary Pack to store it here safely!</div>';
    showPopupModal(
      '<div style="font-size:38px;">🏦💎🎰</div>' +
      '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">The Royal Reliquary Vault of ' + escapeHtml(hero.name) + '</div>' +
      '<div class="lore-subtitle-box">Gold and Heirlooms sealed inside your Personal Vault are protected from death and pickpockets. Up to <b>20💎 Dragon Gems</b> may be locked here to shield them from the 15% midnight decay—though after 7 days they cool into Dulled Slag unless refreshed at the Catacomb Wheel.</div>' +
      '<div style="background:#0b0811;border:2px solid #c5a059;border-radius:4px;padding:10px;margin-bottom:8px;text-align:left;">' +
        '<div style="display:flex;justify-content:space-between;font-size:13px;font-weight:bold;color:#d4af37;margin-bottom:6px;">' +
          '<span>🏦 Vault Gold: ' + (v.gold || 0).toLocaleString() + 'g</span>' +
          '<span style="color:#fde68a;">Carried Gold: ' + hero.gold.toLocaleString() + 'g</span>' +
        '</div>' +
        '<div style="display:flex;gap:6px;">' +
          '<input type="number" id="vaultGoldInput" placeholder="Gold amount (10% guard fee)...">' +
          '<button class="btn btn-gold" onclick="depositVaultGold()">📥 Deposit</button>' +
          '<button class="btn btn-emerald" onclick="withdrawVaultGold()">📤 Withdraw</button>' +
        '</div>' +
