        '<div style="display:flex;justify-content:space-between;font-size:12.5px;font-weight:bold;color:#fde047;margin-bottom:4px;flex-wrap:wrap;">' +
          '<span>💎 Sealed Vault Gems: ' + vGems + ' / 20💎 (' + (vGems > 0 ? ('Cools in ' + gemExpHrs + 'h') : '7-Day Seal') + ')</span>' +
          '<span style="color:#9c8f7a;">🪨 Dulled Slag: ' + vDulled + ' | Carried: ' + (hero.gems || 0) + '💎</span>' +
        '</div>' +
        '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;">' +
          '<input type="number" id="vaultGemInput" placeholder="Gem qty (Max 20)..." style="flex:1;min-width:120px;">' +
          '<button class="btn btn-arcane" onclick="depositVaultGems()">🔒 Seal Gems</button>' +
          '<button class="btn btn-emerald" onclick="withdrawVaultGems()">📤 Withdraw</button>' +
          '<button class="btn ' + (spinsLeft > 0 && vGems > 0 ? 'btn-shine' : 'btn-locked') + '" onclick="playCatacombGemRoulette()">🎰 Catacomb Wheel (-2⚡ • ' + spinsLeft + '/2 Left)</button>' +
        '</div>' +
      '</div>' +
      '<div style="text-align:left;font-size:12.5px;font-weight:bold;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">🗡️ Stored Vault Heirlooms (' + (v.items ? v.items.length : 0) + '/25):</div>' +
      vHtml +
      '<button class="btn" style="width:100%;margin-top:10px;" onclick="closePopupModal()">Close Reliquary Vault</button>'
    );
  }
  else if (fac === "wagers") {
    var mgLeft = Math.max(0, MAX_DAILY_MINIGAMES - (hero.minigamesPlayedToday || 0));
    var codexHtml = '<div style="margin-top:12px;text-align:left;"><div style="font-size:13px;font-weight:bold;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:6px;">📚 The Royal Archives of Valoria</div>' +
      LORE_CODEX.map(function(entry, idx) {
        var unlocked = hero.level >= entry.unlockLv;
        return '<button class="btn ' + (unlocked ? 'btn-sky' : 'btn-locked') + '" style="margin:2px;font-size:10.5px;min-height:28px;padding:3px 7px;" onclick="openLoreCodexModal(' + idx + ')">' + entry.icon + ' Vol.' + (idx + 1) + ' (Lv ' + entry.unlockLv + ')</button>';
      }).join('') + '</div>';
    showPopupModal(
      '<div style="font-size:36px;">🏇🗣️🃏💣</div>' +
      '<div style="font-size:19px;font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;margin-bottom:4px;">The Grand Tourney Grounds &amp; Seer&apos;s Vardo</div>' +
      '<div class="lore-subtitle-box">Compete in the royal lists, debate chancellors, or consult the Tarot Seer to win Gold, Court Fame, and Stress relief. (📅 Contests Remaining Today: <b>' + mgLeft + ' / ' + MAX_DAILY_MINIGAMES + '</b> • ⚡ Your Quests: <b>' + hero.quests + '⚡</b> • 💰 Your Gold: <b>' + hero.gold.toLocaleString() + 'g</b>)</div>' +
      '<div class="slot-grid">' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("wagers") + ';" onclick="openMiniGameModal(&#39;joust&#39;)"><div style="font-size:30px;">🏇</div><div style="text-align:left;"><div style="font-weight:900;color:#d4af37;font-family:&#39;Cinzel&#39;,serif;">The Grand Tourney Lists (-5⚡)</div><div style="font-size:11px;color:#e5dec9;">Tilt against armored knights for Gold, Court Fame &amp; Consort Devotion</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("vault") + ';" onclick="if(window.playRunicLockpickModal)window.playRunicLockpickModal()"><div style="font-size:30px;">🗝️⚙️</div><div style="text-align:left;"><div style="font-weight:900;color:#7dd3fc;font-family:&#39;Cinzel&#39;,serif;">The Thief&apos;s Tumbler Chest (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Set the three runic tumblers to unseal confiscated coffers</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("market") + ';" onclick="if(window.openBromRhythmAnvilModal)window.openBromRhythmAnvilModal()"><div style="font-size:30px;">🎵🔨</div><div style="text-align:left;"><div style="font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;">Brom&apos;s Dwarven Anvil (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Strike glowing rune-steel on the beat to restore durability &amp; temper blades</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("court") + ';" onclick="playHighCourtRhetoricDuel()"><div style="font-size:30px;">🗣️</div><div style="text-align:left;"><div style="font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;">The High Court Debate (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Outwit the Chancellors in rhetoric for +32 Court Fame &amp; -10% Stress</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("courting") + ';" onclick="drawTarotArcana()"><div style="font-size:30px;">🃏</div><div style="text-align:left;"><div style="font-weight:900;color:#f472b6;font-family:&#39;Cinzel&#39;,serif;">The Tarot Seer&apos;s Vardo (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Draw from the veiled Arcana deck for an 8-Quest fate blessing</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("inn") + ';" onclick="brawlTavernSellsword()"><div style="font-size:30px;">🍺</div><div style="text-align:left;"><div style="font-weight:900;color:#fde68a;font-family:&#39;Cinzel&#39;,serif;">The Tavern Pit-Brawl (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Test your Guts against Half-Orc sellswords for Gold, Fame &amp; -12% Stress</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("sanctuary") + ';" onclick="openMiniGameModal(&#39;fishing&#39;)"><div style="font-size:30px;">🎣</div><div style="text-align:left;"><div style="font-weight:900;color:#7dd3fc;font-family:&#39;Cinzel&#39;,serif;">The King&apos;s Dark Weir (-3⚡)</div><div style="text-align:left;font-size:11px;color:#e5dec9;">Angle for silver weir-trout (+8% HP, -10% Stress &amp; +8🍞 Rations)</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("vault") + ';" onclick="openMiniGameModal(&#39;slots&#39;)"><div style="font-size:30px;">🎡</div><div style="text-align:left;"><div style="font-weight:900;color:#c084fc;font-family:&#39;Cinzel&#39;,serif;">The Wheel of Fate (-3⚡)</div><div style="font-size:11px;color:#e5dec9;">Align the three ancient runes for an 8x Gold &amp; Dragon Gem jackpot</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("market") + ';" onclick="openMiniGameModal(&#39;dice&#39;)"><div style="font-size:30px;">🥤🎲</div><div style="text-align:left;"><div style="font-weight:900;color:#86efac;font-family:&#39;Cinzel&#39;,serif;">Gregor&apos;s Bones of Twenty-One (-3⚡)</div><div style="font-size:11px;color:#e5dec9;">Cast ivory bones against the tavern house for double stakes</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("wagers") + ';" onclick="if(window.openGoblinSapperModal)window.openGoblinSapperModal()"><div style="font-size:30px;">💣</div><div style="text-align:left;"><div style="font-weight:900;color:#f97316;font-family:&#39;Cinzel&#39;,serif;">Skarsnik&apos;s Sapper Kegs (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Defuse blackpowder casks with Wits for uncut gems and coin</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("court") + ';" onclick="if(window.playLiarsDiceModal)window.playLiarsDiceModal()"><div style="font-size:30px;">🎲👑</div><div style="text-align:left;"><div style="font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;">The Chancellor&apos;s Liar&apos;s Cup (-2⚡)</div><div style="font-size:11px;color:#e5dec9;">Bluff the high dukes across the velvet table for +30 Court Fame</div></div></div>' +
        '<div class="hub-launcher-card" style="background:' + getTownBannerStyle("legends") + ';" onclick="if(window.playWyvernSkyRaceModal)window.playWyvernSkyRaceModal()"><div style="font-size:30px;">🐲🏔️</div><div style="text-align:left;"><div style="font-weight:900;color:#4ade80;font-family:&#39;Cinzel&#39;,serif;">The Crag-Wyvern Sky-Lists (-3⚡)</div><div style="font-size:11px;color:#e5dec9;">Race tamed wyverns through the glacier gales of Ironcrag</div></div></div>' +
      '</div>' +
      codexHtml +
      '<button class="btn" style="width:100%;margin-top:12px;" onclick="closePopupModal()">Leave the Tourney Grounds</button>'
    );
  }
}

function renderInventoryAndSocketsTabHtml(gearSlots, bagUpgradesCnt) {
  try {
    ensureHeroV3Fields(hero);
    var totMats = getTotalMaterialsCount();
    var maxCap = getMaxForgeCap();
    var myGems = hero.gems || 0;
    var forgesLeft = Math.max(0, MAX_DAILY_FORGES - (hero.forgesUsedToday || 0));
    var socketsLeft = Math.max(0, MAX_DAILY_SOCKETS - (hero.socketsUsedToday || 0));
    var v = hero.vault || { gold: 0, gems: 0, dulledGems: 0, items: [] };
    var dulledCnt = v.dulledGems || 0;
    var curFilter = hero.lootFilter || "none";
    var wBoosts = (hero.weapon && hero.weapon.anvilBoosts) ? hero.weapon.anvilBoosts : 0;

    var bromBanner = '<div style="background:linear-gradient(135deg,#1f1424 0%,#0b0811 100%);border:2px solid #c5a059;border-radius:6px;padding:10px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">' +
      '<div style="display:flex;align-items:center;gap:10px;">' + renderEntityAvatar("Blacksmith Brom Iron-Thumb", "🔨⚒️", 48, false) +
        '<div><div style="font-size:14px;font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;">🔨 Master Blacksmith Brom&apos;s Dwarven Forge (💰' + hero.gold.toLocaleString() + 'g • 💎' + myGems + ' • 📦' + totMats + ' Trophies • 🪨' + dulledCnt + ' Slag)</div>' +
        '<div style="font-size:11.5px;color:#e5dec9;">&ldquo;Tempering weapons demands heavy Monster Trophy tribute (5 + 3 per tier)! Have surplus trophies? Trade them with Master Huntsman Kraven!&rdquo;</div></div>' +
      '</div>' +
      '<div style="display:flex;gap:5px;flex-wrap:wrap;">' +
        '<button class="btn btn-gold" onclick="if(window.openBromRhythmAnvilModal)window.openBromRhythmAnvilModal()">🔨 Dwarven Anvil (' + wBoosts + '/3 • -2⚡)</button>' +
        '<button class="btn ' + (dulledCnt > 0 ? 'btn-arcane' : 'btn-locked') + '" onclick="if(window.crushDulledSlagWhetstone)window.crushDulledSlagWhetstone()">🪨 Crush Slag (Have ' + dulledCnt + '🪨)</button>' +
        '<button class="btn btn-emerald" onclick="if(window.repairAllEquippedGear)window.repairAllEquippedGear()">🔧 Repair All Equipped</button>' +
        '<button class="btn btn-sky" onclick="openHuntsmanTrophyExchangeModal()">🏹 Exchange (' + totMats + '📦)</button>' +
      '</div>' +
    '</div>';

    var htm = bromBanner + '<div class="card-title"><span>🎒 Unequipped Reliquary Pack (' + hero.inventory.length + '/30 — Safe to Sell or Salvage • Tap 🔒 to Lock)</span>' +
      '<div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center;">' +
        '<select style="width:auto;padding:3px 7px;font-size:10.5px;" onchange="setLootFilter(this.value)">' +
          '<option value="none" ' + (curFilter === "none" ? "selected" : "") + '>♻️ Auto-Salvage: Off</option>' +
          '<option value="common" ' + (curFilter === "common" ? "selected" : "") + '>♻️ Auto-Salvage: Common</option>' +
          '<option value="below_rare" ' + (curFilter === "below_rare" ? "selected" : "") + '>♻️ Auto-Salvage: Below Rare</option>' +
          '<option value="non_upgrades" ' + (curFilter === "non_upgrades" ? "selected" : "") + '>♻️ Auto-Salvage: Non-Upgrades</option>' +
        '</select>' +
        '<button class="btn btn-sky" style="min-height:28px;padding:3px 7px;font-size:10.5px;" onclick="openTownFacilityModal(&#39;post&#39;)">🏦 My Vault (' + (v.gems || 0) + '/20💎)</button>' +
