            '<button class="btn ' + (itm.locked ? 'btn-locked' : 'btn-sky') + '" style="min-height:30px;padding:3px 7px;font-size:10.5px;" title="Deposit in Personal Vault" onclick="depositVaultItem(' + idx + ')">🏦 Vault</button>' +
            '<button class="btn ' + (itm.locked ? 'btn-locked' : 'btn-crimson') + '" style="min-height:30px;padding:3px 7px;font-size:10.5px;" title="Sell Unequipped Pack Item" onclick="sellInventoryItem(' + idx + ')">💰 Sell (+' + sellVal + 'g)</button>' +
