    htm += '<div class="card-title" style="margin-top:12px;"><span>🛡️ Currently Equipped Hero Relics (Protected From Selling • ' + forgesLeft + '/' + MAX_DAILY_FORGES + ' Forges Left Today • Max +' + maxCap + ')</span><span style="color:#fde68a;font-size:11px;">📦 Trophies Held: <b>' + totMats + '</b> | 💰 <b>' + hero.gold.toLocaleString() + 'g</b> | 💎 <b>' + myGems + '</b></span></div>';
    gearSlots.forEach(function(g) {
