}

String buildV16ChunkA2a() {
    return '''
// ============================================================================
// v18.4.1 ENGINE PART A2a: SCALED BROM REPAIRS, SLAG GRINDER, FENCE & SMUGGLING
// ============================================================================

function degradeEquippedGearAfterBattle() {
  if (!hero) return "";
  var slots = ["weapon", "armor", "helm", "boots", "relic", "amulet"];
  var pick = slots[Math.floor(Math.random() * slots.length)];
  var itm = hero[pick];
  if (!itm) return "";
  if (itm.maxDur === undefined) itm.maxDur = 100;
  if (itm.dur === undefined) itm.dur = 100;
  if (itm.dur <= 0) return "";
  var loss = 4 + Math.floor(Math.random() * 5);
  itm.dur = Math.max(0, itm.dur - loss);
  if (itm.dur === 0) {
    var msg = "💥 " + escapeHtml(itm.name) + " broke (0% Durability)! Visit Master Blacksmith Brom in the Reliquary tab or Bazaar to repair it!";
    addLog("💥🛠️ <b style='color:#ef4444;'>EQUIPMENT BROKE!</b> Your <b>" + escapeHtml(itm.name) + "</b> reached 0% Durability!");
    showGothicToast("💥 " + itm.name + " BROKE (0% Durability)!");
    return msg;
  }
  return "";
}

function getGearRepairCost(itm) {
  if (!itm) return 0;
  var missing = Math.max(0, (itm.maxDur || 100) - (itm.dur !== undefined ? itm.dur : 100));
  if (missing <= 0) return 0;
  var lv = Math.max(1, hero ? hero.level : 1);
  var upg = itm.upgrade || 0;
  var perPt = 3.5 * lv + Math.pow(lv, 1.85) * 0.55 + (upg * 18);
  return Math.max(35, Math.round((missing / 10.0) * perPt));
}

function repairSingleGearSlot(slotKey) {
  ensureHeroV3Fields(hero);
  var itm = hero[slotKey];
  if (!itm) return;
  var cost = getGearRepairCost(itm);
  if (cost <= 0) return;
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for Blacksmith Brom", "🔨💰", "Master Blacksmith Brom requires <b style='color:#fbbf24;'>" + cost.toLocaleString() + " Gold</b> to hammer <b>" + escapeHtml(itm.name) + "</b> back to 100% Durability at Level " + hero.level + " (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Patrol regions, sell unequipped gear, crush Dulled Slag, or strike Brom's Dwarven Anvil!", "");
    return;
  }
  hero.gold -= cost;
  itm.dur = itm.maxDur || 100;
  playSfx("coin");
  addLog("🔨 <b>Master Blacksmith Brom</b> repaired <b>" + escapeHtml(itm.name) + "</b> to 100% Durability (-" + cost.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left)!");
  queueSaveHero();
  renderGameScreen();
}

function repairAllEquippedGear() {
  ensureHeroV3Fields(hero);
  var slots = ["weapon", "armor", "helm", "boots", "relic", "amulet"];
  var totalCost = 0, repairedCnt = 0;
  slots.forEach(function(k) {
    if (hero[k] && (hero[k].dur !== undefined ? hero[k].dur : 100) < (hero[k].maxDur || 100)) {
      totalCost += getGearRepairCost(hero[k]);
      repairedCnt++;
    }
  });
  if (repairedCnt === 0) {
    showGothicToast("✅ Blacksmith Brom: All equipped gear is already at 100% Durability!");
    return;
  }
  if (hero.gold < totalCost) {
    showRequirementModal("Not Enough Gold for Blacksmith Brom", "🔨💰", "Master Blacksmith Brom requires <b style='color:#fbbf24;'>" + totalCost.toLocaleString() + " Gold</b> to repair all <b>" + repairedCnt + " worn item(s)</b> to 100% Durability at Level " + hero.level + " (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Repair individual pieces one at a time, crush Dulled Gem Slag, or strike Brom's Dwarven Anvil!", "");
    return;
  }
  hero.gold -= totalCost;
  slots.forEach(function(k) { if (hero[k]) hero[k].dur = hero[k].maxDur || 100; });
  playSfx("levelup");
  var rMsg = "🔨⚒️ <b>MASTER BLACKSMITH BROM IRON-THUMB OVERHAUL (-" + totalCost.toLocaleString() + "g • Have " + hero.gold.toLocaleString() + "g left):</b><br>&ldquo;Good as the day it left Durin's anvil!&rdquo; Restored all <b>" + repairedCnt + " equipped relics</b> to <b>100% Durability</b>!";
  addLog(rMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🔨 Blacksmith Brom Repaired All Gear!", "🔨🛡️", "Blacksmith Brom Iron-Thumb", "#4ade80", rMsg, window.currentTownModal);
}

function crushDulledSlagWhetstone() {
  ensureHeroV3Fields(hero);
  if ((hero.slagCrushedToday || 0) >= 2) {
    showRequirementModal("Slag Grinder Daily Limit Reached (2/2 Today)", "🪨⏳", "Master Blacksmith Brom can only grind <b>2 Dulled Gem Slags per day</b> on his dwarven wheel.", "Return tomorrow (or use Admin Reset) to crush more Dulled Slag!", "");
    return;
  }
  var curSlag = (hero.vault && hero.vault.dulledGems) ? hero.vault.dulledGems : 0;
  if (curSlag <= 0) {
    showRequirementModal("No Dulled Gem Slag in Personal Vault (Have 0🪨)", "🪨🔨", "Master Blacksmith Brom requires <b>1🪨 Dulled Gem Slag</b> from your Personal Vault to grind into Dwarven Whetstone Grit.", "Dulled Slag forms when locked Vault Gems expire after 7 days or when drained at the Catacomb Wheel!", "");
    return;
  }
  hero.vault.dulledGems -= 1;
  hero.slagCrushedToday = (hero.slagCrushedToday || 0) + 1;
  ["weapon", "armor", "helm", "boots", "relic", "amulet"].forEach(function(k) {
    if (hero[k]) hero[k].dur = Math.min(hero[k].maxDur || 100, (hero[k].dur !== undefined ? hero[k].dur : 100) + 40);
  });
  playSfx("levelup");
  var sMsg = "🪨🔨 <b>DULLED GEM SLAG CRUSHED INTO WHETSTONE GRIT (" + hero.slagCrushedToday + "/2 Today • -1🪨 Slag • Have " + hero.vault.dulledGems + "🪨 left):</b><br>Blacksmith Brom ground your expired gem slag across his dwarven wheel, restoring <b>+40% Durability</b> to all 6 equipped relics for free!";
  addLog(sMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🪨 Whetstone Grit Applied (+40% Dur)!", "🪨🔨", "Blacksmith Brom Iron-Thumb", "#4ade80", sMsg, null);
}

function openUndergroundFenceModal() {
  ensureHeroV3Fields(hero);
  var hasShadow = (hero.alignment && hero.alignment.Shadow >= 15);
  var contrabands = [];
  (hero.inventory || []).forEach(function(itm, idx) {
    if (itm && itm.stolen) contrabands.push({ itm: itm, idx: idx });
  });
  if (!hasShadow && contrabands.length === 0 && (hero.wantedLevel || 0) <= 0) {
    showRequirementModal(
      "Sewer Grate Locked (Need 15+ Shadow, Contraband, or Wanted Lv)", "🥷🕳️",
      "The Whisper-Broker of the Sewer Fence only opens the iron grate to outlaws with <b>15+ Shadow Alignment</b> (Currently " + ((hero.alignment && hero.alignment.Shadow) || 0) + "), stolen <b>🥷 Contraband</b> in their pack, or an active <b>🚨 Wanted Level</b>.",
      "Choose Shadow options in Trail Encounters or steal contraband in the Bazaar to gain entry!",
      ""
    );
    return;
  }
  var pardonCost = Math.max(400, (hero.wantedLevel || 1) * hero.level * 55);
  var hasFleet = (hero.guild && hero.guild.founded && hero.guild.recruits && hero.guild.recruits.includes("kaelen_fleet"));
  var smugLeft = Math.max(0, 3 - (hero.smugglesToday || 0));
  var fenceRows = contrabands.length ? contrabands.map(function(c) {
    var launderVal = Math.max(25, Math.round((c.itm.value || 50) * 0.85));
    return '<div class="item-row" style="border-color:#f43f5e;text-align:left;">' +
      '<div style="flex:1;">' + formatItemStats(c.itm, false, false) + '</div>' +
      '<button class="btn ' + (smugLeft > 0 ? 'btn-gold' : 'btn-locked') + '" onclick="launderContrabandItem(' + c.idx + ')">🥷 Launder (+' + launderVal.toLocaleString() + 'g • ' + smugLeft + '/3)</button></div>';
  }).join('') : '<div style="font-size:12px;color:#9c8f7a;padding:8px;">No stolen 🥷 Contraband in your backpack right now. Any item stolen from the Bazaar can be laundered here for <b>85% of its full value</b> (or smuggled on your Sovereign Armada for <b>125% Gold &amp; up to +1–2💎 Gems</b>)!</div>';

  showPopupModal(
    '<div style="margin-bottom:6px;">' + renderEntityAvatar("Sewer Fence Whisper", "🥷🕳️", 62, false) + '</div>' +
    '<div style="font-size:19px;font-weight:900;color:#fda4af;font-family:Cinzel,serif;">🥷 The Underground Sewer Fence</div>' +
    '<div style="font-size:12px;color:#e5dec9;margin-bottom:8px;">Shadow Standing: <b>' + ((hero.alignment && hero.alignment.Shadow) || 0) + '</b> • Wanted Level: <b style="color:#ef4444;">' + (hero.wantedLevel || 0) + '</b> • 💰 Your Gold: <b>' + hero.gold.toLocaleString() + 'g</b> • Deals Left Today: <b>' + smugLeft + '/3</b></div>' +
    '<div style="display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap;">' +
      '<button class="btn ' + ((hero.wantedLevel || 0) > 0 ? 'btn-crimson' : 'btn-locked') + '" style="flex:1;" onclick="bribeWatchCaptainClearWanted()">🚨 Burn Wanted Warrant (' + pardonCost.toLocaleString() + 'g • Have ' + hero.gold.toLocaleString() + 'g)</button>' +
      (contrabands.length > 0 ? '<button class="btn ' + (hasFleet && smugLeft > 0 ? 'btn-shine' : 'btn-locked') + '" style="flex:1;" onclick="smuggleContrabandArmada()">🥷⚓ Armada Smuggle Contraband (' + smugLeft + '/3 • +1–2💎 Max)</button>' : '') +
      '<button class="btn ' + (hero.merchantBlacklistUntil > Date.now() ? 'btn-sky' : 'btn-locked') + '" style="flex:1;" onclick="hero.merchantBlacklistUntil=0;hero.gold=Math.max(0,hero.gold-250);showGothicToast(&#39;🥷 Forged Merchant Papers (-250g)!&#39;);openUndergroundFenceModal();">📜 Forge Merchant Pass (-250g ➔ Clear 1h Blacklist)</button>' +
    '</div>' +
    '<div style="text-align:left;font-size:13px;font-weight:bold;color:#fde047;font-family:Cinzel,serif;margin-bottom:6px;">🥷 Launder Stolen Contraband (85% Value Payout):</div>' +
    fenceRows +
    '<button class="btn" style="width:100%;margin-top:10px;" onclick="openTownFacilityModal(&#39;market&#39;)">⬅️ Back to Bazaar</button>'
  );
}

function launderContrabandItem(idx) {
  ensureHeroV3Fields(hero);
  if ((hero.smugglesToday || 0) >= 3) {
    showRequirementModal("Sewer Fence Daily Limit Reached (3/3 Today)", "🥷⏳", "The Whisper-Broker can only fence or smuggle contraband <b>3 times per day</b> before the Citadel Watch tightens patrols.", "Return tomorrow (or use Admin Reset) for fresh fence deals!", "");
    return;
  }
  var itm = hero.inventory[idx];
  if (!itm) return;
  hero.smugglesToday = (hero.smugglesToday || 0) + 1;
  var val = Math.max(25, Math.round((itm.value || 50) * 0.85));
  hero.gold += val;
  hero.inventory.splice(idx, 1);
  playSfx("coin");
  addLog("🥷💰 Laundered Contraband <b>" + escapeHtml(itm.name) + "</b> at the Sewer Fence (" + hero.smugglesToday + "/3 Today) for <b>+" + val.toLocaleString() + " Gold (85% Value)</b>!");
  queueSaveHero();
  openUndergroundFenceModal();
  renderGameScreen();
}

function bribeWatchCaptainClearWanted() {
  ensureHeroV3Fields(hero);
  if ((hero.wantedLevel || 0) <= 0) {
    showGothicToast("✅ You have no active Wanted Bounty!");
    return;
  }
  var cost = Math.max(400, hero.wantedLevel * hero.level * 55);
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for Watch Bribe", "🚨💰", "Bribing the Citadel Watch Captain to burn your Wanted Level " + hero.wantedLevel + " warrant requires <b>" + cost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>).", "Launder contraband or patrol regions to raise Gold!", "");
    return;
  }
  hero.gold -= cost;
  hero.wantedLevel = 0;
  hero.merchantBlacklistUntil = 0;
  playSfx("coin");
  var bMsg = "🚨📜 <b>ROYAL BOUNTY WARRANT BURNED (-" + cost.toLocaleString() + "g):</b><br>Your Wanted Level is now <b>0</b>, Royal Executioners &amp; The Hound have been called off, and High Court Petitions are reopened!";
  addLog(bMsg);
  queueDeltaSaveHero();
  renderGameScreen();
  showOutcomeModal("🚨 Wanted Bounty Cleared!", "🚨📜", null, "#4ade80", bMsg, window.currentTownModal);
}
'''
}

String buildV16ChunkA2b() {
    return '''
// ============================================================================
// v18.4.1 ENGINE PART A2b: ALT BODYGUARD PAYOUTS, RARER GEM SETS & MENAGERIE
// ============================================================================

window.getMercHireCost = function(mMeta) {
  var lv = hero ? Math.max(1, hero.level || 1) : 1;
  var deaths = hero ? (hero.totalRecruitDeaths || (hero.fallenHeroes ? hero.fallenHeroes.length : 0)) : 0;
  var hazardMult = 1 + Math.min(0.60, deaths * 0.12);
  var baseTier = 180;
  if (mMeta) {
    if (mMeta.isMartyr) baseTier = 480;
    else if ((mMeta.costGold || 0) >= 6500) baseTier = 390;
    else if ((mMeta.costGold || 0) >= 5000) baseTier = 320;
    else if ((mMeta.costGold || 0) >= 3800) baseTier = 240;
  }
  var levelCurve = (lv * 28) + Math.round(Math.pow(lv, 1.42) * 5.5);
  return Math.max(150, Math.round((baseTier + levelCurve) * hazardMult));
};

function capturePrisonerToCell() {
  if (!activeCombat || !hero || !activeCombat.isGuard) return;
  ensureHeroV3Fields(hero);
  if (!Array.isArray(hero.prisoners)) hero.prisoners = [];
  if (hero.prisoners.length >= 5) {
    showGothicToast("⛓️ Your Dungeon Interrogation Cell is full (5/5 Prisoners)!");
    return;
  }
  var pName = activeCombat.baseMobName || activeCombat.name;
  var pLv = activeCombat.level || hero.level;
  hero.prisoners.push({ name: pName, lv: pLv });
  var stolenTxt = activeCombat.stolenRewardDesc ? ("<br>• <b>Heist Loot Kept:</b> " + activeCombat.stolenRewardDesc) : "";
  activeCombat = null;
  lastCombatBanner = null;
  window._pendingPostBattleDiseaseCheck = true;
  playSfx("levelup");
  renderBattleModal();
  var cMsg = "⛓️🛡️ <b>GUARD SUBDUED &amp; LOCKED IN DUNGEON GAOL!</b><br>Because you captured <b>" + escapeHtml(pName) + "</b> alive instead of slaying them, you suffered <b>0 Court Fame Loss &amp; 0 Wanted Bounty</b>!" + stolenTxt + "<br>• Visit <b>🏰 Kingdom ➔ ⛓️ Gaol &amp; Tribunal</b> to extract <b>-20% Boss Armor Intel</b>, recruit them as a Defector (+100 Troops), or ransom them!";
  addLog(cMsg);
  saveCurrentHero(null, false, null);
  renderGameScreen();
  showOutcomeModal("⛓️ Guard Imprisoned in Dungeon Gaol!", "⛓️🛡️", pName, "#38bdf8", cMsg, null);
}

function hireAltSlotBodyguard(slotKey) {
  ensureHeroV3Fields(hero);
  if (hero.altBodyguard && hero.altBodyguard.slotKey === slotKey) {
    var oldName = hero.altBodyguard.name;
    hero.altBodyguard = null;
    playSfx("coin");
    addLog("🛡️ Released Alt Bodyguard <b>" + escapeHtml(oldName) + "</b> from retainer duty (Helper Slot freed).");
    queueSaveHero();
    renderGameScreen();
    return;
  }
  var helpersWithoutAlt = getActiveHelperCount(hero) - (hero.altBodyguard ? 1 : 0);
  if (helpersWithoutAlt >= MAX_ACTIVE_HELPERS) {
    showRequirementModal(
      "Two-Helper Party Limit Reached (2/2 Active)", "🛡️⚔️",
      "By Royal Decree, you may bring at most <b>2 Helpers</b> into battle (any combination of Recruits, Animal Companion, Dynasty Heir, or Alt Bodyguard).",
      "Dismiss 1 active Mercenary, Companion, or Battle Heir first to free a helper slot!",
      ""
    );
    return;
  }
  if ((hero.altHiresToday || 0) >= 2) {
    showRequirementModal("Alt Bodyguard Daily Limit Reached (2/2 Today)", "🛡️⏳", "You can only sign <b>2 Cross-Slot Alt Bodyguard contracts per day</b>.", "Return tomorrow (or use Admin Reset) for fresh retainer contracts!", "");
    return;
  }
  var altH = (serverData.slots && serverData.slots[slotKey]) ? serverData.slots[slotKey] : null;
  if (!altH || !altH.name || slotKey === activeSlotKey) return;
  ensureHeroV3Fields(altH);
  var altSt = getHeroStats(altH);
  var cost = Math.max(850, altH.level * 135 + hero.level * 65);
  if (hero.gold < cost) {
    showRequirementModal("Not Enough Gold for Alt Retainer", "🛡️💰", "Hiring your other slot champion <b>" + escapeHtml(altH.name) + " (Lv " + altH.level + ")</b> as a sworn Bodyguard for 8 Quests costs <b style='color:#fbbf24;'>" + cost.toLocaleString() + " Gold</b> (You currently have <b>" + hero.gold.toLocaleString() + "g</b>).<br>• <i>100% of this retainer fee is paid directly into <b>" + escapeHtml(altH.name) + "&apos;s</b> treasury!</i>", "Collect Kingdom Taxes or patrol regions for Gold!", "");
    return;
  }
  hero.gold -= cost;
  hero.altHiresToday = (hero.altHiresToday || 0) + 1;
  hero.altBodyguard = {
    slotKey: slotKey,
    name: altH.name,
    atk: Math.max(18, Math.round(altSt.atk * 0.65)),
    questsLeft: 8
  };
  playSfx("levelup");
  var aMsg = "🛡️👑 <b>SWORN ALT BODYGUARD CONTRACTED (" + hero.altHiresToday + "/2 Today • -" + cost.toLocaleString() + "g Paid to " + escapeHtml(altH.name) + "):</b><br><b>" + escapeHtml(altH.name) + " (Lv " + altH.level + " • " + hero.altBodyguard.atk + " ATK)</b> joined your party (" + getActiveHelperCount(hero) + "/2 Helpers) for <b>8 Quests</b>!<br>• 💰 <b>+" + cost.toLocaleString() + " Gold</b> was transferred directly to <b>" + escapeHtml(altH.name) + " (" + slotKey.toUpperCase() + ")</b>, and they will receive a Raven Battle Report when their service concludes!";
  addLog(aMsg);
  saveCurrentHero("🛡️ " + hero.name + " hired " + altH.name + " as a Cross-Slot Bodyguard for " + cost + "g!", false, null, {
    mailTransfer: { targetSlot: slotKey, gold: cost, xp: 0, fame: 10 },
    altGuardEvent: {
      targetSlot: slotKey,
      goldPaid: cost,
      outcome: "hired",
      summary: "💰 Hired by " + hero.name + " (Lv " + hero.level + ") for +" + cost.toLocaleString() + "g (+10 Fame)!"
    }
  });
  renderGameScreen();
  showOutcomeModal("🛡️ Alt Bodyguard Contracted!", "🛡️👑", altH.name, "#38bdf8", aMsg, null);
}

function checkAltGuardRavenInbox() {
  if (!activeSlotKey || !serverData.altGuardInbox) return;
  var box = serverData.altGuardInbox[activeSlotKey];
  if (!box || (!box.goldEarned && !box.survivedCount && !box.fellCount && (!box.events || !box.events.length))) return;
  var gEarned = box.goldEarned || 0;
  var survCnt = box.survivedCount || 0;
  var fellCnt = box.fellCount || 0;
  var evLines = (box.events || []).map(function(e) { return '<div>• ' + escapeHtml(e) + '</div>'; }).join('');
  delete serverData.altGuardInbox[activeSlotKey];
  playSfx("levelup");
  saveCurrentHero(null, false, null, { clearAltGuardInboxSlot: activeSlotKey });
  showPopupModal(
    '<div style="font-size:46px;">🦅🛡️💰</div><div style="font-size:19px;font-weight:900;color:#4ade80;font-family:Cinzel,serif;margin-top:4px;">RAVEN DISPATCH: BODYGUARD SERVICE REPORT</div>' +
    '<div style="background:#0b1610;border:2px solid #4ade80;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13.5px;line-height:1.65;color:#e5dec9;">' +
      '<div>Your champion <b>' + escapeHtml(hero.name) + '</b> was summoned into battle as a Sworn Alt Bodyguard by another Hero Slot! (<i>Your actual character suffers zero penalty if your shadow-retainer falls</i>):</div>' +
      '<div style="margin-top:6px;">• 💰 <b>Retainer Gold Deposited into Your Treasury:</b> <b style="color:#fde047;">+' + gEarned.toLocaleString() + ' Gold</b></div>' +
      '<div>• 🛡️ <b>Campaigns Survived:</b> <b style="color:#4ade80;">' + survCnt + '</b> | 🩸 <b>Heroic Sacrifices:</b> <b style="color:#fca5a5;">' + fellCnt + '</b></div>' +
      (evLines ? ('<div style="margin-top:6px;padding-top:6px;border-top:1px dashed #15803d;font-size:12px;color:#fde68a;">' + evLines + '</div>') : '') +
    '</div><button class="btn btn-gold" style="width:100%;justify-content:center;" onclick="closePopupModal()">🦅 Pocket Retainer Spoils</button>'
  );
}

var CLASS_ZONE_SETS = {
  "Warrior":     { prefix: "Dragonforged", perk: "Cinder-Cleave (+15% Fire/Armor Break)", icon: "🪓🔥" },
  "Wizard":      { prefix: "Eldritch",     perk: "Astral-Surge (+18% Spell Shock)", icon: "🔮⚡" },
  "Trader":      { prefix: "Sovereign",    perk: "Golden-Aegis (+20% Tithe & Parry)", icon: "⚖️👑" },
  "Sage":        { prefix: "Celestial",    perk: "Chrono-Grace (+15% Mana & Ward)", icon: "📜🌟" },
  "Shadowblade": { prefix: "Vampiric",     perk: "Night-Bleed (+12% Lifesteal & Crit)", icon: "🗡️🩸" },
  "Paladin":     { prefix: "Valiant",      perk: "Solar-Smite (+15% Holy DEF & Heal)", icon: "🛡️☀️" }
};

function hasOwnedSetPiece(setId) {
  var slots = ["weapon", "armor", "helm", "boots", "relic", "amulet"];
  for (var i = 0; i < slots.length; i++) {
    var eq = hero[slots[i]];
    if (eq && eq.setId === setId) return true;
  }
  return (hero.inventory || []).some(function(x) { return x && x.setId === setId; });
}

function rollSmartClassZoneSetDrop(areaId) {
  if (Math.random() > 0.40) {
    return { item: null, scrappedGems: 0 };
  }
  var cSet = CLASS_ZONE_SETS[hero.calling] || CLASS_ZONE_SETS["Warrior"];
  var slotTypes = ["weapon", "armor", "helm", "boots", "relic", "amulet"];
  var targetSlot = slotTypes[Math.floor(Math.random() * slotTypes.length)];
  var setId = "czset_" + hero.calling + "_a" + areaId + "_" + targetSlot;

  if (hasOwnedSetPiece(setId)) {
    return { item: null, scrappedGems: (Math.random() < 0.50 ? 1 : 0) };
  }

  var scale = Math.max(2, areaId * 6 + hero.level * 1.4);
  var itm = {
    setId: setId,
    name: cSet.prefix + " " + hero.calling + " " + targetSlot.toUpperCase() + " of Area " + areaId,
    icon: cSet.icon,
    type: targetSlot,
    rarity: areaId >= 12 ? "Mythic" : "Legendary",
    setPerk: cSet.perk,
    atk: (targetSlot === "weapon" || targetSlot === "relic" || targetSlot === "amulet") ? Math.round(14 + scale * 1.60) : Math.round(scale * 0.5),
    def: (targetSlot !== "weapon") ? Math.round(12 + scale * 1.40) : 0,
    guts: Math.round(4 + areaId * 2.1),
    wits: Math.round(4 + areaId * 2.1),
    charm: Math.round(3 + areaId * 1.7),
    upgrade: 0,
    socket: "dragonfire",
    dur: 100, maxDur: 100, kills: 0,
    value: areaId * 950
  };
  return { item: itm, scrappedGems: 0 };
}

function evolveCompanionStage(compId) {
  ensureHeroV3Fields(hero);
  if (!hero.petEvo) hero.petEvo = {};
  var curStage = hero.petEvo[compId] || 1;
  if (curStage >= 3) return;
  var reqGold = (curStage === 1) ? (1800 + hero.level * 95) : (4200 + hero.level * 180);
  var reqGems = (curStage === 1) ? 3 : 6;
  var reqMats = (curStage === 1) ? 3 : 5;
  var totMats = getTotalMaterialsCount();
  if (hero.gold < reqGold || (hero.gems || 0) < reqGems || totMats < reqMats) {
    showRequirementModal(
      "Insufficient Tribute to Evolve Companion (Stage " + (curStage + 1) + "/3)", "🐾🌟",
      "Forging <b>Stage " + (curStage + 1) + "/3 Celestial War-Barding</b> for your companion requires:<br>" +
      "• <b style='color:#fbbf24;'>" + reqGold.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)<br>" +
      "• <b style='color:#fde68a;'>" + reqGems + "💎 Dragon Gems</b> (You have <b>" + (hero.gems || 0) + "💎</b>)<br>" +
      "• <b style='color:#86efac;'>" + reqMats + " Monster Trophies</b> (You have <b>" + totMats + " Trophies</b>)",
      "Collect Kingdom Taxes, defeat Regional/Delve Bosses for Dragon Gems, and patrol realms for Monster Trophies!",
      ""
    );
    return;
  }
  hero.gold -= reqGold;
  hero.gems -= reqGems;
  consumeAnyMaterials(reqMats);
  hero.petEvo[compId] = curStage + 1;
  if (hero.companion && hero.companion.id === compId) {
    var newMax = Math.round((90 + (hero.level || 1) * 22) * (1 + curStage * 0.35));
    hero.companion.maxHp = newMax;
    hero.companion.hp = newMax;
  }
  playSfx("levelup");
  spawnCanvasParticles("gold", 35);
  var eMsg = "🐾🌟 <b>COMPANION EVOLVED TO STAGE " + (curStage + 1) + "/3 (-" + reqGold.toLocaleString() + "g, -" + reqGems + "💎, -" + reqMats + " Trophies)!</b><br>Your companion donned celestial war-barding, multiplying its passive accuracy/dodge/parry bonuses, combat damage, and Max HP (+35% Vitals)!";
  addLog(eMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🐾 Companion Stage " + (curStage + 1) + "/3!", "🐾🌟", null, "#4ade80", eMsg, null);
}

function captureMonsterMenagerie() {
  if (!activeCombat || !hero) return;
  ensureHeroV3Fields(hero);
  if (activeCombat.isBoss || activeCombat.isPvp || activeCombat.isGuard) return;
  if (hero.menagerie.length >= 12) {
    showGothicToast("🦁 Beastmaster Thulsa's Menagerie is Full (12/12 Cages)!");
    return;
  }
  var capturedName = activeCombat.baseMobName || activeCombat.name;
  var capturedIcon = activeCombat.icon || "👹";
  hero.menagerie.push({ name: capturedName, icon: capturedIcon, areaId: activeCombat.areaId || 1, lv: activeCombat.level || 1 });
  playSfx("levelup");
  spawnCanvasParticles("gold", 32);
  activeCombat = null;
  lastCombatBanner = null;
  window._pendingPostBattleDiseaseCheck = true;
  renderBattleModal();
  var mMsg = "🕸️🦁 <b>CAPTURED FOR BEASTMASTER THULSA'S GRAND MENAGERIE!</b><br>Bound <b>" + capturedIcon + " " + escapeHtml(capturedName) + "</b> into your Royal Menagerie in the Retinue tab (" + hero.menagerie.length + "/12 Beasts)!<br>• <b>Exotic Menagerie Yield:</b> Generates <b>+" + (hero.menagerie.length * 45) + " Gold</b> every 45m tick!";
  addLog(mMsg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🦁 Captured for Grand Menagerie!", capturedIcon, capturedName, "#4ade80", mMsg, null);
}

function discoverFreeFormAlchemy() {
  ensureHeroV3Fields(hero);
  if ((hero.cauldronUsedToday || 0) >= 2) {
    showRequirementModal("Discovery Cauldron Daily Limit (2/2 Today)", "🔮⏳", "Apothecary Mira's Cauldron can only be distilled <b>2 times per day</b>.", "Return tomorrow!", "");
    return;
  }
  var totMats = getTotalMaterialsCount();
  if (hero.quests < 2 || totMats < 3) {
    showRequirementModal("Need 2⚡ Quests & 3 Monster Trophies", "🔮🧪", "Requires <b>2⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>) and <b>3 Monster Trophies</b> (You have <b>" + totMats + " Trophies</b>).", "Patrol any region for Trophies!", "");
    return;
  }
  hero.quests -= 2;
  hero.cauldronUsedToday = (hero.cauldronUsedToday || 0) + 1;
  consumeAnyMaterials(3);
  var roll = Math.random() * 100;
  var msg = "";
  if (roll < 42) {
    playSfx("death");
    var singe = Math.max(8, Math.round(hero.maxHp * 0.15));
    hero.hp = Math.max(1, hero.hp - singe);
    var stMsg = addHeroStress(15);
    hero.belt.firebomb = Math.min(5, (hero.belt.firebomb || 0) + 1);
    msg = "💥🧪 <b>VOLATILE CAULDRON BACKFIRE (" + hero.cauldronUsedToday + "/2 Today)!</b><br>Toxic fumes seared your lungs for <b style='color:#ef4444;'>-" + singe + " HP &amp; +15% Stress</b>, leaving behind <b>+1💣 Fire-Bomb</b>!" + stMsg;
  } else if (roll < 94) {
    playSfx("magic");
    var hAmt = Math.round(hero.maxHp * 0.30);
    hero.hp = Math.min(hero.maxHp, hero.hp + hAmt);
    hero.potions = (hero.potions || 0) + 1;
    msg = "🧪✨ <b>DISTILLED CRIMSON DRAUGHT (" + hero.cauldronUsedToday + "/2 Today)!</b><br>Restored <b>+" + hAmt + " HP</b> and bottled <b>+1🧪 Healing Potion (Now carrying " + hero.potions + "🧪)</b>!";
  } else {
    playSfx("levelup");
    hero.maxHp += 5;
    if (window.syncHeroVitalityMaxHp) syncHeroVitalityMaxHp(hero);
    hero.gems = (hero.gems || 0) + 1;
    msg = "🌟🧪 <b>RARE ALCHEMICAL MIRACLE: PHILOSOPHER'S TINCTURE (" + hero.cauldronUsedToday + "/2 Today • 6% Odds)!</b><br>Granted <b>+5 Permanent Base HP</b> &amp; crystallized <b>+1💎 Dragon Gem (Now " + hero.gems + "💎)</b>!";
  }
  addLog(msg);
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🔮 Apothecary Mira's Cauldron!", "🔮🧪", "Apothecary Mira", "#c084fc", msg, "sanctuary");
}
'''
}

String buildV16ChunkB1() {
    return buildV16ChunkB1a() + "\n" + buildV16ChunkB1b()
}

String buildV16ChunkB1a() {
    return '''
// ============================================================================
// v18.4.1 ENGINE PART B1a: ABYSSAL ESTUS GAUNTLETS & HALL OF LEGENDS
// ============================================================================

var ABYSSAL_GAUNTLETS = [
  { id: 1, name: "I. Gauntlet of the Weeping Ossuary", icon: "💀⛓️", minLv: 10, warden: "Ossuary Apex Warden Malgorth" },
  { id: 2, name: "II. Gauntlet of the Sulfur Crucible", icon: "💣🔥", minLv: 25, warden: "Pyre-Warden Kravok" },
  { id: 3, name: "III. Gauntlet of the Drowned Trench", icon: "🌊🦑", minLv: 40, warden: "Abyssal Warden Narkissa" },
  { id: 4, name: "IV. Gauntlet of the Frozen Spire", icon: "❄️🏔️", minLv: 55, warden: "Rime-Warden Skadi" },
  { id: 5, name: "V. Gauntlet of the Brass Pendulum", icon: "⚙️⚡", minLv: 75, warden: "Chrono-Warden Vex" },
  { id: 6, name: "VI. Gauntlet of the Crimson Eclipse", icon: "🩸🧛", minLv: 95, warden: "Blood-Warden Nosferis" },
  { id: 7, name: "VII. Gauntlet of the Dragon Graveyard", icon: "🦴🐉", minLv: 115, warden: "Grave-Warden Vermithrax" },
  { id: 8, name: "VIII. Gauntlet of the Singularity Maw", icon: "🕳️🌌", minLv: 135, warden: "Omega-Warden Null" }
];

function discoverAbyssalGauntletNode(area) {
  ensureHeroV3Fields(hero);
  if (!Array.isArray(hero.unlockedGauntlets)) hero.unlockedGauntlets = [];
  var nextG = 1;
  for (var i = 1; i <= 8; i++) {
    if (!hero.unlockedGauntlets.includes(i)) { nextG = i; break; }
  }
  if (!hero.unlockedGauntlets.includes(nextG)) hero.unlockedGauntlets.push(nextG);
  var gMeta = ABYSSAL_GAUNTLETS[nextG - 1] || ABYSSAL_GAUNTLETS[0];
  recordMemoirMilestone("Uncovered the hidden stairs to " + gMeta.name + " while patrolling " + area.name + "!");
  playSfx("levelup");
  spawnCanvasParticles("void", 48);
  var dMsg = "🕳️🔥 <b style='color:#fde047;'>YOU FOUND AN ABYSSAL CHASM: " + escapeHtml(gMeta.name.toUpperCase()) + "!</b><br><br>" +
    "While patrolling the mist-shrouded wilds of <b>" + escapeHtml(area.name) + "</b>, your boot breaks through a false flagstone—revealing a spiral staircase of black dragon-glass descending into <b>" + gMeta.icon + " " + escapeHtml(gMeta.name) + "</b>!<br><br>" +
    "🦅 <b>Scoutmaster Kael:</b> <i>&ldquo;I have charted this Abyssal Chasm permanently onto your 🗺️ Royal Atlas, my Liege! Inside wait 10 relentless waves led by <b>" + escapeHtml(gMeta.warden) + "</b> with a rechargeable 3-Sip Estus Soul-Flask!&rdquo;</i>";
  addLog(dMsg);
  queueSaveHero();
  renderGameScreen();
  showPopupModal(
    '<div style="font-size:48px;">🕳️🔥🦅</div>' +
    '<div style="font-size:20px;font-weight:900;color:#fde047;font-family:&#39;Cinzel&#39;,serif;margin-top:4px;">YOU UNSEALED ' + escapeHtml(gMeta.name.toUpperCase()) + '!</div>' +
    '<div style="background:#0b0811;border:2px solid #c084fc;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13.5px;line-height:1.6;color:#e5dec9;">' + dMsg + '</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn btn-shine" style="flex:1;" onclick="confirmEnterAbyssalGauntlet(' + gMeta.id + ')">🕳️ Descend Into Chasm (-6⚡)</button>' +
      '<button class="btn btn-gold" style="flex:1;" onclick="closePopupModal()">🗺️ View on Royal Atlas</button>' +
    '</div>'
  );
}

function confirmEnterAbyssalGauntlet(gId) {
  ensureHeroV3Fields(hero);
  var gMeta = ABYSSAL_GAUNTLETS.find(function(x) { return x.id === gId; }) || ABYSSAL_GAUNTLETS[0];
  var gRunsLeft = Math.max(0, MAX_DAILY_GAUNTLETS - (hero.gauntletsRunToday || 0));
  showPopupModal(
    '<div style="font-size:46px;">🕳️⚠️🔥</div>' +
    '<div style="font-size:19px;font-weight:900;color:#f43f5e;font-family:&#39;Cinzel&#39;,serif;margin-top:4px;">CONFIRM ABYSSAL CHASM DESCENT</div>' +
    '<div style="font-size:14px;font-weight:bold;color:#fde047;margin:4px 0;">' + gMeta.icon + ' ' + escapeHtml(gMeta.name) + ' (Rec. Lv ' + gMeta.minLv + '+)</div>' +
    '<div style="background:#14090e;border:2px solid #ef4444;border-radius:4px;padding:12px;margin:10px 0;text-align:left;font-size:13px;line-height:1.65;color:#fecaca;">' +
      '<div>• <b>10 Relentless Waves &amp; 3-Sip Estus Flask:</b> Fight Waves 1–10 back-to-back! You start with <b>3🧪🔥 Estus Soul-Flask Sips</b> (+40% HP/MP each) that automatically refill <b>+1 Sip after every 3rd wave cleared</b>!</div>' +
      '<div>• <b>🔒 NO FLEEING ALLOWED:</b> Once the obsidian gates seal behind you, the Flee button is completely disabled for all 10 waves!</div>' +
      '<div>• <b>Death Stakes:</b> Falling in battle forfeits <b>-1🪽 Seal of the Valkyrie</b> (You carry <b>' + Math.min(3, hero.valkyrieSeals !== undefined ? hero.valkyrieSeals : 3) + '/3🪽</b>) and drags you back to town (or triggers <b>True Permadeath</b> if you enter with 0 Seals!).</div>' +
      '<div>• <b>Daily Runs Left:</b> <b style="color:#4ade80;">' + gRunsLeft + ' / 2 Today</b> • <b>Entry Cost:</b> <b style="color:#fbbf24;">6⚡ Quests (You have ' + hero.quests + '⚡)</b></div>' +
    '</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button class="btn btn-crimson" style="flex:1;padding:12px;font-size:13.5px;" onclick="startAbyssalGauntlet(' + gMeta.id + ')">⚔️ I Swear the Oath — Enter Chasm (-6⚡)</button>' +
      '<button class="btn" style="flex:1;" onclick="closePopupModal()">Step Back</button>' +
    '</div>'
  );
}

function startAbyssalGauntlet(gId) {
  ensureHeroV3Fields(hero);
  if ((hero.gauntletsRunToday || 0) >= MAX_DAILY_GAUNTLETS) {
    showRequirementModal("Abyssal Chasm Daily Cap (2/2 Today)", "🕳️⏳", "You have already entered the <b>Abyssal Chasms 2 times today</b>.", "Return tomorrow (or use Admin Reset) for 2 fresh daily runs!", "");
    return;
  }
  if (hero.quests < 6) {
    showRequirementModal("Need 6⚡ Quests for 10-Wave Chasm", "🕳️⚡", "Entering a 10-Wave Abyssal Chasm requires <b>6⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>).", "Wait for the 45m stamina tick or visit the Astral Ley-Well!", "");
    return;
  }
  var gMeta = ABYSSAL_GAUNTLETS.find(function(x) { return x.id === gId; }) || ABYSSAL_GAUNTLETS[0];
  hero.quests -= 6;
  hero.gauntletsRunToday = (hero.gauntletsRunToday || 0) + 1;
  closePopupModal();
  spawnGauntletWaveCombat(gMeta, 1, 3);
}

function spawnGauntletWaveCombat(gMeta, waveNum, estusLeft) {
  var isApex = (waveNum === 10);
  var wLv = Math.max(gMeta.minLv, hero.level) + Math.floor(waveNum / 2);
  var wHp = Math.round((102 + wLv * 46 + Math.pow(wLv, 1.73) * 6.0) * (isApex ? 1.55 : 1.15));
  var wArm = Math.round(wHp * 0.25);
  var wAtk = Math.round((15 + wLv * 6.0) * (isApex ? 1.30 : 1.10));
  var wDef = Math.round((7 + wLv * 3.2) * 1.10);
  clearTransientCombatFx();
  activeCombat = {
    isBoss: isApex, isGauntlet: true, gauntletId: gMeta.id, gauntletWave: waveNum, gauntletMeta: gMeta,
    estusSips: (estusLeft !== undefined ? estusLeft : 3),
    isWorldRaid: false, isZoneRaid: false, isDelveBoss: false, isSpire: false, isHerald: false, isPvp: false,
    areaId: hero.selectedArea || 1, baseMobName: isApex ? gMeta.warden : ("Gauntlet Wave " + waveNum + " Fiend"),
    trait: isApex ? "Apex-Warden" : "Gauntlet-Fiend",
    loreIntro: "Wave " + waveNum + " of 10 in " + gMeta.name + " (NO FLEEING! Estus Soul-Flask: " + (estusLeft !== undefined ? estusLeft : 3) + "/3 Sips).",
    icon: gMeta.icon, name: isApex ? ("WAVE 10 APEX: " + gMeta.warden) : ("CHASM WAVE " + waveNum + "/10: Abyssal Vanguard"),
    level: wLv, hp: wHp, maxHp: wHp, armor: wArm, maxArmor: wArm, poise: 100, maxPoise: 100,
    atk: wAtk, def: wDef, eva: 14, parry: 12, acc: 96 + wLv, crit: 15,
    xp: wLv * 55, gold: wLv * 60,
    sessionDamage: 0, alliedUsed: false, tauntUsed: false, tauntedTurns: 0, armorBrokenTurns: 0, hamstrungTurns: 0, silencedTurns: 0, phase2Triggered: false, comboCount: 0, bossCharging: false, partyShield: 0, bleedTurns: 0, heroPoisonTurns: 0, stunned: false
  };
  addLog("🕳️🔥 <b>" + escapeHtml(gMeta.name) + " — WAVE " + waveNum + "/10 (Estus: " + activeCombat.estusSips + "/3)!</b>");
  renderBattleModal();
}

function advanceAbyssalGauntletWave() {
  if (!activeCombat || !activeCombat.isGauntlet) return;
  var clearedW = activeCombat.gauntletWave || 1;
  var nextW = clearedW + 1;
  var gMeta = activeCombat.gauntletMeta || ABYSSAL_GAUNTLETS[0];
  var sips = activeCombat.estusSips !== undefined ? activeCombat.estusSips : 3;
  var refillMsg = "";
  if (clearedW % 3 === 0) {
    sips = Math.min(3, sips + 1);
    refillMsg = " (+1🧪🔥 Estus Sip Refilled!)";
  }
  hero.xp += Math.round(activeCombat.xp * 0.35);
  hero.gold += Math.round(activeCombat.gold * 0.35);
  showGothicToast("🕳️ Wave " + clearedW + "/10 Cleared!" + refillMsg + " Wave " + nextW + " Approaches!");
  spawnGauntletWaveCombat(gMeta, nextW, sips);
}
'''
}

