  showOutcomeModal("🌟 Hall of Legends Stage " + hero.ultQuestStage + "/5!", qMeta.icon, "Grandmaster Solaris", "#fde047", uMsg, "legends");
}

function startVoidRiftRun() {
  ensureHeroV3Fields(hero);
  if (hero.level < 20) {
    showRequirementModal(
      "Void-Rifts Sealed (Requires Level 20+)", "🌌🔒",
      "Astrolabe Seer Caelum forbids heroes below <b>Level 20</b> (Currently Lv " + hero.level + ") from entering the unstable Void-Rifts.",
      "Patrol the realms and complete Warrants to reach Level 20 first!",
      ""
    );
    return;
  }
  if ((hero.riftsRunToday || 0) >= 3) {
    showRequirementModal("Void-Rift Daily Stabilization Cap (3/3 Today)", "🌌⏳", "Your mortal soul can only endure the astral pressure of <b>3 Void-Rift floors per day</b>.", "Return tomorrow (or use Admin Reset) to descend deeper into the Void-Rifts!", "");
    return;
  }
  if (hero.quests < 5 || hero.hp <= Math.round(hero.maxHp * 0.30)) {
    showRequirementModal("Need 5⚡ Quests & >30% HP for Void-Rift", "🌌🩸", "Traversing a Void-Rift requires <b>5⚡ Quests</b> (You have <b>" + hero.quests + "⚡</b>) and at least <b>30% HP</b> (You have <b>" + hero.hp + "/" + hero.maxHp + " HP</b>).", "Heal at the Sanctuary or drink a Potion first!", "");
    return;
  }
  hero.quests -= 5;
  hero.riftsRunToday = (hero.riftsRunToday || 0) + 1;
  var strainDmg = Math.max(10, Math.round(hero.maxHp * 0.25));
  hero.hp = Math.max(1, hero.hp - strainDmg);
  var rFl = hero.voidRiftFloor || 1;
  hero.voidRiftFloor = rFl + 1;
  var gWon = 220 + rFl * 110;
  var xpWon = 180 + rFl * 95;
  hero.gold += gWon; hero.xp += xpWon;
  var runeMsg = "";
  if (rFl % 5 === 0) {
    if ((hero.cosmicRunes || 0) < 15) {
      hero.cosmicRunes = (hero.cosmicRunes || 0) + 1;
      pushBuffToFifo("buff_runes", hero);
      runeMsg = "<br>• 🌟 <b>5-FLOOR MILESTONE REWARD:</b> <span style='color:#c084fc;font-weight:bold;'>+1🌌 Cosmic Rune (Total: " + hero.cosmicRunes + "/15 ➔ +" + (hero.cosmicRunes * 2) + "% All Stats)!</span>";
    } else {
      hero.gems = (hero.gems || 0) + 1;
      runeMsg = "<br>• 🌟 <b>5-FLOOR MILESTONE (Max 15/15 Runes Reached):</b> <span style='color:#fde047;font-weight:bold;'>+1💎 Dragon Gem!</span>";
    }
  } else {
    var remFl = 5 - (rFl % 5);
    runeMsg = "<br>• ⏳ <b>Next Cosmic Rune Milestone:</b> Clear <b>" + remFl + " more floor(s)</b> (Floor " + (rFl + remFl) + ") to earn your next +2% Stat Rune!";
  }
  playSfx("levelup");
  spawnCanvasParticles("void", 36);
  var rMsg = "🌌🕳️ <b>VOID-RIFT FLOOR " + rFl + " CLEARED (" + hero.riftsRunToday + "/3 Today • -5⚡, -" + strainDmg + " HP Rift Strain)!</b><br>Guided by Astrolabe Seer Caelum, you stabilized Rift Floor " + rFl + "!<br>• <b>Spoils:</b> +" + xpWon.toLocaleString() + " XP &amp; +" + gWon.toLocaleString() + " Gold" + runeMsg;
  addLog(rMsg);
  checkLevelUp();
  queueSaveHero();
  renderGameScreen();
  showOutcomeModal("🌌 Void-Rift Floor " + rFl + " Conquered!", "🌌🕳️", "Archmage Caelum", "#c084fc", rMsg, null);
}

function smuggleContrabandArmada() {
