function checkArmadaVoyageCompletion() {
  if (!hero || !hero.armada || !hero.armada.voyageUntil) return;
  if (Date.now() < hero.armada.voyageUntil) return;
  var hrs = hero.armada.voyageHrs || 4;
  hero.armada.voyageUntil = 0;
