String buildV16ChunkB2a() {
    return '''
function getSoulExhumeReqs(deadHero) {
  var dLv = (deadHero && deadHero.level) ? deadHero.level : 1;
  return {
    goldCost: Math.max(450, dLv * 110),
    gemCost: Math.max(2, Math.min(10, 1 + Math.ceil(dLv / 12))),
    bonusG: Math.max(3, Math.round((deadHero.guts || 10) * 0.20)),
    bonusW: Math.max(3, Math.round((deadHero.wits || 10) * 0.20)),
    bonusC: Math.max(3, Math.round((deadHero.charm || 10) * 0.20)),
    bonusHp: Math.max(20, Math.round((deadHero.maxHp || 100) * 0.15)),
    bonusMp: Math.max(10, Math.round((deadHero.maxMp || 40) * 0.15))
  };
}

function findBestFallenHeirloom(deadHero) {
  if (!deadHero) return null;
  var slots = ["weapon", "armor", "helm", "boots", "relic", "amulet"], best = null, bestScore = -1;
  slots.forEach(function(k) {
    var itm = deadHero[k];
    if (itm && typeof itm === "object") {
      var sc = ((itm.upgrade || 0) * 100) + getItemPowerScore(itm);
      if (sc > bestScore) { bestScore = sc; best = JSON.parse(JSON.stringify(itm)); best.type = k; }
    }
  });
  if (best) { best = sanitizeGearItem(best, best.type || "weapon"); best.dur = 25; best.maxDur = 100; }
  return best;
}

