  );
}

function exhumeSameSlotSoul() {
  ensureHeroV3Fields(hero);
  var crypt = serverData.fallenCrypt || {}, entry = activeSlotKey ? crypt[activeSlotKey] : null;
  if (!entry || !entry.hero) return;
  var deadH = entry.hero, req = getSoulExhumeReqs(deadH), missing = [];
  if (hero.level < 5) missing.push("Need <b>Hero Level 5+</b> on this new character (Currently Lv " + hero.level + ")");
  if (hero.gold < req.goldCost) missing.push("Need <b>" + req.goldCost.toLocaleString() + " Gold</b> (You have <b>" + hero.gold.toLocaleString() + "g</b>)");
  if ((hero.gems || 0) < req.gemCost) missing.push("Need <b>" + req.gemCost + "💎 Dragon Gems</b> (You have <b>" + (hero.gems || 0) + "💎</b>)");
  if (missing.length > 0) {
    showRequirementModal("Cannot Exhume " + deadH.name + "’s Soul Yet", "⛏️👻", missing.map(function(m) { return "• " + m; }).join("<br>"), "Patrol the Shire Fields to reach Level 5 and gather the required Gold and Dragon Gems, then return to the Weeping Graveyard!", "");
    return;
  }
  hero.gold -= req.goldCost; hero.gems -= req.gemCost;
  hero.guts += req.bonusG; hero.wits += req.bonusW; hero.charm += req.bonusC;
  hero.maxHp += req.bonusHp; hero.hp = hero.maxHp;
  hero.maxMp += req.bonusMp; hero.mp = hero.maxMp;
  hero.skillPoints = (hero.skillPoints || 0) + 1;
  syncHeroVitalityMaxHp(hero);
  if (!hero.ancestors) hero.ancestors = [];
  hero.ancestors.unshift({ name: deadH.name, level: deadH.level || 1, title: deadH.nobleRank || "Fallen Hero", calling: deadH.calling || "Warrior", date: getTodayDateStr() });
  if (hero.ancestors.length > 10) hero.ancestors.pop();
  var heirloomMsg = "", bestRelic = findBestFallenHeirloom(deadH);
  if (bestRelic && Math.random() < 0.50 && hero.inventory.length < 30) {
    hero.inventory.push(bestRelic);
    heirloomMsg = "<br>• 🗡️ <b style='color:#fde047;'>HEIRLOOM GRAVE-ROBBING SUCCESS (50% Odds):</b> Unearthed <b>" + formatItemStats(bestRelic, false, false) + "</b> from the coffin at 25% Durability!";
  }
  recordMemoirMilestone("Exhumed and imbued the fallen soul of " + deadH.name + " (Lv " + (deadH.level || 1) + ") at the Weeping Graveyard.");
  delete serverData.fallenCrypt[activeSlotKey];
  playSfx("levelup");
  if (window.playAmbianceChord) playAmbianceChord("bell");
  if (window.spawnCanvasParticles) window.spawnCanvasParticles("void", 48);
  var sMsg = "⛏️👻 <b style='color:#fde047;'>ANCESTRAL SOUL EXHUMED &amp; IMBUED!</b><br>Charon Vane broke the iron seal on <b>" + activeSlotKey.toUpperCase() + "’s</b> grave! The spirit of <b>" + escapeHtml(deadH.name) + " (Lv " + (deadH.level || 1) + ")</b> surged into your body!<br>• <b>Permanent Stat Imbuement:</b> <span style='color:#4ade80;font-weight:bold;'>+" + req.bonusG + " Guts, +" + req.bonusW + " Wits, +" + req.bonusC + " Charm</span><br>• <b>Permanent Vitals &amp; Mastery:</b> <span style='color:#7dd3fc;font-weight:bold;'>+" + req.bonusHp + " Max HP, +" + req.bonusMp + " Max MP &amp; +1 Skill Point</span>" + heirloomMsg;
  addLog(sMsg);
  saveCurrentHero("👻 " + hero.name + " exhumed and absorbed the fallen soul of " + deadH.name + " at the Weeping Graveyard!", false, null, { clearCryptSlot: activeSlotKey });
  renderGameScreen();
  showOutcomeModal("👻 Soul of " + deadH.name + " Imbued!", "⛏️👻", deadH.name, "#c084fc", sMsg, "graveyard");
}

