var siegeWindOffset = 0;
function defendStrongholdRamparts() {
  ensureHeroV3Fields(hero);
  if ((hero.armyWarsToday || 0) >= MAX_DAILY_ARMY_WARS) { showRequirementModal("Daily Siege Limit Reached (3/3 Today)", "🛡️⏳", "Max 3 Sieges/Wars per day.", "Return tomorrow!", ""); return; }
  if (hero.quests < 3) { showRequirementModal("Need 3⚡ Quests", "🛡️🏰", "Requires 3⚡ Quests (You have " + hero.quests + "⚡).", "Wait for the 45m tick!", ""); return; }
  var rw = getRealWeather();
  siegeWindOffset = (Math.floor(Math.random() * 41) - 20) + (rw.wind ? 12 : 0);
  var targetPower = Math.max(15, Math.min(90, 65 - siegeWindOffset));
  var recCount = (hero.guild && hero.guild.recruits) ? hero.guild.recruits.length : 0;
  showPopupModal(
    '<div style="font-size:19px;font-weight:900;color:#fde047;font-family:Cinzel,serif;margin-bottom:4px;">🛡️🏰 Stronghold Rampart Siege (-3⚡ • Have ' + hero.quests + '⚡)</div>' +
    '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:8px;text-align:left;font-size:11px;">' +
      '<div style="background:#140c1c;border:1px solid #c5a059;padding:6px;border-radius:4px;"><b style="color:#fde047;">🚪 Gatehouse</b><select id="siegeLaneGate" style="margin-top:4px;padding:4px;font-size:10.5px;"><option value="pitch">🔥 Boiling Pitch (+6m)</option><option value="phalanx">🛡️ Phalanx</option></select></div>' +
      '<div style="background:#140c1c;border:1px solid #c5a059;padding:6px;border-radius:4px;"><b style="color:#7dd3fc;">🏹 Flanks</b><select id="siegeLaneFlank" style="margin-top:4px;padding:4px;font-size:10.5px;"><option value="volley">🏹 Volley (+150g)</option><option value="cavalry">🐎 Sortie</option></select></div>' +
      '<div style="background:#140c1c;border:1px solid #c5a059;padding:6px;border-radius:4px;"><b style="color:#c084fc;">🏰 Inner Keep</b><select id="siegeLaneKeep" style="margin-top:4px;padding:4px;font-size:10.5px;"><option value="wards">🔮 Wards (+5% Stab)</option><option value="reserve">⚔️ Reserve</option></select></div></div>' +
    '<div style="font-size:12px;color:#e5dec9;margin-bottom:8px;">Captains: <b>' + recCount + '/9</b> • Crosswind: <b>' + (siegeWindOffset >= 0 ? '+' + siegeWindOffset : siegeWindOffset) + 'm</b> • Target: <b>65m</b> (Ideal: ~<b>' + targetPower + '%</b>):</div>' +
    '<div style="background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:10px;margin-bottom:10px;text-align:left;">' +
      '<label style="color:#d4af37;font-weight:bold;font-size:12px;">☄️ Counterweight Power: <span id="catPwrLbl">' + targetPower + '%</span></label>' +
      '<input type="range" id="catapultPwrSlider" min="10" max="100" value="' + targetPower + '" oninput="document.getElementById(&#39;catPwrLbl&#39;).textContent=this.value+&#39;%&#39;"></div>' +
    '<button class="btn btn-shine" style="width:100%;padding:11px;font-size:13.5px;" onclick="fireSiegeCatapult()">☄️🔥 FIRE TREBUCHET (-3⚡)!</button>' +
    '<button class="btn" style="width:100%;margin-top:8px;" onclick="closePopupModal()">Cancel</button>'
  );
}

function fireSiegeCatapult() {
  if (hero.quests < 3) return;
  hero.quests -= 3; hero.armyWarsToday = (hero.armyWarsToday || 0) + 1;
  var pwr = parseInt((document.getElementById("catapultPwrSlider") || {}).value || "65", 10);
  var gateOrd = ((document.getElementById("siegeLaneGate") || {}).value) || "pitch";
  var flankOrd = ((document.getElementById("siegeLaneFlank") || {}).value) || "volley";
  var keepOrd = ((document.getElementById("siegeLaneKeep") || {}).value) || "wards";
  var landDist = pwr + siegeWindOffset, err = Math.abs(landDist - 65);
  var famHelp = (hero.spouse ? 1 : 0) + (hero.children && hero.children.length ? 1 : 0);
  var capBonus = Math.min(3, (hero.guild && hero.guild.recruits) ? hero.guild.recruits.length : 0) * 2;
  if (err <= (12 + famHelp * 4 + (gateOrd === "pitch" ? 6 : 3) + capBonus)) {
    var gWon = 260 + hero.level * 48 + (flankOrd === "volley" ? 150 : 80), stabAdd = 12 + (keepOrd === "wards" ? 5 : 2);
    hero.gold += gWon; hero.guild.stability = Math.min(100, (hero.guild.stability || 75) + stabAdd); addHeroFame(30);
    playSfx("crit"); spawnCanvasParticles("fire", 42);
    showOutcomeModal("☄️🎯 Rampart Siege Victory!", "☄️🏰", null, "#4ade80", "Boulder hit at <b>" + landDist + "m</b>! Earned <b>+" + gWon.toLocaleString() + "g, +30 Fame &amp; +" + stabAdd + "% Stability</b>!", null);
  } else {
    hero.guild.stability = Math.max(15, (hero.guild.stability || 75) - 4); playSfx("slash");
    showOutcomeModal("💥 Boulder Overshot (" + landDist + "m)!", "💥🏰", null, "#ef4444", "Raiders scorched the outer gate (-4% Stability).", null);
  }
  queueSaveHero(); renderGameScreen();
}
'''
}

String buildV16ChunkB2c() {
    return '''
var anvilQteState = { stage: 1, hits: 0 };
function openBromRhythmAnvilModal() {
  ensureHeroV3Fields(hero);
  if (!checkMiniGameDailyCap()) return;
  if (hero.quests < 2) { showRequirementModal("Need 2⚡ Quests", "🎵🔨", "Requires 2⚡ Quests (You have " + hero.quests + "⚡).", "Wait for the 45m tick!", ""); return; }
  hero.quests -= 2; hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
  anvilQteState = { stage: 1, hits: 0 }; window.qteMinigameActive = true;
  renderBromRhythmAnvilStage();
}

function renderBromRhythmAnvilStage() {
  var wBoosts = (hero && hero.weapon && hero.weapon.anvilBoosts) ? hero.weapon.anvilBoosts : 0;
  var wName = (hero && hero.weapon && hero.weapon.name) ? hero.weapon.name : "Equipped Weapon";
  showPopupModal(
    '<div style="font-size:19px;font-weight:900;color:#fde047;font-family:Cinzel,serif;margin-bottom:4px;">🔨 Brom’s Dwarven Anvil</div>' +
    '<div style="font-size:11.5px;color:' + (wBoosts >= 3 ? '#f87171' : '#86efac') + ';margin-bottom:4px;">🗡️ <b>' + escapeHtml(wName) + ' Temperings: ' + wBoosts + ' / 3</b></div>' +
    '<div style="font-size:12px;color:#e5dec9;margin-bottom:8px;">Hammer Blow <b>' + anvilQteState.stage + ' of 3</b> (Hits: <b style="color:#4ade80;">' + anvilQteState.hits + '</b>)</div>' +
    '<div class="reflex-bar-track" style="height:24px;margin:10px 0;"><div class="reflex-sweet-spot"></div><div class="reflex-gold-spot"></div><div id="mgQteCursorBar" class="reflex-cursor" style="left:' + reflexPos + '%;"></div></div>' +
    '<button class="btn btn-shine" style="width:100%;padding:12px;font-size:14px;" onclick="strikeQteRhythmAnvil()">🔨🔥 STRIKE RUNE-STEEL NOW!</button>'
  );
}

function strikeQteRhythmAnvil() {
  if (reflexPos >= 36 && reflexPos <= 64) { anvilQteState.hits++; playSfx("crit"); spawnCanvasParticles("gold", 28); }
  else { playSfx("slash"); }
  anvilQteState.stage++;
  if (anvilQteState.stage <= 3) { renderBromRhythmAnvilStage(); }
  else {
    window.qteMinigameActive = false;
    var durGain = 15 + anvilQteState.hits * 15, bonusTxt = "";
    ["weapon", "armor", "helm", "boots", "relic", "amulet"].forEach(function(k) {
      if (hero[k]) hero[k].dur = Math.min(100, (hero[k].dur !== undefined ? hero[k].dur : 100) + durGain);
    });
    if (anvilQteState.hits === 3 && hero.weapon) {
      var curBoosts = hero.weapon.anvilBoosts || 0;
      if (curBoosts < 3) { hero.weapon.anvilBoosts = curBoosts + 1; hero.weapon.atk = (hero.weapon.atk || 5) + 2; bonusTxt = "<br>• 🌟 <b>FLAWLESS 3/3 BEAT:</b> Permanent <b>+2 ATK</b>!"; }
    }
    queueSaveHero(); renderGameScreen();
    showOutcomeModal("🔨 Dwarven Anvil (" + anvilQteState.hits + "/3 Hits)!", "🔨🔥", "Blacksmith Brom", "#4ade80", "Restored <b>+" + durGain + "% Durability</b> across all gear!" + bonusTxt, null);
  }
}

var lockpickQteState = { pin: 1, aligned: 0 };
function playRunicLockpickModal() {
  ensureHeroV3Fields(hero);
  if (!checkMiniGameDailyCap()) return;
  if (hero.quests < 2) { showRequirementModal("Need 2⚡ Quests", "🗝️⚙️", "Requires 2⚡ Quests (You have " + hero.quests + "⚡).", "Wait for the 45m tick!", ""); return; }
  hero.quests -= 2; hero.minigamesPlayedToday = (hero.minigamesPlayedToday || 0) + 1;
  lockpickQteState = { pin: 1, aligned: 0 }; window.qteMinigameActive = true;
  renderRunicLockpickStage();
}

function renderRunicLockpickStage() {
  showPopupModal(
    '<div style="font-size:19px;font-weight:900;color:#7dd3fc;font-family:Cinzel,serif;margin-bottom:4px;">🗝️⚙️ The Thief’s Tumbler Chest</div>' +
    '<div style="font-size:12px;color:#e5dec9;margin-bottom:6px;">Tumbler Pin #' + lockpickQteState.pin + ' of 3 (' + lockpickQteState.aligned + '/3 Aligned)</div>' +
    '<div class="reflex-bar-track" style="height:24px;margin:10px 0;"><div class="reflex-sweet-spot"></div><div class="reflex-gold-spot"></div><div id="mgQteCursorBar" class="reflex-cursor" style="left:' + reflexPos + '%;"></div></div>' +
    '<button class="btn btn-sky" style="width:100%;padding:12px;font-size:14px;" onclick="strikeQteLockpickPin()">🗝️⚡ SET TUMBLER PIN #' + lockpickQteState.pin + '!</button>'
  );
