      showOutcomeModal("🗝️ Chest Unlocked!", "🗝️💎", null, "#4ade80", "Looted <b>+" + gWon.toLocaleString() + "g</b>" + (gemWon ? " &amp; <b>+1💎 Rare Gem (25% Roll)</b>!" : "!"), "wagers");
