String buildV16ChunkB2d1() {
    return '''
// ============================================================================
// LEVEL-SCALED WITS, CHARM & GUTS CHECK ENGINE + FULL SERVER BACKUP/RESTORE
// ============================================================================
function getContestedRollOdds(statKey, diff, areaId, isDelve) {
  if (!hero) return 55;
  var st = getHeroStats(), statVal = st.effGuts;
  if (statKey === "wits") statVal = st.effWits;
  else if (statKey === "charm") statVal = st.effCharm;

  var hLv = Math.max(1, hero.level || 1);
  var aId = Math.max(1, areaId || hero.selectedArea || 1);
  var delveStep = (isDelve && window.activeDelve) ? (activeDelve.step || 0) : 0;

  var baseDiff = diff || 16;
  var delveMult = isDelve ? 1.12 : 1.05;
  var levelBenchmark = (baseDiff * delveMult) + (hLv * (isDelve ? 2.20 : 2.00)) + (Math.pow(hLv, 1.32) * 0.85) + ((aId - 1) * 4.0) + (delveStep * 4.5);
  var expectedPlayerStat = 14 + (hLv * 2.25) + (Math.pow(hLv, 1.32) * 0.80);
  var effectiveTarget = Math.max(levelBenchmark, expectedPlayerStat * (isDelve ? 1.05 : 0.98));

  var ratio = statVal / Math.max(10, effectiveTarget);
  var petBonus = (isDelve && hero.companion) ? 4 : 0;
  var drunkPen = st.isDrunk ? -10 : 0;
  var baseCenter = isDelve ? 52 : 55;
  var rawOdds = Math.round(baseCenter + ((ratio - 1.0) * 50) + petBonus + drunkPen - (delveStep * 1.5));
  var maxCap = isDelve ? 74 : 82;
  return Math.max(20, Math.min(maxCap, rawOdds));
}

function rollContestedStatCheck(statKey, diff, areaId, isDelve) {
  var chance = getContestedRollOdds(statKey, diff, areaId, isDelve), roll = Math.floor(Math.random() * 100) + 1;
  return { passed: (roll <= chance), chance: chance, roll: roll };
}

function formatRiskMeterPill(odds, statKey) {
  var col = odds >= 60 ? "#4ade80" : (odds >= 42 ? "#fde047" : "#f87171");
  var bg  = odds >= 60 ? "#052e16" : (odds >= 42 ? "#451a03" : "#450a0a");
  var ico = statKey === "wits" ? "🔮WITS" : (statKey === "charm" ? "👑CHARM" : "⚔️GUTS");
  return '<span style="background:' + bg + ';border:1px solid ' + col + ';color:' + col + ';padding:2px 7px;border-radius:4px;font-size:10.5px;font-weight:900;font-family:Cinzel,serif;">' + ico + ' • ' + odds + '% ODDS</span>';
}

function addHeroStress(amt) {
  if (!hero || !amt) return "";
  var rw = getRealWeather();
  var hasLazarus = (hero.mercenaries || []).some(function(m) { return m.id === "lazarus" && m.hp > 0; });
  var lazMult = hasLazarus ? 0.80 : 1.0;
  var lodgeStressMult = (hero.lodgingBuff && hero.lodgingBuff.questsLeft > 0 && hero.lodgingBuff.stressRedPct && isPositiveBuffActiveFifo(hero, "buff_lodging")) ? (1 - hero.lodgingBuff.stressRedPct / 100.0) : 1.0;
  var delta = Math.max(1, Math.round(amt * ((rw.lightning || rw.hot) ? 1.05 : 1.0) * lazMult * lodgeStressMult));
  hero.stress = Math.max(0, Math.min(100, (hero.stress || 0) + delta));
  if (window.updateAmbianceVignetteOverlay) updateAmbianceVignetteOverlay();
  if (hero.stress >= 100 && !hero.resolveState && window.RESOLVE_STATES) {
    var isVirtue = (Math.random() < 0.25), pool = isVirtue ? RESOLVE_STATES.virtues : RESOLVE_STATES.afflictions;
    var pick = pool[Math.floor(Math.random() * pool.length)];
    hero.resolveState = { id: pick.id, name: pick.name, isVirtue: isVirtue, statMult: pick.statMult, desc: pick.desc, questsLeft: 6 };
    if (isVirtue) {
      hero.stress = 40;
      pushBuffToFifo("buff_virtue", hero);
      playSfx("levelup");
      return "<br>🌟 <b style='color:#4ade80;'>RESOLVE TEST PASSED (" + escapeHtml(pick.name) + ")!</b> " + escapeHtml(pick.desc);
    }
    playSfx("death");
    return "<br>😰 <b style='color:#ef4444;'>MENTAL BREAKDOWN (" + escapeHtml(pick.name) + ")!</b> " + escapeHtml(pick.desc);
  }
  return "";
}

function openMemoirModal() {
  if (!hero) return;
  var list = (hero.memoir && hero.memoir.length) ? hero.memoir.map(function(m) { return '<div style="padding:5px 0;border-bottom:1px dashed #352940;font-size:12.5px;color:#e5dec9;">✒️ ' + escapeHtml(m) + '</div>'; }).join('') : '<div style="color:#9c8f7a;padding:8px;">No milestones inscribed yet.</div>';
  showPopupModal('<div style="font-size:38px;">🖋️📜👑</div><div style="font-size:19px;font-weight:900;color:#d4af37;font-family:Cinzel,serif;margin-bottom:6px;">Lineage Memoir of ' + escapeHtml(hero.name) + '</div><div style="max-height:320px;overflow-y:auto;text-align:left;background:#0b0811;border:1px solid #4a3823;border-radius:4px;padding:10px;">' + list + '</div><button class="btn btn-gold" style="width:100%;margin-top:10px;" onclick="openHeroSheetModal()">⬅️ Back</button>');
}

