      "@keyframes dodgeRightAnim { 0% { transform: translateX(0); } 35% { transform: translateX(16px) translateY(4px) rotate(9deg); opacity: 0.75; } 100% { transform: translateX(0); opacity: 1; } }" +
      ".anim-lunge-right .fighter-sprite { animation: lungeRightAnim 0.42s cubic-bezier(0.22,1,0.36,1) !important; }" +
      ".anim-lunge-left .fighter-sprite { animation: lungeLeftAnim 0.42s cubic-bezier(0.22,1,0.36,1) !important; }" +
      ".anim-dodge-left .fighter-sprite { animation: dodgeLeftAnim 0.45s ease-out !important; }" +
      ".anim-dodge-right .fighter-sprite { animation: dodgeRightAnim 0.45s ease-out !important; }" +
      ".strike-grid-5 { display: grid !important; grid-template-columns: repeat(6, minmax(0, 1fr)) !important; gap: 6px !important; margin-bottom: 6px !important; }" +
      ".strike-grid-5 > button:nth-child(1), .strike-grid-5 > button:nth-child(2), .strike-grid-5 > button:nth-child(3) { grid-column: span 2 !important; }" +
      ".strike-grid-5 > button:nth-child(4), .strike-grid-5 > button:nth-child(5) { grid-column: span 3 !important; }" +
